// ---------------------------------------------------------------------------
// Text input verification
// ---------------------------------------------------------------------------

/// Read the current value of an element and compare it with the expected text.
///
/// Returns `Ok(report)` with a human-readable comparison: fully typed,
/// partially typed (with character counts), or not typed. Returns `Err(msg)`
/// when the verification itself fails (e.g. element not found, session lost).
async fn verify_element_text(
    client: &Client,
    base_url: &str,
    session_id: &str,
    element_ref: Option<&str>,
    expected_text: &str,
) -> Result<String, String> {
    // Build a JavaScript expression that reads the element's value.
    // When a ref is provided, the expression runs as an arrow function over
    // that element (browser_evaluate passes the element as the argument).
    // Without a ref, read from document.activeElement.
    let expression = if element_ref.is_some() {
        "element => (element.value !== undefined ? (element.value || '') : (element.textContent || ''))".to_string()
    } else {
        "(() => { \
            const el = document.activeElement; \
            return el \
                ? (el.value !== undefined ? (el.value || '') : (el.textContent || '')) \
                : ''; \
        })()"
            .to_string()
    };

    let mut params = json!({
        "sessionId": session_id,
        "expression": expression,
    });
    if let Some(ref_sel) = element_ref {
        params["ref"] = json!(ref_sel);
    }

    let result = call_tool(client, base_url, "browser_evaluate", params).await?;

    // The MCP response may wrap the value in JSON quotes or be a plain string.
    let actual = result.trim().trim_matches('"').to_string();
    let expected_chars = expected_text.chars().count();
    let actual_chars = actual.chars().count();

    if actual == expected_text {
        Ok(format!(
            "Verification: text fully typed ({} chars).",
            expected_chars
        ))
    } else if actual.is_empty() {
        Ok("Verification: text was NOT typed — element is empty.".to_string())
    } else if expected_text.starts_with(&actual) {
        Ok(format!(
            "Verification: text PARTIALLY typed ({}/{} chars). Current value: '{}'",
            actual_chars, expected_chars, actual
        ))
    } else {
        Ok(format!(
            "Verification: text mismatch. Expected '{}', got '{}'.",
            expected_text, actual
        ))
    }
}

/// Handle `type` and `fill` commands with optional verification and automatic
/// post-timeout verification.
async fn handle_text_input_command(
    client: &Client,
    base_url: &str,
    tool_name: &str,
    tool_params: &Value,
    session_name: Option<&str>,
    verify: bool,
) -> Result<(), String> {
    // Extract the text and optional ref from tool_params (already resolved by
    // tool_params_fn). These are the values sent to the server.
    let expected_text = tool_params
        .get("text")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let element_ref = tool_params.get("ref").and_then(|v| v.as_str());

    // Warn when `type` (browser_press_sequentially) is used without a ref —
    // text may go nowhere if no element is currently focused on the page.
    if tool_name == "browser_press_sequentially"
        && element_ref.is_none()
        && !expected_text.is_empty()
    {
        eprintln!(
            "Warning: No element ref specified for 'type' command. \
             Text will be typed into whatever element currently has focus. \
             If nothing is focused, the text will go nowhere. \
             Use 'type <text> <ref>' or 'type <text> --ref <css-selector>' for reliable targeting."
        );
    }

    // Step 1: Call the text input tool.
    let tool_result = with_session(client, base_url, session_name, false, |session_id| {
        let client = client.clone();
        let base_url = base_url.to_string();
        let tool_name = tool_name.to_string();
        let mut params = tool_params.clone();
        params["sessionId"] = json!(session_id);
        async move { call_tool(&client, &base_url, &tool_name, params).await }
    })
    .await;

    match tool_result {
        Ok(text) => {
            // Tool succeeded. Print result if non-empty.
            if !text.is_empty() {
                cli_println!("{}", text);
            }

            // Success confirmation: tell the user what was done.
            let action_label = if tool_name == "browser_press_sequentially" {
                "Typed"
            } else {
                "Filled"
            };
            if let Some(ref_sel) = element_ref {
                cli_println!("✓ {} '{}' into {}", action_label, expected_text, ref_sel);
            } else {
                cli_println!("✓ {} '{}'", action_label, expected_text);
            }

            // Optional --verify: confirm the text was applied.
            if verify {
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                match verify_element_text(client, base_url, &session_id, element_ref, expected_text)
                    .await
                {
                    Ok(report) => {
                        cli_println!("{}", report);
                        json_field("verification", json!(&report));
                    }
                    Err(verify_err) => {
                        cli_println!("Verification could not be completed: {}", verify_err);
                        json_field("verification_error", json!(&verify_err));
                    }
                }
            }

            persist_active_selector(base_url, session_name, tracked_selector(tool_params))?;
            Ok(())
        }
        Err(err) => {
            if is_timeout_error_message(&err) {
                // Automatic verification after timeout — always attempted.
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                let verify_msg = match verify_element_text(
                    client,
                    base_url,
                    &session_id,
                    element_ref,
                    expected_text,
                )
                .await
                {
                    Ok(report) => report,
                    Err(verify_err) => {
                        format!("Verification could not be completed: {}", verify_err)
                    }
                };
                let enriched = format!("{}\n{}", err, verify_msg);
                Err(enriched)
            } else if is_not_focusable_error(&err) {
                // Element can't receive focus — suggest click-first workaround.
                let enriched = format!(
                    "{}\n\nTip: Some elements (e.g. Google search box) cannot receive focus directly.\n\
                     Try 'click <ref>' first to focus the element, then 'type <text>' to enter text.",
                    err
                );
                Err(enriched)
            } else {
                // Not a timeout or focusability issue — propagate as-is.
                Err(err)
            }
        }
    }
}

/// Handle `press` command with optional verification and automatic
/// post-timeout verification.
///
/// For verification, reads the element's current value. If the key is a
/// single printable character the verification checks whether it was
/// appended; for modifier / navigation keys it simply reports the current
/// value so the user can decide.
async fn handle_press_command(
    client: &Client,
    base_url: &str,
    tool_name: &str,
    tool_params: &Value,
    session_name: Option<&str>,
    verify: bool,
) -> Result<(), String> {
    let key_pressed = tool_params
        .get("key")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let element_ref = tool_params.get("ref").and_then(|v| v.as_str());

    // Build the expected check for printable single-character keys.
    let is_printable =
        key_pressed.chars().count() == 1 && !key_pressed.chars().all(|c| c.is_control());

    // Step 1: Call the press tool.
    let tool_result = with_session(client, base_url, session_name, false, |session_id| {
        let client = client.clone();
        let base_url = base_url.to_string();
        let tool_name = tool_name.to_string();
        let mut params = tool_params.clone();
        params["sessionId"] = json!(session_id);
        async move { call_tool(&client, &base_url, &tool_name, params).await }
    })
    .await;

    match tool_result {
        Ok(text) => {
            if !text.is_empty() {
                cli_println!("{}", text);
            }

            // Success confirmation.
            if let Some(ref_sel) = element_ref {
                cli_println!("✓ Pressed '{}' on {}", key_pressed, ref_sel);
            } else {
                cli_println!("✓ Pressed '{}'", key_pressed);
            }

            if verify {
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                match verify_press_result(
                    client,
                    base_url,
                    &session_id,
                    element_ref,
                    key_pressed,
                    is_printable,
                )
                .await
                {
                    Ok(report) => {
                        cli_println!("{}", report);
                        json_field("verification", json!(&report));
                    }
                    Err(verify_err) => {
                        cli_println!("Verification could not be completed: {}", verify_err);
                        json_field("verification_error", json!(&verify_err));
                    }
                }
            }

            persist_active_selector(base_url, session_name, tracked_selector(tool_params))?;
            Ok(())
        }
        Err(err) => {
            if is_timeout_error_message(&err) {
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                let verify_msg = match verify_press_result(
                    client,
                    base_url,
                    &session_id,
                    element_ref,
                    key_pressed,
                    is_printable,
                )
                .await
                {
                    Ok(report) => report,
                    Err(verify_err) => {
                        format!("Verification could not be completed: {}", verify_err)
                    }
                };
                let enriched = format!("{}\n{}", err, verify_msg);
                Err(enriched)
            } else {
                Err(err)
            }
        }
    }
}

/// Verify the result of a `press` command by reading the element value.
async fn verify_press_result(
    client: &Client,
    base_url: &str,
    session_id: &str,
    element_ref: Option<&str>,
    key_pressed: &str,
    is_printable: bool,
) -> Result<String, String> {
    let expression = if element_ref.is_some() {
        "element => (element.value !== undefined ? (element.value || '') : (element.textContent || ''))".to_string()
    } else {
        "(() => { \
            const el = document.activeElement; \
            return el \
                ? (el.value !== undefined ? (el.value || '') : (el.textContent || '')) \
                : ''; \
        })()"
            .to_string()
    };

    let mut params = json!({
        "sessionId": session_id,
        "expression": expression,
    });
    if let Some(ref_sel) = element_ref {
        params["ref"] = json!(ref_sel);
    }

    let result = call_tool(client, base_url, "browser_evaluate", params).await?;
    let actual = result.trim().trim_matches('"').to_string();

    if is_printable {
        if actual.ends_with(key_pressed) {
            Ok(format!(
                "Verification: key '{}' was pressed — value ends with expected character. Current value: '{}'",
                key_pressed, actual
            ))
        } else if actual.is_empty() {
            Ok("Verification: key was NOT applied — element is empty.".to_string())
        } else {
            Ok(format!(
                "Verification: key '{}' may not have been applied. Current value: '{}'",
                key_pressed, actual
            ))
        }
    } else {
        Ok(format!(
            "Verification: element value after '{}' press: '{}'",
            key_pressed, actual
        ))
    }
}

/// True when the tool's text output is nothing but the JSON array of values the
/// user just asked to select — the confirmation line below already reports them
/// (and reports them in the user's own labelling), so the raw array is noise.
fn is_selected_values_echo(text: &str, expected_value: &str) -> bool {
    let trimmed = text.trim();
    if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
        return false;
    }
    match serde_json::from_str::<Value>(trimmed) {
        Ok(Value::Array(items)) if !items.is_empty() => {
            let values: Vec<&str> = match items.iter().map(|item| item.as_str()).collect() {
                Some(values) => values,
                None => return false,
            };
            values.join(",") == expected_value
        }
        _ => false,
    }
}

#[cfg(test)]
mod selected_values_echo_tests {
    use super::is_selected_values_echo;

    #[test]
    fn single_selected_value_is_treated_as_echo() {
        assert!(is_selected_values_echo("[\"sg\"]", "sg"));
        assert!(is_selected_values_echo(" [\"sg\"]\n", "sg"));
    }

    #[test]
    fn multi_select_echo_matches_the_typed_value() {
        assert!(is_selected_values_echo("[\"sg\",\"de\"]", "sg,de"));
        assert!(!is_selected_values_echo("[\"sg\",\"de\"]", "sg"));
    }

    #[test]
    fn real_output_is_never_swallowed() {
        assert!(!is_selected_values_echo("✓ Selected 'sg'", "sg"));
        assert!(!is_selected_values_echo("[\"us\"]", "sg"));
        assert!(!is_selected_values_echo("[]", "sg"));
        assert!(!is_selected_values_echo("", "sg"));
    }
}

/// Handle `select` command with optional verification and automatic
/// post-timeout verification.
async fn handle_select_command(
    client: &Client,
    base_url: &str,
    tool_name: &str,
    tool_params: &Value,
    session_name: Option<&str>,
    verify: bool,
) -> Result<(), String> {
    // Read the display value from the "values" array (set by tool_params_fn).
    // The user types a human-readable label like "United States", but the
    // underlying <option> value may differ (e.g. "us"). We show what the user
    // asked for so the confirmation message is meaningful.
    let expected_value = tool_params
        .get("values")
        .and_then(|v| v.as_array())
        .and_then(|arr| arr.first())
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let element_ref = tool_params.get("ref").and_then(|v| v.as_str());

    let tool_result = with_session(client, base_url, session_name, false, |session_id| {
        let client = client.clone();
        let base_url = base_url.to_string();
        let tool_name = tool_name.to_string();
        let mut params = tool_params.clone();
        params["sessionId"] = json!(session_id);
        async move { call_tool(&client, &base_url, &tool_name, params).await }
    })
    .await;

    match tool_result {
        Ok(text) => {
            // The backend answers a select with the selected values as a JSON
            // array; echoing it dumped a bare `["sg"]` line into human-readable
            // output, right above the confirmation that already reports them.
            if !text.is_empty() && !is_selected_values_echo(&text, expected_value) {
                cli_println!("{}", text);
            }

            // Success confirmation.
            if let Some(ref_sel) = element_ref {
                cli_println!("✓ Selected '{}' in {}", expected_value, ref_sel);
            } else {
                cli_println!("✓ Selected '{}'", expected_value);
            }

            if verify {
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                match verify_select_result(
                    client,
                    base_url,
                    &session_id,
                    element_ref,
                    expected_value,
                )
                .await
                {
                    Ok(SelectVerifyOutcome::Pass { report }) => {
                        cli_println!("{}", report);
                        json_field("verification", json!(&report));
                    }
                    Ok(SelectVerifyOutcome::Fail { report }) => {
                        // A genuine verification mismatch must fail the command
                        // (non-zero exit) so scripts can rely on --verify.
                        json_field("verification", json!(&report));
                        return Err(report);
                    }
                    Ok(SelectVerifyOutcome::Inconclusive { report }) => {
                        cli_println!("{}", report);
                        json_field("verification", json!(&report));
                    }
                    Err(verify_err) => {
                        cli_println!("Verification could not be completed: {}", verify_err);
                        json_field("verification_error", json!(&verify_err));
                    }
                }
            }

            persist_active_selector(base_url, session_name, tracked_selector(tool_params))?;
            Ok(())
        }
        Err(err) => {
            if is_timeout_error_message(&err) {
                let state = require_session(session_name)?;
                let session_id = get_session_id(&state)?.to_string();
                let verify_msg = match verify_select_result(
                    client,
                    base_url,
                    &session_id,
                    element_ref,
                    expected_value,
                )
                .await
                {
                    Ok(SelectVerifyOutcome::Pass { report }) => report,
                    Ok(SelectVerifyOutcome::Fail { report }) | Ok(SelectVerifyOutcome::Inconclusive { report }) => {
                        report
                    }
                    Err(verify_err) => {
                        format!("Verification could not be completed: {}", verify_err)
                    }
                };
                let enriched = format!("{}\n{}", err, verify_msg);
                Err(enriched)
            } else {
                Err(err)
            }
        }
    }
}

/// Outcome of a `select --verify` comparison.
enum SelectVerifyOutcome {
    /// The requested option is the one selected — verification passed.
    Pass { report: String },
    /// The requested option exists but is NOT the one selected — a genuine
    /// mismatch that must fail the command (non-zero exit).
    Fail { report: String },
    /// The argument matched no option (or the select is empty) — advisory
    /// output only, no hard failure.
    Inconclusive { report: String },
}

/// Decide a `select --verify` outcome from the live select state.
///
/// Matching mirrors what the select tool itself accepts: the argument may be
/// the option's value or its visible label, compared case-insensitively.
/// `options` holds (value, visible-text) pairs for every `<option>`.
fn decide_select_verify(
    expected: &str,
    current: &str,
    options: &[(String, String)],
) -> SelectVerifyOutcome {
    let expected = expected.trim();
    let expected_matches_value = |value: &str| value.eq_ignore_ascii_case(expected);
    let expected_matches_label = |text: &str| text.eq_ignore_ascii_case(expected);

    // Options the requested argument refers to (by value and/or visible label).
    let matched: Vec<(String, String)> = options
        .iter()
        .filter(|(value, text)| {
            expected_matches_value(value) || expected_matches_label(text)
        })
        .cloned()
        .collect();

    if matched.is_empty() {
        let current_desc = if current.is_empty() {
            "no option appears to be selected — value is empty".to_string()
        } else {
            format!("current value is \"{current}\"")
        };
        return SelectVerifyOutcome::Inconclusive {
            report: format!(
                "Verification: no option matches \"{expected}\" (neither a value nor a visible label) — {current_desc}."
            ),
        };
    }

    let by_label = matched
        .iter()
        .any(|(value, text)| expected_matches_label(text) && !expected_matches_value(value));

    // Direct equality with the select's current value (case-insensitive).
    if expected_matches_value(current) {
        return SelectVerifyOutcome::Pass {
            report: success_report(expected, current, by_label),
        };
    }
    // The selected option must be one of the options the argument matched.
    if let Some((value, _)) = matched
        .iter()
        .find(|(value, _)| value.eq_ignore_ascii_case(current))
    {
        return SelectVerifyOutcome::Pass {
            report: success_report(expected, value, by_label),
        };
    }
    if current.is_empty() {
        return SelectVerifyOutcome::Fail {
            report: format!(
                "Verification failed: option \"{expected}\" is not selected — no option is currently selected."
            ),
        };
    }
    let first_value = matched[0].0.as_str();
    SelectVerifyOutcome::Fail {
        report: if by_label {
            format!(
                "Verification failed: option \"{expected}\" (value {first_value}) is not selected — current value is \"{current}\"."
            )
        } else {
            format!(
                "Verification failed: option \"{expected}\" is not selected — current value is \"{current}\"."
            )
        },
    }
}

/// Success report for a verified selection.  A label-based selection reports
/// both the visible label and the underlying value so the user can see that
/// `select "Singapore"` really did select the option carrying value `sg`.
fn success_report(expected: &str, matched_value: &str, by_label: bool) -> String {
    if by_label {
        format!("Verification: option \"{expected}\" (value {matched_value}) is selected.")
    } else {
        format!("Verification: option \"{expected}\" is selected.")
    }
}

/// Verify the result of a `select` command by reading the element's selected
/// option plus the full option list, then deciding the outcome with the same
/// value-or-label, case-insensitive semantics the select tool uses.
async fn verify_select_result(
    client: &Client,
    base_url: &str,
    session_id: &str,
    element_ref: Option<&str>,
    expected_value: &str,
) -> Result<SelectVerifyOutcome, String> {
    let expression = if element_ref.is_some() {
        // Read the current value AND the option list in one round trip so a
        // label-based selection can be resolved to its matched option value.
        "element => JSON.stringify({ current: element.value ?? '', options: Array.from(element.options || []).map(o => ({ v: o.value ?? '', t: (o.text ?? o.textContent ?? '').trim() })) })"
            .to_string()
    } else {
        return Err("Verification requires an element ref for select.".to_string());
    };

    let mut params = json!({
        "sessionId": session_id,
        "expression": expression,
    });
    if let Some(ref_sel) = element_ref {
        params["ref"] = json!(ref_sel);
    }

    let result = call_tool(client, base_url, "browser_evaluate", params).await?;
    let payload: Value = serde_json::from_str(result.trim())
        .map_err(|_| format!("could not parse the select state returned by the browser: {result}"))?;
    let current = payload
        .get("current")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let options: Vec<(String, String)> = payload
        .get("options")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|o| {
                    let value = o.get("v").and_then(|v| v.as_str()).unwrap_or("");
                    let text = o.get("t").and_then(|v| v.as_str()).unwrap_or("");
                    Some((value.to_string(), text.to_string()))
                })
                .collect()
        })
        .unwrap_or_default();
    Ok(decide_select_verify(expected_value, &current, &options))
}

// ---------------------------------------------------------------------------
// Agent command handlers
// ---------------------------------------------------------------------------

/// The `command_run` payload fields every `agent run` mode shares.
///
/// `sessionId` is forwarded only when the caller named a session (`-s`): agent
/// tasks used to land in the backend's DEFAULT session no matter what, so two
/// interactive sessions could not be isolated. The backend's `command.run`
/// documents `sessionId` as its transport argument, and it defaults to DEFAULT,
/// so omitting it keeps the previous behaviour.
fn build_agent_run_extra(
    engine: &str,
    noop_limit: Option<i64>,
    coding: bool,
    fresh_workspace: bool,
    shared_workspace: bool,
    access: Option<&str>,
    unattended: Option<bool>,
    session_id: Option<&str>,
    token_budget: Option<i64>,
) -> Value {
    let mut extra = json!({ "engine": engine });
    if let Some(limit) = noop_limit {
        extra["noopLimit"] = json!(limit);
    }
    if coding {
        extra["coding"] = json!(true);
    }
    if fresh_workspace {
        extra["freshWorkspace"] = json!(true);
    }
    if shared_workspace {
        extra["sharedWorkspace"] = json!(true);
    }
    // Per-task token budget: forwarded only when the caller named one, so an
    // omitted value keeps the server-wide `agent.token.budget.total` default
    // (the backend treats an absent key as "use the configured budget").
    if let Some(budget) = token_budget {
        extra["tokenBudget"] = json!(budget);
    }
    // Only forward when set: absent means "use the server-wide
    // `browser4.agent.access` default", not "full".
    if let Some(preset) = access.map(str::trim).filter(|s| !s.is_empty()) {
        extra["access"] = json!(preset);
    }
    // Plan P4-1: an omitted flag keeps the backend's unattended default (which is
    // what a submitted job gets anyway). The interactive REPL is the only caller
    // that decides it, passing `false` on a TTY so the server-wide policy applies
    // to a watched run.
    if let Some(flag) = unattended {
        extra["unattended"] = json!(flag);
    }
    if let Some(session) = session_id.map(str::trim).filter(|s| !s.is_empty()) {
        extra["sessionId"] = json!(session);
    }
    extra
}

/// Forward `--resume <task-id>` into the `command.run` payload.
///
/// A resume is entirely backend-side: the CLI cannot invent the interrupted task's
/// instruction or workspace, it only names the checkpoint. A blank value is not an
/// id, so it must not be forwarded (the backend would look up `""` and fail the
/// task with a confusing "unknown checkpoint").
fn apply_resume_task_id(extra: &mut Value, resume_task_id: Option<&str>) {
    if let Some(id) = resume_task_id.map(str::trim).filter(|s| !s.is_empty()) {
        extra["resumeTaskId"] = json!(id);
    }
}

/// Submit one agent task in async mode and return its task id.
///
/// Shared by the one-shot forms and the interactive session, so every mode
/// reports a missing LLM API key the same actionable way instead of leaving the
/// user with a 180 s HTTP timeout (the backend fails such a task almost
/// immediately).
async fn submit_agent_task(
    client: &Client,
    base_url: &str,
    task: &str,
    extra: Value,
) -> Result<String, String> {
    let result = submit_plain_command_with_options(client, base_url, task, true, extra).await?;

    // The async response is a task ID (possibly JSON-quoted)
    let task_id = result.trim().trim_matches('"').to_string();
    if task_id.is_empty() {
        return Err("The backend returned no task id for the submitted task.".to_string());
    }
    if let Some(message) =
        detect_missing_llm_error_for_submitted_agent_task(client, base_url, &task_id).await?
    {
        return Err(format_missing_llm_error(&message, "agent run"));
    }

    Ok(task_id)
}

/// Session an agent task was bound to, plus that session's connection label.
///
/// The label comes from the CLI state slot that supplied the id — the addressed
/// slot first, then the SWARM slot, mirroring [`resolve_agent_session_id_in`].
/// The connection is `None` when no slot matches the id (a stale record), so the
/// caller never prints a label that describes a different session.
fn agent_task_binding(
    session_id: Option<&str>,
    session_name: Option<&str>,
) -> Option<(String, Option<String>)> {
    let session_id = session_id?;
    let addressed = read_state(None, session_name);
    let state = if addressed.session_id.as_deref() == Some(session_id) {
        Some(addressed)
    } else {
        let swarm = read_state(None, Some(SWARM_SESSION_ID));
        if swarm.session_id.as_deref() == Some(session_id) {
            Some(swarm)
        } else {
            None
        }
    };
    Some((
        session_id.to_string(),
        state.map(|state| connection_label_full(&state, None)),
    ))
}

async fn handle_agent_run(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
    session_name: Option<&str>,
) -> Result<(), String> {
    // --token-budget: rejected rather than ignored when it is not a budget. An
    // ignored flag would run the task under the default budget while the user
    // believes they raised it — the exact failure this flag exists to prevent.
    // Checked before the interactive branch, which would otherwise swallow it.
    if let Some(raw) = tool_params.get("tokenBudgetInvalid").and_then(|v| v.as_str()) {
        return Err(format!(
            "--token-budget expects a non-negative integer (0 = unlimited), got '{}'.",
            raw
        ));
    }
    // Interactive session (`agent run -i`): its own loop owns submission and
    // output, including the optional initial task.
    if tool_params
        .get("interactive")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        if tool_params
            .get("ndjson")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
        {
            eprintln!("⚠ --ndjson does not apply to the interactive session (-i); ignoring it");
        }
        return agent_interactive::run_interactive(client, base_url, tool_params, session_name)
            .await;
    }

    let task = tool_params
        .get("task")
        .and_then(|v| v.as_str())
        .unwrap_or_default();
    // `--resume <id>` makes the task text optional: the backend seeds the run from
    // the interrupted task's checkpoint (its instruction, workspace and files).
    let resume_task_id = tool_params
        .get("resumeTaskId")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty());

    if task.is_empty() && resume_task_id.is_none() {
        return Err(
            "Task description is required (or --resume <task-id> to resume an interrupted task)."
                .to_string(),
        );
    }

    let follow = tool_params
        .get("follow")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    // A silently ignored flag is a lie about what the command did.
    if !follow
        && tool_params
            .get("ndjson")
            .and_then(|v| v.as_bool())
            .unwrap_or(false)
    {
        eprintln!("⚠ --ndjson only affects --follow; ignoring it");
    }

    // Run the task in the CLI's current session (attached browser / `-s <name>` /
    // SWARM), not the backend's DEFAULT session. Without this, `agent run` against
    // an extension-attached browser drove no page at all and started a second
    // browser on the first navigation; `-s <name>` alone was not enough either,
    // because the backend only knows the name after the CLI registered it.
    let resolved_session_id = resolve_agent_session_id(session_name);
    let mut extra = build_agent_run_extra(
        tool_params
            .get("engine")
            .and_then(|v| v.as_str())
            .unwrap_or("cli"),
        tool_params.get("noopLimit").and_then(|v| v.as_i64()),
        // Only forward when set: the payload key itself is the opt-in signal
        // (absent ⇒ browser task, the default).
        tool_params.get("coding").and_then(|v| v.as_bool()) == Some(true),
        tool_params
            .get("freshWorkspace")
            .and_then(|v| v.as_bool())
            == Some(true),
        tool_params
            .get("sharedWorkspace")
            .and_then(|v| v.as_bool())
            == Some(true),
        tool_params.get("access").and_then(|v| v.as_str()),
        // A one-shot `agent run` is unattended: omit the flag so the backend derives
        // its documented default rather than the CLI synthesizing a policy.
        None,
        resolved_session_id.as_deref(),
        tool_params.get("tokenBudget").and_then(|v| v.as_i64()),
    );
    apply_resume_task_id(&mut extra, resume_task_id);
    let task_id = submit_agent_task(client, base_url, task, extra).await?;

    // Say which session the task was bound to.  A silent submission is exactly
    // what hid the 2026-10-25 regression: the task executed in the backend's
    // DEFAULT session (opening a second browser) while the CLI kept reporting
    // the attached Edge, and only the backend log showed the difference.
    let binding = agent_task_binding(resolved_session_id.as_deref(), session_name);

    // NDJSON mode is machine output end to end: the submission is a JSON line
    // too, so a consumer never has to skip prose.
    let ndjson = follow
        && tool_params
            .get("ndjson")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
    if ndjson {
        print_stdout_line(
            &json!({
                "type": "task.submitted",
                "taskId": task_id,
                "sessionId": resolved_session_id,
                "connection": binding.as_ref().and_then(|(_, connection)| connection.clone()),
                "task": task,
            })
            .to_string(),
        );
    } else {
        match &binding {
            Some((session_id, Some(connection))) => cli_println!(
                "Task submitted: {} (session={}, {})",
                task_id,
                session_id,
                connection
            ),
            Some((session_id, None)) => cli_println!(
                "Task submitted: {} (session={}; the connection is unknown to this CLI state)",
                task_id,
                session_id
            ),
            None => cli_println!(
                "Task submitted: {} (no session — a session-less task)",
                task_id
            ),
        }
    }
    json_field("task_id", json!(&task_id));
    json_field("session_id", json!(resolved_session_id));
    json_field(
        "session_connection",
        json!(binding.as_ref().and_then(|(_, connection)| connection.clone())),
    );

    // Persist the task for cross-session tracking in BOTH async and wait
    // modes, so `agent list` always reflects every submitted task — including
    // ones that later time out while the server keeps working on them.
    let _ = track_async_task(&task_id, "agent", task, None);

    // `--follow`: stream the task's steps while waiting. `--wait` stays the
    // quiet, poll-only form it always was.
    if follow {
        let options = agent_interactive::FollowOptions {
            ndjson,
            // No default cap: following a task is an explicit "watch it" request,
            // and `--wait` remains the capped form.
            wait_timeout: tool_params.get("waitTimeout").and_then(|v| v.as_u64()),
        };
        return agent_interactive::follow_task(client, base_url, &task_id, options).await;
    }

    let wait = tool_params
        .get("wait")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if wait {
        cli_println!("Waiting for agent to complete (task {})...", task_id);
        let start = std::time::Instant::now();
        // Per-invocation override (--wait-timeout) wins; falls back to the
        // BROWSER4_CLI_AGENT_WAIT_TIMEOUT_SECS env var; default is 10 minutes.
        let wait_timeout_secs = tool_params
            .get("waitTimeout")
            .and_then(|v| v.as_u64())
            .or_else(|| {
                std::env::var("BROWSER4_CLI_AGENT_WAIT_TIMEOUT_SECS")
                    .ok()
                    .and_then(|raw| raw.trim().parse::<u64>().ok())
            })
            .unwrap_or(600);
        let timeout = std::time::Duration::from_secs(wait_timeout_secs);
        loop {
            if start.elapsed() > timeout {
                // The task is still alive server-side; keep it in the local
                // list so `agent list` / `agent status` can pick it up later.
                let _ = update_async_task_status(&task_id, "processing", None);
                return Err(format!(
                    "Agent task {} timed out after {}s. Use 'agent status {}' to check later.",
                    task_id,
                    start.elapsed().as_secs(),
                    task_id
                ));
            }

            let status = get_command_status(client, base_url, &task_id).await?;
            let parsed: Value =
                serde_json::from_str(&status).unwrap_or(Value::String(status.clone()));
            let process_state = parsed
                .get("processState")
                .and_then(|v| v.as_str())
                .unwrap_or("");
            // Read the shared envelope first. The loop used to know only the legacy
            // `processState`, so a task that reached `status: done` five seconds in
            // could never take the success branch: `--wait` burned its whole timeout
            // and discarded the result it was waiting for (issue 112415#4).
            let envelope_word = envelope_status_word(&parsed);
            let terminal_word = if !envelope_word.is_empty() {
                if is_terminal_shared_status(&envelope_word) {
                    envelope_word.clone()
                } else {
                    String::new()
                }
            } else if matches!(process_state, "done" | "completed")
                || parsed
                    .get("isDone")
                    .and_then(|v| v.as_bool())
                    .unwrap_or(false)
            {
                "done".to_string()
            } else if matches!(process_state, "failed" | "error") {
                "failed".to_string()
            } else {
                String::new()
            };

            match terminal_word.as_str() {
                // Successful terminal state.
                "done" => {
                    let status_code = parsed
                        .get("statusCode")
                        .and_then(|v| v.as_i64())
                        .unwrap_or(200);
                    let failure_reason = parsed
                        .get("failureReason")
                        .or_else(|| parsed.get("error"))
                        .and_then(|v| v.as_str())
                        .map(|s| s.to_string());
                    if status_code >= 400 || failure_reason.is_some() {
                        let message = failure_reason
                            .unwrap_or_else(|| format!("Agent task failed with status code {status_code}"));
                        let _ = update_async_task_status(&task_id, "failed", None);
                        return Err(format!("Agent task failed: {message}"));
                    }
                    let result_text = get_command_result(client, base_url, &task_id).await?;
                    cli_println!("Agent completed in {:.1}s:", start.elapsed().as_secs_f64());
                    cli_println!("{}", result_text);
                    json_field(
                        "raw",
                        json!(serde_json::from_str::<Value>(&result_text)
                            .unwrap_or(Value::String(result_text.clone()))),
                    );
                    let _ = update_async_task_status(&task_id, "completed", None);
                    return Ok(());
                }
                "failed" => {
                    // The envelope carries the reason in `error`; the legacy payload
                    // carried it in `message`/`failureReason`.
                    let message = parsed
                        .get("error")
                        .and_then(|v| v.as_str())
                        .or_else(|| parsed.get("failureReason").and_then(|v| v.as_str()))
                        .or_else(|| parsed.get("message").and_then(|v| v.as_str()))
                        .unwrap_or("Agent task failed");
                    let _ = update_async_task_status(&task_id, "failed", None);
                    return Err(format!("Agent task failed: {}", message));
                }
                "cancelled" => {
                    let _ = update_async_task_status(&task_id, "cancelled", None);
                    return Err(format!(
                        "Agent task {} was cancelled. Use 'agent status {}' to see its final state.",
                        task_id, task_id
                    ));
                }
                _ => {
                    // Show progress indicator, with the agent's own description and
                    // step count when the envelope has them.
                    let elapsed = start.elapsed().as_secs();
                    if elapsed > 0 && elapsed % 5 == 0 {
                        let mut msg = parsed
                            .get("message")
                            .and_then(|v| v.as_str())
                            .unwrap_or("processing...")
                            .to_string();
                        if let Some(steps) = parsed.get("processed").and_then(|v| v.as_u64()) {
                            if steps > 0 {
                                msg.push_str(&format!(" ({} step(s))", steps));
                            }
                        }
                        cli_println!("  [{}s] {}", elapsed, msg);
                    }
                }
            }

            tokio::time::sleep(std::time::Duration::from_secs(2)).await;
        }
    }

    cli_println!(
        "Use 'agent status {}' to check progress, or 'agent list' to view all tracked tasks.",
        task_id
    );

    Ok(())
}

async fn handle_chat(client: &Client, base_url: &str, tool_params: &Value) -> Result<(), String> {
    let prompt = tool_params
        .get("prompt")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if prompt.is_empty() {
        return Err("A prompt is required. Usage: browser4-cli chat \"<message>\"".to_string());
    }

    let is_async = tool_params
        .get("async")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if is_async {
        let task_id = http::chat_with_ai_async(client, base_url, prompt).await?;
        cli_println!("Chat task submitted: {}", task_id);
        cli_println!(
            "Use 'browser4-cli chat result {}' to get the response.",
            task_id
        );
    } else {
        let response = http::chat_with_ai(client, base_url, prompt).await?;
        cli_println!("{}", response);
    }

    Ok(())
}

async fn handle_chat_result(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let task_id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if task_id.is_empty() {
        return Err("A task ID is required. Usage: browser4-cli chat result <id>".to_string());
    }

    let response = http::get_chat_result(client, base_url, task_id).await?;
    cli_println!("{}", response);

    Ok(())
}

async fn handle_act(client: &Client, base_url: &str, description: &str) -> Result<(), String> {
    let result = http::execute_act_command(client, base_url, description).await?;

    if result.is_empty() {
        cli_println!("Action completed (no output).");
    } else {
        cli_println!("{}", result);
    }

    Ok(())
}

async fn detect_missing_llm_error_for_submitted_agent_task(
    client: &Client,
    base_url: &str,
    task_id: &str,
) -> Result<Option<String>, String> {
    for _ in 0..AGENT_RUN_FAILURE_POLL_ATTEMPTS {
        tokio::time::sleep(std::time::Duration::from_millis(
            AGENT_RUN_FAILURE_POLL_INTERVAL_MS,
        ))
        .await;

        let status = get_command_status(client, base_url, task_id).await?;
        if let Some(message) = extract_missing_llm_configuration_message(&status) {
            return Ok(Some(message));
        }

        let Some(parsed) = serde_json::from_str::<Value>(&status).ok() else {
            return Ok(None);
        };
        // Terminal per the shared envelope (`status`) or the legacy `processState`.
        // Reading only `processState` here meant a task the envelope had already
        // finished was polled for the whole failure-detection window.
        let envelope_word = envelope_status_word(&parsed);
        let terminal = if !envelope_word.is_empty() {
            is_terminal_shared_status(&envelope_word)
        } else {
            matches!(
                parsed.get("processState").and_then(|value| value.as_str()),
                Some("done") | Some("completed") | Some("failed") | Some("error")
            )
        };
        if terminal {
            return Ok(None);
        }
    }

    Ok(None)
}

fn extract_missing_llm_configuration_message(status_payload: &str) -> Option<String> {
    let parsed = serde_json::from_str::<Value>(status_payload).ok()?;
    let envelope_word = envelope_status_word(&parsed);
    let finished = if !envelope_word.is_empty() {
        is_terminal_shared_status(&envelope_word)
    } else {
        matches!(
            parsed.get("processState").and_then(|value| value.as_str()),
            Some("done") | Some("completed")
        ) || parsed
            .get("isDone")
            .and_then(|value| value.as_bool())
            .unwrap_or(false)
    };
    let status_code = parsed.get("statusCode").and_then(|value| value.as_i64())?;
    if !finished || status_code < 400 {
        return None;
    }

    let message = parsed
        .get("message")
        .and_then(|value| value.as_str())
        .or_else(|| parsed.get("error").and_then(|value| value.as_str()))
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    if is_missing_llm_configuration_message(message) {
        return Some(message.to_string());
    }

    None
}

fn is_missing_llm_configuration_message(message: &str) -> bool {
    let lower = message.to_ascii_lowercase();
    lower.contains("llm is not configured")
        || lower.contains("llm.api.key is not set")
        || lower.contains("llm api key is not configured")
        || (lower.contains("llm") && lower.contains("api key") && lower.contains("not set"))
        || (lower.contains("llm") && lower.contains("api key") && lower.contains("not configured"))
}

/// Produce a clean, actionable error message for LLM-not-configured failures.
///
/// The raw server message is wrapped with MCP tool names like
/// `"agent_extract failed: LLM API key is not configured..."` — this strips that
/// prefix and formats a consistent, user-facing error with a header and the
/// server's actionable guidance.
fn format_missing_llm_error(raw_message: &str, command_name: &str) -> String {
    // Strip the MCP tool-name prefix, e.g. "agent_extract failed: " →
    // just the server's message body.
    let body = raw_message
        .trim()
        .replacen("agent_extract failed: ", "", 1)
        .replacen("agent_summarize failed: ", "", 1)
        .trim()
        .to_string();

    // Remove internal doc references that won't be present in an end-user's
    // environment (e.g. "see docs/config/llm/llm-config.md").
    let body = body
        .replacen(", see docs/config/llm/llm-config.md", "", 1)
        .replacen("; see docs/config/llm/llm-config.md", "", 1)
        .replace("see docs/config/llm/llm-config.md", "")
        .trim()
        .to_string();

    format!("❌ {command_name} requires an LLM API key\n\n{body}")
}

/// The reason when a `command_status`/`command_result` payload is the backend's
/// structured not-found answer (`statusCode` 404), else `None`.
///
/// The backend serializes an unknown id as a status envelope, not as `null`, so the
/// null-payload guards alone could never fire: a mistyped id printed
/// `{"status":"failed"}` with exit 0 and no reason (issue 112415#6).
fn agent_envelope_not_found_reason(parsed: &Value) -> Option<String> {
    let code = parse_status_code_from_json(parsed);
    if code != "404" && code != "SC_NOT_FOUND" {
        return None;
    }
    Some(
        parsed
            .get("error")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .unwrap_or("the backend has no record of this task id")
            .to_string(),
    )
}

/// Print where an agent task's deliverables live, when the payload names them.
///
/// `agent result` printed only the completion summary for a task whose whole point
/// was returning data, and the artifact itself was reachable only by searching the
/// backend's app-data tree by hand (issue 111443#1). The payload now carries the
/// agent's own completion report (`keyFindings`, `filesChanged`, `problems`) and the
/// workspace its tools wrote into.
fn print_agent_deliverables(payload: &Value) {
    let strings = |key: &str| -> Vec<String> {
        payload
            .get(key)
            .and_then(|v| v.as_array())
            .map(|items| {
                items
                    .iter()
                    .filter_map(|v| v.as_str())
                    .map(str::to_string)
                    .collect()
            })
            .unwrap_or_default()
    };
    let findings = strings("keyFindings");
    let files = strings("filesChanged");
    let problems = strings("problems");
    let workspace = payload
        .get("workspace")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty());

    if findings.is_empty() && files.is_empty() && problems.is_empty() && workspace.is_none() {
        return;
    }

    cli_println!("");
    if !findings.is_empty() {
        cli_println!("Key findings:");
        for finding in findings.iter().take(20) {
            cli_println!("  - {}", finding);
        }
        if findings.len() > 20 {
            cli_println!("  ... and {} more", findings.len() - 20);
        }
    }
    if !files.is_empty() {
        cli_println!("Files the agent reported changing:");
        for file in files.iter().take(20) {
            cli_println!("  {}", file);
        }
        if files.len() > 20 {
            cli_println!("  ... and {} more", files.len() - 20);
        }
    }
    if !problems.is_empty() {
        cli_println!("Unresolved problems reported by the agent:");
        for problem in problems.iter().take(10) {
            cli_println!("  - {}", problem);
        }
    }
    if let Some(workspace) = workspace {
        cli_println!("Task workspace: {}", workspace);
        cli_println!("  (the agent's deliverables live here; `agent result --json` prints the same path in `workspace`)");
    }
}

/// The status word a `command_result` payload reports (`failed`, `cancelled`, …).
///
/// `status` is the shared envelope's word; `processState`/`statusCode` are the
/// fallbacks for an older backend that only has the raw form.
fn agent_result_status_word(payload: &Value) -> Option<String> {
    if let Some(word) = payload.get("status").and_then(|v| v.as_str()) {
        let lower = word.trim().to_lowercase();
        if !lower.is_empty() {
            return Some(lower);
        }
    }
    if let Some(state) = payload.get("processState").and_then(|v| v.as_str()) {
        return match state.trim().to_lowercase().as_str() {
            "done" | "completed" => Some("done".to_string()),
            "failed" | "error" => Some("failed".to_string()),
            "cancelled" | "canceled" => Some("cancelled".to_string()),
            _ => Some("running".to_string()),
        };
    }
    None
}

/// The one-line human verdict of a finished task: `✖ failed (budget) · files: … · resume: …`.
///
/// `agent result` used to append "Files the agent reported changing" even for a
/// failed run, listing whatever happened to be in the workspace (2026-10-28: an old
/// CSV and another task's report, timestamped before the run started). The verdict
/// line names the failure reason, the workspace, the files THIS run wrote, and how
/// to continue — or says plainly that it wrote none.
fn format_agent_result_verdict(task_id: &str, payload: &Value) -> Option<String> {
    let word = agent_result_status_word(payload)?;
    if word != "failed" && word != "cancelled" {
        return None;
    }
    let error_code = payload
        .get("errorCode")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .or_else(|| {
            payload
                .get("result")
                .and_then(|r| r.get("errorCode"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
        });
    let reason = payload
        .get("error")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .or_else(|| payload.get("message").and_then(|v| v.as_str()))
        .map(|s| crate::agent_interactive::truncate(s, 160));
    let details = payload.get("result").unwrap_or(payload);
    let files = details
        .get("filesChanged")
        .and_then(|v| v.as_array())
        .map(|items| items.iter().filter_map(|v| v.as_str()).collect::<Vec<_>>())
        .unwrap_or_default();
    let workspace = details
        .get("workspace")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .or_else(|| payload.get("workspace").and_then(|v| v.as_str()));
    let resumable = details
        .get("resumable")
        .and_then(|v| v.as_bool())
        .or_else(|| payload.get("resumable").and_then(|v| v.as_bool()));
    let budget = payload
        .get("effectiveTokenBudget")
        .and_then(|v| v.as_i64())
        .or_else(|| details.get("effectiveTokenBudget").and_then(|v| v.as_i64()));

    let label = match error_code {
        Some(code) => format!("{} ({})", word, code.to_lowercase()),
        None => word.clone(),
    };
    let mut line = format!("✖ {} · workspace: {}", label, workspace.unwrap_or("(unknown)"));
    if files.is_empty() {
        line.push_str(" · files: (none this run)");
    } else {
        line.push_str(&format!(" · files: {}", files.len()));
    }
    if let Some(limit) = budget {
        if limit > 0 {
            line.push_str(&format!(" · budget: {}", crate::agent_interactive::format_thousands(limit as u64)));
        } else {
            line.push_str(" · budget: unlimited");
        }
    }
    if let Some(reason) = reason {
        line.push_str(&format!(" · reason: {}", reason));
    }
    if resumable.unwrap_or(false) {
        line.push_str(&format!(" · resume: agent run --resume {}", task_id));
    }
    Some(line)
}


async fn handle_agent_status(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required.".to_string());
    }

    let result = get_command_status(client, base_url, id).await?;

    // A null/absent payload means the backend has no record of this task id.
    let parsed = serde_json::from_str::<Value>(&result).ok();
    let is_null_payload = result.trim() == "null"
        || parsed.as_ref().map_or(false, |v| v.is_null());
    if is_null_payload {
        json_field("task_id", json!(id));
        json_field("error", json!(format!("No agent task found with id {}", id)));
        return Err(format!("No agent task found with id '{}'. Run `agent list` to see tracked tasks.", id));
    }

    // An unknown id is answered with a structured notFound envelope, which carries
    // the reason; report it instead of printing a bare `status: failed`.
    if let Some(reason) = parsed.as_ref().and_then(agent_envelope_not_found_reason) {
        json_field("task_id", json!(id));
        json_field("error", json!(reason));
        return Err(format!(
            "No agent task found with id '{}'. Run `agent list` to see tracked tasks.",
            id
        ));
    }

    cli_println!("{}", result);
    json_field("task_id", json!(id));
    json_field(
        "raw",
        json!(serde_json::from_str::<Value>(&result).unwrap_or(Value::String(result.clone()))),
    );

    // Sync the latest status back to the local task list so `agent list`
    // reflects accurate status without requiring a server round-trip.
    sync_agent_status_to_local(id, &result);

    Ok(())
}

/// Update the local task-tracking file with the latest server status for a task.
fn sync_agent_status_to_local(task_id: &str, status_json: &str) {
    // Same guards as `agent list` refresh: "null"/empty/404 answers and
    // terminal-state downgrades never touch the cache (P2.5).
    let mut list = read_async_tasks(None);
    let Some(entry) = list.tasks.iter_mut().find(|t| t.task_id == task_id) else {
        return;
    };
    let Some(fresh) = refreshed_agent_status(&entry.last_status, status_json) else {
        return;
    };
    entry.last_status = fresh;
    let _ = write_async_tasks(&list, None);
}

async fn handle_agent_result(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required.".to_string());
    }

    let result = get_command_result(client, base_url, id).await?;

    // A null/absent payload means the backend has no record of this task id.
    let trimmed_null_check = result.trim();
    let parsed_null_check = serde_json::from_str::<Value>(&result).ok();
    let is_null_payload = trimmed_null_check == "null"
        || trimmed_null_check == "\"null\""
        || parsed_null_check.as_ref().map_or(false, |v| v.is_null());
    if is_null_payload {
        json_field("task_id", json!(id));
        json_field("error", json!(format!("No agent task found with id {}", id)));
        return Err(format!("No agent task found with id '{}'. Run `agent list` to see tracked tasks.", id));
    }

    // An unknown id is answered with a structured notFound envelope — report it with
    // the reason the envelope carries instead of printing a bare `status: failed`.
    let parsed_payload = parsed_null_check.clone();
    if let Some(reason) = parsed_payload.as_ref().and_then(agent_envelope_not_found_reason) {
        json_field("task_id", json!(id));
        json_field("error", json!(reason));
        return Err(format!(
            "No agent task found with id '{}'. Run `agent list` to see tracked tasks.",
            id
        ));
    }

    // Detect an empty result: the agent completed successfully but the payload
    // carries no summary or data. Point at the fields that actually exist — the
    // previous hint named `instructResults`, which the backend stopped serializing,
    // so following it led nowhere (issue 112415#5).
    let trimmed = result.trim();
    let body_is_json_object = parsed_payload
        .as_ref()
        .map(|v| v.is_object())
        .unwrap_or(false);
    let payload = parsed_payload
        .as_ref()
        .and_then(|v| v.get("result"))
        .unwrap_or(&Value::Null);
    let payload_is_empty = match payload {
        Value::Object(map) => map.is_empty(),
        Value::Null => true,
        _ => false,
    };
    let nothing_to_show =
        trimmed.is_empty() || trimmed == "{}" || (body_is_json_object && payload_is_empty);
    if nothing_to_show && !json_active() {
        cli_println!("⚠️  The result carries no data.");
        cli_println!("The task may have completed successfully but produced no summary or");
        cli_println!("structured payload. Try:");
        cli_println!(
            "  agent status {}          (status, statusCode, message and error)",
            id
        );
        cli_println!("  agent status {} --json   (the same envelope as JSON)", id);
        cli_println!("If the agent wrote its deliverable to a file, `agent result` names the");
        cli_println!("task workspace it wrote into.");
    }

    cli_println!("{}", result);
    json_field("task_id", json!(id));
    json_field("raw", json!(&result));
    if !json_active() {
        print_agent_deliverables(payload);
        if let Some(verdict) = format_agent_result_verdict(id, parsed_payload.as_ref().unwrap_or(&Value::Null)) {
            cli_println!("");
            cli_println!("{}", verdict);
        }
    }

    // A failed/cancelled task is a failed command. `agent result` printed the
    // failure and exited 0, so a pipeline could not tell a completed run from an
    // aborted one (2026-10-28 baseline: `status=failed` with exit 0). The payload is
    // printed first — the reason is what the caller needs — then the exit is non-zero.
    // `--allow-failed` is the explicit escape hatch for "give me the failed payload".
    let allow_failed = tool_params
        .get("allowFailed")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let word = parsed_payload
        .as_ref()
        .and_then(agent_result_status_word)
        .unwrap_or_default();
    if !allow_failed && (word == "failed" || word == "cancelled") {
        let code = parsed_payload
            .as_ref()
            .and_then(|v| v.get("errorCode"))
            .and_then(|v| v.as_str())
            .map(|c| format!(" ({})", c))
            .unwrap_or_default();
        return Err(format!(
            "Agent task {} {}{}. The payload above carries the reason; pass --allow-failed to exit 0 anyway.",
            id, word, code
        ));
    }
    Ok(())
}

/// A tracked task's status is terminal once it completed, failed or was cancelled.
///
/// Used by `agent list --clear` to tell history apart from work that is still
/// live server-side, so it must agree with the shared envelope's terminal set
/// (`done`/`failed`/`cancelled`).
fn agent_task_status_is_terminal(status: &str) -> bool {
    state::is_terminal_async_status(status)
}

/// Local status for a tracked task the backend answered "no such id" for.
///
/// Distinct from a failure and from an empty (never-polled) status: the work may
/// well have finished long ago, but nothing can be polled for this id again, so
/// `--clear` may drop the row without pretending the task is still running.
const AGENT_STATUS_GONE: &str = "gone (not tracked by the backend)";

/// Whether a tracked task can be dropped by the default `agent list --clear`.
///
/// History (terminal) and rows the backend no longer knows about are droppable;
/// queued/processing and never-polled rows are kept because they may still be live.
fn agent_clear_drops_terminal(task: &state::AsyncTaskEntry) -> bool {
    agent_task_status_is_terminal(&task.last_status) || task.last_status == AGENT_STATUS_GONE
}

/// Whether `agent list --clear` should drop one tracked async task.
///
/// The default clear removes terminal (completed/failed) tasks only:
/// queued/processing and never-polled (empty status) tasks keep running
/// server-side, so untracking them would hide a live task the user can still
/// monitor. `--all` removes every agent task regardless of state.
fn agent_clear_drops_task(task: &state::AsyncTaskEntry, remove_all: bool) -> bool {
    if task.command != "agent" {
        return false;
    }
    if remove_all {
        return true;
    }
    // Drop history and rows the backend no longer knows about; keep work that is
    // still live.
    agent_clear_drops_terminal(task)
}

async fn handle_agent_list(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    // Support --clear to remove tracked agent tasks. By default only terminal
    // (completed/failed/cancelled) tasks are removed; queued/processing tasks stay so
    // they can still be monitored (they keep running server-side regardless).
    // --clear --all restores the old "remove everything" behavior and reports what it
    // detaches, with the status it actually observed.
    //
    // The branch refreshes from the server BEFORE deciding: it used to run first and
    // trust the cached label, so while the cache was stuck at "queued" (the shared
    // envelope was not being read) `--clear` cleared nothing while telling the user
    // the finished tasks were "still running server-side" (issues 112415#3/#7).
    let backend_reachable = client
        .head(base_url.to_string())
        .timeout(std::time::Duration::from_secs(3))
        .send()
        .await
        .is_ok();

    if tool_params
        .get("clear")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let remove_all = tool_params
            .get("all")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let mut list = read_async_tasks(None);

        if backend_reachable {
            for entry in &mut list.tasks {
                if entry.command != "agent" {
                    continue;
                }
                // A definite "the server has no record of this id" is not a reason to
                // keep the row: nothing can ever be polled for it again.
                match refresh_tracked_agent_task(client, base_url, entry).await {
                    AgentStatusRefresh::Gone => entry.last_status = AGENT_STATUS_GONE.to_string(),
                    _ => {}
                }
            }
        }

        let before = list.tasks.len();
        // What `--all` detaches, with the status observed for it: a task confirmed
        // running is named as such, a task we could not poll is marked unverified
        // rather than asserted to be alive.
        let detached: Vec<(String, String)> = if remove_all {
            list.tasks
                .iter()
                .filter(|t| t.command == "agent" && !agent_task_status_is_terminal(&t.last_status))
                .map(|t| {
                    let label = if t.last_status.is_empty() {
                        "unverified (never polled)".to_string()
                    } else {
                        t.last_status.clone()
                    };
                    (t.task_id.clone(), label)
                })
                .collect()
        } else {
            Vec::new()
        };
        // `retain` keeps what its predicate accepts, so the predicate is the
        // inverse of "drop": non-agent tasks always stay, and the default
        // (non-`--all`) clear keeps queued/processing and never-polled
        // (empty last_status) entries.
        list.tasks.retain(|t| !agent_clear_drops_task(t, remove_all));
        let removed = before - list.tasks.len();
        let kept = list.tasks.iter().filter(|t| t.command == "agent").count();
        write_async_tasks(&list, None).map_err(|e| e.to_string())?;
        cli_println!("Cleared {} tracked agent task(s).", removed);
        if !remove_all && kept > 0 {
            let live = list
                .tasks
                .iter()
                .filter(|t| t.command == "agent")
                .filter(|t| !t.last_status.is_empty())
                .count();
            cli_println!(
                "Kept {} agent task(s) that are not finished ({}, re-run with --all to remove them from tracking too).",
                kept,
                if backend_reachable {
                    format!("{live} with a verified non-terminal status")
                } else {
                    "backend unreachable — statuses are cached, not verified".to_string()
                }
            );
        }
        if remove_all && !detached.is_empty() {
            eprintln!(
                "Warning: {} unfinished task(s) were removed from tracking (their server-side work is unchanged):",
                detached.len()
            );
            for (id, label) in detached.iter().take(10) {
                eprintln!("  {}  {}", id, label);
            }
            if detached.len() > 10 {
                eprintln!("  ... and {} more", detached.len() - 10);
            }
        }
        json_field("cleared", json!(removed));
        json_field("kept", json!(if remove_all { 0 } else { kept }));
        return Ok(());
    }

    let mut list = read_async_tasks(None);

    if backend_reachable {
        // Refresh status for agent tasks from the server so the display is consistent
        // with `agent status`. Tasks that fail to query keep their cached last_status.
        for entry in &mut list.tasks {
            if entry.command != "agent" {
                continue;
            }
            let _ = refresh_tracked_agent_task(client, base_url, entry).await;
        }
        let _ = write_async_tasks(&list, None);
    } else {
        cli_println!("Note: Backend unreachable — showing cached statuses. Run `agent run <task>` or `open <url>` to auto-start the backend for live status.");
    }

    let filtered: Vec<_> = list
        .tasks
        .iter()
        .filter(|t| t.command == "agent")
        .cloned()
        .collect();
    if !filtered.is_empty() {
        cli_println!("{}", summarize_async_tasks(&filtered));
    }

    let limit = tool_params
        .get("limit")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);
    let offset = tool_params
        .get("offset")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);
    let display = state::AsyncTaskList { tasks: filtered };
    // include_count=false: the Status summary above already states the total,
    // so the table header must not print a second count (it shows pagination only).
    cli_println!("{}", state::format_async_task_list_opts(&display, limit, offset, false));
    Ok(())
}

/// `agent cancel <id>` — cancel a running/queued agent task on the server.
///
/// Calls `POST /api/commands/{id}/cancel`; the backend interrupts the agent
/// loop and marks the task failed with reason "Task cancelled".
async fn handle_agent_cancel(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| "Task ID is required (e.g. `agent cancel <task-id>`).".to_string())?;

    let url = format!("{}/api/commands/{}/cancel", base_url.trim_end_matches('/'), id);
    let response = client
        .post(&url)
        .timeout(std::time::Duration::from_secs(30))
        .send()
        .await
        .map_err(|e| format!("Failed to cancel agent task: {e}"))?;

    let status = response.status();
    let text = response
        .text()
        .await
        .map_err(|e| format!("Failed to read cancel response: {e}"))?;

    if !status.is_success() {
        return Err(format!("Failed to cancel agent task (HTTP {}): {}", status.as_u16(), text));
    }

    let parsed: Value = serde_json::from_str(&text).unwrap_or(Value::Null);
    let cancelled = parsed.get("cancelled").and_then(|v| v.as_bool()).unwrap_or(false);
    if cancelled {
        cli_println!("✅ Agent task {} cancelled.", id);
        json_field("cancelled", json!(true));
    } else {
        let message = parsed
            .get("message")
            .and_then(|v| v.as_str())
            .unwrap_or("task not running or unknown");
        cli_println!("⚠ Agent task {} not cancelled: {}", id, message);
        json_field("cancelled", json!(false));
    }
    json_field("task_id", json!(id));
    Ok(())
}

/// Parse `statusCode` from a JSON value, handling both integer and string forms.
///
/// The Kotlin backend serializes `statusCode` as an integer (e.g. `200`, `102`),
/// but some test fixtures or older server versions may emit it as a string.
fn parse_status_code_from_json(value: &Value) -> String {
    value
        .get("statusCode")
        .and_then(|v| {
            v.as_str()
                .map(|s| s.to_string())
                .or_else(|| v.as_i64().map(|i| i.to_string()))
        })
        .unwrap_or_default()
}

/// Extract a human-readable status string from the server's `command_status`
/// JSON response.
///
/// Uses the same lifecycle vocabulary as [`friendly_agent_status`] so that
/// status strings written into the local task-tracking file are consistent
/// with the labels shown in `agent list`.
///
/// Currently referenced only by unit tests (the production call site was
/// removed); kept under `#[cfg(test)]` so the release binary has no dead code.
#[cfg(test)]
fn extract_readable_agent_status(status: &Value) -> String {
    let process_state = status
        .get("processState")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let is_done = status
        .get("isDone")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let status_code = parse_status_code_from_json(status);

    if !process_state.is_empty() || is_done {
        return friendly_agent_status(process_state, is_done, &status_code);
    }

    // Fall back to top-level status field
    if let Some(s) = status.get("status").and_then(|v| v.as_str()) {
        if !s.is_empty() {
            return s.to_lowercase();
        }
    }

    "queued".to_string()
}

// ---------------------------------------------------------------------------
// Swarm command handlers
// ---------------------------------------------------------------------------

/// Effective defaults for `swarm create` when the option is omitted.
///
/// These mirror the values documented in `--help swarm create`
/// (`--max-open-tabs` default 8, `--max-browser-contexts` default 2): the echo
/// line must report what was actually applied, not the word "default".
const SWARM_DEFAULT_MAX_OPEN_TABS: &str = "8";
const SWARM_DEFAULT_MAX_BROWSER_CONTEXTS: &str = "2";

/// One-line report of the terminal swarm tasks `swarm create` auto-cleaned.
///
/// The non-interactive path prunes completed/failed tasks from prior sessions
/// without asking, so the message must name them — otherwise a script cannot
/// tell "nothing was tracked" from "your history was pruned".
fn auto_cleaned_swarm_tasks_message(pruned: &[state::AsyncTaskEntry]) -> String {
    let ids: Vec<&str> = pruned.iter().map(|t| t.task_id.as_str()).collect();
    format!(
        "Auto-cleaned {} completed swarm task(s) from prior sessions (non-interactive auto-clean; \
         use `swarm list` before `swarm create` if you need to keep them): {}",
        ids.len(),
        ids.join(", ")
    )
}

async fn handle_swarm_create(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
    session_name: Option<&str>,
) -> Result<(), String> {
    let capabilities = build_swarm_create_capabilities(tool_params)?;
    // Keep a copy for echoing the effective configuration after creation —
    // build_open_session_request consumes the value.
    let echo_capabilities = capabilities.clone();
    let open_args = build_open_session_request(Some(capabilities), Some(SWARM_SESSION_ID));

    let result = call_tool(client, base_url, "open_session", open_args).await?;

    // Parse session ID from response
    let session_id = if let Ok(parsed) = serde_json::from_str::<Value>(&result) {
        parsed
            .get("sessionId")
            .and_then(|v| v.as_str())
            .unwrap_or(SWARM_SESSION_ID)
            .to_string()
    } else {
        let trimmed = result.trim();
        if trimmed.is_empty() {
            SWARM_SESSION_ID.to_string()
        } else {
            trimmed.trim_matches('"').to_string()
        }
    };

    if session_id != SWARM_SESSION_ID {
        return Err(format!(
            "Swarm create must use the fixed session ID '{}', but Browser4 returned '{}'.",
            SWARM_SESSION_ID, session_id
        ));
    };

    // The swarm session lives in its own named slot ("SWARM") so it never
    // overwrites the default interactive-browser session.  If the user
    // provided `-s <name>` we honour that; otherwise we use "SWARM".
    let effective_name = session_name.or(Some("SWARM"));

    let mut state = read_state(None, effective_name);
    state.session_name = effective_name.map(|s| s.to_string());
    state.session_id = Some(session_id.clone());
    state.base_url = base_url.to_string();
    state.created_at = Some(Utc::now().to_rfc3339());
    state.last_accessed_at = Some(Utc::now().to_rfc3339());
    write_state(&state, None, effective_name).map_err(|e| e.to_string())?;

    // Check for stale swarm tasks from prior sessions.
    // Old tasks in the task store can block the worker pool from picking up
    // new tasks, causing jobs to stay "Created" indefinitely.
    let clear_stale = tool_params
        .get("clearStale")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let mut existing = read_async_tasks(None);
    // The session was just created, so the backend is reachable — refresh the
    // local statuses first so a task the previous swarm actually completed is
    // not mistaken for a stale pending task.
    let _ = refresh_tracked_swarm_statuses(client, base_url, &mut existing).await;

    // Terminal tasks (completed / failed) from prior sessions are pure
    // history — prune them automatically so `swarm create` stops warning
    // about sessions that already finished.  Only still-pending tasks can
    // block a new session, and the warnings below are reserved for those.
    let is_swarm_task = |t: &state::AsyncTaskEntry| {
        t.command == "swarm-submit" || t.command == "swarm-query"
    };
    let is_terminal = |t: &state::AsyncTaskEntry| {
        t.last_status == "completed" || t.last_status.starts_with("failed")
    };
    let pruned: Vec<state::AsyncTaskEntry> = existing
        .tasks
        .iter()
        .filter(|t| is_swarm_task(t) && is_terminal(t))
        .cloned()
        .collect();
    if !pruned.is_empty() {
        existing
            .tasks
            .retain(|t| !(is_swarm_task(t) && is_terminal(t)));
        let _ = write_async_tasks(&existing, None);
        // Name the tasks that were removed: a script that relies on retained
        // tracking must be able to see (and re-submit) what was cleaned.  The
        // non-TTY path auto-cleans without asking, so silence here is
        // indistinguishable from "nothing was tracked".
        cli_println!("{}", auto_cleaned_swarm_tasks_message(&pruned));
        json_field("auto_cleaned_tasks", json!(pruned.len()));
        json_field(
            "auto_cleaned_task_ids",
            json!(pruned.iter().map(|t| t.task_id.as_str()).collect::<Vec<_>>()),
        );
    }

    let swarm_tasks: Vec<_> = existing
        .tasks
        .iter()
        .filter(|t| is_swarm_task(t))
        .collect();
    if !swarm_tasks.is_empty() {
        if clear_stale {
            // User opted in: clear stale tasks automatically.
            let before = existing.tasks.len();
            existing
                .tasks
                .retain(|t| !is_swarm_task(t));
            let removed = before - existing.tasks.len();
            write_async_tasks(&existing, None).map_err(|e| e.to_string())?;
            cli_println!("Cleared {} stale swarm task(s) from prior sessions.", removed);
            json_field("cleared_stale_tasks", json!(removed));
        } else {
            // Only genuinely pending tasks remain here — they may belong to a
            // session that was aborted mid-flight, and they can block the new
            // session's worker pool.
            // Offer an interactive prompt to clear stale tasks,
            // eliminating the multi-step "abort, clear, recreate" flow.
            let is_interactive = std::io::stdin().is_terminal();
            if is_interactive {
                eprintln!();
                eprintln!("╔══════════════════════════════════════════════════════════╗");
                eprintln!("║ ⚠ {} pending swarm task(s) from a prior session remain.    ║", swarm_tasks.len());
                eprintln!("║ Stale tasks can block the worker pool, causing new jobs    ║");
                eprintln!("║ to stay \"Created\" indefinitely.                           ║");
                eprintln!("╚══════════════════════════════════════════════════════════╝");
                eprintln!();
                eprintln!("Clear them now? [Y/n]");

                let mut input = String::new();
                match std::io::stdin().read_line(&mut input) {
                    Ok(_) => {
                        let trimmed = input.trim().to_lowercase();
                        if trimmed.is_empty() || trimmed == "y" || trimmed == "yes" {
                            let before = existing.tasks.len();
                            existing
                                .tasks
                                .retain(|t| !is_swarm_task(t));
                            let removed = before - existing.tasks.len();
                            write_async_tasks(&existing, None).map_err(|e| e.to_string())?;
                            cli_println!("Cleared {} stale swarm task(s).", removed);
                            json_field("cleared_stale_tasks", json!(removed));
                        } else {
                            cli_println!(
                                "Keeping {} pending task(s). Use `swarm list --clear` to remove later, or `swarm create --clear-stale` next time.",
                                swarm_tasks.len()
                            );
                            json_field("stale_swarm_tasks", json!(swarm_tasks.len()));
                        }
                    }
                    Err(_) => {
                        // Can't read stdin — keep tasks and show guidance.
                        cli_println!(
                            "Note: {} pending swarm task(s) from a prior session are still tracked.",
                            swarm_tasks.len()
                        );
                        cli_println!(
                            "  Run `swarm list --clear` to remove stale entries, or `swarm create --clear-stale` to clear and recreate in one step."
                        );
                        json_field("stale_swarm_tasks", json!(swarm_tasks.len()));
                    }
                }
            } else {
                // Non-interactive (pipe, CI, script): show a prominent warning.
                eprintln!();
                eprintln!("⚠ {} pending swarm task(s) from a prior session are still tracked.",
                    swarm_tasks.len()
                );
                eprintln!("  If new jobs get stuck in \"Created\" status, run `swarm list --clear` to remove stale entries,");
                eprintln!("  then recreate the swarm session before resubmitting.");
                eprintln!(
                    "  Or use `swarm create --clear-stale` to clear and recreate in one step."
                );
                json_field("stale_swarm_tasks", json!(swarm_tasks.len()));
            }
        }
    }

    // Echo the effective session configuration so users can confirm their
    // tuning flags were honored (and spot an accidental GUI session before
    // windows pop up).  Omitted options are resolved to the documented
    // effective defaults rather than printed as "default", which left the user
    // guessing what was actually applied.
    let cap_str = |key: &str, default: &str| -> String {
        echo_capabilities
            .get(key)
            .and_then(|v| v.as_str())
            .filter(|s| !s.is_empty())
            .unwrap_or(default)
            .to_string()
    };
    cli_println!(
        "Swarm session created: {} (display={}, contexts={}, max-tabs={})",
        session_id,
        cap_str("displayMode", "HEADLESS"),
        cap_str("maxBrowserContexts", SWARM_DEFAULT_MAX_BROWSER_CONTEXTS),
        cap_str("maxOpenTabs", SWARM_DEFAULT_MAX_OPEN_TABS)
    );
    // A pinned profile reuses one Chrome user-data directory, and a directory can only be
    // used by one browser process at a time — the backend forces a single browser context.
    // Say so, otherwise the "contexts=2" echoed above reads as if the pin had no effect.
    if let Some(src) = echo_capabilities
        .get("profileSession")
        .and_then(|v| v.as_str())
        .map(|s| format!("session '{s}'"))
        .or_else(|| {
            echo_capabilities
                .get("profilePath")
                .and_then(|v| v.as_str())
                .map(|s| format!("profile '{s}'"))
        })
    {
        cli_println!("  Profile: pinned to {src} — one browser context (a user-data dir is single-owner)");
    }
    // Cold-start cue: browser contexts boot lazily after create returns, so
    // first submissions sit "queued" for up to ~60s on a fresh session.  Say
    // so up front — the documented >30s stall heuristic must not lead users
    // to tear down a healthy session during warm-up.
    cli_println!(
        "  Note: browser contexts are starting in the background (~30-60s on a fresh session) — \
         jobs submitted now stay queued until the first context is ready."
    );
    Ok(())
}

/// Mark locally tracked pending swarm tasks as "failed (closed)".
///
/// Pending tasks (never polled, queued, or processing) can never complete
/// after their swarm session closes — the backend drops them, so the local
/// tracking must reflect that instead of showing them "queued" forever.
/// Completed/failed tasks are left untouched.
///
/// Returns the number of tasks marked.
fn mark_local_swarm_tasks_closed(list: &mut state::AsyncTaskList) -> usize {
    let mut marked = 0usize;
    for t in list
        .tasks
        .iter_mut()
        .filter(|t| t.command == "swarm-submit" || t.command == "swarm-query")
    {
        let is_pending = t.last_status.is_empty()
            || t.last_status == "queued"
            || t.last_status == "processing"
            || t.last_status == "pending";
        if is_pending {
            t.last_status = "failed (closed)".to_string();
            marked += 1;
        }
    }
    marked
}

async fn handle_swarm_close(
    client: &Client,
    base_url: &str,
    session_name: Option<&str>,
) -> Result<(), String> {
    // Default to the "SWARM" named session so we match the slot used by
    // handle_swarm_create when no explicit `-s` was provided.
    let effective_name = session_name.or(Some("SWARM"));
    let state = read_state(None, effective_name);
    let Some(session_id) = get_session_id_for_close(&state).map(str::to_string) else {
        clear_state(None, effective_name);
        eprintln!("{}", no_active_session_message());
        json_field("session_id", json!(null));
        json_field("closed", json!(false));
        return Ok(());
    };
    json_field("session_id", json!(&session_id));

    // Ask the backend to abort pending swarm tasks BEFORE closing the session,
    // so they don't stay "queued" forever and leak across sessions. Best-effort:
    // older backends without the DELETE /api/swarm endpoint (or an unreachable
    // backend) must not break the close itself.
    let mut aborted_pending: Option<i64> = None;
    match close_swarm_session(client, base_url).await {
        Ok(payload) => {
            if let Ok(parsed) = serde_json::from_str::<Value>(&payload) {
                aborted_pending = parsed.get("abortedPendingTasks").and_then(|v| v.as_i64());
            }
        }
        Err(e) => {
            eprintln!("Note: could not clean up pending swarm tasks on the backend: {e}");
        }
    }

    // Count tracked swarm tasks before closing (for the summary).  The local
    // tracker can lag the backend — a job the swarm already completed may
    // still be recorded as "queued"/"processing" if it was never polled via
    // `swarm list` — so refresh statuses from the backend first.  Closing must
    // not report completed work as failed.
    let mut list = read_async_tasks(None);
    refresh_tracked_swarm_statuses(client, base_url, &mut list).await;
    let swarm_task_count = list
        .tasks
        .iter()
        .filter(|t| t.command == "swarm-submit" || t.command == "swarm-query")
        .count();
    let completed_count = list
        .tasks
        .iter()
        .filter(|t| {
            (t.command == "swarm-submit" || t.command == "swarm-query")
                && t.last_status == "completed"
        })
        .count();

    // Mark the remaining locally tracked pending tasks as failed (closed) so
    // `swarm list` reflects the cleanup even when the backend was unreachable.
    // Completed tasks are never marked.
    let locally_closed = mark_local_swarm_tasks_closed(&mut list);
    let _ = write_async_tasks(&list, None);

    // Close the swarm session — ignore errors if already closed.
    let _ = call_tool(
        client,
        base_url,
        "close_session",
        json!({ "sessionId": session_id }),
    )
    .await;
    clear_state(None, effective_name);

    json_field("closed", json!(true));
    json_field("aborted_pending_tasks", json!(aborted_pending.unwrap_or(0)));
    if swarm_task_count > 0 {
        // Word the summary by the tasks' actual state.  The local tracker can
        // lag the backend (a job that completed may still be recorded as
        // queued locally), so statuses are refreshed above BEFORE any marking.
        // The summary builder must therefore never claim that completed work
        // was failed, and must never pair "all pending tasks were already
        // finished" with locally marking tasks as failed.
        cli_println!("{}", swarm_close_summary(swarm_task_count, completed_count, locally_closed, aborted_pending));
        json_field("tracked_tasks_retained", json!(swarm_task_count));
        json_field("tracked_tasks_completed", json!(completed_count));
    } else {
        cli_println!("Swarm session closed. Browser terminated.");
    }
    Ok(())
}

/// Build the human-readable `swarm close` summary line from the reconciled
/// counts:
/// - `swarm_task_count` — tracked swarm tasks (submit/query) at close time;
/// - `completed_count` — those the backend confirmed completed (refreshed
///   before closing — the local tracker alone can lag the backend);
/// - `locally_closed` — tasks still recorded as queued/processing/pending at
///   close time, now marked "failed (closed)" (the session close kills them);
/// - `aborted_pending` — how many pending tasks the backend reports it
///   aborted (None when the backend was unreachable or returned no payload).
fn swarm_close_summary(
    swarm_task_count: usize,
    completed_count: usize,
    locally_closed: usize,
    aborted_pending: Option<i64>,
) -> String {
    // A backend note is only added when it adds information: an abort count,
    // or — only when nothing was marked locally and not everything completed —
    // the "all pending were already finished" reassurance.  Pairing that
    // sentence with locally marking tasks as failed was the self-contradictory
    // message that made completed jobs look failed.
    let backend_note = match aborted_pending {
        Some(n) if n > 0 => format!(" {n} pending task(s) aborted on the backend."),
        Some(_) if locally_closed == 0 && completed_count < swarm_task_count => {
            " All pending tasks were already finished.".to_string()
        }
        _ => String::new(),
    };
    if locally_closed > 0 && completed_count > 0 {
        format!(
            "Swarm session closed. Browser terminated.{backend_note} {completed_count} completed task(s) retained for history; {locally_closed} task(s) still queued/processing at close time marked as failed (closed)."
        )
    } else if locally_closed > 0 {
        format!(
            "Swarm session closed. Browser terminated.{backend_note} {locally_closed} task(s) still queued/processing at close time marked as failed (closed)."
        )
    } else if completed_count == swarm_task_count {
        format!(
            "Swarm session closed. Browser terminated. All {completed_count} tracked task(s) had already completed — results retained; use `swarm list --clear` to remove."
        )
    } else {
        format!(
            "Swarm session closed. Browser terminated.{backend_note} {swarm_task_count} tracked task(s) retained for history. Use `swarm list --clear` to remove."
        )
    }
}

async fn handle_swarm_submit(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<usize, String> {
    // Every invocation gets one batch id; all of its tasks carry it so the batch
    // can be tracked as a unit (`swarm list --batch <id>`).
    let batch_id = resolve_batch_id(tool_params);
    let url = tool_params
        .get("url")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let seed_file = tool_params.get("seedFile").and_then(|v| v.as_str());
    let query_raw = tool_params.get("sql").and_then(|v| v.as_str());

    if url.is_empty() && seed_file.is_none() {
        return Err("A URL or --seed-file is required.".to_string());
    }

    // Read query from file if prefixed with @
    let query = match query_raw {
        Some(q) if q.starts_with('@') => {
            let file_path = &q[1..];
            Some(resolve_sql_file(file_path)?)
        }
        Some(q) => Some(q.to_string()),
        None => None,
    };

    // Collect URLs to submit
    let mut urls: Vec<String> = Vec::new();
    if !url.is_empty() {
        urls.push(url.to_string());
    }
    if let Some(file_path) = seed_file {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read seed file '{}': {}", file_path, describe_io_error(&e)))?;
        for line in content.lines() {
            let line = line.trim();
            if !line.is_empty() && !line.starts_with('#') {
                urls.push(line.to_string());
            }
        }
    }

    if urls.is_empty() {
        return Err("No URLs to submit.".to_string());
    }

    // Build load options string from flags
    let mut load_opts = Vec::new();
    if let Some(v) = tool_params.get("deadline").and_then(|v| v.as_str()) {
        load_opts.push(format!("-deadline {}", v));
    }
    if let Some(v) = tool_params.get("expires").and_then(|v| v.as_str()) {
        load_opts.push(format!("-expires {}", v));
    }
    if tool_params
        .get("refresh")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        load_opts.push("-refresh".to_string());
    }
    if tool_params
        .get("parse")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        load_opts.push("-parse".to_string());
    }
    // Free-form LoadOptions last, so an explicit user option wins over a
    // convenience flag expanded above.
    if let Some(v) = tool_params.get("loadOptions").and_then(|v| v.as_str()) {
        let v = v.trim();
        if !v.is_empty() {
            warn_on_hash_in_load_options(v);
            load_opts.push(v.to_string());
        }
    }
    let opts_str = load_opts.join(" ");

    // Submit each URL through the appropriate REST API.
    let mut json_submissions: Vec<serde_json::Value> = Vec::new();
    for u in &urls {
        let (result, method) = if let Some(ref q) = query {
            // X-SQL query mode: send structured JSON to /api/swarm/query
            let payload = json!({
                "url": u,
                "args": opts_str,
                "query": q,
            });
            (
                submit_swarm_query(client, base_url, payload, Some(&batch_id)).await?,
                "query",
            )
        } else {
            // Plain scrape mode: send URL with options to /api/swarm/submit
            let command = if opts_str.is_empty() {
                u.clone()
            } else {
                format!("{} {}", u, opts_str)
            };
            (
                submit_swarm_payload(client, base_url, &command, Some(&batch_id)).await?,
                "submit",
            )
        };

        let task_id = result.trim().trim_matches('"').to_string();
        cli_println!(
            "Task Submitted: {} -> Task ID: {} (via {})",
            u,
            task_id,
            method
        );
        json_submissions.push(json!({
            "url": u,
            "task_id": task_id,
            "batch_id": batch_id,
        }));

        // Persist each task for cross-session tracking, tagged with its batch
        let _ = track_async_task_in_batch(&task_id, "swarm-submit", u, Some(&batch_id), None);
    }
    json_field("submissions", json!(json_submissions));

    // The batch id is how a caller refers to this submission as a whole
    // afterwards (`swarm list --batch <id>`, `GET /api/swarm/batch/<id>`).
    cli_println!(
        "Batch ID: {} — track it with 'swarm list --batch {}'",
        batch_id, batch_id
    );
    json_field("batch_id", json!(batch_id));

    if urls.len() > 1 {
        cli_println!(
            "{} URL(s) submitted. Use 'browser4-cli swarm list' to view all tracked tasks.",
            urls.len()
        );
    }

    // Support --wait: poll until all submitted jobs complete
    let mut unsuccessful = 0usize;
    if tool_params
        .get("wait")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let task_ids: Vec<String> = json_submissions
            .iter()
            .filter_map(|s| {
                s.get("task_id")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
            })
            .collect();
        if !task_ids.is_empty() {
            unsuccessful = swarm_wait_for_jobs(client, base_url, &task_ids, Some(&batch_id)).await?;
        }
    }

    Ok(unsuccessful)
}

async fn handle_swarm_query(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<usize, String> {
    // One batch id per invocation, stamped on every task it submits.
    let batch_id = resolve_batch_id(tool_params);
    let url = tool_params
        .get("url")
        .and_then(|v| v.as_str())
        .unwrap_or("");
    let seed_file = tool_params.get("seedFile").and_then(|v| v.as_str());

    // Handle --sql-stdin: read query from stdin (avoids shell quoting issues on Windows)
    let use_sql_stdin = tool_params
        .get("sqlStdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let query_raw: Option<String> = if use_sql_stdin {
        let mut input = String::new();
        std::io::stdin()
            .read_to_string(&mut input)
            .map_err(|e| format!("Failed to read X-SQL query from stdin: {e}"))?;
        if input.trim().is_empty() {
            return Err("Stdin was empty. Provide a non-empty X-SQL query via stdin.".to_string());
        }
        Some(input)
    } else {
        tool_params
            .get("sql")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
    };

    if url.is_empty() && seed_file.is_none() {
        return Err("A URL or --seed-file is required.".to_string());
    }
    // Allow --sql-base64 standalone (without --sql): the base64 value is decoded
    // later by maybe_decode_base64_sql. If sqlBase64 has a non-empty string value,
    // we can proceed with an empty query_raw; the decode will supply the actual SQL.
    let has_sql_base64_value = tool_params
        .get("sqlBase64")
        .and_then(|v| v.as_str())
        .map(|s| !s.trim().is_empty())
        .unwrap_or(false);

    if query_raw.as_ref().map_or(true, |q| q.is_empty()) && !has_sql_base64_value {
        return Err(
            "--sql is required. Provide an inline X-SQL query, @file.sql, --sql-stdin, or --sql-base64."
                .to_string(),
        );
    }

    // Read query from file if prefixed with @
    let query = match &query_raw {
        Some(q) if q.starts_with('@') => {
            let file_path = &q[1..];
            Some(resolve_sql_file(file_path)?)
        }
        Some(q) => Some(q.clone()),
        None if has_sql_base64_value => Some(String::new()),
        None => None,
    };

    // Handle --sql-base64: decode base64-encoded SQL
    let query = query
        .map(|q| maybe_decode_base64_sql(q, tool_params))
        .transpose()?;

    // Collect URLs to query
    let mut urls: Vec<String> = Vec::new();
    if !url.is_empty() {
        urls.push(url.to_string());
    }
    if let Some(file_path) = seed_file {
        let content = std::fs::read_to_string(file_path)
            .map_err(|e| format!("Failed to read seed file '{}': {}", file_path, describe_io_error(&e)))?;
        for line in content.lines() {
            let line = line.trim();
            if !line.is_empty() && !line.starts_with('#') {
                urls.push(line.to_string());
            }
        }
    }

    if urls.is_empty() {
        return Err("No URLs to query.".to_string());
    }

    // Build load options string from flags
    let mut load_opts = Vec::new();
    if let Some(v) = tool_params.get("deadline").and_then(|v| v.as_str()) {
        load_opts.push(format!("-deadline {}", v));
    }
    if let Some(v) = tool_params.get("expires").and_then(|v| v.as_str()) {
        load_opts.push(format!("-expires {}", v));
    }
    if tool_params
        .get("refresh")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        load_opts.push("-refresh".to_string());
    }
    // Free-form LoadOptions last, so an explicit user option wins over a
    // convenience flag expanded above.
    if let Some(v) = tool_params.get("loadOptions").and_then(|v| v.as_str()) {
        let v = v.trim();
        if !v.is_empty() {
            warn_on_hash_in_load_options(v);
            load_opts.push(v.to_string());
        }
    }
    let opts_str = load_opts.join(" ");

    // Submit each URL via /api/swarm/query
    let mut json_submissions: Vec<serde_json::Value> = Vec::new();
    let q = query.expect("query was validated above");
    for u in &urls {
        let payload = json!({
            "url": u,
            "args": opts_str,
            "query": q,
        });
        let result = submit_swarm_query(client, base_url, payload, Some(&batch_id)).await?;
        let task_id = result.trim().trim_matches('"').to_string();
        cli_println!("Query Submitted: {} -> Task ID: {}", u, task_id);
        json_submissions.push(json!({
            "url": u,
            "task_id": task_id,
        }));

        // Persist each task for cross-session tracking (so they appear in swarm list)
        let _ = track_async_task_in_batch(&task_id, "swarm-query", u, Some(&batch_id), None);
    }
    json_field("submissions", json!(json_submissions));
    cli_println!(
        "Batch ID: {} — track it with 'swarm list --batch {}'",
        batch_id, batch_id
    );
    json_field("batch_id", json!(batch_id));

    if urls.len() > 1 {
        cli_println!(
            "{} URL(s) queried. Use 'browser4-cli swarm list' to view all tracked tasks.",
            urls.len()
        );
    }

    // Support --wait: poll until all submitted jobs complete
    let mut unsuccessful = 0usize;
    if tool_params
        .get("wait")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let task_ids: Vec<String> = json_submissions
            .iter()
            .filter_map(|s| {
                s.get("task_id")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string())
            })
            .collect();
        if !task_ids.is_empty() {
            unsuccessful = swarm_wait_for_jobs(client, base_url, &task_ids, Some(&batch_id)).await?;
        }
    } else {
        // Without --wait, jobs are submitted asynchronously. The user needs
        // a way to track progress — otherwise submitted-but-not-monitored
        // jobs look like they're hung.
        cli_println!(
            "\n💡 Tip: Add --wait to track progress and see results automatically.\n\
               Without --wait, use these commands to monitor:\n  \
               swarm status <task-id>  — check if a job is done\n  \
               swarm result <task-id>  — get the result when complete\n  \
               swarm list             — see all tracked tasks"
        );
        cli_println!(
            "   If jobs appear stuck, run `swarm list` to check their status,\n\
               or `swarm list --clear` to remove stale entries from prior sessions."
        );
    }

    Ok(unsuccessful)
}

/// Map backend swarm status codes to user-friendly lifecycle labels.
/// The raw `status` field from the backend reflects HTTP status names
/// (e.g. "Created" for 201, "OK" for 200), which can confuse users.
/// This maps them to task-oriented labels.
fn friendly_swarm_status(status_code: i64, status_text: &str) -> String {
    match status_code {
        201 => "queued".to_string(),    // SC_CREATED — task waiting for a worker
        200 => "completed".to_string(), // SC_OK — task finished successfully
        202 => "processing".to_string(), // SC_ACCEPTED — task is being processed
        _ => {
            // Use the raw status text for other codes, but lowercase it
            // for a more task-oriented feel
            let lower = status_text.to_lowercase();
            if status_code >= 400 {
                format!("failed ({})", lower)
            } else {
                lower
            }
        }
    }
}

/// Map agent `processState` values to user-friendly lifecycle labels,
/// using the same vocabulary as swarm: queued, processing, completed, failed.
fn friendly_agent_status(process_state: &str, is_done: bool, status_code: &str) -> String {
    if is_done || process_state == "done" {
        if status_code == "SC_OK" || status_code == "200" || status_code.is_empty() {
            "completed".to_string()
        } else {
            format!("failed ({})", status_code.to_lowercase())
        }
    } else if process_state == "created" {
        "queued".to_string()
    } else if process_state == "in_progress" {
        "processing".to_string()
    } else if process_state.is_empty() {
        "queued".to_string() // no processState yet → just submitted
    } else {
        process_state.to_lowercase()
    }
}

/// The status words of the shared async-task envelope (`TaskEnvelopes.STATUSES`).
///
/// Every long-running domain (agent, crawl, swarm, command) answers its status tool
/// with this one shape, so the CLI has a single vocabulary to consume.
const SHARED_TASK_STATUSES: [&str; 5] = ["queued", "running", "done", "failed", "cancelled"];

/// Whether a shared-envelope status word means "stop polling".
fn is_terminal_shared_status(word: &str) -> bool {
    matches!(word, "done" | "failed" | "cancelled")
}

/// The shared envelope's `status` word, lowercased; empty when the payload carries
/// no word from the shared vocabulary.
///
/// Case-insensitive because older backends emitted `RUNNING`/`COMPLETED` in the same
/// field, and an unknown word deliberately yields `""` so the caller falls back to
/// the legacy fields instead of guessing.
fn envelope_status_word(parsed: &Value) -> String {
    parsed
        .get("status")
        .and_then(|v| v.as_str())
        .map(|s| s.trim().to_ascii_lowercase())
        .filter(|s| SHARED_TASK_STATUSES.contains(&s.as_str()))
        .unwrap_or_default()
}

/// The short label inside `failed (…)`: the status code when the backend sent one,
/// else the first line of the envelope's `error`, else a generic marker.
fn failure_label(status_code: &str, error: Option<&str>) -> String {
    if !status_code.is_empty() {
        return status_code.to_lowercase();
    }
    error
        .map(str::trim)
        .filter(|e| !e.is_empty())
        .and_then(|e| e.lines().next())
        .map(|line| line.chars().take(60).collect::<String>())
        .unwrap_or_else(|| "error".to_string())
}

/// Map the shared task envelope onto the CLI's lifecycle vocabulary.
///
/// The backend migrated every long-running tool to one envelope —
/// `{taskId, status, statusCode, message, error, …}` with
/// `queued|running|done|failed|cancelled` — while the CLI's lifecycle consumers kept
/// reading the legacy `processState`/`isDone`/`statusCode`/`finishTime` fields. No
/// agent task could therefore ever reach a terminal cached state: `agent list`
/// reported finished work as "queued" forever, `--clear` cleared nothing and
/// `--wait` burned its whole timeout (issues 112415#1/#2/#3/#4, 111443#1/#3).
///
/// Returns `None` for a word outside the vocabulary so a caller keeps its cache
/// rather than inventing a status.
fn friendly_envelope_status(word: &str, status_code: &str, error: Option<&str>) -> Option<String> {
    match word {
        "queued" => Some("queued".to_string()),
        "running" => Some("processing".to_string()),
        "done" => Some("completed".to_string()),
        "cancelled" => Some("cancelled".to_string()),
        "failed" => Some(format!("failed ({})", failure_label(status_code, error))),
        _ => None,
    }
}

/// What one `command_status` poll says about a locally tracked agent task.
///
/// The three cases must stay apart: `agent list` keeps its cache unless the answer
/// is usable (P2.5 — a restarted backend answering "null" used to poison terminal
/// statuses), while `--clear` needs to know that the server answered *and* has no
/// record of the id, because "your local row cannot be monitored any more" is not
/// "your task is still running server-side".
enum AgentStatusRefresh {
    /// The server answered with a usable status; the cache takes it.
    Fresh(String),
    /// The server answered, but has no record of the id (404 / not found).
    Gone,
    /// No usable answer (unreachable, `null`, or unrelated JSON) — leave the cache.
    Unavailable,
}

/// Classify a fresh server status against the cached local one.
fn classify_agent_status(cached: &str, status_json: &str) -> AgentStatusRefresh {
    let trimmed = status_json.trim();
    if trimmed == "null" || trimmed == "\"null\"" || trimmed.is_empty() {
        return AgentStatusRefresh::Unavailable;
    }
    let Ok(parsed) = serde_json::from_str::<Value>(trimmed) else {
        return AgentStatusRefresh::Unavailable;
    };
    let status_code = parse_status_code_from_json(&parsed);
    if status_code == "404" || status_code == "SC_NOT_FOUND" {
        return AgentStatusRefresh::Gone;
    }
    // The shared envelope is the current contract; the legacy fields stay as a
    // fallback so a mixed-version pair keeps labelling correctly.
    let envelope_word = envelope_status_word(&parsed);
    let fresh = if !envelope_word.is_empty() {
        let error = parsed.get("error").and_then(|v| v.as_str());
        friendly_envelope_status(&envelope_word, &status_code, error)
    } else {
        // Require at least one known legacy status field — a bare `{}` (or unrelated
        // JSON) must not map to "queued" and overwrite the cache.
        let has_status_field = parsed.get("processState").is_some()
            || parsed.get("isDone").is_some()
            || parsed.get("statusCode").is_some()
            || parsed.get("finishTime").is_some();
        if !has_status_field {
            return AgentStatusRefresh::Unavailable;
        }
        let process_state = parsed
            .get("processState")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        let is_done = parsed
            .get("isDone")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        Some(friendly_agent_status(process_state, is_done, &status_code))
    };
    let Some(fresh) = fresh else {
        return AgentStatusRefresh::Unavailable;
    };
    // Terminal states never regress: a restarted backend answering "created" for a
    // task whose cached status is terminal must not reopen it.
    if agent_task_status_is_terminal(cached) && !agent_task_status_is_terminal(&fresh) {
        return AgentStatusRefresh::Unavailable;
    }
    AgentStatusRefresh::Fresh(fresh)
}

/// Map a fresh server status onto the cached local one for `agent list` refresh.
///
/// Returns `None` when the cache must stay untouched: the backend answered
/// "null"/empty (task id unknown after a restart), a structured notFound answer, or
/// a fresh status that would downgrade a cached terminal one.
fn refreshed_agent_status(cached: &str, status_json: &str) -> Option<String> {
    match classify_agent_status(cached, status_json) {
        AgentStatusRefresh::Fresh(fresh) => Some(fresh),
        AgentStatusRefresh::Gone | AgentStatusRefresh::Unavailable => None,
    }
}

/// Poll the backend for one tracked agent task and fold the answer into its record.
///
/// Shared by `agent list`'s display refresh and its `--clear` branch so both decide
/// on the same observation: previously `--clear` trusted the cached label, which the
/// stale cache kept non-terminal forever (issue 112415#3).
async fn refresh_tracked_agent_task(
    client: &Client,
    base_url: &str,
    entry: &mut state::AsyncTaskEntry,
) -> AgentStatusRefresh {
    let Ok(status_json) = get_command_status(client, base_url, &entry.task_id).await else {
        return AgentStatusRefresh::Unavailable;
    };
    let cached = entry.last_status.clone();
    let verdict = classify_agent_status(&cached, &status_json);
    if let AgentStatusRefresh::Fresh(fresh) = &verdict {
        entry.last_status = fresh.clone();
        // Prefer backend finishTime; fall back to the local clock. Only set
        // completed_at when it is unset — the first completion timestamp wins.
        if agent_task_status_is_terminal(fresh) && entry.completed_at.is_none() {
            entry.completed_at = Some(
                serde_json::from_str::<Value>(&status_json)
                    .ok()
                    .and_then(|parsed| {
                        parsed
                            .get("finishTime")
                            .and_then(|v| v.as_str())
                            .map(str::to_string)
                    })
                    .filter(|ts| !ts.is_empty())
                    .unwrap_or_else(|| chrono::Utc::now().to_rfc3339()),
            );
        }
    }
    verdict
}

/// Map crawl status strings to the same lifecycle labels.
///
/// The backend emits `ResourceStatus` display text ("Created", "Processing",
/// "Request Timeout", "Internal Server Error", "Not Found"); token spellings from
/// older payloads are still accepted so a mixed-version pair keeps labelling
/// correctly.  Matching only the tokens — the previous behaviour — mislabelled
/// everything except `"OK"`: `"Request Timeout"` fell through to
/// `"request timeout"` instead of `"failed (timeout)"`, and `"Not Found"` never
/// matched `contains("NOT_FOUND")` at all.
fn friendly_crawl_status(status: &str) -> String {
    match status {
        "Created" | "CREATED" => "queued".to_string(),
        "Processing" | "PROCESSING" | "Accepted" | "SC_ACCEPTED" => "processing".to_string(),
        "OK" | "SC_OK" => "completed".to_string(),
        "Request Timeout" | "REQUEST_TIMEOUT" | "SC_REQUEST_TIMEOUT" => "failed (timeout)".to_string(),
        "Internal Server Error" | "INTERNAL_SERVER_ERROR" | "SC_INTERNAL_SERVER_ERROR" => {
            "failed (error)".to_string()
        }
        // Without this arm the interrupted status would be lowercased into a
        // label of its own ("interrupted" — which happens to be right, but by
        // accident), and `crawl list --status interrupted` could only ever be
        // matched against whatever the fallthrough produced.
        "Interrupted" | "INTERRUPTED" => "interrupted".to_string(),
        s if s.contains("Not Found") || s.contains("NOT_FOUND") => "failed (not found)".to_string(),
        other => other.to_lowercase(),
    }
}

/// Whether a crawl status text means the task's worker died with the backend
/// process.
///
/// Such a task is **terminal** — nothing advances it on its own, so a poller
/// must stop waiting on it — but **resumable** from its checkpoint, which is
/// what `crawl resume` is for.  Spelling it out here keeps the poll loop, the
/// status handler and the list filter agreeing on the same two spellings.
fn is_interrupted_crawl_status(status: &str) -> bool {
    matches!(status, "Interrupted" | "INTERRUPTED")
}

/// Whether a crawl status text is the task-budget timeout, in EVERY spelling
/// the backend can emit: the raw `SC_*` token, the bare constant name, and the
/// friendly ResourceStatus display text.
///
/// The wait loop used to match only the `SC_*` token, so the server's
/// "Request Timeout" fell through to the "still running" arm and the foreground
/// command polled to its own 600 s deadline instead of noticing the terminal
/// state (e.g. right after `crawl cancel`).
fn is_crawl_timeout_status(status: &str) -> bool {
    matches!(status, "SC_REQUEST_TIMEOUT" | "REQUEST_TIMEOUT" | "Request Timeout")
}

/// Whether a crawl status text is a terminal server error, in every spelling
/// (see [is_crawl_timeout_status] for why all three forms are listed).
fn is_crawl_server_error_status(status: &str) -> bool {
    matches!(
        status,
        "SC_INTERNAL_SERVER_ERROR" | "INTERNAL_SERVER_ERROR" | "Internal Server Error"
    )
}

/// Terminal failure arm shared by the crawl status/result/wait handlers: the
/// timeout or the generic server error, regardless of which spelling arrived.
fn is_crawl_terminal_failure_status(status: &str) -> bool {
    is_crawl_timeout_status(status) || is_crawl_server_error_status(status)
}

/// Whether a tracked task's status label matches a `crawl list --status` filter.
///
/// `last_status` is the friendly label stored by the tracking layer (see
/// [friendly_crawl_status] and [crawl_tracked_status_label]): "failed (timeout)"
/// matches `--status failed`, a run that finished with pages missing matches it
/// too through its `partial failure (…)` label — its exit code was 6, so hiding
/// it from the failed filter is how a user auditing history lost the one run
/// that was not clean (#115140#3) — and an interrupted task matches only
/// `--status interrupted`: it is terminal and resumable, so lumping it in with
/// "running" (nothing is moving it) or "failed" (its work is not lost) would be
/// wrong both ways.
fn crawl_status_filter_matches(filter: &str, last_status: &str) -> bool {
    let sf = filter.to_lowercase();
    let s = last_status.to_lowercase();
    match sf.as_str() {
        "completed" => s == "completed" || s == "done" || s == "ok",
        "running" => s == "running" || s == "queued" || s == "created",
        "failed" => {
            s.starts_with("failed")
                || s.starts_with("partial failure")
                || s.contains("error")
                || s.contains("timeout")
        }
        "queued" => s == "queued" || s == "created",
        "interrupted" => s == "interrupted",
        "not found" | "not-found" => s.contains("not found"),
        _ => true, // unknown filter — show all
    }
}

/// What a crawl record says about resuming: whether a checkpoint exists, how
/// often the task was continued, and what the resumed run restored or still has
/// to fetch.
#[derive(Debug, PartialEq, Default, Clone)]
struct CrawlResumeBookkeeping {
    /// The `resumable` flag. `None` when the payload predates the field — an
    /// unknown answer must not be read as "nothing to resume from".
    resumable: Option<bool>,
    /// `resumedFrom`: when the interruption this run continues from happened.
    resumed_from: Option<String>,
    resume_count: i64,
    skipped_already_fetched: i64,
    remaining: i64,
}

impl CrawlResumeBookkeeping {
    /// The checkpoint accounting as one clause, e.g.
    /// `7 URL(s) restored from the checkpoint, 3 URL(s) remaining`.  Empty when
    /// the record carries neither count.
    fn detail(&self) -> String {
        let mut parts: Vec<String> = Vec::new();
        if self.skipped_already_fetched > 0 {
            parts.push(format!(
                "{} URL(s) restored from the checkpoint",
                self.skipped_already_fetched
            ));
        }
        if self.remaining > 0 {
            parts.push(format!("{} URL(s) remaining", self.remaining));
        }
        parts.join(", ")
    }

    /// Whether this record says anything about resuming at all.  A crawl that
    /// ran once and was never interrupted carries nothing, so its output stays
    /// exactly as it was.
    fn has_nothing_to_report(&self) -> bool {
        self.resumable != Some(true)
            && self.resume_count == 0
            && self.skipped_already_fetched == 0
            && self.remaining == 0
    }
}

/// Read the resume bookkeeping out of a crawl status/result record.
fn crawl_resume_bookkeeping(parsed: &Value) -> CrawlResumeBookkeeping {
    CrawlResumeBookkeeping {
        resumable: parsed["resumable"].as_bool(),
        resumed_from: parsed["resumedFrom"]
            .as_str()
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string()),
        resume_count: parsed["resumeCount"].as_i64().unwrap_or(0),
        skipped_already_fetched: parsed["skippedAlreadyFetched"].as_i64().unwrap_or(0),
        remaining: parsed["remaining"].as_i64().unwrap_or(0),
    }
}

/// One line describing the resume bookkeeping of a task that was continued, e.g.
/// `Resume state: resumed 1 time(s) (current run 2); 7 URL(s) restored from the
/// checkpoint, 3 URL(s) remaining`.
///
/// `None` for a task that was never interrupted, so an ordinary crawl's status
/// and result output is unchanged.
fn crawl_resume_note(parsed: &Value) -> Option<String> {
    let bookkeeping = crawl_resume_bookkeeping(parsed);
    if bookkeeping.has_nothing_to_report() {
        return None;
    }
    let mut parts: Vec<String> = Vec::new();
    if bookkeeping.resume_count > 0 {
        parts.push(format!(
            "resumed {} time(s) (current run {})",
            bookkeeping.resume_count,
            bookkeeping.resume_count + 1
        ));
    }
    if let Some(from) = bookkeeping.resumed_from.as_deref() {
        parts.push(format!("continuing from the interruption at {}", from));
    }
    if bookkeeping.resumable == Some(true) {
        parts.push("a checkpoint is available to continue it".to_string());
    }
    let detail = bookkeeping.detail();
    if !detail.is_empty() {
        parts.push(detail);
    }
    Some(format!("Resume state: {}", parts.join("; ")))
}

/// The one-liner `crawl status` prints for an interrupted task: what happened,
/// what its checkpoint holds, and the exact command that continues it.
///
/// Interrupted is terminal, so nothing in the CLI keeps waiting for it; saying so
/// — and giving the resume command — is the whole point of the line.
fn crawl_interrupted_status_line(task_id: &str, parsed: &Value) -> String {
    let bookkeeping = crawl_resume_bookkeeping(parsed);
    let mut line = format!(
        "Crawl {} was interrupted — its worker died with the backend process, so it is terminal \
         (nothing will continue it on its own) but resumable from its checkpoint.",
        task_id
    );
    let detail = bookkeeping.detail();
    if !detail.is_empty() {
        line.push_str(&format!(" {}", detail));
    }
    if bookkeeping.resumable == Some(false) {
        line.push_str(
            " No checkpoint was found for it, so there is nothing to continue from — submit the \
             crawl again.",
        );
    } else {
        line.push_str(&format!(
            " Continue it with: browser4-cli crawl resume {}",
            task_id
        ));
    }
    line
}

/// The error a poll loop returns for a task whose worker died with the backend
/// process: waiting is pointless (terminal), but the collected work is not lost
/// (resumable), so the message is a resume instruction rather than a failure.
fn crawl_interrupted_message(task_id: &str, parsed: &Value) -> String {
    let bookkeeping = crawl_resume_bookkeeping(parsed);
    let mut message = format!(
        "Crawl {} was interrupted: its worker died with the backend process, so the task is \
         terminal and nothing will advance it.",
        task_id
    );
    let detail = bookkeeping.detail();
    if !detail.is_empty() {
        message.push_str(&format!("\n{}", detail));
    }
    if bookkeeping.resumable == Some(false) {
        message.push_str(
            "\nNo checkpoint was found for it, so there is nothing to continue from — submit the \
             crawl again.",
        );
    } else {
        message.push_str(&format!(
            "\nContinue it from its checkpoint (already-fetched URLs are not requested again):\n  \
             browser4-cli crawl resume {}\n\
             Add --retry-failed to also re-submit the URLs that failed before.",
            task_id
        ));
    }
    message
}

/// The hint appended to a failed/timed-out crawl's message when the task kept a
/// resumable checkpoint: the pages already collected are not thrown away, so the
/// crawl can be continued instead of re-run from scratch.
///
/// A task cut off by the server-side `--timeout` budget is exactly this case.
/// `None` unless the server says a checkpoint exists (`resumable == true`).
fn crawl_resume_hint(task_id: &str, parsed: &Value) -> Option<String> {
    let bookkeeping = crawl_resume_bookkeeping(parsed);
    if bookkeeping.resumable != Some(true) {
        return None;
    }
    let detail = bookkeeping.detail();
    let suffix = if detail.is_empty() {
        String::new()
    } else {
        format!(" ({})", detail)
    };
    Some(format!(
        "The crawl kept a resumable checkpoint{}, so it can be continued instead of re-run from \
         scratch:\n  browser4-cli crawl resume {}",
        suffix, task_id
    ))
}

/// Parse a relative time string like "1h", "30m", "1d" into a chrono DateTime.
/// Returns None if the string is unparseable.
fn parse_relative_time(s: &str) -> Option<chrono::DateTime<chrono::Utc>> {
    let s = s.trim();
    let (amount_str, unit) = if let Some(stripped) = s.strip_suffix('h') {
        (stripped.trim(), "h")
    } else if let Some(stripped) = s.strip_suffix('m') {
        (stripped.trim(), "m")
    } else if let Some(stripped) = s.strip_suffix('d') {
        (stripped.trim(), "d")
    } else if let Some(stripped) = s.strip_suffix('s') {
        (stripped.trim(), "s")
    } else {
        return None;
    };
    let amount: f64 = amount_str.parse().ok()?;
    let duration = match unit {
        "s" => chrono::Duration::seconds(amount as i64),
        "m" => chrono::Duration::minutes(amount as i64),
        "h" => chrono::Duration::hours(amount as i64),
        "d" => chrono::Duration::days(amount as i64),
        _ => return None,
    };
    Some(chrono::Utc::now() - duration)
}

async fn handle_swarm_status(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required.".to_string());
    }

    // A task id and a batch id are both uuids handed out by `swarm submit`, so
    // accepting either here is what users expect: an unknown id is retried as a
    // batch before reporting "not found".
    let result = get_swarm_status(client, base_url, id).await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or(Value::String(result.clone()));

    let task_status_code = parsed.get("statusCode").and_then(|v| v.as_i64()).unwrap_or(0);
    // The backend answers an unknown id with a 404 placeholder for *both* the
    // task and the page, and never with isDone; a real task that failed a 404
    // page still reports its own (non-404) status code.
    let task_unknown = parsed.is_string()
        || (task_status_code == 404
            && parsed.get("pageStatusCode").and_then(|v| v.as_i64()) == Some(404)
            && !parsed.get("isDone").and_then(|v| v.as_bool()).unwrap_or(false));
    if task_unknown {
        if let Some(report) = swarm_batch_report(client, base_url, id).await {
            cli_println!("{}", report);
            return Ok(());
        }
    }

    // Show metadata only: id, status, isDone, message, timestamps.
    // `effective_is_done` below is the authoritative terminal check, so the raw
    // isDone flag does not need to be read separately here.
    let status_code = parsed.get("statusCode").and_then(|v| v.as_i64()).unwrap_or(0);

    // Treat any terminal status as done — not just success (200).
    // Failed tasks (417, 4xx, 5xx) and timeout tasks (408) have reached
    // a terminal state and should show isDone: true.  Tasks that are still
    // in progress (201=Created, 202=Accepted) are NOT terminal.
    let effective_is_done = swarm_task_terminal(&parsed);

    let summary = json!({
        "id": parsed.get("id").and_then(|v| v.as_str()).unwrap_or(&id),
        "isDone": effective_is_done,
        "statusCode": status_code,
        "status": parsed.get("status").unwrap_or(&json!(null)),
        "lifecycleState": friendly_swarm_status(status_code, parsed.get("status").and_then(|v| v.as_str()).unwrap_or("")),
        "message": parsed.get("message").unwrap_or(&json!("")),
        "lastModifiedTime": parsed.get("lastModifiedTime").unwrap_or(&json!(null)),
    });
    cli_println!(
        "{}",
        serde_json::to_string_pretty(&summary).unwrap_or_default()
    );

    // Give actionable guidance when the task hasn't started yet
    if !effective_is_done && status_code == 201 {
        cli_println!(
            "Note: Task is queued (statusCode=201 Created).  A worker will pick it up shortly.  \
             Use `swarm list` to see all tracked tasks, or add `--wait` to submit/query to block until completion."
        );
    }
    json_field("task_id", json!(id));
    json_field("raw", parsed);
    Ok(())
}

async fn handle_swarm_result(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required.".to_string());
    }

    let result = get_swarm_result(client, base_url, id).await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or(Value::String(result.clone()));

    // Show result payload only: resultSet, pageContentBytes
    let empty_array = json!([]);
    let result_set = parsed.get("resultSet").unwrap_or(&empty_array);
    let is_empty = result_set.as_array().map(|a| a.is_empty()).unwrap_or(true);
    let payload = json!({
        "id": parsed.get("id").and_then(|v| v.as_str()).unwrap_or(&id),
        "resultSet": result_set,
        "pageContentBytes": parsed.get("pageContentBytes").unwrap_or(&json!(null)),
        "error": parsed.get("error").unwrap_or(&json!(null)),
        "message": parsed.get("message").unwrap_or(&json!(null)),
        "statusCode": parsed.get("statusCode").unwrap_or(&json!(null)),
    });
    cli_println!(
        "{}",
        serde_json::to_string_pretty(&payload).unwrap_or_default()
    );

    // Surface the failure reason for terminal non-success tasks so a completed
    // task with an empty resultSet explains WHY it is empty (page never
    // fetched, aborted, timed out, ...) instead of guessing.
    let has_message = parsed
        .get("message")
        .and_then(|v| v.as_str())
        .map(|s| !s.is_empty())
        .unwrap_or(false);
    if is_empty && has_message {
        cli_println!("Note: {}", parsed["message"].as_str().unwrap_or_default());
    }

    // Guide users when resultSet is empty and no explicit failure reason was
    // provided — distinguish "page never fetched" from "page fetched but
    // nothing extracted" so the hint doesn't mislead `swarm query` users whose
    // task was silently dropped/evicted.
    if is_empty && !has_message && !parsed.get("error").and_then(|v| v.as_str()).map(|s| !s.is_empty()).unwrap_or(false) {
        let page_content_bytes = parsed
            .get("pageContentBytes")
            .and_then(|v| v.as_i64())
            .unwrap_or(0);
        if page_content_bytes <= 0 {
            cli_println!(
                "Note: resultSet is empty and pageContentBytes is 0 — the page was never fetched.\n\
                 The task may have been dropped or evicted. Check `swarm status <id>`, then re-run `swarm query --sql @query.sql --refresh`."
            );
        } else {
            cli_println!(
                "Note: resultSet is empty but the page was fetched ({} bytes).\n\
                 If you used `swarm submit` without --sql, no data was extracted — use `swarm query --sql @query.sql` instead.",
                page_content_bytes
            );
        }
    }
    json_field("task_id", json!(id));
    json_field("raw", parsed);
    Ok(())
}

/// Refresh the live status of locally-tracked swarm tasks from the backend.
///
/// The local tracker can lag reality: a task the swarm already completed may
/// still be recorded as "queued"/"processing"/"" locally if it was never
/// polled through `swarm list`.  Callers that decide anything based on task
/// state (close summaries, stale-task pruning) must refresh first so they
/// never report completed work as pending or failed.
///
/// Returns true when the backend was reachable (statuses may have been
/// updated); false when local records were left untouched.
async fn refresh_tracked_swarm_statuses(
    client: &Client,
    base_url: &str,
    list: &mut state::AsyncTaskList,
) -> bool {
    // Check backend connectivity before querying each task's status.
    // If the backend is unreachable, skip live refresh to avoid hanging
    // on each request's timeout (especially when many tasks are tracked).
    let backend_reachable = client
        .head(base_url.to_string())
        .timeout(std::time::Duration::from_secs(3))
        .send()
        .await
        .is_ok();

    if backend_reachable {
        // Query backend for live status of each tracked swarm task.
        // This fixes the "always pending" display and enables prune_async_tasks
        // to clean up completed tasks.
        for entry in list
            .tasks
            .iter_mut()
            .filter(|t| t.command == "swarm-submit" || t.command == "swarm-query")
        {
            match get_swarm_status(client, base_url, &entry.task_id).await {
                Ok(result) => {
                    if let Ok(parsed) = serde_json::from_str::<Value>(&result) {
                        let status_code = parsed
                            .get("statusCode")
                            .and_then(|v| v.as_i64())
                            .unwrap_or(0);
                        let status_text =
                            parsed.get("status").and_then(|v| v.as_str()).unwrap_or("");

                        // Map the backend status to a user-friendly label.
                        // The raw `status` field reflects HTTP semantics (e.g. "Created"
                        // for 201), but users expect task-lifecycle labels.
                        let terminal = swarm_task_terminal(&parsed);
                        if terminal {
                            entry.last_status = if status_code == 200 {
                                "completed".to_string()
                            } else {
                                friendly_swarm_status(status_code, status_text)
                            };
                            if entry.last_status == "completed" && status_code != 200 {
                                // friendly_swarm_status maps unknown codes to the raw
                                // text; keep the label honest for terminal failures.
                                entry.last_status = format!("failed (status {})", status_code);
                            }
                        } else if parsed
                            .get("startedTime")
                            .and_then(|v| v.as_str())
                            .map(|s| !s.is_empty())
                            .unwrap_or(false)
                        {
                            entry.last_status = "processing".to_string();
                        } else {
                            entry.last_status = "queued".to_string();
                        }

                        // Use backend timestamps when available (added in backend v4.12+).
                        // Prefer finishTime for completion; fall back to local clock.
                        if let Some(ts) = parsed
                            .get("finishTime")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                        {
                            entry.completed_at = Some(ts.to_string());
                        } else if terminal {
                            // Backend doesn't have finishTime yet — use local time.
                            // Covers failed tasks (417, 4xx, 5xx) that have reached
                            // a terminal state but whose finishTime may be missing.
                            if entry.completed_at.is_none() {
                                entry.completed_at = Some(chrono::Utc::now().to_rfc3339());
                            }
                        }
                        // Record when the backend started the task.  This is a
                        // separate field from submitted_at: the duration of a
                        // task is started -> finished, and overwriting the
                        // submission time (as this used to) made the DURATION
                        // column meaningless for queued tasks.
                        if let Some(ts) = parsed
                            .get("startedTime")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                        {
                            entry.started_at = Some(ts.to_string());
                        }
                        if let Some(bid) = parsed
                            .get("batchId")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                        {
                            entry.batch_id = Some(bid.to_string());
                        }
                        if let Some(ms) = parsed.get("durationMillis").and_then(|v| v.as_i64()) {
                            entry.duration_ms = Some(ms);
                        } else if entry.completed_at.is_some() {
                            // Backend duration missing (older build): keep the
                            // derived value consistent with the new timestamps.
                            entry.duration_ms = None;
                        }
                    }
                }
                Err(_) => {
                    // Keep last_status as-is on transient errors.
                }
            }
        }
    }

    backend_reachable
}

/// Label for the `swarm list` window line.
///
/// The date/zone suffix lives in the value; the label says whether the line
/// describes one batch or every tracked task, so "Batch window" is never used
/// for a listing that spans several batches.
fn swarm_window_label(batch_scoped: bool) -> &'static str {
    if batch_scoped {
        "Batch window (local)"
    } else {
        "Tracked window (local)"
    }
}

/// Render a swarm task window (`earliest start -> latest finish`) in **local**
/// time — the same time base as the task rows printed below it.
fn format_swarm_window(started: DateTime<Utc>, finished: DateTime<Utc>) -> String {
    format!(
        "{} -> {}",
        started
            .with_timezone(&Local)
            .format("%Y-%m-%d %H:%M:%S"),
        finished
            .with_timezone(&Local)
            .format("%Y-%m-%d %H:%M:%S")
    )
}

async fn handle_swarm_list(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    // Support --clear to remove all tracked swarm tasks
    if tool_params
        .get("clear")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let mut list = read_async_tasks(None);
        let before = list.tasks.len();
        list.tasks
            .retain(|t| t.command != "swarm-submit" && t.command != "swarm-query");
        let removed = before - list.tasks.len();
        write_async_tasks(&list, None).map_err(|e| e.to_string())?;
        cli_println!("Cleared {} tracked swarm task(s).", removed);
        json_field("cleared", json!(removed));
        return Ok(());
    }

    let mut list = read_async_tasks(None);

    // Query the backend for the live status of each tracked swarm task
    // (fixes the "always pending" display and enables pruning of completed
    // tasks).
    let backend_reachable = refresh_tracked_swarm_statuses(client, base_url, &mut list).await;
    if !backend_reachable {
        cli_println!("Note: Backend unreachable — showing cached statuses. Run `swarm query <url>` or `open <url>` to auto-start the backend for live status.");
    }

    // Persist updated statuses so prune_async_tasks works next time.
    let _ = write_async_tasks(&list, None);

    let mut filtered: Vec<_> = list
        .tasks
        .iter()
        .filter(|t| t.command == "swarm-submit" || t.command == "swarm-query")
        .cloned()
        .collect();

    // Sort by submission time (earliest first) so the task list is stable
    // across invocations.  Without explicit ordering, the display order
    // depends on the backend's iteration order, which changes on every call.
    filtered.sort_by(|a, b| a.submitted_at.cmp(&b.submitted_at));

    // Optional batch filter: after a `swarm submit --seed-file` the batch id is
    // the natural handle for "this submission", so it must be usable directly.
    if let Some(batch) = tool_params
        .get("batch")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
    {
        let before = filtered.len();
        filtered.retain(|t| t.batch_id.as_deref() == Some(batch));
        // "N of M tracked" read as "N selected out of M" / "N of M failed";
        // state plainly how many the batch holds and how many exist overall.
        cli_println!(
            "Batch {}: {} task(s) ({} tracked in total)",
            batch, filtered.len(), before
        );
    }

    // Optional lifecycle filter: the practical question after a batch submit is
    // "which URLs failed?" / "what is still running?", and answering it from a
    // 100-row table is needlessly awkward.
    if let Some(status) = tool_params
        .get("status")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty() && !s.eq_ignore_ascii_case("all"))
    {
        let wanted = status.to_ascii_lowercase();
        let before = filtered.len();
        filtered.retain(|t| swarm_status_matches(&t.last_status, &wanted));
        cli_println!(
            "Filter: {} — {} task(s) ({} tracked in total)",
            wanted, filtered.len(), before
        );
    }

    // Batch summary: total wall-clock window derived from the tasks' own
    // timestamps (earliest start -> latest finish), which is what a caller
    // usually wants to know about a submission.
    if !filtered.is_empty() {
        let batch_id = tool_params
            .get("batch")
            .and_then(|v| v.as_str())
            .map(str::trim)
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .or_else(|| {
                let ids: std::collections::BTreeSet<&str> = filtered
                    .iter()
                    .filter_map(|t| t.batch_id.as_deref())
                    .collect();
                if ids.len() == 1 {
                    ids.iter().next().map(|s| s.to_string())
                } else {
                    None
                }
            });
        let started = filtered
            .iter()
            .filter_map(|t| {
                t.started_at
                    .as_deref()
                    .or(Some(t.submitted_at.as_str()))
                    .and_then(state::parse_timestamp)
            })
            .min();
        let finished = filtered
            .iter()
            .filter_map(|t| t.completed_at.as_deref().and_then(state::parse_timestamp))
            .max();
        if let (Some(started), Some(finished)) = (started, finished) {
            let window_ms = (finished - started).num_milliseconds().max(0);
            // One time base for the whole command: the task rows below are
            // rendered in local time (state::summarize_async_tasks), so the
            // window must be local too — formatting it as UTC produced an
            // 8-hour offset inside a single output on a UTC+8 machine.
            let batch_scoped = tool_params
                .get("batch")
                .and_then(|v| v.as_str())
                .is_some()
                || batch_id.is_some();
            cli_println!(
                "{}: {} ({}), {} task(s)",
                swarm_window_label(batch_scoped),
                format_swarm_window(started, finished),
                state::format_duration_ms(window_ms),
                filtered.len()
            );
        }
        if let Some(id) = batch_id {
            json_field("batch_id", json!(id));
        }
    }

    if !filtered.is_empty() {
        cli_println!("{}", summarize_async_tasks(&filtered));

        // Detect stuck jobs: tasks that have been queued for >60s while
        // OTHER tasks in the same batch have already completed.  This
        // suggests non-FIFO dequeuing or worker pool starvation.
        let now = chrono::Utc::now();
        let has_terminal = filtered
            .iter()
            .any(|t| t.last_status == "completed" || t.last_status.starts_with("failed"));
        let stuck: Vec<_> = filtered
            .iter()
            .filter(|t| {
                t.last_status == "queued"
                    && t.submitted_at
                        .parse::<chrono::DateTime<chrono::Utc>>()
                        .map(|ts| (now - ts).num_seconds() > 60)
                        .unwrap_or(false)
            })
            .collect();
        if has_terminal && !stuck.is_empty() {
            eprintln!(
                "⚠ {} job(s) still queued after >60s while other jobs completed. \
                 The worker pool may be starved. Try increasing --max-browser-contexts, \
                 or clear stale tasks with `swarm list --clear`.",
                stuck.len()
            );
        }
    }

    let limit = tool_params
        .get("limit")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);
    let offset = tool_params
        .get("offset")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);

    // Machine-readable mode: id / url / status per task, so scripts and agents
    // can compute their own completion checks instead of scraping the table.
    if tool_params
        .get("json")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let tasks: Vec<Value> = filtered
            .iter()
            .map(|t| {
                json!({
                    "task_id": t.task_id,
                    "command": t.command,
                    "url": t.description,
                    "status": if t.last_status.is_empty() { "pending" } else { t.last_status.as_str() },
                    "batch_id": t.batch_id,
                    "submitted_at": t.submitted_at,
                    "started_at": t.started_at,
                    "completed_at": t.completed_at,
                    "duration_ms": state::task_duration_ms(t),
                })
            })
            .collect();
        json_field("count", json!(tasks.len()));
        json_field("tasks", json!(tasks));
        return Ok(());
    }

    let display = state::AsyncTaskList { tasks: filtered };
    cli_println!("{}", format_async_task_list(&display, limit, offset));
    Ok(())
}

/// Whether a tracked task's status label belongs to the requested filter.
///
/// Filters name the *lifecycle* state, not the raw label: "failed" matches
/// every `failed (...)` variant (timeout, expectation failed, closed, ...),
/// "pending" matches anything that is neither completed nor failed.
fn swarm_status_matches(last_status: &str, wanted: &str) -> bool {
    let status = last_status.to_ascii_lowercase();
    match wanted {
        "failed" | "failure" | "error" => status.starts_with("failed"),
        "completed" | "complete" | "done" | "succeeded" => status == "completed",
        "queued" => status == "queued" || status.is_empty(),
        "processing" | "running" => status == "processing",
        "pending" => !status.starts_with("failed") && status != "completed",
        other => status == other,
    }
}

/// Poll a list of swarm task IDs until all complete or timeout.
///
/// Returns the number of jobs that did NOT succeed (failed plus still pending
/// when the wait window expires), so the caller can exit non-zero: a scripted
/// `swarm query --wait` used to exit 0 while every job had failed, and the
/// caller had no way to tell.
async fn swarm_wait_for_jobs(
    client: &Client,
    base_url: &str,
    task_ids: &[String],
    batch_id: Option<&str>,
) -> Result<usize, String> {
    let total = task_ids.len();
    match batch_id {
        Some(id) => cli_println!(
            "Waiting for {} job(s) of batch {} to complete...",
            total, id
        ),
        None => cli_println!("Waiting for {} job(s) to complete...", total),
    }

    let poll_interval = std::time::Duration::from_secs(2);
    let max_wait = std::time::Duration::from_secs(300); // 5-minute timeout
    let start = std::time::Instant::now();

    let mut completed = vec![false; total];
    let mut outcomes: Vec<TaskOutcome> = (0..total).map(|_| TaskOutcome::Pending).collect();
    let mut last_report = start;

    loop {
        let mut all_done = true;
        // Prefer the batch endpoint: one request reports every task of the batch
        // instead of N status calls per poll (a 100-URL batch used to make 100
        // requests every 2 seconds).  Falls back to per-task polling when the
        // batch id is unknown or the backend has no batch endpoint.
        if let Some(batch_id) = batch_id {
            if let Ok(payload) = get_swarm_batch_status(client, base_url, batch_id).await {
                if let Ok(parsed) = serde_json::from_str::<Value>(&payload) {
                    if let Some(rows) = parsed.get("tasks").and_then(|v| v.as_array()) {
                        for row in rows {
                            let Some(id) = row.get("id").and_then(|v| v.as_str()) else {
                                continue;
                            };
                            let Some(idx) = task_ids.iter().position(|t| t == id) else {
                                continue;
                            };
                            if completed[idx] {
                                continue;
                            }
                            let is_done = row
                                .get("isDone")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let status_code =
                                row.get("statusCode").and_then(|v| v.as_i64()).unwrap_or(0);
                            // The batch endpoint reports isDone explicitly; a 200
                            // status alone only means the page's query started.
                            if is_done || status_code >= 400 {
                                completed[idx] = true;
                                outcomes[idx] = if status_code == 200 {
                                    TaskOutcome::Succeeded
                                } else {
                                    TaskOutcome::Failed {
                                        code: status_code,
                                        message: row
                                            .get("message")
                                            .and_then(|v| v.as_str())
                                            .unwrap_or("")
                                            .to_string(),
                                    }
                                };
                            }
                        }
                    }
                }
            }
        }

        for (i, id) in task_ids.iter().enumerate() {
            if completed[i] {
                continue;
            }
            match get_swarm_status(client, base_url, id).await {
                Ok(result) => {
                    let parsed: Value = serde_json::from_str(&result).unwrap_or_default();
                    // Terminal means the backend says so (isDone), or the task
                    // reported an error status: a 200 statusCode is emitted when
                    // the page's query starts, not when the task finishes.
                    let status_code = parsed
                        .get("statusCode")
                        .and_then(|v| v.as_i64())
                        .unwrap_or(0);
                    if swarm_task_terminal(&parsed) {
                        completed[i] = true;
                        outcomes[i] = if status_code == 200 {
                            TaskOutcome::Succeeded
                        } else {
                            TaskOutcome::Failed {
                                code: status_code,
                                message: parsed
                                    .get("message")
                                    .and_then(|v| v.as_str())
                                    .unwrap_or("")
                                    .to_string(),
                            }
                        };
                    } else {
                        all_done = false;
                    }
                }
                Err(_) => {
                    // Keep waiting on transient errors
                    all_done = false;
                }
            }
        }

        if all_done {
            return report_swarm_wait_outcome(task_ids, &outcomes, start, total, batch_id);
        }

        if start.elapsed() > max_wait {
            let pending: Vec<_> = task_ids
                .iter()
                .enumerate()
                .filter(|(i, _)| !completed[*i])
                .map(|(_, id)| id.clone())
                .collect();
            let succeeded = outcomes
                .iter()
                .filter(|o| matches!(o, TaskOutcome::Succeeded))
                .count();
            let failed = outcomes
                .iter()
                .filter(|o| matches!(o, TaskOutcome::Failed { .. }))
                .count();
            cli_println!(
                "Timeout after {:.0}s: {} succeeded, {} failed, {} still pending.\n  \
                 Use 'swarm list --status pending' to see what is still running, or \
                 'swarm list --status failed' to see what failed.",
                start.elapsed().as_secs_f64(),
                succeeded,
                failed,
                pending.len(),
            );
            json_field("succeeded", json!(succeeded));
            json_field("failed", json!(failed));
            json_field("pending_task_ids", json!(pending));
            return Ok(failed + pending.len());
        }

        // Progress report every 30 seconds
        if last_report.elapsed() >= std::time::Duration::from_secs(30) {
            let done_count = completed.iter().filter(|&&c| c).count();
            let failed_count = outcomes
                .iter()
                .filter(|o| matches!(o, TaskOutcome::Failed { .. }))
                .count();
            cli_println!(
                "  ... {}/{} job(s) terminal ({} failed) (elapsed: {:.0}s)",
                done_count,
                total,
                failed_count,
                start.elapsed().as_secs_f64()
            );
            last_report = std::time::Instant::now();
        }

        tokio::time::sleep(poll_interval).await;
    }
}

/// Outcome of a single swarm job, as observed while `--wait` polled it.
/// Warn when free-form LoadOptions contain a `#`.
///
/// The URL/args splitter treats `#` as a fragment delimiter, so everything
/// after it — including the option's value and any options that follow — is
/// silently dropped before parsing.  A `#id` selector therefore never reaches
/// the page-quality gate.  Failing loudly here beats a silent no-op.
fn warn_on_hash_in_load_options(opts: &str) {
    if opts.contains('#') {
        eprintln!(
            "⚠ --load-options contains '#': the URL/args parser treats '#' as a fragment \
             delimiter and drops the rest of the option string.\n  \
             Use an attribute selector instead, e.g. -requireNotBlank \"[id=productTitle]\"."
        );
    }
}

/// Resolve the batch id for one `swarm submit` / `swarm query` invocation.
///
/// Uses `--batch-id <id>` when given (so a caller can name its own batches and
/// correlate them with an external system), otherwise mints a fresh one.  Every
/// task of the invocation is stamped with it, which makes the submission
/// addressable as a unit afterwards.
fn resolve_batch_id(tool_params: &Value) -> String {
    tool_params
        .get("batchId")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .unwrap_or_else(new_batch_id)
}

/// Mint a random RFC-4122 v4 batch id.
///
/// Uses the `sha2` dependency the CLI already has (no new crates): 16 bytes are
/// derived from the current time, the process id and a per-process random seed,
/// then version/variant bits are stamped as v4 requires.
fn new_batch_id() -> String {
    use sha2::{Digest, Sha256};
    use std::sync::atomic::{AtomicU64, Ordering};
    use std::time::{SystemTime, UNIX_EPOCH};

    static COUNTER: AtomicU64 = AtomicU64::new(0);
    static SEED: std::sync::OnceLock<u64> = std::sync::OnceLock::new();

    let seed = *SEED.get_or_init(|| {
        // RandomState is seeded from the OS once per process; hashing it gives a
        // value that differs between runs even on the same machine.
        use std::collections::hash_map::RandomState;
        use std::hash::{BuildHasher, Hasher};
        let mut hasher = RandomState::new().build_hasher();
        hasher.write_u64(std::process::id() as u64);
        hasher.finish()
    });
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);
    let seq = COUNTER.fetch_add(1, Ordering::Relaxed);

    let mut hasher = Sha256::new();
    hasher.update(seed.to_le_bytes());
    hasher.update(nanos.to_le_bytes());
    hasher.update(seq.to_le_bytes());
    hasher.update(std::process::id().to_le_bytes());
    let digest = hasher.finalize();

    let mut bytes = [0u8; 16];
    bytes.copy_from_slice(&digest[..16]);
    bytes[6] = (bytes[6] & 0x0f) | 0x40; // version 4
    bytes[8] = (bytes[8] & 0x3f) | 0x80; // RFC 4122 variant

    format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3], bytes[4], bytes[5], bytes[6], bytes[7],
        bytes[8], bytes[9], bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15]
    )
}

/// Outcome of a single swarm job, as observed while `--wait` polled it.
enum TaskOutcome {
    Succeeded,
    Failed { code: i64, message: String },
    Pending,
}

/// Report the final state of a `swarm submit --wait` batch.
///
/// A terminal task is not necessarily a *successful* task: the backend reports
/// timeouts and fetch failures with a 4xx/5xx `statusCode` while still being
/// "done".  Printing "all jobs completed" for a batch in which every fetch
/// failed hides the failure from scripts and users, so the summary separates
/// succeeded / failed / pending, lists the failed URLs, and emits the counts as
/// JSON fields for programmatic checks.
fn report_swarm_wait_outcome(
    task_ids: &[String],
    outcomes: &[TaskOutcome],
    start: std::time::Instant,
    total: usize,
    batch_id: Option<&str>,
) -> Result<usize, String> {
    let succeeded: Vec<&String> = task_ids
        .iter()
        .zip(outcomes)
        .filter(|(_, o)| matches!(o, TaskOutcome::Succeeded))
        .map(|(id, _)| id)
        .collect();
    let failed: Vec<(&String, i64, &str)> = task_ids
        .iter()
        .zip(outcomes)
        .filter_map(|(id, o)| match o {
            TaskOutcome::Failed { code, message } => Some((id, *code, message.as_str())),
            _ => None,
        })
        .collect();
    let pending: Vec<&String> = task_ids
        .iter()
        .zip(outcomes)
        .filter(|(_, o)| matches!(o, TaskOutcome::Pending))
        .map(|(id, _)| id)
        .collect();

    let elapsed = start.elapsed().as_secs_f64();
    let batch_suffix = batch_id
        .map(|id| format!(" (batch {})", id))
        .unwrap_or_default();
    if failed.is_empty() && pending.is_empty() {
        cli_println!("All {} job(s) completed in {:.0}s{}.", total, elapsed, batch_suffix);
    } else {
        cli_println!(
            "{} job(s) finished in {:.0}s{}: {} succeeded, {} failed, {} pending.",
            total,
            elapsed,
            batch_suffix,
            succeeded.len(),
            failed.len(),
            pending.len(),
        );
    }

    // URL for each task id, when the local tracker knows it.
    let tracked = read_async_tasks(None);
    let url_of = |id: &str| -> Option<String> {
        tracked
            .tasks
            .iter()
            .find(|t| t.task_id == id)
            .map(|t| t.description.clone())
            .filter(|d| !d.is_empty())
    };

    if !failed.is_empty() {
        cli_println!("\n  Failed job(s):");
        for (id, code, message) in &failed {
            let url = url_of(id).unwrap_or_else(|| "(unknown url)".to_string());
            let detail = if message.is_empty() {
                String::new()
            } else {
                format!(" — {}", message.lines().next().unwrap_or(""))
            };
            cli_println!("    [{}] {} (status {}){}", short_task_id(id), url, code, detail);
        }
        cli_println!(
            "  Re-submit the failed URLs with: swarm submit --seed-file <file> --wait"
        );
    }
    if !pending.is_empty() {
        cli_println!("\n  Still pending after the wait window: {}", pending.len());
        for id in &pending {
            let url = url_of(id).unwrap_or_else(|| "(unknown url)".to_string());
            cli_println!("    [{}] {}", short_task_id(id), url);
        }
        cli_println!("  Check with: swarm status <id>");
    }

    json_field("succeeded", json!(succeeded.len()));
    json_field("failed", json!(failed.len()));
    json_field("pending", json!(pending.len()));
    if let Some(id) = batch_id {
        json_field("batch_id", json!(id));
    }
    if !failed.is_empty() {
        let entries: Vec<Value> = failed
            .iter()
            .map(|(id, code, message)| {
                json!({
                    "task_id": id,
                    "url": url_of(id),
                    "status_code": code,
                    "message": message,
                })
            })
            .collect();
        json_field("failed_tasks", json!(entries));
    }
    if !pending.is_empty() {
        json_field("pending_task_ids", json!(pending));
    }
    Ok(failed.len() + pending.len())
}

/// Render the aggregate status of a batch, or `None` when the id is not a batch.
///
/// This is what makes `swarm status <batch-uuid>` work: a batch id is just as
/// valid an input as a task id, and the aggregate is a single backend request.
/// Failed tasks are matched against the local tracker so the report can name
/// their URLs instead of bare uuids.
async fn swarm_batch_report(client: &Client, base_url: &str, batch_id: &str) -> Option<String> {
    let payload = get_swarm_batch_status(client, base_url, batch_id).await.ok()?;
    let parsed: Value = serde_json::from_str(&payload).ok()?;

    let total = parsed.get("total").and_then(|v| v.as_i64()).unwrap_or(0);
    if total == 0 {
        // Unknown to both namespaces: let the caller report the task id as missing.
        return None;
    }
    let completed = parsed.get("completed").and_then(|v| v.as_i64()).unwrap_or(0);
    let failed = parsed.get("failed").and_then(|v| v.as_i64()).unwrap_or(0);
    let pending = parsed.get("pending").and_then(|v| v.as_i64()).unwrap_or(0);
    let window = match (
        parsed.get("startedAt").and_then(|v| v.as_str()),
        parsed.get("finishedAt").and_then(|v| v.as_str()),
        parsed.get("durationMillis").and_then(|v| v.as_i64()),
    ) {
        (Some(_), Some(finished), Some(ms)) => format!(
            "{} → {} ({})",
            parsed
                .get("startedAt")
                .and_then(|v| v.as_str())
                .and_then(state::parse_timestamp)
                .map(|t| t.format("%H:%M:%S").to_string())
                .unwrap_or_else(|| "-".to_string()),
            state::parse_timestamp(finished)
                .map(|t| t.format("%H:%M:%S").to_string())
                .unwrap_or_else(|| "-".to_string()),
            state::format_duration_ms(ms)
        ),
        _ => "(still running)".to_string(),
    };

    let mut out = String::new();
    out.push_str(&format!("Batch {}: {} task(s)\n", batch_id, total));
    out.push_str(&format!(
        "  completed: {}  failed: {}  pending: {}\n",
        completed, failed, pending
    ));
    out.push_str(&format!("  window: {}\n", window));

    let tracked = read_async_tasks(None);
    let url_of = |id: &str| -> Option<String> {
        tracked
            .tasks
            .iter()
            .find(|t| t.task_id == id)
            .map(|t| t.description.clone())
            .filter(|d| !d.is_empty())
    };

    if let Some(rows) = parsed.get("tasks").and_then(|v| v.as_array()) {
        let mut failed_lines: Vec<String> = Vec::new();
        let mut slowest: Vec<(i64, String)> = Vec::new();
        for row in rows {
            let Some(task_id) = row.get("id").and_then(|v| v.as_str()) else {
                continue;
            };
            if let Some(ms) = row.get("durationMillis").and_then(|v| v.as_i64()) {
                slowest.push((ms, task_id.to_string()));
            }
            let status_code = row.get("statusCode").and_then(|v| v.as_i64()).unwrap_or(0);
            let is_done = row.get("isDone").and_then(|v| v.as_bool()).unwrap_or(false);
            if is_done && status_code != 200 {
                let url = url_of(task_id).unwrap_or_else(|| "(unknown url)".to_string());
                let message = row.get("message").and_then(|v| v.as_str()).unwrap_or("");
                failed_lines.push(format!(
                    "    [{}] {} (status {}){}",
                    short_task_id(task_id),
                    url,
                    status_code,
                    if message.is_empty() {
                        String::new()
                    } else {
                        format!(" — {}", message.lines().next().unwrap_or(""))
                    }
                ));
            }
        }
        if !failed_lines.is_empty() {
            out.push_str("  failures:\n");
            out.push_str(&failed_lines.join("\n"));
            out.push('\n');
        }
        slowest.sort_by(|a, b| b.0.cmp(&a.0));
        if let Some((ms, id)) = slowest.first() {
            out.push_str(&format!(
                "  slowest task: {} ({})\n",
                short_task_id(id),
                state::format_duration_ms(*ms)
            ));
        }
    }

    // The caller prints the returned report, so this function must not print it
    // as well (that produced a duplicated block on `swarm status <batch-id>`).
    json_field("batch_id", json!(batch_id));
    json_field("total", json!(total));
    json_field("completed", json!(completed));
    json_field("failed", json!(failed));
    json_field("pending", json!(pending));
    json_field(
        "duration_ms",
        parsed.get("durationMillis").cloned().unwrap_or(Value::Null),
    );
    Some(out)
}

/// Whether a swarm task response describes a terminal (settled) task.
///
/// `isDone` is the backend's own terminal flag and the only reliable signal:
/// `statusCode == 200` is set when the page's X-SQL starts executing, well
/// before the task finishes, so treating it as success made `--wait` return
/// while pages were still being extracted.  Older backends do not emit the flag
/// over REST, so a recorded `finishTime` (or a legacy `done` field, or an error
/// status) also counts as settled.
fn swarm_task_terminal(parsed: &Value) -> bool {
    if parsed.get("isDone").and_then(|v| v.as_bool()).unwrap_or(false) {
        return true;
    }
    if parsed.get("done").and_then(|v| v.as_bool()).unwrap_or(false) {
        return true;
    }
    let status_code = parsed.get("statusCode").and_then(|v| v.as_i64()).unwrap_or(0);
    if status_code >= 400 {
        return true;
    }
    parsed
        .get("finishTime")
        .and_then(|v| v.as_str())
        .map(|s| !s.is_empty())
        .unwrap_or(false)
}

/// First 8 characters of a task id — enough to address it in follow-up commands.
fn short_task_id(id: &str) -> &str {
    if id.len() > 8 {
        &id[..8]
    } else {
        id
    }
}

async fn handle_crawl_list(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    // Support --clear to remove all tracked crawl tasks
    if tool_params
        .get("clear")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        let mut list = read_async_tasks(None);
        let before = list.tasks.len();
        list.tasks.retain(|t| t.command != "crawl");
        let removed = before - list.tasks.len();
        write_async_tasks(&list, None).map_err(|e| e.to_string())?;
        cli_println!("Cleared {} tracked crawl task(s).", removed);
        json_field("cleared", json!(removed));
        return Ok(());
    }

    let mut list = read_async_tasks(None);

    // Pre-flight check: skip live refresh if backend is unreachable.
    let backend_reachable = client
        .head(base_url.to_string())
        .timeout(std::time::Duration::from_secs(3))
        .send()
        .await
        .is_ok();

    if backend_reachable {
        // Query backend for live status of each tracked crawl task.
        let mut stale_ids: Vec<String> = Vec::new();
        for entry in list.tasks.iter_mut().filter(|t| t.command == "crawl") {
            if let Ok(text) = get_crawl_result(client, base_url, &entry.task_id).await {
                if let Ok(parsed) = serde_json::from_str::<Value>(&text) {
                    if let Some(s) = parsed.get("status").and_then(|v| v.as_str()) {
                        // The payload's loss ledger decides whether a terminal
                        // "OK" really was a clean run: a crawl that exited 6 was
                        // relabelled "completed" here on every refresh, losing
                        // the partial-failure accounting the run had recorded.
                        let friendly = crawl_tracked_status_label(s, &parsed);
                        // If the server no longer knows about this task, mark it for removal
                        // so it doesn't linger in the list as "not found"
                        if friendly.contains("not found") {
                            stale_ids.push(entry.task_id.clone());
                        }
                        entry.last_status = friendly;
                    }
                    // Only set completed_at when it hasn't been set yet — once set,
                    // keep the first completion timestamp (don't overwrite on later polls).
                    let now_completed = entry.last_status == "completed"
                        || entry.last_status.starts_with("failed")
                        || entry.last_status.starts_with("partial failure");
                    if now_completed && entry.completed_at.is_none() {
                        if let Some(ts) = parsed
                            .get("finishTime")
                            .and_then(|v| v.as_str())
                            .filter(|s| !s.is_empty())
                        {
                            entry.completed_at = Some(ts.to_string());
                        } else {
                            entry.completed_at = Some(chrono::Utc::now().to_rfc3339());
                        }
                    }
                }
            }
        }
        // Remove stale entries that the server has already cleaned up
        if !stale_ids.is_empty() {
            list.tasks.retain(|t| !stale_ids.contains(&t.task_id));
            // Routine housekeeping, but never silent: a row disappearing from
            // `crawl list` used to be unexplained below 20 removals, so the list
            // looked like it had lost a task (#115140#6).
            cli_println!(
                "Pruned {} tracked task(s) the backend no longer knows (routine cleanup; \
                 `crawl list --clear` removes the rest).",
                stale_ids.len()
            );
        }
        // Also prune tasks older than 24h to prevent unbounded accumulation
        let age_cutoff = chrono::Utc::now() - chrono::Duration::hours(24);
        let age_cutoff_str = age_cutoff.to_rfc3339();
        let before = list.tasks.len();
        list.tasks
            .retain(|t| t.command != "crawl" || t.submitted_at >= age_cutoff_str);
        let aged_out = before - list.tasks.len();
        let _ = write_async_tasks(&list, None);
        if aged_out > 0 {
            cli_println!(
                "Dropped {} task record(s) older than the 24h local retention window \
                 (local tracking only — backend records and crawl checkpoints are untouched).",
                aged_out
            );
        }
    } else {
        cli_println!("Note: Backend unreachable — showing cached statuses. Run `crawl <url>` or `open <url>` to auto-start the backend for live status.");
    }

    let mut filtered: Vec<_> = list
        .tasks
        .iter()
        .filter(|t| t.command == "crawl")
        .cloned()
        .collect();

    // Apply --status filter
    if let Some(status_filter) = tool_params.get("status").and_then(|v| v.as_str()) {
        filtered.retain(|t| crawl_status_filter_matches(status_filter, &t.last_status));
        if filtered.is_empty() {
            cli_println!("No crawl tasks matching status filter '{}'.", status_filter);
            return Ok(());
        }
    }

    // Apply --since filter
    if let Some(since) = tool_params.get("since").and_then(|v| v.as_str()) {
        if let Some(cutoff) = parse_relative_time(since) {
            let cutoff_str = cutoff.to_rfc3339();
            filtered.retain(|t| t.submitted_at.as_str() >= cutoff_str.as_str());
        } else {
            cli_println!(
                "Warning: could not parse --since '{}'. Expected format: 1h, 30m, 1d",
                since
            );
        }
        if filtered.is_empty() {
            cli_println!("No crawl tasks found within the last '{}'.", since);
            return Ok(());
        }
    }

    if filtered.is_empty() {
        cli_println!("No tracked crawl tasks. Start one with 'crawl <url>'.");
        return Ok(());
    }
    cli_println!("{}", summarize_async_tasks(&filtered));

    // Default to 20 most recent if no explicit limit
    let limit = tool_params
        .get("limit")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize)
        .or_else(|| {
            // If no explicit limit and no filters applied, default to 20
            if tool_params.get("status").is_none() && tool_params.get("since").is_none() {
                Some(20)
            } else {
                None
            }
        });
    let offset = tool_params
        .get("offset")
        .and_then(|v| v.as_u64())
        .map(|n| n as usize);
    let display = state::AsyncTaskList { tasks: filtered };
    cli_println!("{}", format_async_task_list(&display, limit, offset));
    cli_println!("\nTip: use 'crawl cancel <id>' to cancel a stuck task, 'crawl clear' to remove terminal tasks.");
    Ok(())
}

// ---------------------------------------------------------------------------
// Experience handlers
// ---------------------------------------------------------------------------

async fn handle_experience_save(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let result = call_tool(client, base_url, "experience_save", tool_params.clone()).await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or_default();
    cli_println!(
        "{}",
        serde_json::to_string_pretty(&parsed).unwrap_or(result)
    );
    json_field("result", parsed);
    Ok(())
}

async fn handle_experience_query(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let result = call_tool(client, base_url, "experience_query", tool_params.clone()).await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or_default();
    if let (Some(tier), Some(confidence)) = (
        parsed.get("tier").and_then(|v| v.as_str()),
        parsed.get("confidence").and_then(|v| v.as_f64()),
    ) {
        cli_println!("Tier: {}  |  Confidence: {:.3}", tier, confidence);
    }
    if let Some(summary) = parsed.get("summary").and_then(|v| v.as_str()) {
        cli_println!("{}", summary);
    }
    if let Some(selectors) = parsed.get("primary_selectors").and_then(|v| v.as_object()) {
        if !selectors.is_empty() {
            cli_println!("\nPrimary selectors:");
            for (k, v) in selectors {
                cli_println!("  {}: {}", k, v.as_str().unwrap_or("-"));
            }
        }
    }
    if let Some(warnings) = parsed.get("warnings").and_then(|v| v.as_array()) {
        if !warnings.is_empty() {
            cli_println!("\nWarnings:");
            for w in warnings {
                cli_println!("  ! {}", w.as_str().unwrap_or("-"));
            }
        }
    }
    json_field("result", parsed);
    Ok(())
}

async fn handle_experience_list(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let result = call_tool(client, base_url, "experience_list", tool_params.clone()).await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or_default();
    let total = parsed.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
    let page = parsed.get("page").and_then(|v| v.as_u64()).unwrap_or(1);
    let total_pages = parsed
        .get("total_pages")
        .and_then(|v| v.as_u64())
        .unwrap_or(1);
    cli_println!(
        "Experience entries: {} total (page {}/{})",
        total,
        page,
        total_pages
    );
    if let Some(entries) = parsed.get("entries").and_then(|v| v.as_array()) {
        if entries.is_empty() {
            cli_println!("No knowledge entries found. Run an agent task to build experience, then use 'experience-deep-learn' to promote facts.");
        } else {
            cli_println!(
                "{:<25}  {:<20}  {:<6}  {:<10}  {:<10}  {}",
                "DOMAIN",
                "INTENT",
                "TIER",
                "CONF",
                "STATUS",
                "SITE TYPES"
            );
            cli_println!("{}", "-".repeat(110));
            for entry in entries {
                let domain = entry.get("domain").and_then(|v| v.as_str()).unwrap_or("-");
                let intent = entry.get("intent").and_then(|v| v.as_str()).unwrap_or("-");
                let tier = entry
                    .get("retrieval_tier")
                    .and_then(|v| v.as_str())
                    .unwrap_or("-");
                let confidence = entry
                    .get("confidence")
                    .and_then(|v| v.as_f64())
                    .unwrap_or(0.0);
                let status = entry.get("status").and_then(|v| v.as_str()).unwrap_or("-");
                let site_types = entry
                    .get("site_types")
                    .and_then(|v| v.as_array())
                    .map(|a| {
                        a.iter()
                            .filter_map(|s| s.as_str())
                            .collect::<Vec<_>>()
                            .join(", ")
                    })
                    .unwrap_or_default();
                cli_println!(
                    "{:<25}  {:<20}  {:<6}  {:<10.3}  {:<10}  {}",
                    truncate_str(domain, 25),
                    truncate_str(intent, 20),
                    tier,
                    confidence,
                    status,
                    site_types,
                );
            }
        }
    }
    json_field("result", parsed);
    Ok(())
}

async fn handle_experience_deep_learn(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    cli_println!("Running deep learning analysis (this may take a few seconds)...");
    let result = call_tool(
        client,
        base_url,
        "experience_deep_learn",
        tool_params.clone(),
    )
    .await?;
    let parsed: Value = serde_json::from_str(&result).unwrap_or_default();
    if let Some(completed) = parsed.get("completed").and_then(|v| v.as_bool()) {
        if !completed {
            cli_println!(
                "Deep learning skipped — confidence already high. Use --force to override."
            );
        } else {
            let promoted = parsed
                .get("promoted")
                .and_then(|v| v.as_bool())
                .unwrap_or(false);
            let status_after = parsed
                .get("status_after")
                .and_then(|v| v.as_str())
                .unwrap_or("-");
            let confidence = parsed
                .get("new_confidence")
                .and_then(|v| v.as_f64())
                .unwrap_or(0.0);
            let selectors = parsed
                .get("selectors_found")
                .and_then(|v| v.as_i64())
                .unwrap_or(0);
            cli_println!("Deep learning complete.");
            cli_println!("  Status: {} (promoted: {})", status_after, promoted);
            cli_println!("  Confidence: {:.3}", confidence);
            cli_println!("  Selectors found: {}", selectors);
        }
    }
    if let Some(msg) = parsed.get("message").and_then(|v| v.as_str()) {
        cli_println!("{}", msg);
    }
    json_field("result", parsed);
    Ok(())
}

/// Truncate a string to at most `max_len` characters, appending "…" if truncated.
fn truncate_str(s: &str, max_len: usize) -> String {
    if s.chars().count() <= max_len {
        s.to_string()
    } else {
        format!(
            "{}…",
            &s.chars()
                .take(max_len.saturating_sub(1))
                .collect::<String>()
        )
    }
}

async fn handle_crawl_status(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required. Use 'crawl list' to see tracked tasks.".to_string());
    }

    let result = get_crawl_status(client, base_url, id).await?;
    // Human-readable one-line summary in front of the raw record, so a poll
    // reads as status without forcing the user to parse the JSON envelope.
    // Goes to stderr: stdout must stay a pure JSON record for scripts and
    // tests that parse it directly.
    if !quiet_active() && !json_active() {
        if let Ok(parsed) = serde_json::from_str::<Value>(&result) {
            if let Some(summary) = crawl_task_summary_line(&parsed) {
                eprintln!("{}", summary);
            }
            // An interrupted task is terminal but resumable — the two facts the
            // raw record leaves implicit, and the ones that decide whether the
            // user waits, re-runs, or resumes.
            let status = parsed["status"].as_str().unwrap_or("");
            if is_interrupted_crawl_status(status) {
                eprintln!("{}", crawl_interrupted_status_line(id, &parsed));
            } else if let Some(note) = crawl_resume_note(&parsed) {
                eprintln!("{}", note);
            }
        }
    }
    cli_println!("{}", result);
    json_field("task_id", json!(id));
    let parsed = serde_json::from_str::<Value>(&result).unwrap_or(Value::String(result.clone()));
    // Resume bookkeeping as first-class fields so `crawl status --json` can
    // decide whether to resume without re-parsing `raw`.
    json_field(
        "resumable",
        json!(parsed["resumable"].as_bool().unwrap_or(false)),
    );
    json_field("remaining", json!(parsed["remaining"].as_i64().unwrap_or(0)));
    json_field(
        "skipped_already_fetched",
        json!(parsed["skippedAlreadyFetched"].as_i64().unwrap_or(0)),
    );
    json_field(
        "resume_count",
        json!(parsed["resumeCount"].as_i64().unwrap_or(0)),
    );
    json_field("resumed_from", parsed["resumedFrom"].clone());
    json_field("raw", json!(parsed));
    Ok(())
}

async fn handle_crawl_result(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required. Use 'crawl list' to see tracked tasks.".to_string());
    }

    let result = get_crawl_result(client, base_url, id).await?;
    if !quiet_active() && !json_active() {
        if let Ok(parsed) = serde_json::from_str::<Value>(&result) {
            if let Some(summary) = crawl_task_summary_line(&parsed) {
                eprintln!("{}", summary);
            }
            let status = parsed["status"].as_str().unwrap_or("");
            if is_interrupted_crawl_status(status) {
                // Interrupted is terminal, so "still …" would send the user
                // back to polling a task that will never move. The interrupted
                // line says what it means and how to continue it.
                eprintln!("{}", crawl_interrupted_status_line(id, &parsed));
            } else {
                // The backend returns the current task record — including a
                // PROCESSING status — for non-terminal tasks.  Say so instead of
                // letting the raw record imply completion.
                if !matches!(status, "OK" | "SC_OK" | "TIMEOUT" | "ERROR" | "CANCELLED") {
                    eprintln!(
                        "Note: task is still {} — poll again with 'crawl status {}' or 'crawl result {}'.",
                        status,
                        id,
                        id
                    );
                }
                // Resume bookkeeping: what a resumed run restored from the
                // checkpoint and what is left, like the readonly/parallelism
                // notes below the page listing.
                if let Some(note) = crawl_resume_note(&parsed) {
                    eprintln!("{}", note);
                }
            }
            // Per-page provenance: a row that came from the checkpoint was NOT
            // fetched again by this run, which is the difference between "this
            // run fetched N pages" and "this task has N pages". Rows go to
            // stderr so stdout stays the raw record scripts parse.
            if tool_params
                .get("verbose")
                .and_then(|v| v.as_bool())
                .unwrap_or(false)
            {
                if let Some(pages) = parsed["pages"].as_array() {
                    if !pages.is_empty() {
                        eprintln!("Pages ({}):", pages.len());
                        for page in pages {
                            eprintln!("{}", crawl_result_page_row(page));
                        }
                    }
                }
            }
        }
    }
    cli_println!("{}", result);
    json_field("task_id", json!(id));
    json_field(
        "raw",
        json!(serde_json::from_str::<Value>(&result).unwrap_or(Value::String(result.clone()))),
    );
    Ok(())
}

/// Build a compact one-line status summary from a crawl task record, e.g.
/// `Crawl <id>: OK — 3 page(s) found, 4 link(s) discovered (12s)`.  Returns
/// None when the record cannot be summarized (unrecognized shape).
fn crawl_task_summary_line(parsed: &Value) -> Option<String> {
    let id = parsed["taskId"].as_str().unwrap_or("").to_string();
    if id.is_empty() {
        return None;
    }
    let status = parsed["status"].as_str().unwrap_or("").to_string();
    let pages_found = parsed["pagesFound"].as_i64().unwrap_or(0);
    let links_discovered = parsed["linksDiscovered"].as_i64().unwrap_or(0);
    let seed_error_count = parsed["seedStatuses"]
        .as_array()
        .map(|statuses| {
            statuses
                .iter()
                .filter(|ss| ss["status"].as_str().unwrap_or("") == "error")
                .count()
        })
        .unwrap_or(0);
    let mut parts = vec![format!("Crawl {}: {}", id, status)];
    if pages_found > 0 {
        parts.push(format!("{} page(s) found", pages_found));
    }
    if links_discovered > 0 {
        parts.push(format!("{} link(s) discovered", links_discovered));
    }
    if seed_error_count > 0 {
        parts.push(format!("{} seed error(s)", seed_error_count));
    }
    if let Some(diag) = parsed["diagnostic"].as_str() {
        if !diag.is_empty() {
            parts.push(format!("diagnostic: {}", diag));
        }
    }
    Some(parts.join(" — "))
}

/// One page row for `crawl result --verbose`, with the row's provenance.
///
/// A resumed crawl's listing mixes rows the run actually fetched with rows it
/// restored from the checkpoint; without the marker the two are
/// indistinguishable, and a resume that fetched nothing would still look like a
/// successful re-crawl.
fn crawl_result_page_row(page: &Value) -> String {
    let depth = page["depth"].as_i64().unwrap_or(0);
    let url = page["url"].as_str().unwrap_or("");
    let title = page["title"].as_str().unwrap_or("");
    let run = page["run"].as_i64().unwrap_or(1);
    let mut provenance: Vec<String> = Vec::new();
    if page["restoredFromCheckpoint"].as_bool().unwrap_or(false) {
        provenance.push(format!("restored from checkpoint, run {}", run));
    } else if run > 1 {
        // Run 1 is the original run, so any later run fetched this row itself.
        provenance.push(format!("fetched this run, run {}", run));
    }
    if let Some(fetched_at) = page["fetchedAt"].as_str().filter(|s| !s.is_empty()) {
        provenance.push(format!("fetched {}", fetched_at));
    }
    if provenance.is_empty() {
        // Ordinary first-run row: same shape as the listing `crawl` prints.
        format!("  depth={} | {} | {}", depth, url, title)
    } else {
        format!(
            "  depth={} | {} | {} ({})",
            depth,
            url,
            title,
            provenance.join(", ")
        )
    }
}

async fn handle_crawl_cancel(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required. Use 'crawl list' to see tracked tasks.".to_string());
    }

    let result = cancel_crawl(client, base_url, id).await?;
    cli_println!("{}", result);
    json_field("task_id", json!(id));

    // A failed cancel is otherwise a silent no-op: the task record shows no
    // state change and the user has no way to tell whether the cancel was
    // ignored (worker already gone) or never reached the task.  Explain what
    // happened on stderr (stdout carries the JSON record).
    if !quiet_active() && !json_active() {
        if let Ok(parsed) = serde_json::from_str::<Value>(&result) {
            if parsed["cancelled"].as_bool() == Some(false) {
                eprintln!(
                    "Note: task was not cancellable — no running worker was found for it. \
                     Check its state with 'crawl status {}'; tasks stuck in PROCESSING \
                     without a worker expire automatically after the server-side TTL.",
                    id
                );
            }
        }
    }

    // Update local tracking
    let _ = update_async_task_status(id, "cancelled", None);
    Ok(())
}

async fn handle_crawl_clear(
    client: &Client,
    base_url: &str,
    clear_all: bool,
) -> Result<(), String> {
    let result = if clear_all {
        clear_all_crawls(client, base_url).await?
    } else {
        clear_crawls(client, base_url).await?
    };
    cli_println!("{}", result);
    // Remove ALL crawl tasks from local tracking (server-side clear removes
    // all terminal tasks; local entries pointing to cleared tasks show
    // "not found" if left behind).
    let mut list = read_async_tasks(None);
    let before = list.tasks.len();
    list.tasks.retain(|t| t.command != "crawl");
    let removed = before - list.tasks.len();
    if removed > 0 {
        let _ = write_async_tasks(&list, None);
    }
    if removed > 0 {
        cli_println!("Removed {} crawl task(s) from local tracking.", removed);
    }
    Ok(())
}

/// Continue a crawl from its checkpoint (`crawl resume <id>`).
///
/// The resume decision is the server's: `resumed = false` carries a reason
/// (record says already completed without `--force`, nothing left to fetch, no
/// checkpoint on disk) and is reported as a failure here, because a script that
/// asked for a crawl to continue must not read a no-op as success.  `--force`
/// only lifts the "record says completed" refusal — the plan still skips URLs
/// that already have a row, so the combination that fetches anything is
/// `--force --retry-failed` (the URLs the task lost).
async fn handle_crawl_resume(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), String> {
    let id = tool_params
        .get("id")
        .and_then(|v| v.as_str())
        .unwrap_or_default();

    if id.is_empty() {
        return Err("Task ID is required. Use 'crawl list' to see tracked tasks.".to_string());
    }

    let force = tool_params
        .get("force")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let retry_failed = tool_params
        .get("retryFailed")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let background = tool_params
        .get("background")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let verbose = tool_params
        .get("verbose")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let result = resume_crawl(client, base_url, id, force, retry_failed).await?;
    let parsed: Value = serde_json::from_str(&result)
        .map_err(|e| format!("Failed to parse crawl resume response: {}", e))?;

    let resumed = parsed["resumed"].as_bool().unwrap_or(false);
    let status = parsed["status"].as_str().unwrap_or("");
    let message = parsed["message"].as_str().unwrap_or("");
    let remaining = parsed["remaining"].as_i64().unwrap_or(0);
    let skipped = parsed["skippedAlreadyFetched"].as_i64().unwrap_or(0);
    let resume_count = parsed["resumeCount"].as_i64().unwrap_or(0);
    // Run 1 is the original run, so the Nth resume is run N+1 (the backend
    // counts resumes, not runs).
    let run = resume_count + 1;

    // Human report first, then the server's record as the machine-readable
    // answer (both are stdout chatter, suppressed by --quiet / --json).
    if resumed {
        crawl_status_println!(
            "Crawl {} resumed (run {}). {}",
            id,
            run,
            crawl_resume_summary(skipped, remaining, resume_count)
        );
        if background {
            crawl_status_println!(
                "Use 'browser4-cli crawl status {}' or 'crawl list' to track progress.",
                id
            );
        }
    }

    cli_println!("{}", result);
    json_field("task_id", json!(id));
    json_field("resumed", json!(resumed));
    json_field("status", json!(status));
    json_field("message", json!(message));
    json_field("remaining", json!(remaining));
    json_field("skipped_already_fetched", json!(skipped));
    json_field("resume_count", json!(resume_count));

    if !resumed {
        // The server explains a no-op better than the CLI can: pass its message
        // through and fail, so `crawl resume` in a script is not mistaken for a
        // crawl that is now running.
        let reason = if message.is_empty() {
            "the server did not start a resumed run"
        } else {
            message
        };
        return Err(format!(
            "Crawl {} was not resumed: {}.\n\
             Inspect it with 'crawl status {}'; pass --force to attempt a resume anyway \
             (combine it with --retry-failed to fetch the URLs the task lost).",
            id, reason, id
        ));
    }

    if background {
        return Ok(());
    }

    // Poll the resumed run the same way `crawl <url>` does (2s cadence, quiet
    // periodic progress); the per-page listing is not duplicated here — the
    // user asked to continue a crawl, so a concise summary plus a pointer at
    // `crawl result <id>` is what is useful.
    let poll_interval = std::time::Duration::from_secs(2);
    let timeout = crawl_request_timeout();
    let start = std::time::Instant::now();
    let mut last_report = std::time::Duration::ZERO;
    let first_report_interval = std::time::Duration::from_secs(5);
    let report_interval = std::time::Duration::from_secs(10);
    // Signature of the last progress line: repeated identical counts are
    // suppressed, exactly as in handle_crawl.
    let mut last_report_pages: i64 = -1;
    let mut last_report_remaining: i64 = -1;
    // Pages already reported by --verbose, so each one is listed once.
    let mut reported_pages: HashSet<String> = HashSet::new();

    crawl_status_println!(
        "Waiting for the resumed crawl to finish. Use --background for long-running crawls."
    );

    loop {
        if start.elapsed() > timeout {
            let _ = update_async_task_status(
                id,
                &format!("timeout after {}s", timeout.as_secs()),
                None,
            );
            // Same contract as handle_crawl: the CLI's wait timing out does not
            // stop the task, which keeps running server-side.
            return Err(format!(
                "Resumed crawl timed out after {} seconds (CLI wait). Task ID: {}.\n\
                 The task keeps running server-side — poll it with:\n\
                   browser4-cli crawl status {}\n\
                   browser4-cli crawl result {}\n\
                 Increase the CLI wait with the BROWSER4_CLI_CRAWL_TIMEOUT_SECS environment variable.",
                timeout.as_secs(),
                id,
                id,
                id
            ));
        }

        tokio::time::sleep(poll_interval).await;

        let response_text = get_crawl_result(client, base_url, id).await?;
        let parsed: Value = serde_json::from_str(&response_text)
            .map_err(|e| format!("Failed to parse crawl response: {}", e))?;

        let status = parsed["status"].as_str().unwrap_or("");
        let pages_found = parsed["pagesFound"].as_i64().unwrap_or(0);
        let error = parsed["error"].as_str();

        // --verbose: list each page the resumed run records, marked as
        // restored-from-checkpoint or fetched-this-run — the distinction that
        // makes "the resume only had to fetch the rest" visible.
        if verbose {
            if let Some(pages) = parsed["pages"].as_array() {
                for page in pages {
                    let page_url = page["url"].as_str().unwrap_or("").to_string();
                    if page_url.is_empty() || !reported_pages.insert(page_url) {
                        continue;
                    }
                    crawl_status_println!("{}", crawl_result_page_row(page));
                }
            }
        }

        // Periodic progress indicator so a foreground resume doesn't look hung.
        // A resumed run re-fetches only what is left, so `remaining` is the
        // count that actually moves.
        let elapsed = start.elapsed();
        let interval = if last_report == std::time::Duration::ZERO {
            first_report_interval
        } else {
            report_interval
        };
        if elapsed - last_report >= interval {
            last_report = elapsed;
            let remaining = crawl_resume_bookkeeping(&parsed).remaining;
            if pages_found != last_report_pages || remaining != last_report_remaining {
                crawl_status_println!(
                    "Resumed crawl... {} page(s) recorded, {} URL(s) remaining ({}s elapsed)",
                    pages_found,
                    remaining,
                    elapsed.as_secs()
                );
                last_report_pages = pages_found;
                last_report_remaining = remaining;
            }
        }

        match status {
            "OK" | "SC_OK" => {
                let page_count = parsed["pages"].as_array().map(|p| p.len()).unwrap_or(0);
                crawl_status_println!(
                    "Resumed crawl {} finished (run {}, status {}). {} page(s) recorded.",
                    id,
                    run,
                    status,
                    page_count
                );
                if let Some(note) = crawl_resume_note(&parsed) {
                    crawl_status_println!("{}", note);
                }
                crawl_status_println!("Full page listing: browser4-cli crawl result {}", id);
                json_field("pages_found", json!(page_count));
                json_field("pages", json!(parsed["pages"]));
                // Keep local tracking honest, like handle_crawl's completion path.
                let _ = update_async_task_status(
                    id,
                    &format!("{} ({} pages)", status, page_count),
                    None,
                );
                return Ok(());
            }
            s if is_crawl_terminal_failure_status(s) => {
                let err_msg = error.unwrap_or("Unknown crawl error");
                let _ = update_async_task_status(id, &format!("error: {}", err_msg), None);
                let mut message = format!("Resumed crawl failed: {}", err_msg);
                if let Some(hint) = crawl_resume_hint(id, &parsed) {
                    message.push('\n');
                    message.push_str(&hint);
                }
                return Err(message);
            }
            s if is_interrupted_crawl_status(s) => {
                // The resumed worker died as well. Terminal again, and again
                // resumable: another `crawl resume` continues from the newer
                // checkpoint instead of re-fetching what this run got through.
                let _ = update_async_task_status(id, &friendly_crawl_status(s), None);
                return Err(crawl_interrupted_message(id, &parsed));
            }
            _ => {
                // Still running — reported on the periodic cadence above.
            }
        }
    }
}

/// What a resumed run restored and what is left, for the one-line resume
/// report: `7 already-fetched URL(s) restored from the checkpoint, 3 URL(s)
/// still to fetch (resume 1)`.
///
/// Both counts are always printed — including zeroes — because "nothing was
/// restored" and "3 URLs were restored" are the two outcomes a user needs to
/// tell apart, and an omitted count reads as unknown.
fn crawl_resume_summary(skipped: i64, remaining: i64, resume_count: i64) -> String {
    format!(
        "{} already-fetched URL(s) restored from the checkpoint, {} URL(s) still to fetch (resume {})",
        skipped, remaining, resume_count
    )
}

/// Resolve @file references and --args-stdin in crawl args.
/// Returns None if both raw_args and stdin are empty; otherwise
/// returns the joined resolved args string.
///
/// Only `@file` tokens are replaced: every other byte is kept verbatim, so a
/// quoted value keeps its internal spacing instead of being re-joined token by
/// token with single spaces.
fn resolve_crawl_args_fallible(
    raw_args: &str,
    args_stdin_content: Option<&str>,
) -> Result<Option<String>, String> {
    if raw_args.is_empty() && args_stdin_content.is_none() {
        return Ok(None);
    }
    let mut resolved = String::with_capacity(raw_args.len());
    let mut cursor = 0usize;
    for (start, end) in crawl_option_spans(raw_args) {
        let token = &raw_args[start..end];
        if let Some(file_path) = token.strip_prefix('@') {
            let content = std::fs::read_to_string(file_path)
                .map_err(|e| format!("Failed to read args file '{}': {}", file_path, e))?;
            resolved.push_str(&raw_args[cursor..start]);
            resolved.push_str(content.trim());
            cursor = end;
        }
    }
    resolved.push_str(&raw_args[cursor..]);
    if let Some(stdin_content) = args_stdin_content {
        if !resolved.is_empty() && !stdin_content.is_empty() {
            resolved.push(' ');
        }
        resolved.push_str(stdin_content);
    }
    Ok(Some(resolved))
}

/// Build the server-bound params for a crawl submission by stripping
/// CLI-only keys and injecting resolved values (urls, sql, args).
fn build_crawl_server_params(
    tool_params: &Value,
    urls: &[String],
    resolved_sql: Option<&str>,
    resolved_args: Option<&str>,
) -> Value {
    let mut server_params = tool_params.clone();
    if let Value::Object(ref mut m) = server_params {
        m.remove("seedFile");
        m.remove("sqlStdin");
        m.remove("sqlBase64");
        m.remove("argsStdin");
        m.remove("format");
        m.remove("output");
        // CLI-only switches: read back from `tool_params` by the CLI itself, never by the
        // backend (`CrawlRequest` has no such fields), so they must not ride along.
        m.remove("background");
        m.remove("verbose");
        m.remove("out-link-selector");
        m.remove("out-link-pattern");
        // --parallel is a CLI spelling: the backend field is `parallelTabs`.
        // Translate it here (rather than sending `parallel`) so the server
        // never has to accept two names for one budget.
        if let Some(value) = m.remove("parallel") {
            if let Some(n) = value
                .as_str()
                .and_then(|s| s.trim().parse::<u32>().ok())
                .or_else(|| value.as_u64().map(|n| n as u32))
            {
                m.insert("parallelTabs".to_string(), json!(n));
            }
        }
        // --timeout is a CLI spelling too: the backend field is `taskTimeoutMillis`, and the
        // value is a user-facing duration there (`10m`), so it is converted here.
        if let Some(value) = m.remove("timeout") {
            if let Some(millis) = value.as_str().and_then(crawl_timeout_to_millis) {
                m.insert("taskTimeoutMillis".to_string(), json!(millis));
            }
        }
        // --depth arrives as the typed string so it could be refused before submission
        // (validate_crawl_depth); the server field is an Int.
        if let Some(value) = m.remove("depth") {
            if let Some(n) = value
                .as_i64()
                .or_else(|| value.as_str().and_then(|s| s.trim().parse::<i64>().ok()))
            {
                m.insert("depth".to_string(), json!(n));
            }
        }
        // Insert resolved urls array
        let url_array: Vec<Value> = urls.iter().map(|u| json!(u)).collect();
        m.insert("urls".to_string(), json!(url_array));
        // Insert resolved sql
        if let Some(sql) = resolved_sql {
            m.insert("sql".to_string(), json!(sql));
        }
        // Override args with resolved value (handles @file and stdin)
        if let Some(args) = resolved_args {
            m.insert("args".to_string(), json!(args));
        } else {
            // Ensure args is always present (Kotlin non-null)
            m.entry("args".to_string()).or_insert(json!(""));
        }
        // Ensure url is set to the first URL for backward compat
        let url = tool_params
            .get("url")
            .and_then(|v| v.as_str())
            .unwrap_or("");
        if url.is_empty() {
            m.insert("url".to_string(), json!(urls[0]));
        }
    }
    server_params
}

/// Validate the --format value. Returns Ok(()) for valid formats,
/// Err with a message for invalid ones.
fn validate_crawl_format(format: &str) -> Result<(), String> {
    match format {
        "json" | "csv" | "table" => Ok(()),
        other => Err(format!(
            "Invalid --format '{}'. Expected: json, csv, or table",
            other
        )),
    }
}

/// Upper bound accepted for `--parallel`.
///
/// Must match `CrawlService.MAX_PARALLEL_TABS`; the backend rejects anything
/// larger, and catching it here turns a round trip into an immediate message.
const CRAWL_MAX_PARALLEL_TABS: u32 = 32;

/// Validate the --parallel value: a positive tab count within the server's
/// ceiling. An absent/empty value is fine (the backend's default applies).
fn validate_crawl_parallel(value: &str) -> Result<(), String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(());
    }
    match value.parse::<u32>() {
        Ok(n) if n >= 1 && n <= CRAWL_MAX_PARALLEL_TABS => Ok(()),
        Ok(0) => Err(
            "Invalid --parallel value '0'. Use --parallel 1 for a strictly sequential crawl, \
             or omit --parallel to use the server default"
                .to_string(),
        ),
        Ok(n) => Err(format!(
            "Invalid --parallel value '{}'. The maximum is {}, because every parallel unit needs \
             its own browser tab",
            n, CRAWL_MAX_PARALLEL_TABS
        )),
        Err(_) => Err(format!(
            "Invalid --parallel value '{}'. Expected a positive integer (number of tabs to \
             collect with at the same time)",
            value
        )),
    }
}

/// Validate the --depth value: a non-negative integer. An absent/empty value
/// means the default (1).
///
/// The backend treats anything `<= 1` as one link level, so a rejected typo used
/// to read as a perfectly ordinary crawl: `--depth abc` became 1 (silently) and
/// `--depth -1` became 1 too, while the command description still printed the
/// value the user typed.
fn validate_crawl_depth(value: &str) -> Result<i64, String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(1);
    }
    match value.parse::<i64>() {
        Ok(n) if n >= 0 => Ok(n),
        Ok(_) => Err(format!(
            "Invalid --depth value '{}'. Depth is a non-negative integer: 0 fetches the seed \
             page only, 1 follows one link level",
            value
        )),
        Err(_) => Err(format!(
            "Invalid --depth value '{}'. Expected a non-negative integer (0 = the seed page \
             only, 1 = follow one link level)",
            value
        )),
    }
}

/// Task-budget range the server accepts for one crawl, in milliseconds.
///
/// Must match `CrawlSupport.MIN_REQUEST_TASK_TIMEOUT_MS` / `MAX_REQUEST_TASK_TIMEOUT_MS`:
/// the server clamps into this range, and clamping silently is exactly what a caller cannot
/// see — so the CLI refuses the value up front, while the response still reports the budget
/// that was used (mirroring `--parallel`).
const CRAWL_MIN_TASK_TIMEOUT_MS: i64 = 1_000;
const CRAWL_MAX_TASK_TIMEOUT_MS: i64 = 3_600_000;

/// A task budget in milliseconds: a plain integer means seconds (the same reading the load
/// options use), and `ms`/`s`/`m`/`h`/`d` suffixes are honoured. `None` when the value is not
/// a duration at all.
///
/// Delegates to [commands::crawl_timeout_to_millis] so `--timeout` is validated and
/// translated by exactly one implementation (the CLI-side copy had drifted into a
/// second parser).
fn crawl_timeout_to_millis(value: &str) -> Option<i64> {
    commands::crawl_timeout_to_millis(value)
}

/// Validate the --timeout value: a duration inside the range one request may ask for.
///
/// An absent/empty value is fine (the server's 10-minute default applies). The budget is
/// what makes a large crawl end with an accounted-for TIMEOUT instead of being killed
/// mid-flight, so a value the user cannot have meant must fail here rather than quietly
/// become the default.
fn validate_crawl_timeout(value: &str) -> Result<(), String> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(());
    }
    let millis = crawl_timeout_to_millis(value).ok_or_else(|| {
        format!(
            "Invalid --timeout value '{}'. Expected seconds (900) or a duration such as 30s, \
             10m, 1h",
            value
        )
    })?;
    if millis < CRAWL_MIN_TASK_TIMEOUT_MS {
        return Err(format!(
            "Invalid --timeout value '{}'. The minimum is 1s: a crawl with no time at all \
             cannot start a single round",
            value
        ));
    }
    if millis > CRAWL_MAX_TASK_TIMEOUT_MS {
        return Err(format!(
            "Invalid --timeout value '{}'. The maximum is 1h, because the budget buys browser \
             time; split the work across several crawls",
            value
        ));
    }
    Ok(())
}

/// The parallelism report for a finished crawl: the budget it ran under and the
/// peak number of fetch units it actually had in flight.
///
/// A *unit* is one seed URL's fetch-and-extract round (one browser tab while it
/// runs); links discovered inside a unit are fetched from the shared tab pool.
/// The line spells that out because "peak 1 unit(s) in flight" on a 11-page
/// single-seed crawl read as "the flag was ignored" (#115140#5) — one seed can
/// never peak above 1, and a peak of 1 with several units means the collection
/// was serial no matter what `--parallel` asked for, which is exactly the
/// failure a parallelism budget exists to prevent.
fn crawl_parallelism_note(parsed: &Value) -> Option<String> {
    let budget = parsed["parallelTabs"].as_i64().unwrap_or(0);
    if budget <= 0 {
        return None;
    }
    let peak = parsed["maxConcurrentFetches"].as_i64().unwrap_or(0);
    let units = parsed["seedStatuses"]
        .as_array()
        .map(|a| a.len())
        .unwrap_or(0);
    let verdict = if peak <= 1 && units > 1 {
        " — nothing overlapped: the units were collected one at a time"
    } else {
        ""
    };
    Some(format!(
        "Parallelism: budget {} tab(s), peak {} seed unit(s) in flight{} \
         (a unit is one seed URL's fetch-and-extract round, one tab each; \
         links found inside a unit come from the shared tab pool)",
        budget, peak, verdict
    ))
}

/// Whether a value is a load-options duration: a plain integer or an integer
/// with an ms/s/m/h/d suffix, e.g. `30`, `30s`, `1m`, `1h`, `1d`.
///
/// A plain number is seconds because [commands::load_option_duration] attaches the
/// `s` unit before the value reaches the backend, which would otherwise read it as
/// milliseconds (and read a single digit as an invalid, always-expired duration).
fn is_duration_value(value: &str) -> bool {
    let value = value.trim();
    let suffixes = ["ms", "s", "m", "h", "d"];
    let number_part = suffixes
        .iter()
        .find_map(|suffix| value.strip_suffix(suffix))
        .unwrap_or(value);
    !number_part.is_empty() && number_part.chars().all(|c| c.is_ascii_digit())
}

/// Byte spans of the tokens in a raw LoadOptions string, split the way the
/// backend splits it (`PulsarOptions.split`, pattern `"…"|\S+`): a
/// double-quoted segment is one token (backslash escapes honored), anything
/// else is a non-whitespace run.
///
/// `split_whitespace()` tears a quoted value apart, so `-outLink "a[href*='x y']"`
/// looked like three tokens — validation then read half a value, and an option
/// *name* written inside a quoted value could be mistaken for a real option.
fn crawl_option_spans(args: &str) -> Vec<(usize, usize)> {
    let mut spans = Vec::new();
    let mut i = 0usize;
    let len = args.len();
    while i < len {
        let ch = args[i..].chars().next().unwrap();
        if ch.is_whitespace() {
            i += ch.len_utf8();
            continue;
        }
        let start = i;
        if ch == '"' {
            // A quoted token: scan to the closing quote, skipping escaped characters.
            let mut j = start + 1;
            let mut close = None;
            while j < len {
                let c = args[j..].chars().next().unwrap();
                if c == '\\' {
                    j += c.len_utf8();
                    if let Some(escaped) = args[j..].chars().next() {
                        j += escaped.len_utf8();
                    }
                } else if c == '"' {
                    close = Some(j + 1);
                    break;
                } else {
                    j += c.len_utf8();
                }
            }
            if let Some(end) = close {
                let ends_the_token = args[end..]
                    .chars()
                    .next()
                    .map(|c| c.is_whitespace())
                    .unwrap_or(true);
                if ends_the_token {
                    spans.push((start, end));
                    i = end;
                    continue;
                }
            }
        }
        // A plain token: a non-whitespace run.  An unterminated quote starts one
        // too — the backend's `\S+` alternative matches the same characters.
        let mut j = start;
        while j < len {
            let c = args[j..].chars().next().unwrap();
            if c.is_whitespace() {
                break;
            }
            j += c.len_utf8();
        }
        spans.push((start, j));
        i = j;
    }
    spans
}

/// The tokens of a raw LoadOptions string, quote-aware.
fn crawl_option_tokens(args: &str) -> Vec<&str> {
    crawl_option_spans(args)
        .into_iter()
        .map(|(start, end)| &args[start..end])
        .collect()
}

/// Validate typed load-option values embedded in the crawl args string
/// (`-expires`, `-pageLoadTimeout`, `-priority`, `-topLinks`). The backend
/// silently defaults malformed values, so the CLI must reject them loudly —
/// mirroring the existing `--format` reject-with-nonzero-exit pattern.
/// Returns Ok(()) when every recognized option carries a valid value.
fn validate_crawl_option_tokens(args: &str) -> Result<(), String> {
    let tokens = crawl_option_tokens(args);
    let mut i = 0;
    while i < tokens.len() {
        let token = tokens[i];
        let (key, inline_value) = match token.split_once('=') {
            Some((key, value)) => (key, Some(value)),
            None => (token, None),
        };
        // Accept both single-dash (backend LoadOptions form) and
        // double-dash (user-facing flag form) spellings.
        let key = key.trim_start_matches('-');
        match key {
            "expires" | "pageLoadTimeout" | "page-load-timeout" => {
                // The value token: inline after '=' when present, otherwise the
                // next whitespace-separated token.
                let value = match inline_value {
                    Some(v) => v.to_string(),
                    None => tokens
                        .get(i + 1)
                        .map(|v| v.to_string())
                        .ok_or_else(|| {
                            format!("Missing value for '--{}' in crawl load options", key)
                        })?,
                };
                if !is_duration_value(&value) {
                    return Err(format!(
                        "Invalid --{} value '{}'. Expected a duration such as 30s, 1m, 1h, 1d (or a plain number of seconds)",
                        key,
                        value
                    ));
                }
                // A one-character value (`5`, `0`) is shorter than the backend's
                // duration parser accepts: it answers its "invalid duration" sentinel,
                // which reads as *always expired* (so `--readonly --expires 5` silently
                // fetches instead of serving the store). The unit must be spelled out.
                if value.trim().len() < 2 {
                    return Err(format!(
                        "Invalid --{} value '{}'. Write the unit too ({}s): the backend cannot \
                         parse a bare single digit and treats it as an always-expired cache",
                        key,
                        value,
                        value.trim()
                    ));
                }
                if inline_value.is_none() {
                    i += 1;
                }
            }
            "priority" => {
                let value = match inline_value {
                    Some(v) => v.to_string(),
                    None => tokens
                        .get(i + 1)
                        .map(|v| v.to_string())
                        .ok_or_else(|| {
                            format!("Missing value for '--{}' in crawl load options", key)
                        })?,
                };
                match value.parse::<i64>() {
                    Ok(priority) if priority >= 0 => {}
                    Ok(_) => {
                        return Err(format!(
                            "Invalid --priority value '{}'. Priority must be a non-negative integer (lower = higher priority)",
                            value
                        ));
                    }
                    Err(_) => {
                        return Err(format!(
                            "Invalid --priority value '{}'. Expected an integer (lower = higher priority)",
                            value
                        ));
                    }
                }
                if inline_value.is_none() {
                    i += 1;
                }
            }
            "topLinks" | "top-links" => {
                // A malformed value does not merely lose this option: the whole
                // LoadOptions parse fails, so every other option in the string falls
                // back to its default *and* the outLink selector/pattern quote fix
                // is skipped — the crawl then discovers zero links with no trace.
                let value = match inline_value {
                    Some(v) => v.to_string(),
                    None => tokens
                        .get(i + 1)
                        .map(|v| v.to_string())
                        .ok_or_else(|| {
                            format!("Missing value for '--{}' in crawl load options", key)
                        })?,
                };
                match value.parse::<i64>() {
                    Ok(n) if n >= 0 => {}
                    Ok(_) => {
                        return Err(format!(
                            "Invalid --top-links value '{}'. Expected a non-negative integer",
                            value
                        ));
                    }
                    Err(_) => {
                        return Err(format!(
                            "Invalid --top-links value '{}'. Expected an integer (maximum links extracted per page)",
                            value
                        ));
                    }
                }
                if inline_value.is_none() {
                    i += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    Ok(())
}

/// Whether the crawl args string carries any of [names] as a load option.
///
/// Tokens must start with `-`, so an option *value* never counts (`-expires 1d`
/// contributes `1d`, which does not start with `-`); the `=` spelling
/// (`-expires=1d`) is recognized.  Tokens are split quote-aware, so a `-expires`
/// written *inside* a quoted value (`-outLink "a -expires b"`) is not the option.
fn crawl_args_have_option(args: &str, names: &[&str]) -> bool {
    crawl_option_tokens(args).into_iter().any(|token| {
        if !token.starts_with('-') {
            return false;
        }
        let key = token.split_once('=').map(|(key, _)| key).unwrap_or(token);
        names.contains(&key.trim_start_matches('-'))
    })
}

/// The schemes a crawl seed may use.
///
/// Mirrors `URLUtils.isStandard` on the server, which accepts http(s) and `file:`.  Anything else
/// (`ftp:`, `mailto:`, `data:`) parses as a URL but is not a document this pipeline fetches, and
/// the submission boundary refuses it — the CLI must not be more permissive than the boundary it
/// feeds.
const CRAWL_SEED_SCHEMES: [&str; 3] = ["http", "https", "file"];

/// What a crawl seed has to be, spelled the same way in every refusal.
const CRAWL_SEED_EXPECTATION: &str =
    "expected an absolute http(s) or file:/// URL such as https://example.com/page";

/// How many refused seeds one message spells out; the rest are counted.
const MAX_REPORTED_CRAWL_SEED_PROBLEMS: usize = 5;

/// The url part of a seed.
///
/// A seed may carry trailing LoadOptions (`https://example.com -expires 1d`), exactly like the
/// scrape payloads do — the server splits them with `URLUtils.splitUrlArgs` — so only the first
/// whitespace-separated token is the address.
fn crawl_seed_url_part(seed: &str) -> &str {
    seed.trim().split_whitespace().next().unwrap_or("")
}

/// Why [seed] cannot start a crawl, or `None` when it can.
///
/// `crawl formats` used to be submitted like any other seed: the fetcher substituted its default
/// search-engine url for the page nobody asked for, the task reported `0 pages found` and the CLI
/// exited 0 — a typo that looked exactly like an empty site (issue #616).  The backend refuses such
/// a seed at the submission boundary (`Malformed url: <...>`), so the CLI refuses it here, before
/// the server is launched and before a task exists.
fn crawl_seed_problem(seed: &str) -> Option<String> {
    let raw = crawl_seed_url_part(seed);
    // An absent seed is reported as "No URLs provided", not as a malformed one.
    if raw.is_empty() {
        return None;
    }

    // Checked before the parser: a schemeless address with a port (`localhost:18080/ec`) does
    // *parse* — as a URL whose scheme is `localhost` — so trusting the parse first would report an
    // unsupported scheme where the user only forgot `https://`.
    if let Some(url) = crawl_seed_https_hint(raw) {
        return Some(format!("did you mean '{url}'?"));
    }

    match reqwest::Url::parse(raw) {
        Ok(parsed) => {
            let scheme = parsed.scheme();
            if !CRAWL_SEED_SCHEMES.contains(&scheme) {
                return Some(format!("unsupported scheme '{scheme}' — {CRAWL_SEED_EXPECTATION}"));
            }
            // `file:///tmp/a.html` legitimately has an empty host; http(s) never does.
            if scheme != "file" && parsed.host_str().unwrap_or("").is_empty() {
                return Some(CRAWL_SEED_EXPECTATION.to_string());
            }
            None
        }
        Err(_) => Some(CRAWL_SEED_EXPECTATION.to_string()),
    }
}

/// The `https://` spelling of a seed that is a plausible address without its scheme
/// (`amazon.com`, `www.example.com/product/7`, `localhost:18080/ec`) — the one typo a crawl seed
/// is most likely to be, and the one a bare "expected an absolute URL" cannot act on.
fn crawl_seed_https_hint(raw: &str) -> Option<String> {
    if raw.is_empty() || raw.contains("://") {
        return None;
    }
    let authority = raw.split(|c| c == '/' || c == '?' || c == '#').next().unwrap_or("");
    // A colon is a port (`localhost:18080`) or the value is not an address at all
    // (`mailto:a@b.com`, `data:text/html`, `C:\tmp\a.html`).
    let host = match authority.rsplit_once(':') {
        Some((host, port)) if !port.is_empty() && port.chars().all(|c| c.is_ascii_digit()) => host,
        Some(_) => return None,
        None => authority,
    };
    let is_host = host == "localhost"
        || (host.contains('.')
            && !host.starts_with('.')
            && !host.ends_with('.')
            && host
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '-' | '_')));
    if is_host {
        Some(format!("https://{raw}"))
    } else {
        None
    }
}

/// The refusal for one seed, or `None` when the seed is fine.
///
/// [origin] names where the value came from (`command argument`, `urls.txt line 3`), so a refused
/// seed in a large seed file can be found instead of only recognized.
fn crawl_seed_refusal(seed: &str, origin: &str) -> Option<String> {
    crawl_seed_problem(seed).map(|problem| {
        // The hint form of the problem already ends with '?' ("did you mean
        // 'https://…'?") — appending the sentence period unconditionally
        // produced the double terminator "?.".
        let terminator = if problem.ends_with(['.', '?', '!']) { "" } else { "." };
        format!("Invalid crawl URL '{seed}' ({origin}): {problem}{terminator}")
    })
}

/// Resolve the URL list for a crawl: combines the direct URL argument with URLs from the seed file
/// (if any).
///
/// Fails with [ExitCode::Usage] — "bad URL" in the exit code's own terms — when a seed is not a URL
/// a crawl can fetch, and with the historical [ExitCode::General] when there is nothing to crawl: a
/// seed the backend will refuse must not be submitted, and a typo must exit like the usage error it
/// is whether it was typed as the argument or written into a seed file. Lines starting with `#` and
/// blank lines are ignored in seed file content.
///
/// [seed_file] is the file's `(path, content)`, so a refused seed can name the file and the line it
/// came from.  Values are trimmed, including the direct argument.
fn resolve_crawl_urls(url: &str, seed_file: Option<(&str, &str)>) -> Result<Vec<String>, CliError> {
    // (value, where it came from) — the provenance is only used for a refusal.
    let mut seeds: Vec<(String, String)> = Vec::new();
    if !url.trim().is_empty() {
        seeds.push((url.trim().to_string(), "command argument".to_string()));
    }
    if let Some((path, content)) = seed_file {
        for (index, line) in content.lines().enumerate() {
            let line = line.trim();
            if !line.is_empty() && !line.starts_with('#') {
                seeds.push((line.to_string(), format!("{path} line {}", index + 1)));
            }
        }
    }
    if seeds.is_empty() {
        return Err(CliError(
            ExitCode::General,
            "No URLs provided. Specify a URL argument or --seed-file.".to_string(),
        ));
    }

    let refusals: Vec<String> = seeds
        .iter()
        .filter_map(|(value, origin)| crawl_seed_refusal(value, origin))
        .collect();
    if refusals.len() == 1 {
        let refusal = refusals.into_iter().next().unwrap_or_default();
        return Err(CliError(ExitCode::Usage, refusal));
    }
    if !refusals.is_empty() {
        let shown = refusals.len().min(MAX_REPORTED_CRAWL_SEED_PROBLEMS);
        let mut message = format!(
            "{} of {} crawl seeds are not URLs a crawl can fetch:\n  {}",
            refusals.len(),
            seeds.len(),
            refusals[..shown].join("\n  ")
        );
        if refusals.len() > shown {
            message.push_str(&format!("\n  … and {} more", refusals.len() - shown));
        }
        return Err(CliError(ExitCode::Usage, message));
    }

    Ok(seeds.into_iter().map(|(value, _)| value).collect())
}

/// Parse the crawl poll response and classify its status.
///
/// Mirrors the poll loop's terminal branches: `Interrupted` is terminal (the
/// worker died with the backend process, so a poller must stop waiting) and
/// resumable, which is why it is neither `Error` nor `Running`.
#[cfg(test)]
#[derive(Debug, PartialEq)]
enum CrawlPollStatus {
    /// Crawl completed successfully.
    Done { pages_found: i64 },
    /// Crawl failed with a terminal error.
    Error { message: String },
    /// Crawl's worker died with the backend process; `crawl resume` continues it.
    Interrupted,
    /// Crawl is still in progress.
    Running { pages_found: i64 },
}

#[cfg(test)]
fn parse_crawl_poll_response(parsed: &Value) -> CrawlPollStatus {
    let status = parsed["status"].as_str().unwrap_or("");
    let pages_found = parsed["pagesFound"].as_i64().unwrap_or(0);
    let error = parsed["error"].as_str();

    match status {
        "OK" | "SC_OK" => CrawlPollStatus::Done { pages_found },
        "SC_REQUEST_TIMEOUT" | "SC_INTERNAL_SERVER_ERROR" => CrawlPollStatus::Error {
            message: error.unwrap_or("Unknown crawl error").to_string(),
        },
        s if is_interrupted_crawl_status(s) => CrawlPollStatus::Interrupted,
        _ => CrawlPollStatus::Running { pages_found },
    }
}

/// Write crawl output string to either a file or return it for stdout display.
/// Returns the written content when no output file is specified (caller prints),
/// or a confirmation message when written to a file.
#[derive(Debug)]
enum CrawlOutput {
    Stdout(String),
    FileWritten { path: String, summary: String },
}

fn write_crawl_output(
    content: &str,
    output_file: Option<&str>,
    summary: &str,
) -> Result<CrawlOutput, String> {
    if let Some(file_path) = output_file {
        std::fs::write(file_path, content)
            .map_err(|e| format!("Failed to write output file '{}': {}", file_path, describe_io_error(&e)))?;
        Ok(CrawlOutput::FileWritten {
            path: file_path.to_string(),
            summary: summary.to_string(),
        })
    } else {
        Ok(CrawlOutput::Stdout(content.to_string()))
    }
}

/// Failure accounting for a terminal crawl: `(ok_pages, failed)`.
///
/// The primary signal is `failedPages` — the backend's own loss ledger of URLs
/// it submitted and never got a page back for.  It is disjoint from `pages`
/// (`pagesFound + failedPages.size == pagesExpected`), so the ledger alone
/// gives a coherent split of the crawl's work items.
///
/// Delivered pages that failed X-SQL extraction (`extractionError`) or came
/// back with a 0-byte body are added on top: they are pages the crawl *did*
/// deliver but which carry no usable content, and they are never part of the
/// loss ledger.  Historical crawl rows carry no `failedPages` at all; there
/// the per-page errors and seed-level errors are the only backstop, and the
/// two are not summed (a seed that errors is normally also a lost page, so
/// adding both would report more failures than the crawl had work items).
fn crawl_failure_counts(parsed: &Value, page_count: usize) -> (usize, usize) {
    let broken_pages = parsed["pages"]
        .as_array()
        .map(|pages| {
            pages
                .iter()
                .filter(|pg| {
                    pg["extractionError"].as_str().is_some()
                        || pg["contentLength"].as_i64().unwrap_or(-1) == 0
                })
                .count()
        })
        .unwrap_or(0);

    let seed_errors = parsed["seedStatuses"]
        .as_array()
        .map(|statuses| {
            statuses
                .iter()
                .filter(|s| s["status"].as_str().unwrap_or("") == "error")
                .count()
        })
        .unwrap_or(0);

    let failed = match parsed["failedPages"].as_array() {
        Some(lost) => lost.len() + broken_pages,
        None => broken_pages.max(seed_errors),
    };
    (page_count.saturating_sub(broken_pages), failed)
}

/// The first per-page failure reason the terminal crawl payload carries.
///
/// The reason exists per page (`pages[].extractionError`, or the backend's loss
/// ledger `failedPages[].reason`) but was only reachable through
/// `crawl result <id> --verbose`; naming it where the completion line is
/// printed makes the cause visible next to the counts it explains.
fn crawl_first_failure_reason(parsed: &Value) -> Option<String> {
    let from_pages = parsed["pages"].as_array().and_then(|pages| {
        pages.iter().find_map(|page| {
            page["extractionError"]
                .as_str()
                .map(str::trim)
                .filter(|reason| !reason.is_empty())
                .map(String::from)
        })
    });
    let from_ledger = parsed["failedPages"].as_array().and_then(|lost| {
        lost.iter().find_map(|page| {
            page["reason"]
                .as_str()
                .map(str::trim)
                .filter(|reason| !reason.is_empty())
                .map(String::from)
        })
    });
    from_pages.or(from_ledger)
}

/// The completion line for a crawl that delivered rows.
///
/// `attempted` is the number of pages the crawl *tried*; the payload's
/// `failedPages` / `pagesExpected` split that into delivered and lost, and
/// [`crawl_failure_counts`] folds in pages that came back with no usable
/// content.  Reporting `attempted` as "pages crawled" announced "10 pages
/// crawled" for a run whose every page failed extraction — one line above
/// "Summary: ok: 0, failed: 10" — so when anything failed the line names the
/// successes, the expected total and the first reason instead.
fn crawl_completion_line(parsed: &Value, attempted: usize, rows: usize) -> String {
    // Share the terminal accounting with the tracked-status label so the line a
    // crawl prints and the row `crawl list` stores can never disagree.
    let (failed, expected, ok_pages) = crawl_terminal_page_accounting(parsed);
    if failed == 0 {
        return format!("{attempted} pages crawled, {rows} rows extracted.");
    }
    let reason = crawl_first_failure_reason(parsed)
        .map(|reason| {
            let single_line = reason.replace(['\r', '\n'], " ");
            let shown = if single_line.chars().count() > 120 {
                format!("{}…", single_line.chars().take(119).collect::<String>())
            } else {
                single_line
            };
            format!(" — first failure: {shown}")
        })
        .unwrap_or_default();
    format!(
        "{ok_pages} of {expected} page(s) crawled ({failed} failed){reason}, {rows} rows extracted. \
         Use `crawl result <id> --verbose` for every failed page."
    )
}

/// The label a tracked crawl task should carry for a terminal payload.
///
/// The backend keeps `status = OK` for a crawl whose pages partly failed — by
/// design, so a poller stops on the terminal status — which is why a run that
/// exited 6 was stored as "completed" and `crawl list --status failed` could
/// never find it (#115140#3).  `status` still decides the *lifecycle* label
/// (queued / processing / completed / interrupted / failed…), and the payload's
/// loss ledger decides whether that "completed" was clean.
fn crawl_tracked_status_label(status: &str, parsed: &Value) -> String {
    let friendly = friendly_crawl_status(status);
    if friendly != "completed" {
        return friendly;
    }
    let (failed, expected, ok_pages) = crawl_terminal_page_accounting(parsed);
    if failed == 0 {
        return friendly;
    }
    format!("partial failure ({ok_pages} of {expected} pages ok)")
}

/// `(failed_pages, expected_pages, successful_pages)` for a terminal crawl
/// payload, derived from the backend's own accounting.
///
/// * `failedPages` is the loss ledger of URLs the crawl never got a page back
///   for; a page that was delivered but carries no usable content
///   (`extractionError`, or a 0-byte body) counts as a failure too;
/// * `pagesFound` is the delivered count, so successes are the delivered pages
///   that produced content;
/// * `pagesExpected` is the backend's own work-item total
///   (`pagesFound + failedPages.size`); when it is absent the two counts are
///   summed, so a historical row still reports a coherent denominator.
fn crawl_terminal_page_accounting(parsed: &Value) -> (usize, usize, usize) {
    let broken_pages = parsed["pages"]
        .as_array()
        .map(|pages| {
            pages
                .iter()
                .filter(|page| {
                    page["extractionError"].as_str().is_some()
                        || page["contentLength"].as_i64().unwrap_or(-1) == 0
                })
                .count()
        })
        .unwrap_or(0);
    let seed_errors = parsed["seedStatuses"]
        .as_array()
        .map(|statuses| {
            statuses
                .iter()
                .filter(|status| status["status"].as_str().unwrap_or("") == "error")
                .count()
        })
        .unwrap_or(0);

    let (lost_pages, failed) = match parsed["failedPages"].as_array() {
        Some(lost) => (lost.len(), lost.len() + broken_pages),
        // Without the ledger the two failure signals overlap (a seed that errors
        // is normally also a lost page), so the larger one is the honest count.
        None => (0, broken_pages.max(seed_errors)),
    };

    let delivered = parsed["pagesFound"]
        .as_i64()
        .map(|found| found.max(0) as usize)
        .or_else(|| parsed["pages"].as_array().map(|pages| pages.len()))
        .unwrap_or(0);
    let ok_pages = delivered.saturating_sub(broken_pages);
    let expected = parsed["pagesExpected"]
        .as_i64()
        .map(|value| value.max(0) as usize)
        .filter(|value| *value > 0)
        .unwrap_or_else(|| ok_pages + failed.max(lost_pages));
    (failed, expected, ok_pages)
}

async fn handle_crawl(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
    _session_name: Option<&str>,
) -> Result<(), CliError> {
    // ---- Resolve URLs ----
    let url = tool_params
        .get("url")
        .and_then(|v| v.as_str())
        .unwrap_or("");

    let seed_file = tool_params.get("seedFile").and_then(|v| v.as_str());

    let seed_content: Option<String> = match seed_file {
        Some(file_path) => {
            let content = std::fs::read_to_string(file_path)
                .map_err(|e| format!("Failed to read seed file '{}': {}", file_path, describe_io_error(&e)))?;
            Some(content)
        }
        None => None,
    };

    let urls = resolve_crawl_urls(url, seed_file.zip(seed_content.as_deref()))?;

    // ---- Validate the crawl depth ----
    let depth = validate_crawl_depth(
        tool_params.get("depth").and_then(|v| v.as_str()).unwrap_or(""),
    )?;

    // ---- Validate the browser choice ----
    // `--session` and `--profile` name two different browsers; the backend refuses the pair
    // with `require(fetchSession == null || profile == null)`, which only reaches the user
    // after a round trip and a server-side stack trace.
    {
        let fetch_session = tool_params
            .get("fetchSession")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim();
        let profile = tool_params
            .get("profile")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim();
        if !fetch_session.is_empty() && !profile.is_empty() {
            return Err(
                "--session and --profile are mutually exclusive. --session borrows a live \
                 session's browser; --profile launches the crawl's own browser on that Chrome \
                 user-data directory. Name one browser."
                    .into(),
            );
        }
    }

    // ---- Resolve X-SQL query ----
    let use_sql_stdin = tool_params
        .get("sqlStdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let query_raw: Option<String> = if use_sql_stdin {
        let mut input = String::new();
        std::io::stdin()
            .read_to_string(&mut input)
            .map_err(|e| format!("Failed to read X-SQL query from stdin: {e}"))?;
        if input.trim().is_empty() {
            return Err("Stdin was empty but --sql-stdin was specified.".into());
        }
        Some(input)
    } else {
        tool_params
            .get("sql")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string())
    };

    // `--sql-base64 <value>` supplies the query itself, with no `--sql` next to it.
    // Without this branch that shape was dropped on the floor: the value was neither
    // decoded nor reported, and the crawl ran with an empty SQL.
    let has_sql_base64_value = tool_params
        .get("sqlBase64")
        .and_then(|v| v.as_str())
        .map(|s| !s.trim().is_empty())
        .unwrap_or(false);

    // An empty inline value is not a query: it would be submitted as a blank statement and
    // come back as an X-SQL engine error instead of a usage error. (`--sql-base64 <value>`
    // supplies the query itself, so an accompanying empty `--sql` is irrelevant there.)
    if !has_sql_base64_value
        && query_raw
            .as_deref()
            .map(|q| q.trim().is_empty())
            .unwrap_or(false)
    {
        return Err(
            "The --sql value is empty. Provide a query, @file.sql, --sql-stdin, or --sql-base64."
                .into(),
        );
    }

    let has_sql = query_raw.is_some() || has_sql_base64_value;
    let resolved_sql: Option<String> = match query_raw {
        Some(q) if q.starts_with('@') => {
            let file_path = &q[1..];
            // Decode after `@file`, so a base64-encoded query file works too.
            Some(maybe_decode_base64_sql(resolve_sql_file(file_path)?, tool_params)?)
        }
        Some(q) => Some(maybe_decode_base64_sql(q, tool_params)?),
        // Mode 1 of `maybe_decode_base64_sql` reads the value from `sqlBase64`; the
        // empty argument is only the placeholder that shape never uses.
        None if has_sql_base64_value => {
            Some(maybe_decode_base64_sql(String::new(), tool_params)?)
        }
        None => None,
    };

    // ---- Resolve args: @file prefix and --args-stdin ----
    let use_args_stdin = tool_params
        .get("argsStdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let args_stdin_content: Option<String> = if use_args_stdin {
        let mut input = String::new();
        std::io::stdin()
            .read_to_string(&mut input)
            .map_err(|e| format!("Failed to read args from stdin: {e}"))?;
        if input.trim().is_empty() {
            return Err("Stdin was empty but --args-stdin was specified.".into());
        }
        Some(input.trim().to_string())
    } else {
        None
    };

    let raw_args = tool_params
        .get("args")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .to_string();
    let resolved_args = resolve_crawl_args_fallible(&raw_args, args_stdin_content.as_deref())?;

    // Validate typed load-option values (--expires/--page-load-timeout/
    // --priority) before submitting. The backend silently defaults
    // malformed values, so an invalid value must fail loudly here —
    // the user must be able to detect that '--expires 1x' was not applied.
    if let Some(args_str) = resolved_args.as_deref() {
        validate_crawl_option_tokens(args_str)?;
    }

    // ---- Resolve output options ----
    let format = tool_params
        .get("format")
        .and_then(|v| v.as_str())
        .unwrap_or("table")
        .to_ascii_lowercase();

    validate_crawl_format(&format)?;

    // ---- Validate the parallelism budget ----
    // The budget is a count of browser tabs the crawl may drive at once.  A
    // value the user cannot have meant must fail here rather than silently
    // becoming the default: a typo that quietly serializes a bulk crawl would
    // look exactly like a slow site.
    validate_crawl_parallel(
        tool_params
            .get("parallel")
            .and_then(|v| v.as_str())
            .unwrap_or(""),
    )?;

    // ---- Validate the task budget ----
    // The budget is the crawl's own clock: a round derives its timeout from what is left of
    // it, and a seed that cannot fit is reported as an unstarted loss.  A value outside the
    // server's per-request range is refused here rather than clamped silently.
    validate_crawl_timeout(
        tool_params
            .get("timeout")
            .and_then(|v| v.as_str())
            .unwrap_or(""),
    )?;

    // When the X-SQL payload goes directly to stdout (no --output file), the
    // status/progress chatter must move to stderr so a redirected
    // `--format csv > out.csv` contains ONLY the CSV.  Background crawls
    // return before any payload, and interactive terminal use reads both
    // streams together, so those keep the historical behavior.
    let bg_requested = tool_params
        .get("background")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let payload_to_stdout = has_sql
        && tool_params.get("output").and_then(|v| v.as_str()).is_none()
        && !bg_requested
        && !std::io::stdout().is_terminal();
    crawl_set_structured_stdout(payload_to_stdout);

    // --format csv|json only renders X-SQL result sets. Without --sql there is
    // no structured set to format: writing the human-readable listing to an
    // -o file whose extension promises csv/json produces a file that lies
    // about its content, so refuse that combination instead of creating it.
    // (On stdout we keep the advisory warning — there is no misleading file.)
    if !has_sql && (format == "csv" || format == "json") {
        let fmt = format.to_uppercase();
        if let Some(path) = tool_params.get("output").and_then(|v| v.as_str()) {
            return Err(format!(
                "--format {fmt} only applies to --sql result sets, but no --sql was provided, \
                 so the output would be a plain-text listing rather than {fmt}. Refusing to write \
                 it to {path:?}. Add --sql, or drop --format. For a JSON page listing of a plain \
                 crawl use the global --json flag before the command — it needs no --sql."
            )
            .into());
        }
        crawl_status_println!(
            "Warning: --format {} has no effect without --sql. \
             Use --sql to produce structured output, or omit --format for plain-text output. \
             (The global --json flag prints the page listing as JSON without --sql.)",
            fmt
        );
    }

    // The global --json flag prints its envelope on stdout while `-o` still
    // receives the human-readable listing, so `--json crawl … -o out.json`
    // produced a .json file that was not JSON — the same lying-file problem as
    // the --format guardrail above, and refused the same way instead of writing
    // prose under a JSON name.
    if !has_sql && json_active() {
        if let Some(path) = tool_params.get("output").and_then(|v| v.as_str()) {
            return Err(format!(
                "--json prints the JSON envelope on stdout, while --output would receive the \
                 plain-text listing — {path:?} would not be JSON. Refusing to write it. Drop \
                 --output to read the envelope (it already carries the page listing), or add \
                 --sql to make --output receive a structured result set."
            )
            .into());
        }
    }

    // The backend LoadOptions tokenizer cannot carry a literal double quote
    // inside -outLinkPattern: double quotes delimit tokens and are never
    // unescaped. Fail fast instead of silently truncating the regex (unlike a
    // CSS selector, a regex quote has no single-quote equivalent).
    if let Some(pattern) = tool_params.get("out-link-pattern").and_then(|v| v.as_str()) {
        if pattern.contains('"') {
            return Err(format!(
                "--out-link-pattern cannot contain a double quote (\"): the LoadOptions \
                 argument tokenizer uses double quotes as delimiters and does not unescape \
                 them. Rewrite the regex without double quotes (pattern was {pattern:?})."
            )
            .into());
        }
    }

    // Inform when depth >= 1 but no --out-link-selector: link discovery is skipped
    {
        let has_out_link_selector = tool_params
            .get("out-link-selector")
            .and_then(|v| v.as_str())
            .map(|s| !s.is_empty())
            .unwrap_or(false);
        if depth >= 1 && !has_out_link_selector {
            crawl_status_println!(
                "Note: Link discovery disabled (no --out-link-selector). Processing seed URLs only."
            );
        }
    }

    // `--expires` is a page-store TTL, and a fetching crawl forces a fresh fetch for every
    // page: `resolveRoundArgs` adds `-refresh`, which expands to `-i 0s` and makes every
    // stored copy look expired. Only a read-only crawl leaves the TTL in charge, so say
    // that out loud instead of letting the flag look applied.
    {
        let args_str = resolved_args.as_deref().unwrap_or("");
        if crawl_args_have_option(args_str, &["expires", "expire"])
            && !crawl_args_have_option(args_str, &["readonly"])
        {
            crawl_status_println!(
                "Note: --expires has no effect on a fetching crawl — every page is fetched \
                 fresh. Add --readonly to let the page store answer within that TTL."
            );
        }
    }

    // Warn when --out-link-pattern looks like a Windows path.  MSYS2 (Git
    // Bash) rewrites slash-leading arguments into Windows paths when it
    // spawns a native executable, so `-olp "/product/"` arrives here as
    // `-olp "C:/Program Files/Git/product/"` — every link is filtered out
    // and the crawl silently reports the seed page only.  The mangled form
    // is recognizable (drive letter + ":/"); warn with the workaround
    // instead of letting the crawl fail silently.
    {
        let pattern = tool_params
            .get("out-link-pattern")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let looks_mangled = !pattern.is_empty()
            && pattern.len() >= 3
            && pattern.as_bytes()[0].is_ascii_alphabetic()
            && pattern.as_bytes()[1] == b':'
            && pattern.as_bytes()[2] == b'/';
        if looks_mangled {
            cli_println!(
                "Warning: the --out-link-pattern '{}' looks like a Windows path — \
                 Git Bash's MSYS path conversion probably rewrote a slash-leading value \
                 (e.g. '/product/') before it reached the CLI. Every link will be filtered \
                 out by this pattern. Run the command via ./b4w.sh (conversion disabled), \
                 or use a value that does not start with '/', e.g. -olp \"product/\".",
                pattern
            );
        }
    }

    let output_file = tool_params
        .get("output")
        .and_then(|v| v.as_str());

    // ---- Build server-bound params (strip CLI-only keys) ----
    let server_params = build_crawl_server_params(
        tool_params,
        &urls,
        resolved_sql.as_deref(),
        resolved_args.as_deref(),
    );

    let task_id = submit_crawl(client, base_url, &server_params).await?;
    let task_id = task_id.trim().trim_matches('"').to_string();
    crawl_status_println!("Crawl task submitted: {}", task_id);
    crawl_status_println!("  URLs: {}", urls.len());
    // State the parallelism up front: each unit needs its own browser tab, so a
    // user watching a slow crawl should know whether it was asked to overlap at
    // all (and the completion report confirms what it actually achieved).
    let requested_parallel = tool_params
        .get("parallel")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    crawl_status_println!(
        "  Parallel tabs: {}",
        if requested_parallel.is_empty() {
            "server default".to_string()
        } else {
            requested_parallel
        }
    );
    if has_sql {
        crawl_status_println!("  X-SQL extraction: enabled");
    }
    // Which browser profile the pages are read with decides *what the site answers*
    // (locale, currency, delivery location, login), so it is stated up front: a
    // storefront mismatch is otherwise only visible as an odd-looking price column.
    let fetch_session = tool_params
        .get("fetchSession")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    let fetch_profile = tool_params
        .get("profile")
        .and_then(|v| v.as_str())
        .unwrap_or("")
        .trim()
        .to_string();
    if !fetch_profile.is_empty() {
        crawl_status_println!("  Fetch profile: {} (own browser)", fetch_profile);
    } else {
        crawl_status_println!(
            "  Fetch session: {}",
            if fetch_session.is_empty() {
                "DEFAULT".to_string()
            } else {
                fetch_session
            }
        );
    }
    json_field("task_id", json!(task_id));

    // Build a compact description from command context instead of just the first URL.
    // This makes `crawl list` entries distinguishable without needing to remember task IDs.
    let refresh = tool_params
        .get("refresh")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let crawl_background = tool_params
        .get("background")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let crawl_desc = {
        let mut parts: Vec<String> = Vec::new();
        parts.push(format!("{} URLs", urls.len()));
        if depth == 0 {
            parts.push("depth 0".to_string());
        } else {
            parts.push(format!("depth {}", depth));
        }
        if has_sql {
            parts.push("X-SQL".to_string());
        }
        if crawl_background {
            parts.push("--bg".to_string());
        }
        if refresh {
            parts.push("--refresh".to_string());
        }
        parts.join(", ")
    };

    // Persist the task for cross-session tracking
    let _ = track_async_task(&task_id, "crawl", &crawl_desc, None);

    let background = tool_params
        .get("background")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let verbose = tool_params
        .get("verbose")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if background {
        cli_println!(
            "Running in background. Task ID: {}. Use 'browser4-cli crawl list' to view all tracked tasks.",
            task_id
        );
        return Ok(());
    }

    let poll_interval = std::time::Duration::from_secs(2);
    let timeout = crawl_request_timeout();
    let start = std::time::Instant::now();
    let mut last_report = std::time::Duration::ZERO;
    // First progress report after 5s (quick feedback), then every 10s
    let first_report_interval = std::time::Duration::from_secs(5);
    let report_interval = std::time::Duration::from_secs(10);
    // Signature of the last printed progress line.  Interval reports whose
    // counts did not change are suppressed so crawls don't emit repeated
    // identical lines (which read as stalled and spammed scripts with
    // duplicate formats).  Initialised to -1 so the first report prints.
    let mut last_report_pages: i64 = -1;
    let mut last_report_links: i64 = -1;
    let mut last_report_extracted: i64 = -1;
    let mut last_report_rows: i64 = -1;
    let url_count = urls.len();

    crawl_status_println!(
        "Waiting for crawl to complete (task {}, {} URL{}). Use --background for long-running crawls.",
        task_id,
        url_count,
        if url_count == 1 { "" } else { "s" }
    );

    loop {
        if start.elapsed() > timeout {
            let _ = update_async_task_status(
                &task_id,
                &format!("timeout after {}s", timeout.as_secs()),
                None,
            );
            // The CLI wait timing out does NOT stop the crawl: the task keeps
            // running server-side until it completes or its own internal
            // timeout fires.  Point the user at the polling commands instead
            // of implying the crawl died with the wait.
            return Err(format!(
                "Crawl timed out after {} seconds (CLI wait). Task ID: {}.\n\
                 The task keeps running server-side — poll it with:\n\
                   browser4-cli crawl status {}\n\
                   browser4-cli crawl result {}\n\
                 Increase the CLI wait with the BROWSER4_CLI_CRAWL_TIMEOUT_SECS environment variable.",
                timeout.as_secs(),
                task_id,
                task_id,
                task_id
            )
            .into());
        }

        tokio::time::sleep(poll_interval).await;

        let response_text = get_crawl_result(client, base_url, &task_id).await?;
        let parsed: Value = serde_json::from_str(&response_text)
            .map_err(|e| format!("Failed to parse crawl response: {}", e))?;

        let status = parsed["status"].as_str().unwrap_or("");
        let pages_found = parsed["pagesFound"].as_i64().unwrap_or(0);
        let error = parsed["error"].as_str();

        // Periodic progress indicator so foreground crawls don't look hung
        let elapsed = start.elapsed();
        let interval = if last_report == std::time::Duration::ZERO {
            first_report_interval
        } else {
            report_interval
        };
        if elapsed - last_report >= interval {
            last_report = elapsed;
            if pages_found > 0 {
                let links_discovered = parsed["linksDiscovered"].as_i64().unwrap_or(0);
                // When X-SQL extraction is active, include per-seed progress
                // with extracted row counts from the intermediate response so
                // the user can see extraction results as they come in.
                if has_sql {
                    let extracted_count = parsed["pages"]
                        .as_array()
                        .map(|pages| {
                            pages
                                .iter()
                                .filter(|p| {
                                    p["extracted"].as_array().map_or(false, |e| !e.is_empty())
                                })
                                .count()
                        })
                        .unwrap_or(0);
                    let total_rows: usize = parsed["pages"]
                        .as_array()
                        .map(|pages| {
                            pages
                                .iter()
                                .map(|p| p["extracted"].as_array().map(|a| a.len()).unwrap_or(0))
                                .sum()
                        })
                        .unwrap_or(0);

                    // Don't repeat a line whose counts are unchanged since the
                    // previous interval report.
                    let unchanged = pages_found == last_report_pages
                        && extracted_count as i64 == last_report_extracted
                        && total_rows as i64 == last_report_rows;
                    if unchanged {
                        // fall through to the status check below
                    } else {
                        // Show a one-line preview of the latest extraction if available
                        let preview = parsed["pages"].as_array()
                            .and_then(|pages| pages.iter().rev()
                                .find(|p| p["extracted"].as_array()
                                    .map_or(false, |e| !e.is_empty()))
                            )
                            .and_then(|page| {
                                page["extracted"].as_array()
                                    .and_then(|rows| rows.first())
                                    .map(|row| {
                                        let vals: Vec<String> = row.as_object()
                                            .map(|obj| obj.values()
                                                .filter_map(|v| v.as_str())
                                                .filter(|s| !s.is_empty())
                                                .take(2)  // first 2 non-empty values
                                                .map(|s| {
                                                    if s.len() > 30 {
                                                        format!("{}...", &s[..27])
                                                    } else {
                                                        s.to_string()
                                                    }
                                                })
                                                .collect()
                                            )
                                            .unwrap_or_default();
                                        if vals.is_empty() {
                                            String::new()
                                        } else {
                                            format!(" ({})", vals.join(" / "))
                                        }
                                    })
                            })
                            .unwrap_or_default();

                        // NOTE: do NOT render `extracted_count/url_count` as a
                        // "seeds done" fraction. At depth>0 the crawl discovers
                        // and extracts more pages than the initial seed list, so
                        // the page numerator can exceed the seed denominator
                        // ("2/1 seeds done"); and `extracted_count` is pages that
                        // returned rows, not completed seeds. Report page-based
                        // counters, which stay truthful.
                        crawl_status_println!(
                            "Crawling... {} pages found, {} with rows, {} rows extracted{} ({}s elapsed)",
                            pages_found,
                            extracted_count,
                            total_rows,
                            preview,
                            elapsed.as_secs()
                        );
                        last_report_pages = pages_found;
                        last_report_extracted = extracted_count as i64;
                        last_report_rows = total_rows as i64;
                    }
                } else {
                    // Cumulative page count (the backend now publishes per-page
                    // progress); show discovered links too when link discovery
                    // is active.  Skip lines whose counts are unchanged.
                    if pages_found != last_report_pages || links_discovered != last_report_links {
                        if links_discovered > 0 {
                            crawl_status_println!(
                                "Crawling... {} pages found, {} link(s) discovered ({}s elapsed)",
                                pages_found,
                                links_discovered,
                                elapsed.as_secs()
                            );
                        } else {
                            crawl_status_println!(
                                "Crawling... {} pages found ({}s elapsed)",
                                pages_found,
                                elapsed.as_secs()
                            );
                        }
                        last_report_pages = pages_found;
                        last_report_links = links_discovered;
                    }
                }
            } else {
                // No page recorded yet.  Once links have been discovered the
                // crawl is fetching pages — say so instead of repeating the
                // waiting line while pages are actively being processed.
                let links_discovered = parsed["linksDiscovered"].as_i64().unwrap_or(0);
                if links_discovered > 0 {
                    crawl_status_println!(
                        "Crawling... {} link(s) discovered, fetching pages ({}s elapsed)",
                        links_discovered,
                        elapsed.as_secs()
                    );
                } else {
                    crawl_status_println!(
                        "Crawling... waiting for first page ({}s elapsed, {} URLs queued)",
                        elapsed.as_secs(),
                        url_count
                    );
                }
            }
        }

        match status {
            "OK" | "SC_OK" => {
                let pages = parsed["pages"].as_array();
                let page_count = pages.map(|p| p.len()).unwrap_or(0);

                // Collect extracted data from all pages when X-SQL was provided
                let mut all_extracted: Vec<Value> = Vec::new();
                if has_sql {
                    if let Some(pages) = pages {
                        for page in pages {
                            if let Some(extracted) = page["extracted"].as_array() {
                                all_extracted.extend(extracted.iter().cloned());
                            }
                        }
                    }
                }

                // Format output
                if has_sql {
                    let extraction_error_count = if let Some(pages) = pages {
                        pages
                            .iter()
                            .filter(|p| p["extractionError"].as_str().is_some())
                            .count()
                    } else {
                        0
                    };

                    // Detect rows where every field is an empty string (query ran but selectors
                    // matched nothing — different from query-execution failure)
                    let all_rows_empty = !all_extracted.is_empty()
                        && all_extracted.iter().all(|row| {
                            row.as_object().map_or(false, |obj| {
                                !obj.is_empty()
                                    && obj
                                        .values()
                                        .all(|v| v.as_str().map_or(true, |s| s.is_empty()))
                            })
                        });

                    let extracted_output: String = if all_extracted.is_empty() {
                        "No extracted data.".to_string()
                    } else {
                        match format.as_str() {
                            "json" => serde_json::to_string_pretty(&all_extracted)
                                .unwrap_or_else(|_| "[]".to_string()),
                            "csv" => format_csv(&all_extracted),
                            "table" | _ => format_table(&all_extracted),
                        }
                    };

                    // Summary line — always show extraction stats unless in JSON mode
                    if all_extracted.is_empty() {
                        let diag = if extraction_error_count > 0 {
                            format!(
                                "⚠ X-SQL query failed on {}/{} page(s). Try re-running with --verbose for per-page diagnostics.",
                                extraction_error_count, page_count
                            )
                        } else {
                            format!(
                                "⚠ X-SQL returned 0 results across {} pages — check your selectors. \
                                 Use 'htmlsnapshot inspect' to discover available selectors on the page.",
                                page_count
                            )
                        };
                        crawl_status_println!("{}", diag);
                    } else if all_rows_empty {
                        crawl_status_println!(
                            "⚠ X-SQL returned {} rows but all fields are empty ({} pages crawled). \
                             The query executed but selectors did not match any elements. \
                             Verify selectors with 'htmlsnapshot inspect' or 'htmlsnapshot grep'. \
                             If the page loaded successfully, try adding --refresh.",
                            all_extracted.len(), page_count
                        );
                    } else {
                        crawl_status_println!(
                            "{}",
                            crawl_completion_line(&parsed, page_count, all_extracted.len())
                        );
                    }

                    // Readonly-mode note: what --readonly did (served from the
                    // store with age, or verified every page fetched fresh).
                    if let Some(note) = parsed["readonlyNote"].as_str() {
                        crawl_status_println!("{}", note);
                        json_field("readonly_note", json!(note));
                    }

                    // Parallelism: the budget this crawl ran under and the peak
                    // overlap it achieved (see crawl_parallelism_note).
                    if let Some(note) = crawl_parallelism_note(&parsed) {
                        crawl_status_println!("{}", note);
                        json_field("parallel_tabs", parsed["parallelTabs"].clone());
                        json_field(
                            "max_concurrent_fetches",
                            parsed["maxConcurrentFetches"].clone(),
                        );
                    }

                    let summary = format!("Results written");
                    let output = write_crawl_output(&extracted_output, output_file, &summary)?;
                    match output {
                        CrawlOutput::FileWritten { path, summary } => {
                            crawl_status_println!("{} to {}", summary, path);
                        }
                        CrawlOutput::Stdout(content) => {
                            cli_println!("\n{}", content);
                        }
                    }

                    json_field("extracted", json!(all_extracted));
                } else {
                    let mut page_lines: Vec<String> = Vec::new();
                    page_lines.push(format!("Crawl completed. {} page{} found.", page_count, if page_count == 1 { "" } else { "s" }));

                    // Surface seed-level errors even in non-verbose mode.
                    // When a seed URL fails (e.g. link discovery crashes, protocol
                    // handler not ready), the error is stored in seedStatuses but
                    // the page listing shows a hollow "depth=0 | URL | " entry with
                    // no indication of failure.  Without this warning, users see
                    // "Crawl completed. N pages found." and assume all succeeded.
                    if let Some(seed_statuses) = parsed["seedStatuses"].as_array() {
                        let failed: Vec<&Value> = seed_statuses
                            .iter()
                            .filter(|ss| ss["status"].as_str().unwrap_or("") == "error")
                            .collect();
                        if !failed.is_empty() {
                            page_lines.push(format!(
                                "\n⚠ {} of {} seed URL(s) failed:",
                                failed.len(),
                                seed_statuses.len()
                            ));
                            for ss in &failed {
                                let s_url = ss["url"].as_str().unwrap_or("");
                                let s_error = ss["error"].as_str().unwrap_or("unknown error");
                                page_lines.push(format!("    ✗ {} — {}", s_url, s_error));
                            }
                            page_lines
                                .push("  Use --verbose for full per-seed diagnostics.".to_string());
                        }
                    }

                    // Display per-seed-URL status when verbose
                    if verbose {
                        if let Some(seed_statuses) = parsed["seedStatuses"].as_array() {
                            if !seed_statuses.is_empty() {
                                page_lines.push(String::new());
                                page_lines.push("  Seed URL Status:".to_string());
                                for ss in seed_statuses {
                                    let s_url = ss["url"].as_str().unwrap_or("");
                                    let s_status = ss["status"].as_str().unwrap_or("");
                                    let s_pages = ss["pagesReturned"].as_i64().unwrap_or(0);
                                    let s_error = ss["error"].as_str().unwrap_or("");
                                    let icon = match s_status {
                                        "fetched" => "✓",
                                        "skipped" => "⊘",
                                        _ => "✗",
                                    };
                                    if s_error.is_empty() {
                                        page_lines.push(format!(
                                            "    {} {} → {} page(s)",
                                            icon, s_url, s_pages
                                        ));
                                    } else {
                                        page_lines.push(format!(
                                            "    {} {} → {} (error: {})",
                                            icon, s_url, s_pages, s_error
                                        ));
                                    }
                                }
                            }
                        }
                    }

                    // Link-discovery crawls always count the seed page(s), so
                    // page_count == 0 can not signal "discovery found nothing"
                    // — links_discovered == 0 is that signal.  Surface the
                    // backend diagnostic whenever a discovery crawl found no
                    // out-links (e.g. the pattern filtered every link), instead
                    // of reporting a hollow 'Crawl completed. N pages found.'
                    let links_discovered = parsed["linksDiscovered"].as_i64().unwrap_or(0);
                    let discovery_requested = depth >= 1
                        && tool_params
                            .get("out-link-selector")
                            .and_then(|v| v.as_str())
                            .map(|s| !s.is_empty())
                            .unwrap_or(false);
                    // "Discovered but nothing new fetched" is also a hollow
                    // success: fragment-only hrefs ('#'), self-references, and
                    // duplicates of the seed URLs all resolve back to already
                    // visited pages, so a crawl can report links_discovered > 0
                    // while fetching zero new pages (one result row per seed).
                    let fetched_no_new_pages = discovery_requested
                        && links_discovered > 0
                        && page_count <= urls.len();
                    if discovery_requested && links_discovered == 0 {
                        page_lines.push(format!(
                            "\n⚠ Link discovery found no out-links — only {} page(s) recorded.",
                            page_count
                        ));
                        if let Some(diag) = parsed["diagnostic"].as_str() {
                            page_lines.push(format!("  Diagnostic: {}", diag));
                        }
                        page_lines.push("  Tips:".to_string());
                        page_lines.push("    - Verify the --out-link-selector targets the correct elements".to_string());
                        if let Some(pattern) = tool_params.get("out-link-pattern").and_then(|v| v.as_str()) {
                            // Echo the pattern the crawl actually used — a
                            // shell-mangled pattern (e.g. MSYS path conversion
                            // in Git Bash) otherwise filters everything with no
                            // visible trace.
                            page_lines.push(format!(
                                "    - The effective --out-link-pattern was: {}",
                                pattern
                            ));
                        }
                        page_lines.push("    - Use 'snapshot' or 'htmlsnapshot' to inspect the page structure first".to_string());
                    } else if fetched_no_new_pages {
                        page_lines.push(format!(
                            "\n⚠ Link discovery found {} link(s), but no NEW pages were fetched — \
                             every discovered link resolved back to an already-visited URL \
                             (fragment-only hrefs like '#', self-references, or seed duplicates).",
                            links_discovered
                        ));
                        page_lines.push("  Tips:".to_string());
                        page_lines.push("    - Fragment-only anchors (href=\"#\") can never navigate — check the page's real links with 'snapshot' or 'htmlsnapshot'".to_string());
                        page_lines.push("    - Verify --out-link-pattern does not match the seed URL itself".to_string());
                    } else if page_count == 0 {
                        // Display diagnostic info when 0 pages found (e.g. selector matched no elements)
                        if let Some(diag) = parsed["diagnostic"].as_str() {
                            page_lines.push(format!("\n  Diagnostic: {}", diag));
                        }
                        page_lines.push("\n  Tips:".to_string());
                        page_lines.push(
                            "    - Verify the --out-link-selector targets the correct elements"
                                .to_string(),
                        );
                        page_lines.push("    - Use 'snapshot' or 'htmlsnapshot' to inspect the page structure first".to_string());
                    }

                    if let Some(pages) = pages {
                        for page in pages {
                            let page_url = page["url"].as_str().unwrap_or("");
                            let page_title = page["title"].as_str().unwrap_or("");
                            let page_depth = page["depth"].as_i64().unwrap_or(0);
                            let extraction_error = page["extractionError"].as_str();
                            let content_len = page["contentLength"].as_i64().unwrap_or(-1);
                            // Readonly surfacing: pages whose content was served
                            // from the page store (--readonly) carry markers; the
                            // title cell shows the content came from the store and
                            // how old it is.
                            let served_from_store = page["servedFromStore"].as_bool().unwrap_or(false);
                            let store_age_secs = page["storeAgeSeconds"].as_i64();
                            let mut title_cell = page_title.to_string();
                            if served_from_store {
                                match store_age_secs {
                                    Some(age) => title_cell.push_str(&format!(
                                        " (served from store, {} old)", format_store_age(age)
                                    )),
                                    None => title_cell.push_str(" (served from store)"),
                                }
                            }
                            // Show fetch errors inline even in non-verbose mode so the
                            // user isn't misled by "Crawl completed" for failed pages.
                            if let Some(err) = extraction_error {
                                page_lines.push(format!(
                                    "  depth={} | {} | ⚠ {}",
                                    page_depth, page_url, err
                                ));
                            } else if content_len == 0 {
                                page_lines.push(format!(
                                    "  depth={} | {} | ⚠ fetch returned 0 bytes",
                                    page_depth, page_url
                                ));
                            } else {
                                page_lines.push(format!(
                                    "  depth={} | {} | {}",
                                    page_depth, page_url, title_cell
                                ));
                            }
                            if verbose {
                                if extraction_error.is_none()
                                    && has_sql
                                    && page["extracted"].as_array().map_or(false, |a| a.is_empty())
                                {
                                    page_lines
                                        .push("    ⚠ X-SQL extraction returned 0 rows".to_string());
                                }
                            }
                        }
                    }
                    // Show a summary when pages had errors so the user doesn't see
                    // "Crawl completed. N pages found." and assume all succeeded.
                    let error_count = pages
                        .map(|p| {
                            p.iter()
                                .filter(|pg| {
                                    pg["extractionError"].as_str().is_some()
                                        || pg["contentLength"].as_i64().unwrap_or(-1) == 0
                                })
                                .count()
                        })
                        .unwrap_or(0);
                    if error_count > 0 {
                        page_lines.push(format!(
                            "\n⚠ {} of {} page(s) had fetch or extraction errors. \
                             Use --verbose for per-page diagnostics.",
                            error_count, page_count
                        ));
                    }
                    // Lost pages: a crawl that dropped pages must not report a page
                    // count smaller than the number of pages it set out to fetch.
                    // The backend guarantees pagesFound + failedPages.size ==
                    // pagesExpected, so this is the accounting that makes "the site
                    // does not have it" distinguishable from "the crawl lost it".
                    if let Some(failed) = parsed["failedPages"].as_array() {
                        if !failed.is_empty() {
                            let pages_expected = parsed["pagesExpected"].as_i64().unwrap_or(0);
                            page_lines.push(format!(
                                "\n⚠ {} of {} submitted page(s) were never delivered — \
                                 this crawl is incomplete, not just small:",
                                failed.len(),
                                pages_expected
                            ));
                            const MAX_SHOWN: usize = 5;
                            for f in failed.iter().take(MAX_SHOWN) {
                                let url = f["url"].as_str().unwrap_or("");
                                let depth = f["depth"].as_i64().unwrap_or(-1);
                                let protocol_status = f["protocolStatus"].as_i64().unwrap_or(0);
                                let reason = f["reason"].as_str().unwrap_or("no reason reported");
                                let status_part = if protocol_status == 0 {
                                    String::new()
                                } else {
                                    format!("status={} ", protocol_status)
                                };
                                page_lines.push(format!(
                                    "    depth={} | {} | {}{}",
                                    depth, url, status_part, reason
                                ));
                            }
                            if failed.len() > MAX_SHOWN {
                                page_lines.push(format!("    (+{} more)", failed.len() - MAX_SHOWN));
                            }
                            json_field("failed_pages", json!(failed.clone()));
                            json_field("pages_expected", json!(pages_expected));
                        }
                    }
                    // Readonly-mode note: what --readonly did (served from the
                    // store with age, or verified every page fetched fresh).
                    if let Some(note) = parsed["readonlyNote"].as_str() {
                        page_lines.push(String::new());
                        page_lines.push(note.to_string());
                        json_field("readonly_note", json!(note));
                    }
                    // Parallelism: the budget this crawl ran under and the peak
                    // overlap it achieved, so a serialized "parallel" crawl is
                    // visible instead of just slow.
                    if let Some(note) = crawl_parallelism_note(&parsed) {
                        page_lines.push(String::new());
                        page_lines.push(note);
                        json_field("parallel_tabs", parsed["parallelTabs"].clone());
                        json_field(
                            "max_concurrent_fetches",
                            parsed["maxConcurrentFetches"].clone(),
                        );
                    }
                    let page_output = page_lines.join("\n");
                    let page_summary = format!("Crawl completed. {} page{} found.", page_count, if page_count == 1 { "" } else { "s" });
                    let output = write_crawl_output(&page_output, output_file, &page_summary)?;
                    match output {
                        CrawlOutput::FileWritten { path, summary } => {
                            // `summary` already ends in its own period, so do
                            // not add another before "Results".
                            crawl_status_println!("\n{} Results written to {}", summary, path);
                        }
                        CrawlOutput::Stdout(content) => {
                            cli_println!("\n{}", content);
                        }
                    }
                }

                json_field("pages", json!(pages));
                json_field("pages_found", json!(page_count));
                // Failure accounting: reported in JSON (`pages_failed`) and in
                // the exit code, so automation can detect a partially failed
                // crawl instead of parsing the ⚠ warning lines.
                let (ok_count, failed_total) = crawl_failure_counts(&parsed, page_count);
                json_field("pages_failed", json!(failed_total));
                // Update the locally-tracked task status so `crawl list`
                // reflects completion instead of forever showing "pending".
                let _ = update_async_task_status(
                    &task_id,
                    &format!("{} ({} pages)", status, page_count),
                    None,
                );
                // Exit non-zero when anything failed, so a crawl that lost
                // pages (or delivered pages with no usable content) is not
                // mistaken for a clean one.  Exit 0 stays reserved for fully
                // successful crawls, whose output is unchanged.
                if failed_total > 0 {
                    cli_println!("\nSummary: ok: {}, failed: {}", ok_count, failed_total);
                    let _ = update_async_task_status(
                        &task_id,
                        &format!("partial failure ({} of {} pages ok)", ok_count, page_count),
                        None,
                    );
                    return Err(CliError(
                        ExitCode::PartialFailure,
                        format!(
                            "crawl completed with errors: ok: {}, failed: {}. \
                             Use 'crawl result {}' or --verbose for per-page diagnostics.",
                            ok_count, failed_total, task_id
                        ),
                    ));
                }
                return Ok(());
            }
            s if is_crawl_terminal_failure_status(s) => {
                let err_msg = error.unwrap_or("Unknown crawl error");
                let _ = update_async_task_status(
                    &task_id,
                    &format!("error: {}", err_msg),
                    None,
                );
                // A crawl cut off by the server-side --timeout budget keeps a
                // resumable checkpoint, so the work already collected is not
                // lost: say how to continue instead of only how it failed.
                let mut message = format!("Crawl failed: {}", err_msg);
                if let Some(hint) = crawl_resume_hint(&task_id, &parsed) {
                    message.push('\n');
                    message.push_str(&hint);
                }
                return Err(message.into());
            }
            s if is_interrupted_crawl_status(s) => {
                // The worker died with the backend process.  Terminal — waiting
                // here would hang forever, and letting the status fall into the
                // `_` "still running" arm is exactly that bug.  Resumable, so
                // the message is a resume instruction, not a dead end.
                let _ = update_async_task_status(&task_id, &friendly_crawl_status(s), None);
                return Err(crawl_interrupted_message(&task_id, &parsed).into());
            }
            _ => {
                // Still running — progress is reported on the periodic cadence
                // above; printing here too would duplicate every periodic line.
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Output formatting helpers for extracted crawl data
// ---------------------------------------------------------------------------

/// Format seconds as a compact human age (e.g. "45s", "2m 5s", "1h 3m").
fn format_store_age(seconds: i64) -> String {
    let h = seconds / 3600;
    let m = (seconds % 3600) / 60;
    let s = seconds % 60;
    if h > 0 {
        format!("{}h {}m", h, m)
    } else if m > 0 {
        format!("{}m {}s", m, s)
    } else {
        format!("{}s", s)
    }
}

/// Format a list of extracted data rows as CSV with header row.
/// Uses manual escaping (no csv crate dependency needed).
fn format_csv(rows: &[Value]) -> String {
    if rows.is_empty() {
        return String::new();
    }

    // Collect column names in order of first appearance
    let mut columns: Vec<String> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for row in rows {
        if let Value::Object(map) = row {
            for key in map.keys() {
                if seen.insert(key.clone()) {
                    columns.push(key.clone());
                }
            }
        }
    }

    if columns.is_empty() {
        return String::new();
    }

    // CSV escape: wrap in double quotes if contains comma, quote, or newline
    let escape = |s: &str| -> String {
        if s.contains(',') || s.contains('"') || s.contains('\n') {
            format!("\"{}\"", s.replace('"', "\"\""))
        } else {
            s.to_string()
        }
    };

    let mut out = String::new();
    // Header row
    out.push_str(
        &columns
            .iter()
            .map(|c| escape(c))
            .collect::<Vec<_>>()
            .join(","),
    );
    out.push('\n');
    // Data rows
    for row in rows {
        let vals: Vec<String> = columns
            .iter()
            .map(|col| {
                row.get(col)
                    .map(|v| match v {
                        Value::String(s) => escape(s),
                        Value::Null => String::new(),
                        other => escape(&other.to_string()),
                    })
                    .unwrap_or_default()
            })
            .collect();
        out.push_str(&vals.join(","));
        out.push('\n');
    }
    out
}

/// Format extracted data as a human-readable aligned table.
fn format_table(rows: &[Value]) -> String {
    if rows.is_empty() {
        return "No data.".to_string();
    }

    // Collect column names in order of first appearance
    let mut columns: Vec<String> = Vec::new();
    let mut seen = std::collections::HashSet::new();
    for row in rows {
        if let Value::Object(map) = row {
            for key in map.keys() {
                if seen.insert(key.clone()) {
                    columns.push(key.clone());
                }
            }
        }
    }

    if columns.is_empty() {
        return "No data.".to_string();
    }

    // Build string data and compute column widths
    let mut col_widths: Vec<usize> = columns.iter().map(|c| c.len()).collect();
    let cell_data: Vec<Vec<String>> = rows
        .iter()
        .map(|row| {
            columns
                .iter()
                .enumerate()
                .map(|(i, col)| {
                    let val = row
                        .get(col)
                        .map(|v| match v {
                            Value::String(s) => s.clone(),
                            Value::Null => String::new(),
                            Value::Bool(b) => b.to_string(),
                            Value::Number(n) => n.to_string(),
                            _ => v.to_string(),
                        })
                        .unwrap_or_default();
                    col_widths[i] = col_widths[i].max(val.len());
                    val
                })
                .collect()
        })
        .collect();

    let mut out = String::new();

    // Header
    let header: Vec<String> = columns
        .iter()
        .enumerate()
        .map(|(i, c)| format!("{:width$}", c, width = col_widths[i]))
        .collect();
    out.push_str("  ");
    out.push_str(&header.join(" | "));
    out.push('\n');

    // Separator
    let sep: Vec<String> = col_widths.iter().map(|w| "-".repeat(*w)).collect();
    out.push_str("  ");
    out.push_str(&sep.join("-+-"));
    out.push('\n');

    // Data rows
    for row_cells in &cell_data {
        let formatted: Vec<String> = row_cells
            .iter()
            .enumerate()
            .map(|(i, val)| format!("{:width$}", val, width = col_widths[i]))
            .collect();
        out.push_str("  ");
        out.push_str(&formatted.join(" | "));
        out.push('\n');
    }

    out
}

// ---------------------------------------------------------------------------
// Loop command — periodic task execution
// ---------------------------------------------------------------------------

/// Parse arguments for the `loop` command from raw CLI tokens (everything
/// after the command name).
///
/// Recognises `--shell`, `--`, `--interval`/`-i`, `--count`/`-n`,
/// `--timeout`/`-t`, `--pause`/`--resume`/`--pause-all`/`--resume-all`/`--stop-all`,
/// and collects everything else as the task.
const DEFAULT_LOOP_INTERVAL_SECS: u64 = 3600; // 1 hour
const DEFAULT_LOOP_TIMEOUT_SECS: u64 = 604800; // 1 week
const PAUSE_POLL_INTERVAL_SECS: u64 = 2; // How often to check for resume while paused

/// How long `--stop-all` waits for signalled workers to clear their state files
/// before reporting which loops still look active.
///
/// A worker only notices the stop at its next checkpoint, so a loop in the
/// middle of a long iteration legitimately outlives this wait; the command
/// reports that instead of asserting success (which is what made a still-running
/// loop look stopped — issue 122234#3).
const STOP_ALL_SETTLE_TIMEOUT_SECS: u64 = 10;

fn parse_loop_args(args: &[String]) -> Result<LoopArgs, String> {
    let mut out = LoopArgs {
        interval_secs: DEFAULT_LOOP_INTERVAL_SECS,
        timeout_secs: Some(DEFAULT_LOOP_TIMEOUT_SECS),
        ..Default::default()
    };
    let mut after_dash_dash = false;
    let mut i = 0;

    // Set of known loop-level flags. When any of these appear after `--`
    // (i.e. in subcommand position), they are silently captured by the
    // subcommand rather than being parsed by the loop command. We detect
    // this and warn the user.
    let known_loop_flags: &[&str] = &[
        "--name",
        "--interval",
        "-i",
        "--count",
        "-n",
        "--timeout",
        "-t",
        "--shell",
        "--pause",
        "--pause-all",
        "--resume",
        "--resume-all",
        "--stop",
        "--stop-all",
        "--status",
        "--list",
    ];

    while i < args.len() {
        let arg = &args[i];

        if after_dash_dash {
            // Detect known loop flags that appear after `--` and warn.
            // The user likely intended these as loop-level options.
            let flag_name = if let Some(_val) = arg.strip_prefix("--name=") {
                Some("--name")
            } else if let Some(_val) = arg.strip_prefix("--interval=") {
                Some("--interval")
            } else if let Some(_val) = arg.strip_prefix("--count=") {
                Some("--count")
            } else if let Some(_val) = arg.strip_prefix("--timeout=") {
                Some("--timeout")
            } else if known_loop_flags.contains(&arg.as_str()) {
                Some(arg.as_str())
            } else {
                None
            };

            if let Some(flag) = flag_name {
                eprintln!(
                    "[WARN] `{}` after `--` is treated as a nested browser4-cli argument, \
                     not a loop option.  Did you mean `loop {} <value> -- ...`?",
                    arg, flag,
                );
            }

            out.task_tokens.push(arg.clone());
            i += 1;
            continue;
        }

        if arg == "--" {
            after_dash_dash = true;
            out.is_subcommand = true;
            i += 1;
            continue;
        }

        // Control flags (no task required)
        if arg == "--stop" {
            out.stop = true;
            i += 1;
            continue;
        }

        if arg == "--stop-all" {
            out.stop_all = true;
            i += 1;
            continue;
        }

        if arg == "--status" {
            out.status = true;
            i += 1;
            continue;
        }

        if arg == "--list" {
            out.list = true;
            i += 1;
            continue;
        }

        if arg == "--pause" {
            out.pause = true;
            i += 1;
            continue;
        }

        if arg == "--resume" {
            out.resume = true;
            i += 1;
            continue;
        }

        if arg == "--pause-all" {
            out.pause_all = true;
            i += 1;
            continue;
        }

        if arg == "--resume-all" {
            out.resume_all = true;
            i += 1;
            continue;
        }

        if arg == "--history" {
            out.history = true;
            i += 1;
            continue;
        }

        if arg == "--keep-state" {
            out.keep_state = true;
            i += 1;
            continue;
        }

        if arg == "--shell" {
            out.is_shell = true;
            i += 1;
            continue;
        }

        if let Some(val) = arg.strip_prefix("--name=") {
            let name = val.to_string();
            validate_loop_name(&name)?;
            out.name = Some(name);
        } else if arg == "--name" {
            let name = next_arg(&args, &mut i, "name")?.to_string();
            validate_loop_name(&name)?;
            out.name = Some(name);
        } else if let Some(val) = arg.strip_prefix("--interval=") {
            out.interval_secs = parse_u64_required(val, "--interval")?;
        } else if arg == "--interval" || arg == "-i" {
            out.interval_secs =
                parse_u64_required(next_arg(&args, &mut i, "interval")?, "interval")?;
        } else if let Some(val) = arg.strip_prefix("--count=") {
            out.count = Some(parse_u64_required(val, "--count")?);
        } else if arg == "--count" || arg == "-n" {
            out.count = Some(parse_u64_required(
                next_arg(&args, &mut i, "count")?,
                "count",
            )?);
        } else if let Some(val) = arg.strip_prefix("--timeout=") {
            out.timeout_secs = Some(parse_u64_required(val, "--timeout")?);
        } else if arg == "--timeout" || arg == "-t" {
            out.timeout_secs = Some(parse_u64_required(
                next_arg(&args, &mut i, "timeout")?,
                "timeout",
            )?);
        } else if arg.starts_with('-') {
            return Err(format!("Unknown option: {}", arg));
        } else {
            out.task_tokens.push(arg.clone());
        }
        i += 1;
    }

    // Flags that are control-only — they reject combining with a task.
    // --pause is excluded from this set: combining --pause with a task starts
    // the loop in paused state (the user can --resume later).
    let no_task_flags = out.stop
        || out.stop_all
        || out.status
        || out.list
        || out.resume
        || out.pause_all
        || out.resume_all
        || out.history;

    if no_task_flags {
        if !out.task_tokens.is_empty() {
            let flag = if out.stop {
                "--stop"
            } else if out.stop_all {
                "--stop-all"
            } else if out.status {
                "--status"
            } else if out.list {
                "--list"
            } else if out.resume {
                "--resume"
            } else if out.pause_all {
                "--pause-all"
            } else if out.resume_all {
                "--resume-all"
            } else {
                "--history"
            };
            return Err(format!(
                "The {} flag cannot be combined with a task. Use just `browser4-cli loop {}`.",
                flag, flag,
            ));
        }
        // --list doesn't make sense with --name
        if out.list && out.name.is_some() {
            return Err("The --list and --name flags cannot be combined. Use just `browser4-cli loop --list`.".to_string());
        }
        // --pause-all, --resume-all, --stop-all don't need --name
        if (out.pause_all || out.resume_all || out.stop_all) && out.name.is_some() {
            let flag = if out.pause_all {
                "--pause-all"
            } else if out.resume_all {
                "--resume-all"
            } else {
                "--stop-all"
            };
            return Err(format!(
                "The {} flag cannot be combined with --name. It applies to all loops.",
                flag
            ));
        }
        // --pause and --resume are mutually exclusive
        if out.pause && out.resume {
            return Err("The --pause and --resume flags are mutually exclusive.".to_string());
        }
        return Ok(out);
    }

    // --pause without other control flags: if a task is provided, this is
    // "start paused"; if not, it's a control op handled above.
    // --resume with a task is always an error — you resume an existing loop.
    if out.resume && !out.task_tokens.is_empty() {
        return Err("The --resume flag cannot be combined with a task. Use just `browser4-cli loop --resume` to resume an existing loop.".to_string());
    }

    // --pause with a task: start-paused is valid (falls through to normal validation)
    if out.pause && out.task_tokens.is_empty() {
        return Ok(out); // control op: pause running loop, no task needed
    }

    // Validate
    if out.is_shell && out.is_subcommand {
        return Err("The --shell flag and -- separator are mutually exclusive. Use --shell for shell commands or -- for browser4-cli subcommands.".to_string());
    }

    if out.task_tokens.is_empty() {
        return Err("A task is required. Provide a plain text command, x-sql query, --shell <cmd>, -- <browser4-cli subcommand>, --list, --stop, --status, --pause, or --resume.".to_string());
    }

    Ok(out)
}

/// Helper: get the next argument from the iterator, advancing past it.
fn next_arg<'a>(args: &'a [String], i: &mut usize, name: &str) -> Result<&'a str, String> {
    *i += 1;
    args.get(*i)
        .map(|s| s.as_str())
        .ok_or_else(|| format!("Expected a value after --{}", name))
}

/// Helper: parse a string to u64, emitting a contextual error.
fn parse_u64_required(s: &str, flag: &str) -> Result<u64, String> {
    s.parse::<u64>().map_err(|_| {
        format!(
            "Invalid value for {}: '{}'. Expected a non-negative integer.",
            flag, s
        )
    })
}

/// Validate a loop --name value. Only allows alphanumeric, dot, hyphen,
/// and underscore characters.  Rejects names that contain path separators,
/// parent-directory sequences, or other characters that could be used for
/// path traversal.
fn validate_loop_name(name: &str) -> Result<(), String> {
    if name.is_empty() {
        return Err("Loop name must not be empty.".to_string());
    }
    if name.contains('/') || name.contains('\\') || name.contains("..") {
        return Err(format!(
            "Loop name contains invalid path characters: '{}'. \
             Use only letters, digits, dots, hyphens, and underscores.",
            name,
        ));
    }
    if !name
        .chars()
        .all(|c| c.is_ascii_alphanumeric() || c == '.' || c == '-' || c == '_')
    {
        return Err(format!(
            "Invalid loop name: '{}'. \
             Use only letters, digits, dots, hyphens, and underscores.",
            name,
        ));
    }
    Ok(())
}

/// Format a duration in seconds as a human-readable string.
///
/// Examples: `30s`, `5m 30s`, `2h 15m`, `3d 6h`, `1w 2d`.
fn format_duration(total_secs: u64) -> String {
    if total_secs == 0 {
        return "0s".to_string();
    }
    let weeks = total_secs / 604800;
    let days = (total_secs % 604800) / 86400;
    let hours = (total_secs % 86400) / 3600;
    let minutes = (total_secs % 3600) / 60;
    let seconds = total_secs % 60;

    let mut parts: Vec<String> = Vec::new();
    if weeks > 0 {
        parts.push(format!("{}w", weeks));
    }
    if days > 0 {
        parts.push(format!("{}d", days));
    }
    if hours > 0 {
        parts.push(format!("{}h", hours));
    }
    if minutes > 0 {
        parts.push(format!("{}m", minutes));
    }
    if seconds > 0 || parts.is_empty() {
        parts.push(format!("{}s", seconds));
    }
    parts.join(" ")
}

/// Execute a shell command via the OS shell.
///
/// Uses `cmd /C` on Windows and `sh -c` on Unix.
fn run_shell_command(task: &str) -> Result<String, String> {
    #[cfg(windows)]
    let (shell, flag) = ("cmd", "/C");
    #[cfg(not(windows))]
    let (shell, flag) = ("sh", "-c");

    // On Windows, prepend `chcp 65001 >nul &&` to switch the console code
    // page to UTF-8 (65001) so that non-ASCII characters (e.g. Chinese
    // day-of-week from `date /t`) are captured correctly by the UTF-8
    // String::from_utf8_lossy decoder.
    #[cfg(windows)]
    let command = format!("chcp 65001 >nul && {}", task);
    #[cfg(not(windows))]
    let command = task.to_string();

    let output = std::process::Command::new(shell)
        .arg(flag)
        .arg(&command)
        .stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped())
        .output()
        .map_err(|e| format!("Failed to execute shell command: {}", e))?;

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();

    if output.status.success() {
        Ok(stdout.trim().to_string())
    } else {
        Err(if stderr.is_empty() {
            format!(
                "Shell command exited with {}: {}",
                output.status,
                stdout.trim()
            )
        } else {
            stderr.trim().to_string()
        })
    }
}

/// Execute a `browser4-cli` subcommand by spawning the current binary with
/// the given tokens.
async fn run_browser4_cli(tokens: &[String]) -> Result<String, String> {
    let exe = std::env::current_exe().map_err(|e| format!("Cannot determine CLI path: {}", e))?;

    let tokens = tokens.to_vec();
    let output = tokio::task::spawn_blocking(move || {
        std::process::Command::new(&exe)
            .args(&tokens)
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .output()
    })
    .await
    .map_err(|e| format!("Subprocess spawn failed: {}", e))?
    .map_err(|e| format!("Failed to execute browser4-cli: {}", e))?;

    let stdout = String::from_utf8_lossy(&output.stdout).to_string();
    let stderr = String::from_utf8_lossy(&output.stderr).to_string();

    if output.status.success() {
        Ok(stdout.trim().to_string())
    } else {
        Err(if stderr.is_empty() {
            format!(
                "browser4-cli exited with {}: {}",
                output.status,
                stdout.trim()
            )
        } else {
            stderr.trim().to_string()
        })
    }
}

/// Spawn a detached background process that survives parent exit.
///
/// On Windows, uses `CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS` so the
/// child is not tied to the parent console / process tree, and clears the
/// inherit flag on this process's own std handles for the duration of the
/// spawn: `Command::spawn` passes `bInheritHandles = TRUE`, so every
/// *inheritable* handle of the parent — including the write end of a caller's
/// pipe — is duplicated into the worker.  The worker never writes to it, but
/// keeping it open meant a piped `loop --resume | cat` never saw EOF and
/// appeared to hang (issue 122234#2).  On Unix `Command::spawn` only dups the
/// explicitly configured descriptors and sets `CLOEXEC` on the rest, so no
/// handle leaks and no equivalent step is needed.
fn spawn_detached(exe: &std::path::Path, args: &[String], log_path: Option<&std::path::Path>) -> Result<u32, String> {
    let mut cmd = std::process::Command::new(exe);
    cmd.args(args)
        .stdin(std::process::Stdio::null());
    match log_path {
        Some(path) => {
            let file = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(path)
                .map_err(|e| format!("Cannot open loop log file {}: {}", path.display(), e))?;
            cmd.stdout(file.try_clone().map_err(|e| format!("Cannot clone stdout handle: {}", e))?);
            cmd.stderr(file);
        }
        None => {
            cmd.stdout(std::process::Stdio::null());
            cmd.stderr(std::process::Stdio::null());
        }
    }

    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NEW_PROCESS_GROUP: u32 = 0x0000_0200;
        const DETACHED_PROCESS: u32 = 0x0000_0008;
        cmd.creation_flags(CREATE_NEW_PROCESS_GROUP | DETACHED_PROCESS);
    }

    #[cfg(windows)]
    let restore_inherit = win_std_handles_disable_inherit();

    let spawn_result = cmd
        .spawn()
        .map_err(|e| format!("Failed to spawn background process: {}", e));

    #[cfg(windows)]
    win_std_handles_restore(restore_inherit);

    Ok(spawn_result?.id())
}

/// Clear `HANDLE_FLAG_INHERIT` on stdin/stdout/stderr for the next spawn.
///
/// Returns the handles with their previous flags so [`win_std_handles_restore`]
/// can put them back.  The WinAPI functions are declared here the same way
/// `daemon.rs` declares `OpenProcess`, so no extra crate is needed.
#[cfg(windows)]
fn win_std_handles_disable_inherit() -> Vec<(*mut core::ffi::c_void, u32)> {
    const HANDLE_FLAG_INHERIT: u32 = 0x0000_0001;
    const STD_INPUT_HANDLE: u32 = 0xFFFF_FFF6; // (DWORD)-10
    const STD_OUTPUT_HANDLE: u32 = 0xFFFF_FFF5; // (DWORD)-11
    const STD_ERROR_HANDLE: u32 = 0xFFFF_FFF4; // (DWORD)-12

    // Declared with the same signatures `daemon.rs` uses for these symbols, so
    // the crate has one declaration of each rather than two that disagree.
    extern "system" {
        fn GetStdHandle(n_std_handle: u32) -> *mut core::ffi::c_void;
        fn GetHandleInformation(h_object: *mut core::ffi::c_void, lpdw_flags: *mut u32) -> i32;
        fn SetHandleInformation(
            h_object: *mut core::ffi::c_void,
            dw_mask: u32,
            dw_flags: u32,
        ) -> i32;
    }

    let mut previous: Vec<(*mut core::ffi::c_void, u32)> = Vec::new();
    for id in [STD_INPUT_HANDLE, STD_OUTPUT_HANDLE, STD_ERROR_HANDLE] {
        unsafe {
            let handle = GetStdHandle(id);
            if handle.is_null() || handle as isize == -1 {
                continue;
            }
            let mut flags: u32 = 0;
            if GetHandleInformation(handle, &mut flags) == 0 {
                continue;
            }
            if flags & HANDLE_FLAG_INHERIT == 0 {
                // Already non-inheritable — nothing to restore for this handle.
                continue;
            }
            if SetHandleInformation(handle, HANDLE_FLAG_INHERIT, 0) != 0 {
                previous.push((handle, flags));
            }
        }
    }
    previous
}

/// Restore the std-handle flags collected by [`win_std_handles_disable_inherit`].
#[cfg(windows)]
fn win_std_handles_restore(previous: Vec<(*mut core::ffi::c_void, u32)>) {
    const HANDLE_FLAG_INHERIT: u32 = 0x0000_0001;
    extern "system" {
        fn SetHandleInformation(
            h_object: *mut core::ffi::c_void,
            dw_mask: u32,
            dw_flags: u32,
        ) -> i32;
    }
    for (handle, flags) in previous {
        unsafe {
            SetHandleInformation(handle, HANDLE_FLAG_INHERIT, flags & HANDLE_FLAG_INHERIT);
        }
    }
}

/// Handle the `loop` command — execute a task periodically with persistence,
/// resume, pause, and stop support.
async fn handle_loop(
    client: &Client,
    base_url: &str,
    global: &args::GlobalFlags,
) -> Result<(), String> {
    let parsed = parse_loop_args(&global.args[1..])?;

    let loop_name: Option<&str> = parsed.name.as_deref();

    // --- --list: list all persisted loops ---
    if parsed.list {
        let entries = state::list_loop_states(None);
        if entries.is_empty() {
            cli_println!("No persisted loops. Start one with `browser4-cli loop <task>`.");
            cli_println!("Completed loops are auto-cleaned — see `browser4-cli loop --history` for recent results.");
        } else {
            cli_println!("{} persisted loop(s):\n", entries.len());
            for entry in &entries {
                let (icon, status_label) = match entry.status.as_str() {
                    "running" => ("▶", "running"),
                    "paused" => ("⏸", "paused"),
                    "stopped" => ("⏹", "stopped"),
                    "completed" => ("✓", "completed"),
                    _ => ("?", &entry.status[..]),
                };
                let name_display = if entry.name == "default" {
                    "(default)".to_string()
                } else {
                    entry.name.clone()
                };
                let count_display = match entry.status.as_str() {
                    "completed" => entry.iterations_completed.to_string(),
                    _ => match entry.count {
                        Some(max) => format!("{}/{}", entry.iterations_completed, max),
                        None => format!("{}", entry.iterations_completed),
                    },
                };
                let interval_display = format_duration(entry.interval_secs);
                cli_println!(
                    "  {}  {:<20}  {:>6} iters  {:>5} intv  {:<8}  {}",
                    icon,
                    name_display,
                    count_display,
                    interval_display,
                    status_label,
                    entry.task,
                );
            }
            cli_println!("\nColumns: name, iters (completed[/max]), interval, status, task.");
            // The auto-clean hint used to appear only when the list was empty, so
            // a loop that finished while others kept running simply vanished from
            // the table with no explanation (#8).  Always explain it, and name the
            // state directory the rows live in — in dev mode that is the
            // per-checkout workspace directory, not `~/.browser4` (#7).
            cli_println!("Completed loops are auto-cleaned — see `browser4-cli loop --history` (--keep-state retains the state file).");
            cli_println!(
                "State directory: {}",
                state::resolve_default_state_dir().display()
            );
            cli_println!("Use --status [name] for full details, --pause/--resume [name] to control, --stop [name] to clear.");
        }
        json_field("loops", json!(entries));
        return Ok(());
    }

    // --- --history: show recently completed loops ---
    if parsed.history {
        let entries = state::read_loop_history(None);
        if entries.is_empty() {
            cli_println!(
                "No completed loops in history. Start one with `browser4-cli loop <task>`."
            );
        } else {
            cli_println!(
                "{} completed loop(s) in history (newest last):\n",
                entries.len()
            );
            for entry in &entries {
                let reason_label = match entry.exit_reason.as_str() {
                    "count-reached" => "count reached",
                    "timeout" => "timeout",
                    "stopped" => "stopped by user",
                    "interrupted" => "interrupted",
                    _ => &entry.exit_reason,
                };
                let name_display = if entry.name == "default" {
                    "(default)".to_string()
                } else {
                    entry.name.clone()
                };
                cli_println!(
                    "  ✓  {:<20}  {:>3} iters  {:<16}  {}  {}",
                    name_display,
                    entry.iterations_completed,
                    reason_label,
                    entry.completed_at,
                    entry.task_tokens.join(" "),
                );
            }
            cli_println!(
                "\nHistory keeps the most recent {} completed loops.",
                state::MAX_HISTORY_ENTRIES
            );
        }
        json_field("history", json!(entries));
        return Ok(());
    }

    // --- --status: print loop state and exit ---
    if parsed.status {
        let state_path = state::loop_state_path(None, loop_name);
        match state::read_loop_state(None, loop_name) {
            Some(ls) => {
                let label = if let Some(ref n) = parsed.name {
                    format!("Loop \"{}\"", n)
                } else {
                    "Loop".to_string()
                };
                let (icon, status_label) = match ls.status.as_str() {
                    "running" => ("▶", "Running"),
                    "paused" => ("⏸", "Paused"),
                    "stopped" => ("⏹", "Stopped by user"),
                    "completed" => ("✓", "Completed"),
                    _ => ("?", &ls.status[..]),
                };
                cli_println!("{}  {} {}", icon, label, status_label);
                cli_println!("   Task:       {}", ls.task_tokens.join(" "));
                cli_println!("   Mode:       {}", ls.mode);
                cli_println!("   Interval:   {}", format_duration(ls.interval_secs));
                if let Some(n) = ls.count {
                    let remaining = n.saturating_sub(ls.iterations_completed);
                    cli_println!(
                        "   Iterations: {}/{} ({} remaining)",
                        ls.iterations_completed,
                        n,
                        remaining
                    );
                } else {
                    cli_println!("   Iterations: {} (no limit)", ls.iterations_completed);
                }
                if let Some(t) = ls.timeout_secs {
                    if let Ok(started) = chrono::DateTime::parse_from_rfc3339(&ls.started_at) {
                        let started_utc = started.with_timezone(&Utc);
                        let elapsed = Utc::now()
                            .signed_duration_since(started_utc)
                            .to_std()
                            .unwrap_or_default();
                        let elapsed_secs = elapsed.as_secs();
                        let remaining_secs = t.saturating_sub(elapsed_secs);
                        cli_println!(
                            "   Timeout:    {} total, {} elapsed, {} remaining",
                            format_duration(t),
                            format_duration(elapsed_secs),
                            format_duration(remaining_secs),
                        );
                    } else {
                        cli_println!("   Timeout:    {}", format_duration(t));
                    }
                }
                cli_println!(
                    "   Started:    {}",
                    format_timestamp_display(&ls.started_at)
                );
                cli_println!(
                    "   Updated:    {}",
                    format_timestamp_display(&ls.updated_at)
                );
                cli_println!("   State file: {}", state_path.display());
                json_field(
                    "loop_state",
                    json!({
                        "name": loop_name.unwrap_or("default"),
                        "task_tokens": ls.task_tokens,
                        "mode": ls.mode,
                        "interval_secs": ls.interval_secs,
                        "count": ls.count,
                        "timeout_secs": ls.timeout_secs,
                        "iterations_completed": ls.iterations_completed,
                        "started_at": ls.started_at,
                        "updated_at": ls.updated_at,
                        "status": ls.status,
                        "state_file": state_path.to_string_lossy(),
                    }),
                );
            }
            None => {
                if let Some(n) = loop_name {
                    cli_println!("No loop named \"{}\".", n);
                    if state_path.exists() {
                        cli_println!("State file: {}", state_path.display());
                    } else {
                        cli_println!("Use `browser4-cli loop --list` to see persisted loops, or `browser4-cli loop --history` for completed ones.");
                    }
                } else {
                    cli_println!("No active loop.");
                    cli_println!("State file: {}", state_path.display());
                    cli_println!("Start one with `browser4-cli loop <task>`.");
                }
            }
        }
        return Ok(());
    }

    // --- --stop: clear persisted loop state and exit ---
    if parsed.stop {
        let state_path = state::loop_state_path(None, loop_name);
        match state::read_loop_state(None, loop_name) {
            Some(ls) => {
                let total = ls.iterations_completed;
                let was_active = ls.status == "running" || ls.status == "paused";
                let live_worker = state::live_loop_worker_pid(None, loop_name);
                let label = loop_name.unwrap_or("default");

                // The sentinel is written FIRST and is independent of the
                // progress file: a worker that wakes from a sleep no longer
                // finds "no state file" and recreates itself as running.
                if was_active {
                    let _ = state::request_loop_stop(None, loop_name, "stop");
                }

                // History is written by the worker — the only process that can
                // observe why the loop ended — so the control command writes an
                // entry only for a loop that had no worker left to do it (an
                // already-inactive record).  A loop that was running may still
                // have a worker that has not persisted its PID yet, and writing
                // here as well produced two entries per stop (#122234#6).
                if !was_active {
                    let history_entry = state::LoopHistoryEntry {
                        name: label.to_string(),
                        task_tokens: ls.task_tokens.clone(),
                        mode: ls.mode.clone(),
                        iterations_completed: total,
                        exit_reason: "stopped".to_string(),
                        completed_at: Utc::now().to_rfc3339(),
                    };
                    let _ = state::write_loop_history(&history_entry, None);
                }

                // For an active loop, persist status "stopped" as well so workers
                // that only poll the status file also see the signal.  Deleting
                // the file here would let the worker's next progress persist
                // recreate it as "running", making the loop appear to revive.
                if was_active {
                    let _ = state::set_loop_status(None, loop_name, "stopped");
                } else {
                    state::clear_loop_state(None, loop_name);
                    state::clear_loop_stop_request(None, loop_name);
                }

                if let Some(pid) = live_worker {
                    // Verify the worker actually exits before claiming success:
                    // the old message asserted it while the loop kept running.
                    let deadline = std::time::Instant::now()
                        + std::time::Duration::from_secs(STOP_ALL_SETTLE_TIMEOUT_SECS);
                    while std::time::Instant::now() < deadline && state::is_process_alive(pid) {
                        tokio::time::sleep(std::time::Duration::from_millis(
                            PAUSE_POLL_INTERVAL_SECS * 250,
                        ))
                        .await;
                    }
                    if state::is_process_alive(pid) {
                        cli_println!(
                            "⏹  Stop signaled to loop \"{}\" ({} iteration(s) so far); \
                             worker PID {} is still finishing its current iteration after {}s.",
                            label,
                            total,
                            pid,
                            STOP_ALL_SETTLE_TIMEOUT_SECS
                        );
                        cli_println!(
                            "   It exits at its next checkpoint and then clears its state and \
                             writes the history entry; re-run --stop to confirm."
                        );
                        json_field("worker_still_running", json!(true));
                    } else {
                        cli_println!(
                            "✓  Loop \"{}\" stopped ({} iteration(s)); worker PID {} exited.",
                            label,
                            total,
                            pid
                        );
                        json_field("worker_still_running", json!(false));
                    }
                    json_field("worker_pid", json!(pid));
                } else if was_active {
                    // No PID is recorded yet — the worker may still be starting
                    // (a `--resume` spawns it and returns immediately).  The
                    // sentinel is deliberately LEFT in place so that worker stops
                    // at its first checkpoint instead of running on as an orphan;
                    // `--resume` clears it when the user wants the loop to live.
                    cli_println!(
                        "⏹  Stop signaled to loop \"{}\" (was {} with {} iteration(s)); no worker \
                         PID was recorded yet, so the stop request stays pending until a worker \
                         honours it.",
                        label,
                        ls.status,
                        total
                    );
                    cli_println!(
                        "   A starting worker exits at its first checkpoint; `loop --resume` \
                         clears the pending request."
                    );
                    json_field("worker_pid", json!(null));
                    json_field("worker_still_running", json!(null));
                } else {
                    cli_println!(
                        "✓  Loop \"{}\" state cleared (was {} with {} iteration(s)).",
                        label,
                        ls.status,
                        total
                    );
                    cli_println!("   Removed: {}", state_path.display());
                }
                json_field("stopped", json!(true));
                json_field("signaled", json!(was_active));
                json_field("name", json!(label));
                json_field("iterations_completed", json!(total));
                json_field("previous_status", json!(ls.status));
            }
            None => {
                if let Some(n) = loop_name {
                    cli_println!("No loop named \"{}\" to stop.", n);
                } else {
                    cli_println!("No active loop to stop.");
                }
                if state_path.exists() {
                    cli_println!("State file: {}", state_path.display());
                } else {
                    cli_println!("Use `browser4-cli loop --list` to see persisted loops, or `browser4-cli loop --history` for completed ones.");
                }
            }
        }
        return Ok(());
    }

    // --- --stop-all: signal all active loops and clear inactive states ---
    if parsed.stop_all {
        let entries = state::list_loop_states(None);
        if entries.is_empty() {
            cli_println!("No persisted loops to stop.");
            return Ok(());
        }
        // Signal active (running/paused) loops two ways: the stop sentinel —
        // which is independent of the progress file, so a worker that wakes up
        // mid-sleep cannot miss it — and the status field, which workers that
        // are polling pick up as before.  Deleting the state files here would
        // let a worker's next persist recreate them as "running" (the loops
        // would appear to revive).
        let mut live_pids: Vec<(String, u32)> = Vec::new();
        for entry in &entries {
            let name_opt = if entry.name == "default" {
                None
            } else {
                Some(entry.name.as_str())
            };
            if let Some(pid) = state::live_loop_worker_pid(None, name_opt) {
                live_pids.push((entry.name.clone(), pid));
            }
            if entry.status == "running" || entry.status == "paused" {
                let _ = state::request_loop_stop(None, name_opt, "stop-all");
            }
        }
        let signaled_count =
            state::set_all_loop_statuses_filtered(None, Some("running"), "stopped")
                + state::set_all_loop_statuses_filtered(None, Some("paused"), "stopped");
        // Inactive loops (completed/stopped/…) have no worker to notify — remove
        // their state files directly.
        let mut removed = 0usize;
        for entry in &entries {
            let was_active = entry.status == "running" || entry.status == "paused";
            if !was_active {
                let name_opt = if entry.name == "default" {
                    None
                } else {
                    Some(entry.name.as_str())
                };
                state::clear_loop_state(None, name_opt);
                state::clear_loop_stop_request(None, name_opt);
                removed += 1;
            }
        }

        if signaled_count > 0 {
            // A signalled worker only exits at its next checkpoint (up to one
            // iteration away).  Wait for the recorded worker PIDs to actually
            // disappear and report what happened instead of asserting success:
            // the old success line was printed before any worker could react,
            // and a loop was still running minutes later (#122234#3).
            let deadline = std::time::Instant::now()
                + std::time::Duration::from_secs(STOP_ALL_SETTLE_TIMEOUT_SECS);
            while std::time::Instant::now() < deadline
                && live_pids
                    .iter()
                    .any(|(_, pid)| state::is_process_alive(*pid))
            {
                tokio::time::sleep(std::time::Duration::from_millis(PAUSE_POLL_INTERVAL_SECS * 250))
                    .await;
            }
        }
        let surviving_workers: Vec<String> = live_pids
            .iter()
            .filter(|(_, pid)| state::is_process_alive(*pid))
            .map(|(name, pid)| format!("{name} (PID {pid})"))
            .collect();
        let survivors: Vec<String> = state::list_loop_states(None)
            .iter()
            .filter(|e| e.status == "running" || e.status == "paused")
            .map(|e| e.name.clone())
            .collect();

        cli_println!(
            "⏹  Stop signaled to {} active loop(s); removed {} inactive state file(s).",
            signaled_count,
            removed
        );
        if !surviving_workers.is_empty() {
            cli_println!(
                "⚠  {} worker(s) still alive after {}s: {}.",
                surviving_workers.len(),
                STOP_ALL_SETTLE_TIMEOUT_SECS,
                surviving_workers.join(", ")
            );
            cli_println!(
                "   They exit at the next checkpoint (a long iteration can outlast this wait); \
                 re-run --stop-all to confirm."
            );
        }
        if !survivors.is_empty() {
            cli_println!(
                "⚠  {} loop(s) still report running/paused: {}.",
                survivors.len(),
                survivors.join(", ")
            );
        }
        // Every loop that reported inactive had no worker; a signalled worker
        // clears its own file and sentinel when it exits.  Anything left belongs
        // to a loop whose worker may still be exiting, so it is never deleted
        // here (a deleted file is what let a mid-sleep worker recreate itself as
        // "running" and revive the loop).  With no active loop at all the whole
        // store is stale state, which is exactly what clear_all_loop_states is for.
        if signaled_count == 0 {
            let cleared = state::clear_all_loop_states(None);
            if cleared != removed {
                removed = cleared;
            }
        }
        for entry in &entries {
            cli_println!(
                "   - {} ({} iters, was {})",
                entry.name,
                entry.iterations_completed,
                entry.status
            );
        }
        json_field("stopped_all", json!(true));
        json_field("signaled_count", json!(signaled_count));
        json_field("cleared_count", json!(removed));
        json_field("survivors", json!(survivors));
        json_field("loops", json!(entries));
        return Ok(());
    }

    // --- --pause: control op (pause running loop) or start-paused ---
    if parsed.pause {
        // If a task is provided, this is "start paused" — persist the
        // loop in paused state so the user can --resume later.
        if !parsed.task_tokens.is_empty() {
            let mode_key = if parsed.is_subcommand {
                "subcommand"
            } else if parsed.is_shell {
                "shell"
            } else {
                "plain"
            };
            let mode_label = if parsed.is_subcommand {
                "browser4-cli subcommand"
            } else if parsed.is_shell {
                "shell command"
            } else {
                "plain-text command"
            };
            let started_at = Utc::now().to_rfc3339();
            let state = state::LoopState {
                task_tokens: parsed.task_tokens.clone(),
                mode: mode_key.to_string(),
                interval_secs: parsed.interval_secs,
                count: parsed.count,
                timeout_secs: parsed.timeout_secs,
                iterations_completed: 0,
                started_at: started_at.clone(),
                updated_at: Utc::now().to_rfc3339(),
                status: "paused".to_string(),
                // Created paused: no worker exists until `--resume` spawns one.
                worker_pid: None,
            };
            let state_path = state::loop_state_path(None, loop_name);
            if let Err(e) = state::write_loop_state(&state, None, loop_name) {
                eprintln!("[WARN] Failed to persist loop state: {}", e);
            }
            let label = loop_name.unwrap_or("default");
            cli_println!(
                "Loop: \"{}\" — every {}s{}",
                parsed.task_tokens.join(" "),
                parsed.interval_secs,
                match (parsed.count, parsed.timeout_secs) {
                    (Some(n), Some(t)) => format!(", up to {} iterations or {}s", n, t),
                    (Some(n), None) => format!(", up to {} iterations", n),
                    (None, Some(t)) => format!(", up to {}s", t),
                    (None, None) => String::new(),
                }
            );
            cli_println!("  Mode: {}", mode_label);
            cli_println!(
                "⏸  Created as paused. Use `browser4-cli loop --resume{}` to start.",
                if parsed.name.is_some() {
                    format!(" --name {}", parsed.name.as_ref().unwrap())
                } else {
                    String::new()
                },
            );
            cli_println!("   State file: {}", state_path.display());
            json_field("started_paused", json!(true));
            json_field("name", json!(label));
            return Ok(());
        }

        // No task — control op: pause an existing running loop.
        let state_path = state::loop_state_path(None, loop_name);
        match state::set_loop_status(None, loop_name, "paused") {
            Some(prev) => {
                let label = loop_name.unwrap_or("default");
                if prev == "paused" {
                    cli_println!("⏸  Loop \"{}\" is already paused.", label);
                } else {
                    cli_println!(
                        "⏸  Loop \"{}\" paused (was {}). Use `browser4-cli loop --resume{}` to continue.",
                        label,
                        prev,
                        if parsed.name.is_some() { format!(" --name {}", parsed.name.as_ref().unwrap()) } else { String::new() },
                    );
                }
                cli_println!("   State file: {}", state_path.display());
                json_field("paused", json!(true));
                json_field("name", json!(label));
                json_field("previous_status", json!(prev));
            }
            None => {
                if let Some(n) = loop_name {
                    cli_println!("No loop named \"{}\" to pause.", n);
                } else {
                    cli_println!("No active loop to pause.");
                }
                if state_path.exists() {
                    cli_println!("State file: {}", state_path.display());
                } else {
                    cli_println!("Use `browser4-cli loop --list` to see persisted loops, or `browser4-cli loop --history` for completed ones.");
                }
            }
        }
        return Ok(());
    }

    // --- --resume: set loop status to "running" and spawn execution ---
    if parsed.resume {
        let state_path = state::loop_state_path(None, loop_name);
        // A paused loop keeps its worker resident (the worker polls the state
        // file and continues on its own), so spawning here produced TWO workers
        // for one loop and every iteration ran twice (122234#1).  Un-stopping
        // also clears any stop sentinel left by a previous `--stop`.
        let live_worker = state::live_loop_worker_pid(None, loop_name);
        state::clear_loop_stop_request(None, loop_name);
        match state::set_loop_status(None, loop_name, "running") {
            Some(prev) => {
                let label = loop_name.unwrap_or("default");
                if prev == "running" {
                    cli_println!("▶  Loop \"{}\" is already running.", label);
                    if let Some(pid) = live_worker {
                        cli_println!("   Worker PID {} is alive — not starting a second one.", pid);
                    }
                    cli_println!("   State file: {}", state_path.display());
                    json_field("resumed", json!(true));
                    json_field("name", json!(label));
                    json_field("previous_status", json!(prev));
                    json_field("worker_pid", json!(live_worker));
                } else {
                    cli_println!("▶  Loop \"{}\" resumed (was {}).", label, prev);
                    if let Some(pid) = live_worker {
                        // The resident worker picks the status change up at its
                        // next poll; starting another one would duplicate it.
                        cli_println!(
                            "   Existing worker PID {} continues this loop — no new worker started.",
                            pid
                        );
                        cli_println!("   Iteration output: {}", state_path.with_extension("log").display());
                        json_field("resumed", json!(true));
                        json_field("name", json!(label));
                        json_field("previous_status", json!(prev));
                        json_field("worker_pid", json!(pid));
                        return Ok(());
                    }

                    // Read the full loop state to reconstruct the command and
                    // spawn a detached background process that actually executes
                    // the iterations.
                    if let Some(ls) = state::read_loop_state(None, loop_name) {
                        // Reconstruct the CLI arguments for the loop command.
                        let mut cmd_args: Vec<String> = vec!["loop".to_string()];

                        // Add --name if named
                        if let Some(ref n) = parsed.name {
                            cmd_args.push("--name".to_string());
                            cmd_args.push(n.clone());
                        }

                        // Add mode flags
                        match ls.mode.as_str() {
                            "shell" => {
                                cmd_args.push("--shell".to_string());
                            }
                            "subcommand" => {
                                cmd_args.push("--".to_string());
                            }
                            _ => {} // plain mode — no flag
                        }

                        // Add task tokens
                        cmd_args.extend(ls.task_tokens.clone());

                        // Add scheduling flags
                        cmd_args.push("--interval".to_string());
                        cmd_args.push(ls.interval_secs.to_string());
                        if let Some(c) = ls.count {
                            cmd_args.push("--count".to_string());
                            cmd_args.push(c.to_string());
                        }
                        if let Some(t) = ls.timeout_secs {
                            // Use `-t` (short form) instead of `--timeout` so the
                            // global HTTP-timeout parser cannot swallow it.
                            cmd_args.push("-t".to_string());
                            cmd_args.push(t.to_string());
                        }

                        // Spawn a detached background process with a per-loop log
                        // file so iteration output is visible after --resume.
                        let log_path = state_path.with_extension("log");
                        let exe = std::env::current_exe()
                            .map_err(|e| format!("Cannot determine CLI path: {}", e))?;

                        match spawn_detached(&exe, &cmd_args, Some(&log_path)) {
                            Ok(child_id) => {
                                cli_println!(
                                    "   Spawned background process (PID: {}). Use --list to monitor, \
                                     --pause to pause, --stop to clear.",
                                    child_id,
                                );
                                cli_println!(
                                    "   Iteration output: {}",
                                    log_path.display(),
                                );
                            }
                            Err(e) => {
                                eprintln!(
                                    "[WARN] Failed to spawn background process: {}. \
                                     Run the same loop command manually to start execution.",
                                    e,
                                );
                            }
                        }
                    }

                    cli_println!("   State file: {}", state_path.display());
                    json_field("resumed", json!(true));
                    json_field("name", json!(label));
                    json_field("previous_status", json!(prev));
                }
            }
            None => {
                if let Some(n) = loop_name {
                    cli_println!("No loop named \"{}\" to resume.", n);
                } else {
                    cli_println!("No active loop to resume.");
                    cli_println!("Start one with `browser4-cli loop <task>`.");
                }
                if state_path.exists() {
                    cli_println!("State file: {}", state_path.display());
                } else {
                    cli_println!("Use `browser4-cli loop --list` to see persisted loops, or `browser4-cli loop --history` for completed ones.");
                }
            }
        }
        return Ok(());
    }

    // --- --pause-all: pause all running loops ---
    if parsed.pause_all {
        let entries = state::list_loop_states(None);
        let running: Vec<_> = entries.iter().filter(|e| e.status == "running").collect();
        if running.is_empty() {
            cli_println!("No running loops to pause.");
            if !entries.is_empty() {
                cli_println!("Use --list to see all loops.");
            }
            return Ok(());
        }
        let updated = state::set_all_loop_statuses_filtered(None, Some("running"), "paused");
        cli_println!("⏸  Paused {} running loop(s):", updated);
        for entry in &running {
            cli_println!("   - {}", entry.name);
        }
        cli_println!("\nUse `browser4-cli loop --resume-all` to resume all, or --resume --name <n> for a specific loop.");
        json_field("paused_all", json!(true));
        json_field("paused_count", json!(updated));
        json_field("loops", json!(running));
        return Ok(());
    }

    // --- --resume-all: resume all paused loops and spawn execution ---
    if parsed.resume_all {
        let entries = state::list_loop_states(None);
        let paused: Vec<_> = entries.iter().filter(|e| e.status == "paused").collect();
        if paused.is_empty() {
            cli_println!("No paused loops to resume.");
            if !entries.is_empty() {
                cli_println!("Use --list to see all loops.");
            }
            return Ok(());
        }
        let updated = state::set_all_loop_statuses_filtered(None, Some("paused"), "running");
        cli_println!("▶  Resumed {} paused loop(s):", updated);

        let exe = std::env::current_exe().unwrap_or_default();
        for entry in &paused {
            let name = if entry.name == "default" {
                None
            } else {
                Some(entry.name.as_str())
            };
            // Same ownership rule as `--resume`: a live worker picks the status
            // change up itself, so spawning another one would duplicate it.
            state::clear_loop_stop_request(None, name);
            if let Some(pid) = state::live_loop_worker_pid(None, name) {
                cli_println!(
                    "   - {} (worker PID {} still alive — signalled, no new worker)",
                    entry.name,
                    pid
                );
                continue;
            }
            if let Some(ls) = state::read_loop_state(None, name) {
                // Reconstruct CLI arguments
                let mut cmd_args: Vec<String> = vec!["loop".to_string()];
                if let Some(n) = name {
                    cmd_args.push("--name".to_string());
                    cmd_args.push(n.to_string());
                }
                match ls.mode.as_str() {
                    "shell" => {
                        cmd_args.push("--shell".to_string());
                    }
                    "subcommand" => {
                        cmd_args.push("--".to_string());
                    }
                    _ => {}
                }
                cmd_args.extend(ls.task_tokens.clone());
                cmd_args.push("--interval".to_string());
                cmd_args.push(ls.interval_secs.to_string());
                if let Some(c) = ls.count {
                    cmd_args.push("--count".to_string());
                    cmd_args.push(c.to_string());
                }
                if let Some(t) = ls.timeout_secs {
                    cmd_args.push("-t".to_string());
                    cmd_args.push(t.to_string());
                }

                let log_path = state::loop_state_path(None, name).with_extension("log");
                match spawn_detached(&exe, &cmd_args, Some(&log_path)) {
                    Ok(child_id) => {
                        cli_println!("   - {} (PID: {})", entry.name, child_id);
                    }
                    Err(e) => {
                        cli_println!("   - {} (failed to spawn: {})", entry.name, e);
                    }
                }
            }
        }
        json_field("resumed_all", json!(true));
        json_field("resumed_count", json!(updated));
        json_field("loops", json!(paused));
        return Ok(());
    }

    // Ensure the server is running before loop execution.
    // (Loop control-flow commands like --list / --stop return early above
    // without reaching here, so the server is only started when needed.)
    ensure_server_running(base_url, should_enforce_server_version(global)).await?;

    // --- build the mode label ---
    let mode_label = if parsed.is_subcommand {
        "browser4-cli subcommand"
    } else if parsed.is_shell {
        "shell command"
    } else {
        "plain-text command"
    };
    let mode_key = if parsed.is_subcommand {
        "subcommand"
    } else if parsed.is_shell {
        "shell"
    } else {
        "plain"
    };

    // --- check for existing persisted loop state (resume) ---
    let mut iteration: u64 = 1;
    let overall_start: std::time::Instant;
    let started_at: String;

    if let Some(existing) = state::read_loop_state(None, loop_name) {
        if existing.status == "stopped" {
            // Previous loop was explicitly stopped — start fresh
            state::clear_loop_state(None, loop_name);
            started_at = Utc::now().to_rfc3339();
            overall_start = std::time::Instant::now();
        } else if existing.task_tokens == parsed.task_tokens && existing.mode == mode_key {
            // Same task, same mode — resume
            iteration = existing.iterations_completed + 1;
            cli_println!(
                "Resuming loop: \"{}\" from iteration {}",
                parsed.task_tokens.join(" "),
                iteration
            );
            started_at = existing.started_at;
            // Use the original started_at to calculate the overall elapsed time
            let started = chrono::DateTime::parse_from_rfc3339(&started_at)
                .map(|dt| dt.with_timezone(&Utc))
                .unwrap_or_else(|_| Utc::now());
            let elapsed = Utc::now()
                .signed_duration_since(started)
                .to_std()
                .unwrap_or_default();
            overall_start = std::time::Instant::now()
                .checked_sub(elapsed)
                .unwrap_or(std::time::Instant::now());
            if existing.status == "paused" {
                cli_println!("  Loop was paused — resuming now.");
            }
        } else {
            // Different task — warn and start fresh
            cli_println!(
                "Note: A different loop task was persisted. Starting fresh. \
                 Use --stop to clear the previous loop first if needed."
            );
            state::clear_loop_state(None, loop_name);
            started_at = Utc::now().to_rfc3339();
            overall_start = std::time::Instant::now();
        }
    } else {
        started_at = Utc::now().to_rfc3339();
        overall_start = std::time::Instant::now();
    }

    cli_println!(
        "Loop: \"{}\" — every {}s{}",
        parsed.task_tokens.join(" "),
        parsed.interval_secs,
        match (parsed.count, parsed.timeout_secs) {
            (Some(n), Some(t)) => format!(", up to {} iterations or {}s", n, t),
            (Some(n), None) => format!(", up to {} iterations", n),
            (None, Some(t)) => format!(", up to {}s", t),
            (None, None) => " (Ctrl+C to stop, --pause to pause)".to_string(),
        }
    );
    cli_println!("  Mode: {}", mode_label);
    if iteration > 1 {
        cli_println!("  Resumed at iteration: {}", iteration);
    }

    let mut results: Vec<Value> = Vec::new();

    // Persist initial state before the first iteration.
    // Track first write failure so we warn exactly once.
    let write_warned = std::cell::Cell::new(false);
    let persist = |task_tokens: &[String],
                   mode: &str,
                   interval: u64,
                   count: Option<u64>,
                   timeout: Option<u64>,
                   completed: u64,
                   started: &str,
                   status: &str| {
        let state = state::LoopState {
            task_tokens: task_tokens.to_vec(),
            mode: mode.to_string(),
            interval_secs: interval,
            count,
            timeout_secs: timeout,
            iterations_completed: completed,
            started_at: started.to_string(),
            updated_at: Utc::now().to_rfc3339(),
            status: status.to_string(),
            // This process owns the loop: recorded so `--pause`/`--resume`/`--stop`
            // can tell a live worker from a leftover state file (122234#1).
            worker_pid: Some(std::process::id()),
        };
        if let Err(e) = state::write_loop_state(&state, None, loop_name) {
            if !write_warned.replace(true) {
                eprintln!(
                    "[WARN] Failed to persist loop state: {}. Progress will not survive a restart.",
                    e,
                );
            }
        }
    };

    persist(
        &parsed.task_tokens,
        mode_key,
        parsed.interval_secs,
        parsed.count,
        parsed.timeout_secs,
        iteration.saturating_sub(1),
        &started_at,
        "running",
    );

    // Set when a control command (`--stop` / `--stop-all`) ended this run, so
    // the history entry this worker writes is labelled "stopped" instead of
    // "interrupted" (#122234#6).
    let mut stopped_by_control = false;

    loop {
        // --- check for external signals (stop / pause) ---
        // The stop sentinel is authoritative and independent of the progress
        // file: a control command writes it first, so a worker that wakes from a
        // sleep cannot miss the stop and recreate the state file as "running"
        // (issue 122234#3).
        if state::loop_stop_requested(None, loop_name) {
            stopped_by_control = true;
            cli_println!(
                "\nStop requested. Halting after {} iteration(s).",
                iteration.saturating_sub(1)
            );
            break;
        }
        if let Some(existing) = state::read_loop_state(None, loop_name) {
            if existing.status == "stopped" {
                stopped_by_control = true;
                cli_println!(
                    "\nStop signal detected. Halting after {} iteration(s).",
                    iteration.saturating_sub(1)
                );
                break;
            }
            if existing.status == "paused" {
                cli_println!(
                    "\n⏸  Pause signal detected after {} iteration(s). Waiting for resume...",
                    iteration.saturating_sub(1)
                );
                cli_println!(
                    "   Use `browser4-cli loop --resume{}` to continue, or --stop to clear.",
                    if let Some(ref n) = parsed.name {
                        format!(" --name {}", n)
                    } else {
                        String::new()
                    }
                );

                // Poll until resumed or stopped
                loop {
                    if state::loop_stop_requested(None, loop_name) {
                        stopped_by_control = true;
                        cli_println!("Stop requested while paused. Halting.");
                        break;
                    }
                    match state::read_loop_state(None, loop_name) {
                        Some(current) if current.status == "stopped" => {
                            stopped_by_control = true;
                            cli_println!("Stop signal detected while paused. Halting.");
                            // Break outer loop by using the stopped check at top
                            break;
                        }
                        Some(current) if current.status == "running" => {
                            cli_println!("▶  Resumed — continuing loop.\n");
                            break;
                        }
                        None => {
                            // State file disappeared (e.g. deleted externally or
                            // by a --stop that cleared it). Treat as a stop signal
                            // to avoid an orphaned paused process.
                            stopped_by_control = true;
                            cli_println!("State file removed while paused — treating as stop. Halting.");
                            break;
                        }
                        _ => {}
                    }
                    // Also check for Ctrl+C while paused
                    tokio::select! {
                        _ = tokio::time::sleep(std::time::Duration::from_secs(PAUSE_POLL_INTERVAL_SECS)) => {},
                        _ = tokio::signal::ctrl_c() => {
                            cli_println!(
                                "\n\nInterrupted while paused. {} iteration(s) completed.",
                                iteration.saturating_sub(1)
                            );
                            cli_println!(
                                "State remains paused. Use --resume to continue or --stop to clear."
                            );
                            json_field("iterations", json!(results));
                            json_field("total_iterations", json!(iteration.saturating_sub(1)));
                            json_field("status", json!("paused"));
                            return Ok(());
                        },
                    }
                }

                // Re-check status after the inner loop to handle "stopped"
                continue;
            }
        }

        // --- limit checks (at top so --count 0 returns immediately) ---
        if let Some(max) = parsed.count {
            if iteration > max {
                break;
            }
        }

        if let Some(timeout) = parsed.timeout_secs {
            if overall_start.elapsed().as_secs() >= timeout {
                cli_println!(
                    "\nTimeout reached ({}s). Stopping after {} iteration(s).",
                    timeout,
                    iteration.saturating_sub(1)
                );
                break;
            }
        }

        let iter_start = std::time::Instant::now();
        let timestamp = Local::now().format("%Y-%m-%d %H:%M:%S%.3f").to_string();

        cli_println!("\n--- Iteration {} [{}] ---", iteration, timestamp);

        // --- execute ---
        // Race the execution against Ctrl+C so the loop can persist progress
        // and exit cleanly instead of leaving a stale state file.
        let ctrl_c_fut = tokio::signal::ctrl_c();
        tokio::pin!(ctrl_c_fut);

        let exec_fut = async {
            if parsed.is_subcommand {
                run_browser4_cli(&parsed.task_tokens).await
            } else if parsed.is_shell {
                run_shell_command(&parsed.task_tokens.join(" "))
            } else {
                // Plain text command (or x-sql — server auto-detects)
                submit_plain_command(
                    client,
                    base_url,
                    &parsed.task_tokens.join(" "),
                    false, // sync — the loop itself provides the pacing
                )
                .await
            }
        };
        tokio::pin!(exec_fut);

        let result: Result<String, String> = tokio::select! {
            r = &mut exec_fut => r,
            _ = &mut ctrl_c_fut => {
                // Ctrl+C arrived mid-execution.  Persist the progress we have
                // (the current iteration did not complete) so the loop can be
                // resumed from the last finished iteration.
                persist(
                    &parsed.task_tokens, mode_key, parsed.interval_secs,
                    parsed.count, parsed.timeout_secs,
                    iteration.saturating_sub(1), &started_at, "running",
                );
                let state_path = state::loop_state_path(None, loop_name);
                cli_println!(
                    "\n\n⏸  Interrupted during iteration {} — {} iteration(s) completed.",
                    iteration,
                    iteration.saturating_sub(1),
                );
                cli_println!(
                    "   State saved to {}. Run the same command to resume, \
                     or `browser4-cli loop --stop` to clear.",
                    state_path.display(),
                );
                json_field("iterations", json!(results));
                json_field("total_iterations", json!(iteration.saturating_sub(1)));
                return Ok(());
            },
        };

        match &result {
            Ok(output) => {
                if output.is_empty() {
                    cli_println!("(empty)");
                } else if !parsed.is_shell && !parsed.is_subcommand {
                    // Plain-text mode: the output is a raw JSON envelope from
                    // the server's command_run endpoint. Print a concise
                    // human-readable line instead of the full envelope.
                    if let Ok(json) = serde_json::from_str::<serde_json::Value>(output) {
                        // The envelope carries the agent's text under
                        // `commandResult.summary` (and a top-level `message`);
                        // looking only for `pageSummary`/`instructResults[0]`
                        // missed both, and the fallback then dumped the whole
                        // ~2.5 KB envelope per iteration (#122234#4).
                        let summary = json
                            .get("commandResult")
                            .and_then(|cr| cr.get("summary"))
                            .or_else(|| {
                                json.get("commandResult")
                                    .and_then(|cr| cr.get("pageSummary"))
                            })
                            .or_else(|| {
                                json.get("instructResults")
                                    .and_then(|ir| ir.as_array()?.first())
                                    .and_then(|first| first.get("result"))
                            })
                            .or_else(|| json.get("message"))
                            .and_then(|v| v.as_str())
                            .map(str::trim)
                            .filter(|s| !s.is_empty());
                        if let Some(s) = summary {
                            // First 120 chars for monitoring
                            let display = if s.chars().count() > 120 {
                                format!("{}...", s.chars().take(117).collect::<String>())
                            } else {
                                s.to_string()
                            };
                            cli_println!("  {}", display);
                        } else {
                            // Fallback: print the raw output (not valid JSON)
                            cli_println!("{}", output);
                        }
                        // A payload-level failure must be visible even though the
                        // envelope itself arrived: name the reason on stderr.
                        let failure = json
                            .get("error")
                            .and_then(|v| v.as_str())
                            .or_else(|| {
                                json.get("commandResult")
                                    .and_then(|cr| cr.get("error"))
                                    .and_then(|v| v.as_str())
                            })
                            .map(str::trim)
                            .filter(|e| !e.is_empty());
                        let success = json
                            .get("success")
                            .and_then(|v| v.as_bool())
                            .or_else(|| {
                                json.get("commandResult")
                                    .and_then(|cr| cr.get("success"))
                                    .and_then(|v| v.as_bool())
                            });
                        if success == Some(false) || failure.is_some() {
                            let reason = failure.unwrap_or("the command reported success:false");
                            eprintln!("  [FAILED] {}", reason);
                        }
                    } else {
                        // Not valid JSON — print as-is
                        cli_println!("{}", output);
                    }
                } else {
                    cli_println!("{}", output);
                }
                results.push(json!({
                    "iteration": iteration,
                    "timestamp": timestamp,
                    "ok": true,
                    "output": output,
                }));
            }
            Err(err) => {
                eprintln!("[ERROR] Iteration {}: {}", iteration, err);
                results.push(json!({
                    "iteration": iteration,
                    "timestamp": timestamp,
                    "ok": false,
                    "error": err,
                }));
            }
        }

        // --- persist progress after each iteration ---
        // Preserve an externally-set control status ("stopped"/"paused") instead of
        // blindly overwriting it with "running" — otherwise a `loop --stop` issued
        // mid-iteration would be lost and the loop would appear to revive.
        let current_status = state::read_loop_state(None, loop_name)
            .map(|ls| ls.status)
            .unwrap_or_else(|| "running".to_string());
        let persist_status = match current_status.as_str() {
            "stopped" | "paused" => current_status.as_str(),
            _ => "running",
        };
        // A stop request always wins over a stale "running" status: persisting
        // "running" here is what let a worker revive a stopped loop.
        let persist_status = if state::loop_stop_requested(None, loop_name) {
            "stopped"
        } else {
            persist_status
        };
        persist(
            &parsed.task_tokens,
            mode_key,
            parsed.interval_secs,
            parsed.count,
            parsed.timeout_secs,
            iteration,
            &started_at,
            persist_status,
        );
        if persist_status != "running" {
            // Top-of-loop check will handle the stop/pause on the next pass.
            iteration += 1;
            continue;
        }

        iteration += 1;

        // --- check count again so we don't print a separator after the last ---
        if let Some(max) = parsed.count {
            if iteration > max {
                break;
            }
        }

        // --- sleep (minus elapsed execution time) ---
        let elapsed = iter_start.elapsed();
        let interval = std::time::Duration::from_secs(parsed.interval_secs);
        if elapsed < interval {
            let mut remaining = interval - elapsed;

            // If a timeout is set, cap the sleep so we wake up in time to
            // honour the timeout at the top of the next iteration.
            if let Some(timeout) = parsed.timeout_secs {
                let budget =
                    std::time::Duration::from_secs(timeout).saturating_sub(overall_start.elapsed());
                if budget < remaining {
                    remaining = budget;
                }
            }

            if remaining > std::time::Duration::ZERO {
                // Race: sleep vs ctrl+c vs pause signal
                // Use a polling loop so we can detect external pause/stop signals
                let poll_interval = std::time::Duration::from_secs(PAUSE_POLL_INTERVAL_SECS);
                let mut slept = std::time::Duration::ZERO;

                while slept < remaining {
                    let chunk = std::cmp::min(poll_interval, remaining - slept);
                    tokio::select! {
                        _ = tokio::time::sleep(chunk) => {
                            slept += chunk;
                        },
                        _ = tokio::signal::ctrl_c() => {
                            // Persist progress on Ctrl+C so it can be resumed
                            persist(
                                &parsed.task_tokens, mode_key, parsed.interval_secs,
                                parsed.count, parsed.timeout_secs,
                                iteration.saturating_sub(1), &started_at, "running",
                            );
                            let state_path = state::loop_state_path(None, loop_name);
                            cli_println!(
                                "\n\n⏸  Interrupted — {} of {} iteration(s) completed.",
                                iteration.saturating_sub(1),
                                parsed.count.map_or("∞".to_string(), |n| n.to_string()),
                            );
                            cli_println!(
                                "   State saved to {}. Run the same command to resume, \
                                 or `browser4-cli loop --stop` to clear.",
                                state_path.display(),
                            );
                            json_field("iterations", json!(results));
                            json_field("total_iterations", json!(iteration.saturating_sub(1)));
                            return Ok(());
                        },
                    }

                    // Check for external pause/stop signal during sleep.  The
                    // sentinel is checked first: it survives even if the state
                    // file was already cleared by another worker.
                    if state::loop_stop_requested(None, loop_name) {
                        stopped_by_control = true;
                        persist(
                            &parsed.task_tokens,
                            mode_key,
                            parsed.interval_secs,
                            parsed.count,
                            parsed.timeout_secs,
                            iteration.saturating_sub(1),
                            &started_at,
                            "stopped",
                        );
                        break; // exit the sleep loop, top-of-loop will handle
                    }
                    if let Some(current) = state::read_loop_state(None, loop_name) {
                        if current.status == "stopped" || current.status == "paused" {
                            // Persist and let the top-of-loop check handle it
                            persist(
                                &parsed.task_tokens,
                                mode_key,
                                parsed.interval_secs,
                                parsed.count,
                                parsed.timeout_secs,
                                iteration.saturating_sub(1),
                                &started_at,
                                &current.status,
                            );
                            break; // exit the sleep loop, top-of-loop will handle
                        }
                    }
                }
            }
        }
    }

    // --- summary ---
    let total = iteration.saturating_sub(1);

    // Count failed iterations.  Every executed attempt is recorded in
    // `results` with "ok": true/false, and a failed attempt consumes --count
    // exactly like a successful one (the count limit is checked at the top of
    // each iteration regardless of the previous outcome).
    let failed = results
        .iter()
        .filter(|r| r.get("ok").and_then(|v| v.as_bool()) == Some(false))
        .count();

    // Determine the exit reason for the history log.  A control-command stop is
    // reported as such — this worker is the only process that can observe it, so
    // it is also the only writer of the entry (#122234#6).
    let stopped_by_control = stopped_by_control || state::loop_stop_requested(None, loop_name);
    let exit_reason = {
        let count_reached = parsed.count.map_or(false, |max| total >= max);
        let timed_out = parsed
            .timeout_secs
            .map_or(false, |t| overall_start.elapsed().as_secs() >= t);
        if stopped_by_control {
            "stopped"
        } else if count_reached && !timed_out {
            "count-reached"
        } else if timed_out {
            "timeout"
        } else {
            "interrupted"
        }
    };

    let (summary, all_failed) = format_loop_summary(total, failed as u64);
    cli_println!("\n========================================");
    cli_println!("{}", summary);

    // Write a history entry so users can review past loop completions.
    let history_entry = state::LoopHistoryEntry {
        name: loop_name.unwrap_or("default").to_string(),
        task_tokens: parsed.task_tokens.clone(),
        mode: mode_key.to_string(),
        iterations_completed: total,
        exit_reason: exit_reason.to_string(),
        completed_at: Utc::now().to_rfc3339(),
    };
    let _ = state::write_loop_history(&history_entry, None);

    // The worker honoured the stop request: clear the sentinel so the next run
    // of this loop (and `--resume`) starts from a clean slate.  The sentinel is
    // removed only here or by a control command, never by the progress file.
    state::clear_loop_stop_request(None, loop_name);

    // Clear persisted state on normal completion — the summary was already
    // printed and re-running the same command starts a fresh loop anyway.
    // Unless --keep-state was specified.
    if !parsed.keep_state {
        state::clear_loop_state(None, loop_name);
        cli_println!("   (State auto-cleaned. Use `browser4-cli loop --history` to review past loops, or --keep-state to retain the state file.)");
    } else {
        // Persist final completed state for inspection
        persist(
            &parsed.task_tokens,
            mode_key,
            parsed.interval_secs,
            parsed.count,
            parsed.timeout_secs,
            total,
            &started_at,
            "completed",
        );
        let state_path = state::loop_state_path(None, loop_name);
        cli_println!("   State preserved at: {}", state_path.display());
    }

    json_field("iterations", json!(results));
    json_field("failed_iterations", json!(failed));
    json_field("total_iterations", json!(total));
    json_field("exit_reason", json!(exit_reason));

    if all_failed {
        // Every iteration failed — surface the failure instead of implying
        // success with exit 0, so monitoring scripts can trust the exit code.
        // Partial failures keep exit 0: they are reported in the summary line
        // and in the failed_iterations JSON field, and for long-running loops
        // an occasional failed iteration is expected noise.
        Err(format!(
            "all {} iteration(s) failed — no iteration completed successfully",
            total
        ))
    } else {
        Ok(())
    }
}

/// Compose the final summary for a completed loop run.
///
/// Returns the summary text (the caller prints the separator line) and
/// whether the run is considered failed — i.e. every executed iteration
/// failed.  Partial failures are reported in the summary but do not make the
/// run "failed": a long monitoring loop is allowed to have the odd bad
/// iteration, whereas a run where nothing ever succeeded is a broken check.
fn format_loop_summary(total: u64, failed: u64) -> (String, bool) {
    let all_failed = total > 0 && failed == total;
    let summary = if all_failed {
        format!("✗  Loop finished — all {} iteration(s) failed.", total)
    } else if failed > 0 {
        format!(
            "✓  Loop finished — {} iteration(s) completed, {} failed.",
            total, failed
        )
    } else {
        format!("✓  Loop finished — {} iteration(s) completed.", total)
    };
    (summary, all_failed)
}

/// Format the output lines for `handle_install`.  Extracted as a pure function
/// so the branching logic can be unit-tested without network I/O.
fn format_install_output(runtime: &InstalledBrowser4Runtime) -> Vec<String> {
    let mut lines = Vec::new();
    if runtime.reused_existing {
        lines.push("Browser4 runtime already installed.".to_string());
    } else {
        lines.push("Browser4 runtime installed successfully.".to_string());
    }
    lines.push(format!("- Tag: {}", runtime.tag));
    lines.push(format!("- Asset: {}", runtime.asset_name));
    lines.push(format!("- Install dir: {}", runtime.install_dir.display()));
    lines.push(format!("- Lib dir: {}", runtime.lib_dir.display()));
    lines.push(format!("- Java: {}", runtime.java_path.display()));
    lines.push(format!("- Source: {}", runtime.download_url));
    lines
}

/// Outcome of syncing bundled skill files into a runtime install directory.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct SkillsSyncOutcome {
    /// Number of files written because they were missing or outdated.
    files_written: usize,
    /// Total number of bundled skill files.
    files_total: usize,
}

/// Format the user-facing message for a skill sync.  Pure function so the
/// branching logic can be unit-tested.
fn format_skills_sync_message(outcome: SkillsSyncOutcome, skills_dir: &Path) -> String {
    if outcome.files_written > 0 {
        format!(
            "📦 Unpacked {} skill files to {}",
            outcome.files_written,
            skills_dir.display()
        )
    } else {
        format!(
            "✅ Bundled skill files already up to date at {} ({} files)",
            skills_dir.display(),
            outcome.files_total
        )
    }
}

/// Unpack bundled skill files into the runtime's versioned install directory
/// (`<install_dir>/skills`) so the skills on disk always match the CLI binary.
///
/// Runs on every `install` / `upgrade`, including when the runtime was
/// already present: the CLI binary may embed newer skills than the installed
/// runtime (e.g. after upgrading the binary alone).  Write-if-changed keeps
/// re-syncs cheap.  The skills directory sits alongside the runtime, so it
/// is versioned with the install and `skills path` finds it automatically.
fn sync_skills_for_runtime(runtime: &InstalledBrowser4Runtime) -> Result<SkillsSyncOutcome, String> {
    let skills_dir = runtime.install_dir.join("skills");
    let files_total = skills::bundled_skill_file_count();
    let files_written = skills::unpack_skills_to(&skills_dir)?;
    Ok(SkillsSyncOutcome {
        files_written,
        files_total,
    })
}

/// Format the user-facing message for an AI-agent skills sync (`~/.agents/skills`).
/// Pure function so the branching logic can be unit-tested.
fn format_agents_skills_sync_message(outcome: SkillsSyncOutcome, agents_dir: &Path) -> String {
    if outcome.files_written > 0 {
        format!(
            "🤖 Installed {} skill files for AI agents to {}",
            outcome.files_written,
            agents_dir.display()
        )
    } else {
        format!(
            "🤖 Bundled skill files already up to date for AI agents at {}",
            agents_dir.display()
        )
    }
}

/// Copy the agent-synced bundled skill files into the AI-agent skills
/// directory (`~/.agents/skills`, overridable via `BROWSER4_AGENTS_SKILLS_DIR`).
///
/// By default only the `browser4-cli` skill is copied there
/// (`skills::AGENT_SYNCED_SKILL_NAMES`): the other bundled skills are
/// Browser4-development oriented and would otherwise pollute the agent skill
/// space shared with the user.  Agents that want the full set can unpack it
/// explicitly (`browser4-cli skills unpack <dest>`).  Like the versioned-dir
/// sync this is idempotent (write-if-changed) and never deletes files, so
/// skills written by older CLI versions stay on disk.  Returns `Ok(None)`
/// when no agents directory can be resolved (no override and no home dir).
fn sync_skills_to_agents_dir() -> Result<Option<(SkillsSyncOutcome, PathBuf)>, String> {
    let Some(agents_dir) = skills::agents_skills_dir() else {
        eprintln!("⚠  Could not resolve the home directory; skipping AI-agent skills install.");
        return Ok(None);
    };
    let files_total = skills::bundled_agent_skill_file_count();
    let files_written = skills::unpack_agent_skills_to(&agents_dir)?;
    Ok(Some((
        SkillsSyncOutcome {
            files_written,
            files_total,
        },
        agents_dir,
    )))
}

async fn handle_install(tool_params: &Value) -> Result<(), String> {
    let tag = tool_params.get("tag").and_then(|value| value.as_str());
    let force = tool_params
        .get("force")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    let runtime = install_browser4_runtime(tag, force).await?;

    // Pre-train the JVM AOT cache in the background right after the runtime is
    // committed, so a first `open` shortly after install already hits the
    // cache.  Non-blocking and non-fatal; a failed training run self-heals on
    // the next launch (its marker is reclaimed after a short grace period).
    ensure_aot_cache_trained(&runtime);

    for line in format_install_output(&runtime) {
        cli_println!("{}", line);
    }

    // Check that a supported browser is available.  Auto-install Chrome on
    // Debian/Ubuntu; print guidance on other platforms.  Failure is non-fatal
    // — the runtime bundle is already installed at this point.
    // Skip this check when the runtime was already present: Chrome hasn't
    // changed and running the check every time produces spurious warnings.
    if !runtime.reused_existing {
        if let Err(e) = ensure_chrome_available() {
            eprintln!("⚠  Chrome check failed: {e}");
        }
    }

    json_field("tag", json!(&runtime.tag));
    json_field("asset_name", json!(&runtime.asset_name));
    json_field(
        "install_dir",
        json!(runtime.install_dir.display().to_string()),
    );
    json_field("reused_existing", json!(runtime.reused_existing));
    json_field("source_url", json!(&runtime.download_url));

    // Unpack bundled skill files into the versioned installation directory.
    // The skills directory is at <install_dir>/skills/ alongside the runtime.
    // This runs on every install — including the reuse fast-path — so the
    // on-disk skills always match the CLI binary that is installed.  Failure
    // is non-fatal: the runtime bundle is already installed at this point.
    let skills_dir = runtime.install_dir.join("skills");
    match sync_skills_for_runtime(&runtime) {
        Ok(outcome) => {
            eprintln!("{}", format_skills_sync_message(outcome, &skills_dir));
            json_field("skills_dir", json!(skills_dir.display().to_string()));
            json_field("skills_files_unpacked", json!(outcome.files_written));
            json_field("skills_files_total", json!(outcome.files_total));
        }
        Err(e) => {
            eprintln!("⚠  Failed to unpack skill files: {e}");
        }
    }

    // Also copy the agent-synced skills (only the `browser4-cli` skill by
    // default) into the AI-agent skills directory (`~/.agents/skills`) so
    // agents like Codex can load them automatically.
    match sync_skills_to_agents_dir() {
        Ok(Some((outcome, agents_dir))) => {
            eprintln!("{}", format_agents_skills_sync_message(outcome, &agents_dir));
            json_field("agents_skills_dir", json!(agents_dir.display().to_string()));
            json_field("agents_skills_files_unpacked", json!(outcome.files_written));
        }
        Ok(None) => {}
        Err(e) => {
            eprintln!("⚠  Failed to install skill files for AI agents: {e}");
        }
    }

    Ok(())
}

// ---------------------------------------------------------------------------
// skills command handlers
// ---------------------------------------------------------------------------

fn handle_skills_list() -> Result<(), String> {
    let names = skills::list_skill_names();
    if names.is_empty() {
        cli_println!("No skills bundled.");
        return Ok(());
    }
    cli_println!("Bundled skills:");
    for name in &names {
        let file_count = skills::skill_files_for(name).len();
        cli_println!("  {} ({} files)", name, file_count);
    }
    Ok(())
}

fn handle_skills_get(tool_params: &Value) -> Result<(), String> {
    let all = tool_params
        .get("all")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let full = tool_params
        .get("full")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let name = tool_params
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty());

    if all {
        cli_println!("{}", skills::get_all_skills());
        return Ok(());
    }

    let skill_name = match name {
        Some(n) => n.to_string(),
        None => {
            // No name given — list available skills.
            return handle_skills_list();
        }
    };

    match skills::get_skill(&skill_name, full) {
        Some(content) => {
            cli_println!("{}", content);
            Ok(())
        }
        None => {
            let available = skills::list_skill_names();
            Err(format!(
                "Unknown skill '{}'. Available skills: {}",
                skill_name,
                available.join(", ")
            ))
        }
    }
}

fn handle_skills_path(tool_params: &Value) -> Result<(), String> {
    // Check BROWSER4_SKILLS_DIR first, then the current versioned install dir,
    // then the default skills directory.
    let skills_dir = if std::env::var("BROWSER4_SKILLS_DIR")
        .map(|v| !v.trim().is_empty())
        .unwrap_or(false)
    {
        skills::get_skills_dir()
    } else if let Some(tag) = daemon::read_current_tag() {
        let versioned = state::resolve_runtime_data_dir()
            .join("versions")
            .join(&tag)
            .join("skills");
        if versioned.is_dir() {
            versioned
        } else {
            skills::get_skills_dir()
        }
    } else {
        skills::get_skills_dir()
    };

    let name = tool_params
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty());

    match name {
        Some(n) => {
            cli_println!("{}", skills_dir.join(n).display());
        }
        None => {
            cli_println!("{}", skills_dir.display());
        }
    }
    Ok(())
}

fn handle_skills_unpack(tool_params: &Value) -> Result<(), String> {
    let dest = tool_params
        .get("dest")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty());

    let dest_dir = match dest {
        Some(d) => PathBuf::from(d),
        None => skills::get_skills_dir(),
    };

    match skills::unpack_skills_to(&dest_dir) {
        Ok(n) => {
            if n > 0 {
                cli_println!("Unpacked {} skill files to {}", n, dest_dir.display());
            } else {
                cli_println!(
                    "Bundled skill files already up to date at {}",
                    dest_dir.display()
                );
            }
            Ok(())
        }
        Err(e) => Err(format!("Failed to unpack skill files: {e}")),
    }
}

// ---------------------------------------------------------------------------
// webminer (WebMiner) command handlers
// ---------------------------------------------------------------------------

/// Forward raw CLI tokens (everything after the command name) to
/// `java -jar scent-miner.jar`, optionally prefixing a jar command name.
/// A non-zero child exit code is surfaced as a command failure.
fn forward_webminer_run(raw_args: &[String], jar_command: Option<&str>) -> Result<(), CliError> {
    let mut forward: Vec<String> = Vec::new();
    if let Some(cmd) = jar_command {
        forward.push(cmd.to_string());
    }
    // raw_args[0] is the (possibly rewritten) command name.
    forward.extend(raw_args.iter().skip(1).cloned());

    match webminer::run_pipeline(&forward) {
        Ok(0) => Ok(()),
        Ok(code) => Err(CliError(
            ExitCode::General,
            format!("webminer exited with code {code}"),
        )),
        Err(e) => Err(CliError(ExitCode::General, e)),
    }
}

/// Print the installed/latest/Java summary (shared by `version` and the
/// bare `webminer` status view).
async fn print_webminer_status(show_usage: bool) -> Result<(), CliError> {
    let status = webminer::version_status().await;
    json_field("installed", json!(status.installed));
    json_field(
        "install_dir",
        json!(status.install_dir.display().to_string()),
    );
    json_field(
        "latest",
        json!(status.latest.as_ref().map(|l| &l.tag_name)),
    );

    cli_println!();
    cli_println!("  webminer (WebMiner) — cluster HTML pages into interactive views");
    cli_println!("  ----------------------------------------------------------------");
    match &status.installed {
        Some(version) => {
            let size = status
                .jar_bytes
                .map(|b| format!("{:.1} MB", b as f64 / 1_048_576.0))
                .unwrap_or_else(|| "(JAR missing)".to_string());
            cli_println!("  Installed : {version}  ({size})");
            cli_println!("  Location  : {}", status.install_dir.display());
        }
        None => {
            cli_println!("  Installed : (none) — run `browser4-cli webminer install`");
        }
    }
    match java::find_java17() {
        Ok(java) => cli_println!("  Java 17+  : {}", java.display()),
        Err(e) => cli_println!("  Java 17+  : not found ({e})"),
    }
    match (&status.latest, &status.latest_error) {
        (Some(latest), _) => {
            let size = latest
                .jar_size
                .map(|b| format!("{:.1} MB", b as f64 / 1_048_576.0))
                .unwrap_or_else(|| "?".to_string());
            cli_println!("  Latest    : {}  ({size})", latest.tag_name);
            if let Some(published) = &latest.published_at {
                // Never print an empty Published line — an empty value is
                // worse than omitting the field entirely.
                if !published.is_empty() {
                    cli_println!("  Published : {published}");
                }
            }
            if status.installed.as_deref() != Some(latest.tag_name.as_str()) {
                cli_println!();
                cli_println!("  Update available! Run: browser4-cli webminer update");
            }
        }
        (None, Some(err)) => {
            cli_println!("  Latest    : (cannot reach GitHub or OSS mirror: {err})");
        }
        (None, None) => {}
    }
    if show_usage {
        cli_println!();
        cli_println!("  Subcommands:");
        cli_println!("    install [version]   Download and install scent-miner.jar (GitHub → OSS mirror)");
        cli_println!("    update              Update to the latest release");
        cli_println!("    version             Show installed and latest versions");
        cli_println!("    uninstall           Remove the installed release");
        cli_println!("    run-example         Download the sample dataset and run the full pipeline (needs 7-Zip)");
        cli_println!("    all <html-dir>      Run the full pipeline on downloaded HTML files");
        cli_println!("    views <result-dir>  Rebuild the interactive views from an existing run");
        cli_println!();
        cli_println!("  Other commands are forwarded to scent-miner.jar. See `browser4-cli help webminer`.");
    }
    cli_println!();
    Ok(())
}

async fn handle_webminer(raw_args: &[String]) -> Result<(), CliError> {
    // Bare `webminer` → status + usage.  Anything else is forwarded
    // verbatim to scent-miner.jar: known subcommands (install, all, views …)
    // are rewritten to webminer-<sub> before dispatch, so this branch
    // covers arbitrary JAR commands like `webminer encode <dir>`.
    if raw_args.len() <= 1 {
        return print_webminer_status(true).await;
    }
    forward_webminer_run(raw_args, None)
}

async fn handle_webminer_install(tool_params: &Value) -> Result<(), CliError> {
    let version = tool_params.get("version").and_then(|v| v.as_str());
    let force = tool_params
        .get("force")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let outcome = webminer::install(version, force)
        .await
        .map_err(CliError::from)?;
    json_field("tag", json!(&outcome.tag));
    json_field(
        "install_dir",
        json!(outcome.install_dir.display().to_string()),
    );
    json_field("reused_existing", json!(outcome.reused_existing));
    json_field("source_url", json!(&outcome.source_url));
    if outcome.reused_existing {
        cli_println!("✓ webminer {} is already installed.", outcome.tag);
    } else {
        cli_println!(
            "✓ webminer {} installed to {}",
            outcome.tag,
            outcome.install_dir.display()
        );
    }
    Ok(())
}

async fn handle_webminer_update() -> Result<(), CliError> {
    let outcome = webminer::update().await.map_err(CliError::from)?;
    json_field("tag", json!(&outcome.tag));
    json_field("reused_existing", json!(outcome.reused_existing));
    if outcome.reused_existing {
        cli_println!("✓ webminer is up to date ({}).", outcome.tag);
    } else {
        cli_println!("✓ webminer updated to {}.", outcome.tag);
    }
    Ok(())
}

async fn handle_webminer_version() -> Result<(), CliError> {
    print_webminer_status(false).await
}

fn handle_webminer_uninstall() -> Result<(), CliError> {
    let root = webminer::uninstall().map_err(CliError::from)?;
    json_field("install_dir", json!(root.display().to_string()));
    if root.is_dir() {
        cli_println!("No webminer installation found at {}.", root.display());
    } else {
        cli_println!("✓ Removed webminer installation at {}.", root.display());
    }
    Ok(())
}

async fn handle_webminer_run_example(raw_args: &[String]) -> Result<(), CliError> {
    let forward: Vec<String> = raw_args.iter().skip(1).cloned().collect();
    match webminer::run_example(&forward).await {
        Ok(0) => Ok(()),
        Ok(code) => Err(CliError(
            ExitCode::General,
            format!("webminer exited with code {code}"),
        )),
        Err(e) => Err(CliError(ExitCode::General, e)),
    }
}

async fn handle_webminer_all(raw_args: &[String]) -> Result<(), CliError> {
    forward_webminer_run(raw_args, Some("all"))
}

async fn handle_webminer_views(raw_args: &[String]) -> Result<(), CliError> {
    forward_webminer_run(raw_args, Some("views"))
}

// ---------------------------------------------------------------------------
// plugin command handlers
// ---------------------------------------------------------------------------

/// Handle code-* commands that do NOT require a browser session.
///
/// These commands call the server's `/mcp/call-tool` endpoint directly,
/// without injecting a sessionId. The backend dispatches them through
/// the CodingToolExecutor with a standalone target (no browser needed).
///
/// For content-bearing commands (write, append, replace, shell, run),
/// `--stdin` / `--file` / `--base64` options are resolved here — the
/// actual content is read and injected into params before the server call.
async fn handle_code_command(
    client: &reqwest::Client,
    base_url: &str,
    tool_name: &str,
    tool_params: &mut Value,
    command: &str,
) -> Result<(), String> {
    // --- Resolve --stdin for content-bearing commands ---
    let use_stdin = tool_params
        .get("stdin")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if use_stdin {
        let stdin_field = match command {
            "code-write" | "code-append" => "content",
            "code-replace" => "newStr",
            "code-shell" => "command",
            "code-run" => "code",
            _ => "",
        };
        if !stdin_field.is_empty() {
            let mut input = String::new();
            std::io::stdin()
                .read_to_string(&mut input)
                .map_err(|e| format!("Failed to read stdin: {e}"))?;
            let input = input.trim().to_string();
            if input.is_empty() {
                return Err("Stdin was empty. Provide non-empty content via stdin.".to_string());
            }
            if let Value::Object(ref mut m) = tool_params {
                m.insert(stdin_field.to_string(), json!(input));
            }
        }
    }

    // --- Resolve --file for write/append ---
    if matches!(command, "code-write" | "code-append") {
        let file_path = tool_params
            .get("file")
            .and_then(|v| v.as_str())
            .map(|s| s.to_string());
        if let Some(fp) = file_path {
            let content = std::fs::read_to_string(&fp)
                .map_err(|e| format!("Failed to read file '{}': {e}", fp))?;
            if let Value::Object(ref mut m) = tool_params {
                m.insert("content".to_string(), json!(content));
            }
        }
    }

    // --- Resolve --base64 for write ---
    if command == "code-write" {
        let use_base64 = tool_params
            .get("base64")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        if use_base64 {
            use base64::Engine;
            let encoded = tool_params
                .get("content")
                .and_then(|v| v.as_str())
                .unwrap_or_default();
            let decoded = base64::engine::general_purpose::STANDARD
                .decode(encoded)
                .map_err(|e| format!("Failed to decode base64 content: {e}"))?;
            let content = String::from_utf8(decoded)
                .map_err(|e| format!("Decoded content is not valid UTF-8: {e}"))?;
            if let Value::Object(ref mut m) = tool_params {
                m.insert("content".to_string(), json!(content));
            }
        }
    }

    // --- Strip CLI-only flags before sending to server ---
    if let Value::Object(ref mut m) = tool_params {
        m.remove("stdin");
        m.remove("file");
        m.remove("base64");
    }

    // --- Call the server directly (no session required) ---
    let result = http::call_tool(client, base_url, tool_name, tool_params.clone()).await?;

    // In --json mode `cli_println!` is suppressed, so expose the tool reply as
    // an envelope field instead — otherwise `--json` would emit an empty
    // `output` object for every code command.
    if json_active() {
        json_field("result", json_text_or_value(&result));
    }

    if result.trim().is_empty() {
        cli_println!("(no output)");
    } else {
        cli_println!("{}", result);
    }

    // --- Verdict → exit code (plan P0.3) ---
    // A build/validation/verification that FAILED must not exit 0, otherwise a
    // CI gate reading only the exit code reports green on a red build (eval
    // K5). The check is conservative: output without a machine-checkable
    // verdict (e.g. a mock server) keeps the historical exit-0 behaviour.
    if let Some(reason) = code_command_failure(command, &result) {
        return Err(format!("{command} failed — {reason}"));
    }
    Ok(())
}

/// Machine-checkable failure signal of a `code ...` command, if any.
///
/// Never guesses: each branch keys off text this codebase itself generates
/// (`mvn -pl ... → exit N`, the `VERDICT_JSON:` line, `✗ Validation failed`),
/// so an arbitrary tool reply cannot accidentally turn into a failure.
fn code_command_failure(command: &str, output: &str) -> Option<String> {
    match command {
        "code-verify" | "code-devtask" => verification_failure(output),
        "code-mvn" => maven_failure(output),
        "code-validate" => validation_failure(output),
        _ => None,
    }
}

/// Prefix of the machine-readable verdict line emitted by `coding.verify`.
const VERDICT_JSON_PREFIX: &str = "VERDICT_JSON: ";

fn verification_failure(output: &str) -> Option<String> {
    // Human mode: the verdict is the last VERDICT_JSON line.
    if let Some(line) = output
        .lines()
        .rev()
        .find(|l| l.trim_start().starts_with(VERDICT_JSON_PREFIX))
    {
        let json_text = line.trim_start().trim_start_matches(VERDICT_JSON_PREFIX);
        if let Ok(verdict) = serde_json::from_str::<Value>(json_text) {
            if verdict.get("passed").and_then(Value::as_bool) == Some(false) {
                return Some(verdict_failure_reason(&verdict));
            }
        }
    }
    // `--json` mode: the tool reply IS the verdict object.
    if let Ok(verdict) = serde_json::from_str::<Value>(output.trim()) {
        if verdict.get("checks").is_some()
            && verdict.get("passed").and_then(Value::as_bool) == Some(false)
        {
            return Some(verdict_failure_reason(&verdict));
        }
    }
    // `code devtask --execute` stops at the first failing plan step.
    if output.contains("Stopped at first failure.") {
        return Some("dev-task plan execution stopped at the first failing step".to_string());
    }
    None
}

fn verdict_failure_reason(verdict: &Value) -> String {
    verdict
        .get("failureReason")
        .and_then(Value::as_str)
        .filter(|r| !r.is_empty())
        .unwrap_or("verification verdict is not passed")
        .to_string()
}

fn maven_failure(output: &str) -> Option<String> {
    // Human mode: `mvn -pl <module> -am <goals> → exit <code>`.
    for line in output.lines() {
        if let Some(idx) = line.find("→ exit ") {
            let digits: String = line[idx + "→ exit ".len()..]
                .chars()
                .take_while(|c| c.is_ascii_digit() || *c == '-')
                .collect();
            if let Ok(code) = digits.parse::<i32>() {
                if code != 0 {
                    return Some(format!("maven build failed with exit {code}"));
                }
            }
        }
    }
    // `--json` mode: {"exitCode": N, "timedOut": bool, ...}
    if let Ok(build) = serde_json::from_str::<Value>(output.trim()) {
        if build.get("timedOut").and_then(Value::as_bool) == Some(true) {
            return Some("maven build timed out".to_string());
        }
        if let Some(code) = build.get("exitCode").and_then(Value::as_i64) {
            if code != 0 {
                return Some(format!("maven build failed with exit {code}"));
            }
        }
    }
    None
}

fn validation_failure(output: &str) -> Option<String> {
    // Human mode: ValidationResult.format() marks failures with `✗ Validation failed`.
    if output.contains("✗ Validation failed") {
        return Some("validation failed".to_string());
    }
    // `--json` mode: {"valid": false, "errorCount": N, ...}
    if let Ok(result) = serde_json::from_str::<Value>(output.trim()) {
        if result.get("valid").and_then(Value::as_bool) == Some(false) {
            let errors = result
                .get("errorCount")
                .and_then(Value::as_u64)
                .unwrap_or_default();
            return Some(format!("validation failed with {errors} error(s)"));
        }
    }
    None
}

/// `profile-import` — import browser personal data via the
/// `profile_import_import` / `profile_import_list_sources` MCP tools
/// (browser4-profile-import plugin). No browser session required; the call
/// goes straight to the backend, like the coding tools.
async fn handle_profile_import_command(
    client: &reqwest::Client,
    base_url: &str,
    tool_name: &str,
    tool_params: &mut Value,
) -> Result<(), String> {
    // Strip CLI-only flags before sending to the server. (`--json` is a
    // global flag consumed by the CLI itself; it never reaches the backend.)
    if let Value::Object(ref mut m) = tool_params {
        m.remove("json");
    }

    let result = http::call_tool(client, base_url, tool_name, tool_params.clone()).await?;
    if result.trim().is_empty() {
        cli_println!("(no output)");
        return Ok(());
    }

    match serde_json::from_str::<Value>(&result) {
        Ok(v) => {
            if let Some(import_dir) = v.get("importDir").and_then(|x| x.as_str()) {
                cli_println!("Import dir: {}", import_dir);
            }
            if let Some(profile_dir) = v.get("profileDir").and_then(|x| x.as_str()) {
                cli_println!("Profile dir: {}", profile_dir);
            }
            if let Some(browser) = v.get("browser").and_then(|x| x.as_str()) {
                cli_println!("Browser: {}", browser);
            }
            if let Some(source_profile) = v.get("sourceProfile").and_then(|x| x.as_str()) {
                cli_println!("Source profile: {}", source_profile);
            }
            if let Some(files) = v.get("filesCopied") {
                cli_println!("Files copied: {}", files);
            }
            if let Some(data) = v.get("data").and_then(|x| x.as_array()) {
                let list = data.iter().filter_map(|x| x.as_str()).collect::<Vec<_>>().join(",");
                cli_println!("Data: {}", list);
            }
            if let Some(bookmarks) = v.get("bookmarksImported") {
                cli_println!("Bookmarks imported: {}", bookmarks);
            }
            if let Some(cookies) = v.get("cookiesImported") {
                cli_println!("Cookies imported: {}", cookies);
            }
            if let Some(warnings) = v.get("warnings").and_then(|x| x.as_array()) {
                for w in warnings.iter().filter_map(|x| x.as_str()) {
                    cli_println!("Warning: {}", w);
                }
            }
            if let Some(next) = v.get("nextStep").and_then(|x| x.as_str()) {
                cli_println!("Next step: {}", next);
            }
            if v.get("importDir").is_none() && v.get("bookmarksImported").is_none() {
                // Fall back to raw output (e.g. list_sources result).
                cli_println!("{}", result);
            }
        }
        Err(_) => cli_println!("{}", result),
    }
    Ok(())
}

async fn handle_plugin_list(client: &reqwest::Client, base_url: &str) -> Result<(), String> {
    let response = http::list_plugins(client, base_url).await?;
    // Pretty-print the JSON array of PluginInfo objects
    let parsed: serde_json::Value = serde_json::from_str(&response)
        .map_err(|e| format!("Failed to parse plugin list response: {}", e))?;

    if let Some(plugins) = parsed.as_array() {
        if plugins.is_empty() {
            cli_println!("No plugins installed.");
            cli_println!(
                "Install one with `browser4-cli plugin install <path-to-plugin.jar>`, \
                 then restart the backend so it is loaded."
            );
            json_field("plugins", json!([]));
            return Ok(());
        }
        cli_println!("Installed plugins ({}):", plugins.len());
        for plugin in plugins {
            let name = plugin
                .get("fileName")
                .and_then(|v| v.as_str())
                .unwrap_or("?");
            let loaded = plugin
                .get("loaded")
                .and_then(|v| v.as_bool())
                .unwrap_or(false);
            let enabled = plugin
                .get("enabled")
                .and_then(|v| v.as_bool())
                .unwrap_or(true);
            let status = match (loaded, enabled) {
                (true, true) => "loaded",
                (true, false) => "loaded (disabled override)",
                (false, true) => "inactive (restart required)",
                (false, false) => "disabled",
            };
            let manifest = plugin.get("manifest");
            let version = manifest
                .and_then(|m| m.get("version"))
                .and_then(|v| v.as_str())
                .unwrap_or("-");
            let sdk = manifest
                .and_then(|m| m.get("sdkVersion"))
                .and_then(|v| v.as_str())
                .filter(|s| !s.is_empty())
                .unwrap_or("-");
            let desc = manifest
                .and_then(|m| m.get("description"))
                .and_then(|v| v.as_str())
                .unwrap_or("");
            cli_println!(
                "  {:<36} v{:<10} sdk {:<10} {:<28} {}",
                name, version, sdk, status, desc
            );
        }
        // This command lists plugin JARs, not the tools they contribute; the
        // help text used to send users here to find tool names.
        cli_println!("");
        cli_println!("This lists plugin JARs. Their callable MCP tools:");
        cli_println!("  browser4-cli tool list                 every advertised tool name");
        cli_println!("  browser4-cli tool list --filter captcha  names matching a substring");
        cli_println!("  browser4-cli plugin <domain> --help    methods of one plugin domain");
        cli_println!("Details for one plugin: browser4-cli plugin info <name>");
    } else {
        cli_println!("{}", response);
    }
    json_field("plugins", parsed);
    Ok(())
}

/// Resolve the user's plugin argument and fetch that plugin.
async fn handle_plugin_info(
    client: &reqwest::Client,
    base_url: &str,
    tool_params: &serde_json::Value,
) -> Result<(), String> {
    let name = tool_params
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| "Plugin name is required".to_string())?;

    // The backend matches the manifest name or the JAR file name only, so a
    // short name the CLI itself advertises elsewhere (`plugin captcha`, and the
    // domain printed by `plugin`) used to answer a bare
    // "HTTP request failed with status 404 Not Found and an empty response body".
    // Resolve it against the installed plugins first and say which name was used.
    let (resolved_name, note) = resolve_installed_plugin(client, base_url, name).await?;
    if let Some(note) = note.as_deref() {
        if !quiet_active() && !json_active() {
            eprintln!("ℹ️  {note}");
        }
    }

    let response = http::get_plugin(client, base_url, &resolved_name).await?;
    let parsed: serde_json::Value = serde_json::from_str(&response)
        .map_err(|e| format!("Failed to parse plugin info response: {}", e))?;

    let file_name = parsed
        .get("fileName")
        .and_then(|v| v.as_str())
        .unwrap_or("?");
    let file_size = parsed.get("fileSize").and_then(|v| v.as_u64()).unwrap_or(0);
    let loaded = parsed
        .get("loaded")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let path = parsed.get("path").and_then(|v| v.as_str()).unwrap_or("?");

    cli_println!("Plugin: {}", file_name);
    cli_println!("  Path:      {}", path);
    cli_println!("  Size:      {} bytes", file_size);
    cli_println!(
        "  Status:    {}",
        if loaded {
            "loaded"
        } else {
            "inactive (restart required)"
        }
    );

    if let Some(manifest) = parsed.get("manifest") {
        if let Some(m_name) = manifest.get("name").and_then(|v| v.as_str()) {
            cli_println!(
                "  Manifest:  {} v{}",
                m_name,
                manifest
                    .get("version")
                    .and_then(|v| v.as_str())
                    .unwrap_or("-")
            );
        }
        if let Some(desc) = manifest.get("description").and_then(|v| v.as_str()) {
            if !desc.is_empty() {
                cli_println!("  Desc:      {}", desc);
            }
        }
        if let Some(deps) = manifest.get("dependsOn").and_then(|v| v.as_array()) {
            if !deps.is_empty() {
                let dep_strs: Vec<&str> = deps.iter().filter_map(|d| d.as_str()).collect();
                cli_println!("  Depends:   {}", dep_strs.join(", "));
            }
        }
        if let Some(classes) = manifest
            .get("autoConfigurationClasses")
            .and_then(|v| v.as_array())
        {
            if !classes.is_empty() {
                cli_println!("  AutoConfig: {} class(es)", classes.len());
                for cls in classes.iter().filter_map(|c| c.as_str()) {
                    cli_println!("    - {}", cls);
                }
            }
        }
    }

    json_field("plugin", parsed);
    Ok(())
}

/// An installed plugin as the CLI has to reference it.
#[derive(Debug, Clone, PartialEq, Eq)]
struct InstalledPluginRef {
    /// JAR file name — always accepted by `GET /api/plugins/{name}`.
    file_name: String,
    /// Manifest name, when the JAR declares one.
    manifest_name: Option<String>,
}

/// Normalize a plugin reference into the keys that may match an installed JAR.
///
/// Accepts what users actually type: the short name the CLI advertises
/// (`captcha`), the artifact base name (`browser4-captcha`), the full JAR name
/// (`browser4-captcha-4.14.1-SNAPSHOT.jar`) and a path to it.
fn plugin_reference_keys(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.is_empty() {
        return Vec::new();
    }
    // A path is as good as its file name: `plugins/browser4-media.jar`.
    let base = trimmed.rsplit(['/', '\\']).next().unwrap_or(trimmed);
    let lower = base.to_ascii_lowercase();

    let mut keys = vec![lower.clone()];
    let without_ext = lower.strip_suffix(".jar").unwrap_or(&lower).to_string();
    let stem = plugin_stem(&without_ext);
    let singular = depluralize(&stem);
    for key in [without_ext, stem, singular] {
        if !key.is_empty() && !keys.contains(&key) {
            keys.push(key);
        }
    }
    keys
}

/// `browser4-captcha-4.14.1-snapshot` → `captcha`.
///
/// Everything from the first version-looking segment on is dropped, and the
/// `browser4-` artifact prefix with it, so the JAR name and the plugin's tool
/// domain agree.
fn plugin_stem(name: &str) -> String {
    let mut kept: Vec<&str> = Vec::new();
    for segment in name.split('-') {
        if segment
            .chars()
            .next()
            .is_some_and(|c| c.is_ascii_digit())
        {
            break;
        }
        kept.push(segment);
    }
    let joined = kept.join("-");
    joined
        .strip_prefix("browser4-")
        .unwrap_or(&joined)
        .to_string()
}

/// Drop a trailing plural `s` (`images` → `image`) without mangling `ss`.
fn depluralize(name: &str) -> String {
    if name.len() > 1 && name.ends_with('s') && !name.ends_with("ss") {
        name[..name.len() - 1].to_string()
    } else {
        name.to_string()
    }
}

/// Resolve `input` to the JAR file name of an installed plugin.
///
/// Error text lists the installed plugins and the discovery commands, because
/// the backend's own 404 body is empty — the user saw
/// "HTTP request failed with status 404 Not Found and an empty response body"
/// with no hint that `captcha` is not one of its accepted names.
fn resolve_plugin_reference(
    input: &str,
    installed: &[InstalledPluginRef],
) -> Result<String, String> {
    let wanted = plugin_reference_keys(input);
    if wanted.is_empty() {
        return Err("Plugin name is required".to_string());
    }

    if let Some(found) = installed.iter().find(|plugin| {
        let mut keys = plugin_reference_keys(&plugin.file_name);
        if let Some(manifest) = plugin.manifest_name.as_deref() {
            for key in plugin_reference_keys(manifest) {
                if !keys.contains(&key) {
                    keys.push(key);
                }
            }
        }
        // An exact match on any accepted spelling wins.
        keys.iter().any(|key| wanted.contains(key))
    }) {
        return Ok(found.file_name.clone());
    }

    let names: Vec<&str> = installed
        .iter()
        .map(|plugin| plugin.file_name.as_str())
        .collect();
    Err(format!(
        "Unknown plugin '{}'. Installed plugins: {}\n\
         Run `browser4-cli plugin list` for details, or `browser4-cli tool list` \
         for the MCP tools they expose.",
        input,
        if names.is_empty() {
            "(none)".to_string()
        } else {
            names.join(", ")
        }
    ))
}

/// Resolve the user's plugin argument to an installed JAR, using the backend's
/// plugin list when it is reachable.
///
/// Returns the name to query plus an optional note naming the substitution.  A
/// plugin list that cannot be fetched leaves the argument untouched so the
/// backend's own answer (or error) is what the user sees.
async fn resolve_installed_plugin(
    client: &reqwest::Client,
    base_url: &str,
    input: &str,
) -> Result<(String, Option<String>), String> {
    let Ok(body) = http::list_plugins(client, base_url).await else {
        return Ok((input.to_string(), None));
    };
    let Ok(parsed) = serde_json::from_str::<Value>(&body) else {
        return Ok((input.to_string(), None));
    };
    let installed: Vec<InstalledPluginRef> = parsed
        .as_array()
        .map(|plugins| {
            plugins
                .iter()
                .filter_map(|plugin| {
                    let file_name = plugin.get("fileName").and_then(|v| v.as_str())?;
                    Some(InstalledPluginRef {
                        file_name: file_name.to_string(),
                        manifest_name: plugin
                            .get("manifest")
                            .and_then(|m| m.get("name"))
                            .and_then(|v| v.as_str())
                            .map(String::from),
                    })
                })
                .collect()
        })
        .unwrap_or_default();
    if installed.is_empty() {
        return Ok((input.to_string(), None));
    }

    let resolved = resolve_plugin_reference(input, &installed)?;
    let note = (resolved != input)
        .then(|| format!("resolved plugin '{input}' to installed plugin '{resolved}'"));
    Ok((resolved, note))
}

/// True when [raw] contains a glob wildcard the CLI has to expand itself.
fn contains_glob_wildcard(raw: &str) -> bool {
    raw.contains('*') || raw.contains('?')
}

/// Expand a single-directory glob pattern (`dir/prefix-*.jar`) against the
/// filesystem.
///
/// PowerShell does not expand wildcards for native commands, so the documented
/// `plugin install …/browser4-captcha-*.jar` arrives at the CLI verbatim and has
/// to be expanded here.
fn expand_glob_pattern(pattern: &str) -> Vec<PathBuf> {
    let path = Path::new(pattern);
    let Some(file_pattern) = path.file_name().and_then(|n| n.to_str()) else {
        return Vec::new();
    };
    let parent = match path.parent() {
        Some(parent) if !parent.as_os_str().is_empty() => parent.to_path_buf(),
        _ => PathBuf::from("."),
    };
    let Ok(regex) = glob_to_regex(file_pattern) else {
        return Vec::new();
    };
    let Ok(entries) = std::fs::read_dir(&parent) else {
        return Vec::new();
    };
    let mut matches: Vec<PathBuf> = entries
        .filter_map(|entry| entry.ok())
        .filter(|entry| entry.path().is_file())
        .filter(|entry| {
            entry
                .file_name()
                .to_str()
                .is_some_and(|name| regex.is_match(name))
        })
        .map(|entry| entry.path())
        .collect();
    matches.sort();
    matches
}

/// Compile a file-name glob (`*`, `?`) into an anchored regex.
fn glob_to_regex(pattern: &str) -> Result<regex::Regex, regex::Error> {
    let mut source = String::from("^");
    for ch in pattern.chars() {
        match ch {
            '*' => source.push_str(".*"),
            '?' => source.push('.'),
            other => source.push_str(&regex::escape(&other.to_string())),
        }
    }
    source.push('$');
    regex::Regex::new(&source)
}

/// Resolve `plugin install`'s positional argument(s) to exactly one JAR path.
///
/// Two shapes reach this function and both must end in "the JAR you meant" or an
/// error naming the candidates:
/// * a shell-expanded wildcard — six positionals that `build_command_args`
///   joins with spaces into one path that cannot exist (the previous error
///   echoed that bogus join, hiding the real cause);
/// * a literal wildcard, which the CLI expands itself.
///
/// When several files match, the artifact whose name contains this CLI's
/// version is preferred and the choice is reported — the documented command
/// matched six versioned JARs and gave no hint which one belongs to the
/// checkout.
fn resolve_plugin_install_path(
    raw: &str,
    version: &str,
) -> Result<(PathBuf, Option<String>), String> {
    let tokens: Vec<&str> = raw.split_whitespace().filter(|t| !t.is_empty()).collect();
    if tokens.is_empty() {
        return Err("Plugin JAR file path is required".to_string());
    }

    let mut candidates: Vec<PathBuf> = Vec::new();
    for token in &tokens {
        let path = Path::new(token);
        if path.is_file() {
            candidates.push(path.to_path_buf());
            continue;
        }
        if contains_glob_wildcard(token) {
            let expanded = expand_glob_pattern(token);
            if expanded.is_empty() {
                return Err(format!(
                    "Plugin file not found: {token}\nNo file matches that pattern."
                ));
            }
            candidates.extend(expanded);
            continue;
        }
        return Err(format!("Plugin file not found: {token}"));
    }
    candidates.sort();
    candidates.dedup();

    if candidates.len() == 1 {
        return Ok((candidates.remove(0), None));
    }

    let matched: Vec<&PathBuf> = candidates
        .iter()
        .filter(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.contains(version))
        })
        .collect();
    if let [only] = matched.as_slice() {
        let chosen = (*only).clone();
        let note = format!(
            "{} files matched; installing the version-matched artifact {}",
            candidates.len(),
            chosen.display()
        );
        return Ok((chosen, Some(note)));
    }

    let names: Vec<String> = candidates
        .iter()
        .map(|path| path.display().to_string())
        .collect();
    Err(format!(
        "Expected exactly one plugin JAR, got {}:\n  {}\n\
         Pass one of them, or a pattern that matches a single file \
         (the version-matched artifact contains '{version}').",
        candidates.len(),
        names.join("\n  ")
    ))
}

async fn handle_plugin_install(
    client: &reqwest::Client,
    base_url: &str,
    tool_params: &serde_json::Value,
) -> Result<(), String> {
    let raw_path = tool_params
        .get("file")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| "Plugin JAR file path is required".to_string())?;

    let (file_path, note) = resolve_plugin_install_path(raw_path, VERSION)?;
    if let Some(note) = note.as_deref() {
        if !quiet_active() && !json_active() {
            eprintln!("ℹ️  {note}");
        }
    }
    let file_path = file_path.to_string_lossy().to_string();

    let replace = tool_params
        .get("replace")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let response = http::install_plugin(client, base_url, &file_path, replace).await?;
    let parsed: serde_json::Value = serde_json::from_str(&response)
        .map_err(|e| format!("Failed to parse plugin install response: {}", e))?;

    let name = parsed
        .get("fileName")
        .and_then(|v| v.as_str())
        .unwrap_or("?");
    let manifest_name = parsed
        .get("manifest")
        .and_then(|m| m.get("name"))
        .and_then(|v| v.as_str())
        .unwrap_or(name);

    cli_println!("✓ Plugin installed: {} ({})", manifest_name, name);
    cli_println!("  Restart the application to activate:");
    cli_println!("    browser4-cli stop");
    cli_println!("  The next browser4-cli command auto-starts the dev backend and loads the plugin.");
    cli_println!("  Plugin tools are then callable via: browser4-cli tool call <mcp-tool-name>");

    json_field("plugin", parsed);
    Ok(())
}

async fn handle_plugin_remove(
    client: &reqwest::Client,
    base_url: &str,
    tool_params: &serde_json::Value,
) -> Result<(), String> {
    let name = tool_params
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .ok_or_else(|| "Plugin name is required".to_string())?;

    let skip_confirm = tool_params
        .get("yes")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if !skip_confirm {
        // Confirm removal when not in quiet/json mode
        let is_interactive = !json_active() && !quiet_active();
        if is_interactive {
            eprintln!("Remove plugin '{}'? [y/N]: ", name);
            let mut input = String::new();
            std::io::stdin()
                .read_line(&mut input)
                .map_err(|e| format!("Failed to read input: {}", e))?;
            if !input.trim().eq_ignore_ascii_case("y") && !input.trim().eq_ignore_ascii_case("yes")
            {
                cli_println!("Plugin removal cancelled.");
                return Ok(());
            }
        }
    }

    let response = http::remove_plugin(client, base_url, name).await?;
    let parsed: serde_json::Value = serde_json::from_str(&response)
        .map_err(|e| format!("Failed to parse plugin remove response: {}", e))?;

    let removed_name = parsed
        .get("fileName")
        .and_then(|v| v.as_str())
        .unwrap_or(name);
    cli_println!("✓ Plugin removed: {}", removed_name);
    if parsed
        .get("loaded")
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
    {
        cli_println!("  Beans will be cleaned up on next restart.");
    }

    json_field("plugin", parsed);
    Ok(())
}

/// Convert camelCase to snake_case.
///
/// Examples: "detectVideos" → "detect_videos", "download" → "download",
/// "getInfo" → "get_info".
fn camel_to_snake(s: &str) -> String {
    let mut result = String::with_capacity(s.len() + 4);
    for (i, ch) in s.char_indices() {
        if ch.is_uppercase() {
            if i > 0 {
                result.push('_');
            }
            result.push(ch.to_ascii_lowercase());
        } else {
            result.push(ch);
        }
    }
    result
}

/// Resolve which MCP tool to invoke from a plugin-<domain> command.
///
/// If the first positional argument matches a known method (after converting to
/// snake_case and prefixing with the domain), that specific tool is selected and
/// the method name is stripped from the positional args.  An unrecognized
/// positional is a usage error — silently running the alphabetically first tool
/// would perform real side effects (file writes, downloads) under a name the
/// user never asked for.  When no positional method is supplied at all, falls
/// back to the first matching tool alphabetically (the plugin's default tool).
fn resolve_plugin_method(
    tools: &[&str],
    domain: &str,
    matching: &[&&str],
    raw_parsed: &mut HashMap<String, Value>,
) -> Result<String, CliError> {
    // Get the positional args and look at the first one after the command name.
    let positionals = raw_parsed
        .get("_")
        .and_then(|v| v.as_array())
        .map(|a| a.iter().collect::<Vec<_>>())
        .unwrap_or_default();

    // The first positional (_[0]) is the command itself (e.g. "plugin-media").
    // The second positional (_[1]) is the candidate method name.
    if positionals.len() >= 2 {
        if let Some(candidate) = positionals[1].as_str() {
            // Accept camelCase, snake_case and kebab-case spellings of the
            // method name (CLI users habitually type kebab-case).
            let snake_method = camel_to_snake(&candidate.replace('-', "_"));
            let candidate_tool = format!("{}_{}", domain, snake_method);
            if tools.contains(&candidate_tool.as_str()) {
                // Remove the method name from positionals so it isn't
                // passed as a tool parameter.
                if let Some(arr) = raw_parsed.get_mut("_").and_then(|v| v.as_array_mut()) {
                    if arr.len() > 1 {
                        arr.remove(1);
                    }
                }
                return Ok(candidate_tool);
            }
            // Unknown method: report the available ones instead of silently
            // executing the default tool.
            let prefix = format!("{}_", domain);
            let mut methods: Vec<String> = matching
                .iter()
                .map(|t| t.strip_prefix(&prefix).unwrap_or(t).to_string())
                .collect();
            methods.sort();
            return Err(CliError(
                ExitCode::Usage,
                format!(
                    "Unknown method '{}' for plugin '{}'.\nAvailable methods: {}",
                    candidate,
                    domain,
                    methods.join(", ")
                ),
            ));
        }
    }

    // Fall back: use the first matching tool alphabetically
    Ok(matching[0].to_string())
}

/// A tool spec declared for CLI use by a plugin (`ToolSpec.cliName`), as
/// served by the backend's `GET /mcp/tools/specs` endpoint.
#[derive(Clone, Debug, serde::Deserialize)]
struct CliToolSpec {
    #[serde(rename = "cliName")]
    cli_name: String,
    domain: String,
    method: String,
    #[serde(default)]
    description: Option<String>,
    #[serde(default)]
    arguments: Vec<CliToolArg>,
}

#[derive(Clone, Debug, serde::Deserialize)]
struct CliToolArg {
    name: String,
    #[serde(rename = "type")]
    arg_type: String,
    #[serde(rename = "defaultValue", default)]
    default_value: Option<String>,
}

/// Find the plugin-declared CLI tool spec matching `spaced` (e.g.
/// `"profile import"`).
fn find_declared_cli_spec<'a>(specs: &'a [CliToolSpec], spaced: &str) -> Option<&'a CliToolSpec> {
    specs.iter().find(|s| s.cli_name == spaced)
}

/// Fetch the raw tool specs served by `GET /mcp/tools/specs`.
///
/// Callers that only list whatever the backend advertises use
/// [fetch_tool_spec_values]; callers that must tell "no specs" from "the request
/// failed" use [probe_tool_specs_within] directly.
/// Budget for the optional plugin-declared-command section appended to help.
///
/// The static reference is printed *before* this runs, so the wait never delays
/// the page the user asked for — but a dead backend must not add its full 2 s
/// specs timeout to every help invocation either.
const HELP_SPECS_BUDGET: std::time::Duration = std::time::Duration::from_millis(400);

/// Outcome of the `GET /mcp/tools/specs` discovery probe.
///
/// Discovery is best-effort, but "the backend answered with no specs" and "the
/// request never completed" are different facts: the endpoint legitimately
/// returns an empty list on a stock install (it only advertises specs whose
/// `cliName` is set), so collapsing both into an empty `Vec` made `--help
/// --examples` blame a healthy backend.
enum ToolSpecFetch {
    /// The backend answered with a (possibly empty) list of specs.
    Specs(Vec<Value>),
    /// The request itself failed — the reason names the endpoint and the cause.
    Failed(String),
}

impl ToolSpecFetch {
    /// The specs, or an empty list when the request failed.  For callers whose
    /// behavior is identical either way (best-effort listing, help extras).
    fn specs_or_empty(self) -> Vec<Value> {
        match self {
            ToolSpecFetch::Specs(specs) => specs,
            ToolSpecFetch::Failed(_) => Vec::new(),
        }
    }
}

/// Fetch the tool specs from `GET /mcp/tools/specs` with an explicit budget.
async fn probe_tool_specs_within(base_url: &str, budget: std::time::Duration) -> ToolSpecFetch {
    probe_tool_specs_at(base_url, budget, false).await
}

/// Same probe, also asking for built-in specs that declare usage examples
/// (`?includeExamples=true`). The `--help --examples` path needs those: the
/// default payload advertises plugin-declared CLI commands only, so a built-in
/// command like `code devtask` had no examples to show (eval K7).
async fn probe_tool_specs_with_examples_within(
    base_url: &str,
    budget: std::time::Duration,
) -> ToolSpecFetch {
    probe_tool_specs_at(base_url, budget, true).await
}

async fn probe_tool_specs_at(
    base_url: &str,
    budget: std::time::Duration,
    include_examples: bool,
) -> ToolSpecFetch {
    let base = base_url.trim_end_matches('/');
    let url = if include_examples {
        format!("{base}/mcp/tools/specs?includeExamples=true")
    } else {
        format!("{base}/mcp/tools/specs")
    };
    let Ok(client) = reqwest::Client::builder().timeout(budget).build() else {
        return ToolSpecFetch::Failed(format!("could not build an HTTP client for {url}"));
    };
    let response = match client.get(&url).send().await {
        Ok(response) => response,
        Err(error) => {
            return ToolSpecFetch::Failed(format!("GET {url} failed: {error}"));
        }
    };
    let status = response.status();
    if !status.is_success() {
        return ToolSpecFetch::Failed(format!("GET {url} returned HTTP {status}"));
    }
    let Ok(body) = response.json::<Value>().await else {
        return ToolSpecFetch::Failed(format!("GET {url} returned a body that is not JSON"));
    };
    match body.get("tools").and_then(|v| v.as_array()) {
        Some(specs) => ToolSpecFetch::Specs(specs.clone()),
        None => ToolSpecFetch::Failed(format!("GET {url} answered without a 'tools' array")),
    }
}

async fn fetch_tool_spec_values_within(base_url: &str, budget: std::time::Duration) -> Vec<Value> {
    probe_tool_specs_within(base_url, budget).await.specs_or_empty()
}

async fn fetch_tool_spec_values(base_url: &str) -> Vec<Value> {
    fetch_tool_spec_values_within(base_url, std::time::Duration::from_secs(2)).await
}

/// Fetch all plugin-declared CLI tool specs from `GET /mcp/tools/specs`.
/// Returns an empty vec when the backend is unreachable or has none.
async fn fetch_all_declared_cli_specs(base_url: &str) -> Vec<CliToolSpec> {
    fetch_tool_spec_values(base_url)
        .await
        .iter()
        .filter_map(|t| serde_json::from_value(t.clone()).ok())
        .collect()
}

/// Fetch the plugin-declared CLI tool spec matching `spaced` (e.g.
/// `"profile import"`). Returns None when the backend is unreachable or no
/// spec declares that command name — the caller then falls through to the
/// normal command dispatch.
async fn fetch_declared_cli_spec(base_url: &str, spaced: &str) -> Option<CliToolSpec> {
    let specs = fetch_all_declared_cli_specs(base_url).await;
    find_declared_cli_spec(&specs, spaced).cloned()
}

/// Render a declared command's arguments as `--name [=default]` tokens.
/// Reads `default_value` so declared defaults surface in help output.
fn render_spec_args(spec: &CliToolSpec) -> String {
    spec.arguments
        .iter()
        .map(|a| match a.default_value.as_deref() {
            Some(d) if !d.is_empty() && d != "null" => format!("--{}={}", a.name, d),
            _ => format!("--{}", a.name),
        })
        .collect::<Vec<_>>()
        .join(" ")
}

/// Render the plugin-declared CLI command listing for `plugin commands`.
fn render_declared_commands(specs: &[CliToolSpec]) -> String {
    if specs.is_empty() {
        return "No plugin-declared CLI commands.".to_string();
    }
    let mut lines = vec!["Declared plugin CLI commands (from /mcp/tools/specs):".to_string()];
    for spec in specs {
        let args = render_spec_args(spec);
        let args_suffix = if args.is_empty() {
            String::new()
        } else {
            format!(" [{args}]")
        };
        lines.push(format!(
            "  {:<28} -> {}.{}   (plugin domain)",
            format!("{}{}", spec.cli_name, args_suffix),
            spec.domain,
            spec.method
        ));
    }
    lines.join("\n")
}

// ---------------------------------------------------------------------------
// `--help --examples` — runnable usage examples of a command's tool
// ---------------------------------------------------------------------------

/// One entry of a tool spec's `examples` list, as advertised by
/// `GET /mcp/tools/specs`.
///
/// `args` is written as JSON (never as a typed map) so an example carrying a
/// non-string argument value still deserializes; `runnable`/`executable` are
/// optional because the backend emits them only when set.
#[derive(Clone, Debug, Default, serde::Deserialize)]
struct ToolExampleSpec {
    #[serde(default)]
    title: Option<String>,
    #[serde(default)]
    args: serde_json::Map<String, Value>,
    #[serde(default)]
    code: Option<String>,
    #[serde(default)]
    notes: Option<String>,
    #[serde(default, rename = "expectsError")]
    expects_error: bool,
    #[serde(default)]
    runnable: Option<bool>,
    #[serde(default)]
    executable: Option<bool>,
}

impl ToolExampleSpec {
    /// Whether the example is a call a client can actually make: `runnable`
    /// when the backend set it, otherwise the presence of arguments — the same
    /// rule the backend's `ToolExample.executable` derives.
    fn is_executable(&self) -> bool {
        self.runnable.unwrap_or(!self.args.is_empty()) || self.executable == Some(true)
    }
}

/// The part of a tool spec `--help --examples` needs: what the tool is called
/// (`domain`, `method`, `mcpNames`) and what callable examples it carries.
#[derive(Clone, Debug, Default, serde::Deserialize)]
struct ToolSpecDoc {
    #[serde(default)]
    domain: String,
    #[serde(default)]
    method: String,
    #[serde(default, rename = "mcpNames")]
    mcp_names: Vec<String>,
    #[serde(default)]
    examples: Vec<ToolExampleSpec>,
}

/// Normalize a tool name for comparison: case and separators are not
/// significant, so the CLI's camelCase tool names (`coding_listDir`) match the
/// backend's snake_case canonical names (`coding_list_dir`).
fn normalize_tool_name(name: &str) -> String {
    name.chars()
        .filter(|c| !matches!(c, '_' | '.' | '-'))
        .flat_map(|c| c.to_lowercase())
        .collect()
}

/// Find the spec that advertises `tool` — the MCP name the CLI would call.
///
/// The spec's `mcpNames` is authoritative when present, but it does not list
/// every frontend alias (`click` is advertised as `click` while the CLI calls
/// `browser_click`), and the raw-spec shape carries no `mcpNames` at all, so
/// the names derived from `domain`/`method` are tried too — against the tool
/// name and against its alias-stripped form.
fn find_tool_spec<'a>(specs: &'a [ToolSpecDoc], tool: &str) -> Option<&'a ToolSpecDoc> {
    let wanted = normalize_tool_name(tool);
    let bare = normalize_tool_name(tool.strip_prefix("browser_").unwrap_or(tool));
    specs.iter().find(|spec| {
        let snake_method = camel_to_snake(&spec.method);
        let mut candidates: Vec<String> = spec.mcp_names.clone();
        candidates.push(format!("{}_{}", spec.domain, snake_method));
        candidates.push(snake_method);
        candidates.iter().any(|name| {
            let normalized = normalize_tool_name(name);
            normalized == wanted || normalized == bare
        })
    })
}

/// Render an example's arguments as an inline JSON object, e.g.
/// `{"url": "https://example.com", "depth": "1"}`.
///
/// String values are quoted (the backend transports every argument as a
/// string); other JSON values keep their own form so a numeric argument is not
/// silently turned into a string.
fn render_example_args(args: &serde_json::Map<String, Value>) -> String {
    let pairs = args
        .iter()
        .map(|(key, value)| {
            let key = serde_json::to_string(key).unwrap_or_else(|_| format!("\"{key}\""));
            let value = match value {
                Value::String(text) => {
                    serde_json::to_string(text).unwrap_or_else(|_| format!("\"{text}\""))
                }
                other => other.to_string(),
            };
            format!("{key}: {value}")
        })
        .collect::<Vec<_>>()
        .join(", ");
    format!("{{{pairs}}}")
}

/// Render the `examples` of a tool for `--help --examples`.
///
/// Returns `None` when no example is renderable, so the caller prints its
/// "no examples" line instead of a header with nothing under it.
///
/// Executable examples render as `- <title>: <args>`; a runnable example that
/// takes no arguments says so (`no arguments`) rather than rendering an empty
/// bullet; documentation-only snippets (`code` without args) render as an
/// indented fenced block. `notes` follow on an indented `- ` line, and an
/// example flagged `expectsError` is marked as such — a failing call presented
/// as a happy path would be a trap.
fn render_tool_examples(label: &str, examples: &[ToolExampleSpec]) -> Option<String> {
    let mut lines = vec![format!("Examples for {label}:")];
    let mut rendered = 0;

    for example in examples {
        let title = example
            .title
            .as_deref()
            .map(str::trim)
            .filter(|t| !t.is_empty())
            .unwrap_or("example");

        if !example.args.is_empty() || example.is_executable() {
            lines.push(format!(
                "  - {title}: {}",
                if example.args.is_empty() {
                    "no arguments".to_string()
                } else {
                    format!("`{}`", render_example_args(&example.args))
                }
            ));
        } else if let Some(code) = example.code.as_deref().filter(|c| !c.trim().is_empty()) {
            lines.push(format!("  - {title}:"));
            lines.push("    ```".to_string());
            for code_line in code.lines() {
                lines.push(format!("    {code_line}"));
            }
            lines.push("    ```".to_string());
        } else {
            // Nothing callable and nothing to show — an empty bullet would be
            // noise, so the example is skipped entirely.
            continue;
        }

        rendered += 1;
        if let Some(notes) = example.notes.as_deref().map(str::trim).filter(|n| !n.is_empty()) {
            lines.push(format!("    - {notes}"));
        }
        if example.expects_error {
            lines.push("    - expected to fail".to_string());
        }
    }

    (rendered > 0).then(|| lines.join("\n"))
}

/// Resolve the MCP tool a CLI command dispatches to.
///
/// Mirrors the dispatch path: `CommandDef.tool_name_fn` for built-in commands
/// (called with an empty argument map — `--help` carries no arguments, so the
/// arg-dependent selectors fall back to their default tool), and the
/// `plugin <domain> <method>` convention for dynamic plugin commands. Returns
/// `None` when the command maps to no single tool.
fn resolve_command_tool(command: &str, args: &[String]) -> Option<String> {
    let cmd_map = commands_map();
    if let Some(def) = cmd_map.get(command) {
        let tool = (def.tool_name_fn)(&HashMap::new());
        return (!tool.is_empty()).then_some(tool);
    }

    // Dynamic plugin command: `plugin-<domain> <method>` → `<domain>_<method>`.
    // Same rule `resolve_plugin_method` applies after confirming the tool
    // against `GET /mcp/tools`; here the spec lookup is the confirmation.
    let domain = command.strip_prefix("plugin-")?;
    if domain.is_empty() {
        return None;
    }
    let method = args
        .iter()
        .skip_while(|arg| arg.as_str() != command)
        .skip(1)
        .find(|arg| !arg.starts_with('-'))?;
    Some(format!("{}_{}", domain, camel_to_snake(method)))
}

/// Build the `--help --examples` report for a CLI command.
///
/// Sourcing, in order: the CLI's own `Examples:` block (shipped in the binary,
/// so this works with no backend at all), then the richer tool-level examples
/// read from `GET /mcp/tools/specs` — the same endpoint (and the same base URL /
/// session-independent path) the CLI already uses to discover plugin-declared
/// commands.
///
/// Never fails: an unreachable backend, an unknown command, a tool the backend
/// does not advertise and a tool without examples each end in an explanatory
/// line, and the command still exits 0.
async fn build_command_examples(base_url: &str, command: &str, args: &[String]) -> String {
    // A quoted spaced name (`--help "htmlsnapshot get" --examples`) arrives as
    // one argument; resolve it to the internal key its help page lives under
    // before looking anything up.
    let resolved = match classify_help_target(command) {
        HelpTarget::Command(resolved) => resolved,
        _ => command.to_string(),
    };
    let command = resolved.as_str();

    let public = help::public_command_name(command);
    let local = help::command_examples(command);

    let Some(tool) = resolve_command_tool(command, args) else {
        return if commands_map().contains_key(command) || command.starts_with("plugin") {
            examples_or_reason(public, &local, "the command maps to no single tool.")
        } else {
            examples_or_reason(public, &local, "unknown command.")
        };
    };

    match build_tool_examples(base_url, &tool).await {
        Ok(report) => report,
        Err(reason) => examples_or_reason(public, &local, &reason),
    }
}

/// Render a command's built-in examples, or explain why there are none.
fn examples_or_reason(public: &str, local: &[String], reason: &str) -> String {
    if local.is_empty() {
        return format!("No examples available for '{public}' — {reason}");
    }
    let mut lines = vec![format!(
        "Examples for browser4-cli {public} (built into the CLI):"
    )];
    lines.extend(local.iter().cloned());
    lines.push(String::new());
    lines.push(format!("Tool-level examples are unavailable: {reason}"));
    lines.push(format!(
        "Run `browser4-cli --help {public}` for arguments, options, and notes."
    ));
    lines.join("\n")
}

/// Why `--help --examples` has no tool-level examples to show.
///
/// `GET /mcp/tools/specs` only advertises specs that declare a `cliName`
/// (plugin-declared CLI commands), so an HTTP 200 with an empty list is the
/// *normal* answer on a stock install — reporting "is the backend running?"
/// for it (as the CLI used to) misdiagnoses a healthy backend.
fn no_tool_level_examples_reason() -> String {
    "the backend is running but advertises no tool-level examples \
     (`/mcp/tools/specs` lists plugin-declared CLI commands only)."
        .to_string()
}

/// Like [build_command_examples] but for an already-resolved tool — used by
/// plugin-declared commands (`ToolSpec.cliName`), whose tool name comes from the
/// spec rather than from `CommandDef.tool_name_fn`.
///
/// `Err` carries the reason as a phrase the caller drops into its own message,
/// so both the one-line report and the built-in fallback can explain themselves.
async fn build_tool_examples(base_url: &str, tool: &str) -> Result<String, String> {
    let values = match probe_tool_specs_with_examples_within(base_url, std::time::Duration::from_secs(2)).await {
        // The request failed (unreachable, timeout, HTTP error, malformed body):
        // only here is "is the backend running?" the honest diagnosis.
        ToolSpecFetch::Failed(reason) => {
            return Err(format!("is the backend running? ({reason})"));
        }
        // HTTP 200 with no specs: the tools endpoint answered, it just has
        // nothing tool-level to advertise.
        ToolSpecFetch::Specs(values) if values.is_empty() => {
            return Err(no_tool_level_examples_reason());
        }
        ToolSpecFetch::Specs(values) => values,
    };
    let specs: Vec<ToolSpecDoc> = values
        .iter()
        .filter_map(|value| serde_json::from_value(value.clone()).ok())
        .collect();
    if specs.is_empty() {
        // The list was non-empty but nothing deserialized — the endpoint
        // answered with a shape this CLI does not understand.
        return Err(format!(
            "the backend's tool specs could not be read (GET /mcp/tools/specs returned {} entr{} this CLI could not parse).",
            values.len(),
            if values.len() == 1 { "y" } else { "ies" }
        ));
    }

    let Some(spec) = find_tool_spec(&specs, tool) else {
        return Err(format!("the backend does not advertise '{tool}'."));
    };

    let label = format!("{}.{} ({})", spec.domain, spec.method, tool);
    render_tool_examples(&label, &spec.examples)
        .ok_or_else(|| format!("the tool '{tool}' declares no examples."))
}

/// `plugin commands` — list CLI commands declared by installed plugins via
/// `ToolSpec.cliName` (the plugin-declared, first-class command surface).
async fn handle_plugin_commands_command(
    base_url: &str,
    global: &args::GlobalFlags,
) -> Result<(), CliError> {
    ensure_server_running(base_url, should_enforce_server_version(global)).await?;
    let specs = fetch_all_declared_cli_specs(base_url).await;
    cli_println!("{}", render_declared_commands(&specs));
    Ok(())
}

/// Execute a plugin-declared CLI command: parse `--key value` arguments from
/// the tool spec's declared arguments, then call the tool
/// (`<domain>_<method>`) through the session-aware executor.
async fn handle_declared_cli_command(
    base_url: &str,
    spec: &CliToolSpec,
    global: &args::GlobalFlags,
) -> Result<(), CliError> {
    ensure_server_running(base_url, should_enforce_server_version(global)).await?;
    let client = make_client();

    // Boolean args are flags (no value consumed); everything else takes a value.
    let bool_opts: HashSet<String> = spec
        .arguments
        .iter()
        .filter(|a| a.arg_type == "Boolean")
        .map(|a| a.name.clone())
        .collect();
    let short_to_long = HashMap::new();
    let mut parsed = parse_raw_args(&global.args[2..], Some(&short_to_long), Some(&bool_opts));
    // Declared commands take named options only; drop positionals.
    parsed.remove("_");

    let tool_name = format!("{}_{}", spec.domain, spec.method);
    let session_name = global.session_name.as_deref();
    let timeout_override = global.timeout_secs;
    let result = with_session(&client, base_url, session_name, false, |session_id| {
        let client = client.clone();
        let base_url = base_url.to_string();
        let tool_name = tool_name.clone();
        let mut params = Value::Object(parsed.clone().into_iter().collect());
        params["sessionId"] = json!(session_id);
        async move {
            call_tool_with_timeout_override(
                &client,
                &base_url,
                &tool_name,
                params,
                timeout_override,
            )
            .await
        }
    })
    .await
    .map_err(|e| CliError(ExitCode::General, e))?;

    cli_println!("{}", result);
    Ok(())
}

/// Handle a dynamic plugin command (plugin-<name>) that has no hardcoded
/// CommandDef.  Discovers the matching MCP tool from the server's /mcp/tools
/// endpoint and executes it generically.
async fn handle_dynamic_plugin_command(
    client: &Client,
    base_url: &str,
    domain: &str,
    global: &GlobalFlags,
) -> Result<(), CliError> {
    let tool_names = fetch_advertised_tool_names(client, base_url)
        .await
        .map_err(|e| CliError(ExitCode::Server, e))?;
    let tools: Vec<&str> = tool_names.iter().map(String::as_str).collect();

    // If domain is empty (bare `plugin` command), list all available plugin tools
    if domain.is_empty() {
        let domains = available_plugin_domains(&tools);
        if domains.is_empty() {
            cli_println!("No plugin tools available.");
            cli_println!(
                "Installed plugins: browser4-cli plugin list   All advertised tools: browser4-cli tool list"
            );
        } else {
            cli_println!(
                "Available plugin tools ({} domain(s), `plugin <domain> <method>`):",
                domains.len()
            );
            cli_println!("{}", format_plugin_domains(&domains));
            cli_println!("");
            cli_println!("Call one with: browser4-cli plugin <domain> <method> [--key value]");
            cli_println!("Or directly:   browser4-cli tool call <domain>_<method> [--json '{{...}}']");
            cli_println!("Every advertised tool name: browser4-cli tool list");
        }
        json_field("result", json!(domains));
        return Ok(());
    }

    // Find tools matching the domain prefix (e.g. "pptx_*")
    let prefix = format!("{}_", domain);
    let matching: Vec<&&str> = tools.iter().filter(|t| t.starts_with(&prefix)).collect();

    if matching.is_empty() {
        let domains = available_plugin_domains(&tools);
        let hint = if domains.is_empty() {
            "  (no plugin tools available)".to_string()
        } else {
            format!("Available plugin tools:\n{}", format_plugin_domains(&domains))
        };
        // The plugin exists in this checkout but is not installed: name the JAR
        // and the install command instead of only the tool name.
        let install_hint = suggest_plugin_jar_for_domain(domain)
            .map(|jar| format!("\n{}", plugin_install_hint(&jar)))
            .unwrap_or_default();
        return Err(CliError(
            ExitCode::Usage,
            format!("No plugin tools found for '{}'.\n{}{}", domain, hint, install_hint),
        ));
    }

    // Parse remaining args generically: pass through all --key value pairs
    let mut raw_parsed = parse_raw_args(&global.args, None, None);

    // Try to resolve a specific method from the first positional argument.
    // Supports: plugin-media detectVideos, plugin-media download --url ..., etc.
    let tool_name = resolve_plugin_method(&tools, domain, &matching, &mut raw_parsed)?;

    let mut tool_params = serde_json::Map::new();
    for (key, value) in &raw_parsed {
        if key != "_" {
            // CLI flags are conventionally kebab-case (e.g. --max-depth) while
            // plugin tool parameters are camelCase (maxDepth); normalize so
            // kebab-case flags are not silently ignored by the backend.
            tool_params.insert(kebab_to_camel(key), value.clone());
        }
    }

    // Determine session name
    let session_name = global.session_name.as_deref();

    // Execute the tool
    let timeout_override = global.timeout_secs;
    let result = with_session(client, base_url, session_name, false, |session_id| {
        let client = client.clone();
        let base_url = base_url.to_string();
        let tool_name = tool_name.clone();
        let mut params = Value::Object(tool_params.clone());
        params["sessionId"] = json!(session_id);
        async move {
            call_tool_with_timeout_override(
                &client,
                &base_url,
                &tool_name,
                params,
                timeout_override,
            )
            .await
        }
    })
    .await
    .map_err(|e| CliError(ExitCode::General, e))?;

    cli_println!("{}", result);
    // Emit the payload into the JSON envelope too — otherwise --json mode
    // produces no output at all for plugin commands.
    json_field("result", json_text_or_value(&result));
    Ok(())
}

/// Fetch the MCP tool names the backend advertises (`GET /mcp/tools`).
///
/// The single place that talks to the tool-listing endpoint, shared by the
/// plugin command surface, `tool list` and the help path so they cannot drift
/// on how a "no tools" answer is spelled.
async fn fetch_advertised_tool_names(
    client: &Client,
    base_url: &str,
) -> Result<Vec<String>, String> {
    let tools_url = format!("{}/mcp/tools", base_url.trim_end_matches('/'));
    let tools_response = client
        .get(&tools_url)
        .send()
        .await
        .map_err(|e| format!("Failed to fetch the MCP tool list from {tools_url}: {e}"))?;
    let status = tools_response.status();
    let tools_body = tools_response
        .text()
        .await
        .map_err(|e| format!("Failed to read the MCP tool list from {tools_url}: {e}"))?;
    if !status.is_success() {
        return Err(format!("GET {tools_url} returned HTTP {status}"));
    }
    let tools_json: Value = serde_json::from_str(&tools_body)
        .map_err(|e| format!("Failed to parse the MCP tool list from {tools_url}: {e}"))?;
    Ok(tools_json
        .get("tools")
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .filter_map(|t| t.as_str())
                .map(String::from)
                .collect()
        })
        .unwrap_or_default())
}

/// List the MCP tool names the running backend advertises (`tool list`).
async fn handle_tool_list(
    client: &Client,
    base_url: &str,
    tool_params: &Value,
) -> Result<(), CliError> {
    let tools = fetch_advertised_tool_names(client, base_url)
        .await
        .map_err(|e| CliError(ExitCode::Server, e))?;
    let filter = tool_params
        .get("filter")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|f| !f.is_empty());

    let matched: Vec<&String> = tools
        .iter()
        .filter(|name| tool_name_matches_filter(name, filter))
        .collect();

    for name in &matched {
        cli_println!("{}", name);
    }
    json_field("tools", json!(matched));
    json_field("tool_count", json!(matched.len()));

    if !json_active() {
        match filter {
            Some(filter) => eprintln!(
                "{} of {} advertised MCP tool(s) match '{filter}'.",
                matched.len(),
                tools.len()
            ),
            None => eprintln!("{} advertised MCP tool(s).", matched.len()),
        }
        if matched.is_empty() {
            eprintln!(
                "Plugins are listed by `browser4-cli plugin list`; \
                 plugin tool domains by `browser4-cli plugin`."
            );
        }
    }
    Ok(())
}

/// Case-insensitive substring match used by `tool list --filter`.
fn tool_name_matches_filter(name: &str, filter: Option<&str>) -> bool {
    match filter {
        None => true,
        Some(filter) => name
            .to_ascii_lowercase()
            .contains(&filter.to_ascii_lowercase()),
    }
}

/// Helper for diagnostics that name a tool call's target and payload.
///
/// `tool call` is a passthrough: the backend returns the tool's own result,
/// including tools that report failure *inside* their payload (`success:false`
/// or a non-empty `error`) rather than as a transport error.  Printing that and
/// exiting 0 makes a failed tool look like a success to any script that checks
/// `$?`, so the failure is surfaced on stderr and can be turned into a non-zero
/// exit with `--fail-on-error`.
fn tool_call_failure_summary(tool_name: &str, result: &str) -> Option<String> {
    let parsed: Value = serde_json::from_str(result).ok()?;
    tool_call_failure_summary_from_json(tool_name, &parsed)
}

/// [tool_call_failure_summary] over an already-parsed payload.
///
/// An envelope (`{"status":"ok","output":{...}}`) is unwrapped first, so a tool
/// result nested in the CLI's own envelope is inspected as well.
fn tool_call_failure_summary_from_json(tool_name: &str, parsed: &Value) -> Option<String> {
    let payload = parsed.get("output").unwrap_or(parsed);

    let failed = payload
        .get("success")
        .and_then(|v| v.as_bool())
        .map(|ok| !ok)
        .unwrap_or(false);
    let error = payload
        .get("error")
        .and_then(|v| v.as_str())
        .map(str::trim)
        .filter(|e| !e.is_empty() && !e.eq_ignore_ascii_case("null"));

    if !failed && error.is_none() {
        return None;
    }
    let reason = error.unwrap_or("the tool reported success:false");
    Some(format!("{tool_name} reported a failure: {reason}"))
}

/// Invoke an arbitrary MCP tool by name (`tool call <mcp-name> [--json '{...}']`).
///
/// Generic passthrough for tools that have no dedicated CLI command — most
/// notably plugin-provided agent tools such as `captcha_detect`. The active
/// session's sessionId is injected automatically, the same as for plugin
/// commands.
async fn handle_tool_call(
    client: &Client,
    base_url: &str,
    tool_name: &str,
    tool_args: Value,
    global: &GlobalFlags,
    fail_on_error: bool,
) -> Result<(), CliError> {
    let session_name = global.session_name.as_deref();
    let timeout_override = global.timeout_secs;
    let tool_name_owned = tool_name.to_string();
    let result = with_session(
        client,
        base_url,
        session_name,
        false,
        |session_id| {
            let client = client.clone();
            let base_url = base_url.to_string();
            let tool_name = tool_name_owned.clone();
            let mut params = tool_args.clone();
            params["sessionId"] = json!(session_id);
            async move {
                call_tool_with_timeout_override(&client, &base_url, &tool_name, params, timeout_override)
                    .await
            }
        },
    )
    .await
    .map_err(|e| CliError(ExitCode::General, enrich_unknown_tool_error(e, tool_name)))?;

    cli_println!("{}", result);
    json_field("result", json_text_or_value(&result));

    // A tool that reports its own failure must not look like a success: the
    // payload stays on stdout untouched, the diagnostic goes to stderr, and
    // --fail-on-error turns it into a non-zero exit for scripts.
    if let Some(failure) = tool_call_failure_summary(tool_name, &result) {
        if !quiet_active() {
            eprintln!("⚠️  {failure}");
        }
        if fail_on_error {
            return Err(CliError(
                ExitCode::PartialFailure,
                format!("{failure}\nThe tool result is on stdout; re-run without --fail-on-error to ignore it."),
            ));
        }
    }
    Ok(())
}

/// Parse the `--fail-on-error` option of `tool call`.
fn parse_tool_call_fail_on_error(raw: Option<Value>) -> bool {
    raw.and_then(|v| v.as_bool()).unwrap_or(false)
}

/// Parse the `--json` option of `tool call` into a JSON object map.
/// Extracted as a pure function so the validation logic can be unit-tested
/// without a running backend.
fn parse_tool_call_json(raw: Option<&str>) -> Result<serde_json::Map<String, Value>, CliError> {
    let raw = match raw.map(str::trim).filter(|s| !s.is_empty()) {
        Some(raw) => raw,
        None => return Ok(serde_json::Map::new()),
    };
    let parsed: Value = serde_json::from_str(raw).map_err(|e| {
        CliError(
            ExitCode::Usage,
            format!(
                "Invalid --json payload: {}. Expected a JSON object, e.g. --json '{{\"siteKey\": \"...\"}}'",
                e
            ),
        )
    })?;
    match parsed {
        Value::Object(map) => Ok(map),
        other => {
            let kind = match other {
                Value::Null => "null",
                Value::Bool(_) => "a boolean",
                Value::Number(_) => "a number",
                Value::String(_) => "a string",
                Value::Array(_) => "an array",
                Value::Object(_) => unreachable!(),
            };
            Err(CliError(
                ExitCode::Usage,
                format!(
                    "--json must be a JSON object, got {}. Example: --json '{{\"type\": \"RECAPTCHA_V2\", \"siteKey\": \"...\"}}'",
                    kind
                ),
            ))
        }
    }
}

/// Extract the available plugin tool domains from the server's tool list
/// (filtering out built-in tools), deduplicated and sorted.
///
/// `GET /mcp/tools` is a flat name list, so `domain -> methods` has to be
/// reconstructed.  Splitting every name at its **last** underscore (the
/// previous implementation) invented domains out of method words —
/// `captcha_get_balance` became the domain `captcha_get`, so `captcha_detect`
/// never appeared in the listing and `plugin captcha_get` was advertised as a
/// command that does not exist — and camelCase API names, which the naming
/// layer snake_cases per capital (`baseURL` → `base_u_r_l`), produced
/// single-letter domains (`base`, `nano`, `outer`) out of core `tab`/`system`
/// methods.
///
/// A name is treated as a plugin tool when **all** of these hold:
/// * it is not one of the tools the CLI's own command registry already exposes,
/// * it is not under a built-in tool-domain prefix, and
/// * its snake form has no run of two or more single-letter tokens — such a run
///   is a per-capital acronym split, not a `domain_method` boundary.
///
/// The domain is then the first token and the method the remainder, which keeps
/// `plugin <domain> <method>` resolvable (`media` + `detect_videos` →
/// `media_detect_videos`); the grouping is only a listing aid, the pair is what
/// the invocation needs.
fn available_plugin_domains(tools: &[&str]) -> Vec<PluginToolDomain> {
    let builtin = builtin_tool_names();
    let mut grouped: std::collections::BTreeMap<String, Vec<String>> =
        std::collections::BTreeMap::new();

    for tool in tools {
        if is_builtin_tool_name_by_shape(tool) || builtin.contains(*tool) {
            continue;
        }
        let Some((domain, method)) = split_plugin_tool_name(tool) else {
            continue;
        };
        grouped
            .entry(domain.to_string())
            .or_default()
            .push(method.to_string());
    }

    grouped
        .into_iter()
        .map(|(domain, mut methods)| {
            methods.sort();
            methods.dedup();
            PluginToolDomain { domain, methods }
        })
        .collect()
}

/// One plugin tool domain and the method names advertised under it.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
struct PluginToolDomain {
    /// Tool domain, e.g. `captcha`.
    domain: String,
    /// Method names as they appear after the domain prefix, e.g. `get_balance`.
    methods: Vec<String>,
}

/// True when [tool] belongs to a tool domain the CLI already exposes as its own
/// command — by name shape (session lifecycle, frontend aliases, snapshot/DOM
/// helpers) or because a `CommandDef` maps to it.
fn is_builtin_tool_name(tool: &str) -> bool {
    is_builtin_tool_name_by_shape(tool) || builtin_tool_names().contains(tool)
}

/// The shape-only half of [`is_builtin_tool_name`].
///
/// The registry half is the expensive part (it walks every `CommandDef`), so
/// callers testing many names build that set once and call this directly.
fn is_builtin_tool_name_by_shape(tool: &str) -> bool {
    /// Session-lifecycle tools every backend advertises
    /// (`MCPToolController.buildStaticToolNames`), listed exactly because their
    /// names do not share a common prefix — `list_sessions` would otherwise be
    /// split into the domain `list`.
    const BUILTIN_EXACT_NAMES: &[&str] = &[
        "open_session",
        "close_session",
        "list_sessions",
        "close_all_sessions",
        "kill_all_sessions",
        "delete_session_data",
        "attach_browser",
        "check_session_ready",
    ];
    const BUILTIN_PREFIXES: &[&str] = &[
        "browser_",
        "open_",
        "close_",
        "attach_",
        "delete_",
        "command_",
        "crawl_",
        "swarm_",
        "skill_",
        "html_snapshot_",
        "check_session_",
        "wait_for_",
        "bounding_box_",
        "select_first_",
        "page_",
        "switch_tab",
        "tab_",
        "keydown",
        "keyup",
        "mousemove",
        "mousedown",
        "mouseup",
        "mousewheel",
        "delay",
        "scroll_by",
        "execute_cdp",
        "clear_browser_cookies",
        "delete_cookies",
        "generate_locator",
    ];
    BUILTIN_EXACT_NAMES.contains(&tool) || BUILTIN_PREFIXES.iter().any(|p| tool.starts_with(p))
}

/// Every MCP tool name the CLI's own command registry maps to.
///
/// This is the *positive* built-in filter: a name in this set has a first-class
/// CLI command, so listing it as a plugin tool would be wrong no matter how it
/// is spelled.  The `tool_name_fn` closures are total functions of the argument
/// map (they only read it through the `get_*` helpers), so calling them with an
/// empty map is safe and side-effect free.
fn builtin_tool_names() -> std::collections::HashSet<String> {
    let empty = HashMap::new();
    commands_map()
        .values()
        .map(|def| (def.tool_name_fn)(&empty))
        .filter(|name| !name.is_empty())
        .collect()
}

/// Split `<domain>_<method>` out of an MCP tool name, or `None` when the name
/// is not a plugin tool (`fill`, `document_u_r_i`, …).
fn split_plugin_tool_name(tool: &str) -> Option<(&str, &str)> {
    let (domain, method) = tool.split_once('_')?;
    if domain.is_empty() || method.is_empty() {
        return None;
    }
    // `document_u_r_i` / `base_u_r_l` / `nano_d_o_m` / `outer_h_t_m_l`: the
    // naming layer inserts an underscore before every capital, so a run of
    // single-letter tokens is an acronym, not a domain/method boundary.
    if has_single_letter_token_run(method) {
        return None;
    }
    Some((domain, method))
}

/// True when [name] contains two or more consecutive single-character tokens.
fn has_single_letter_token_run(name: &str) -> bool {
    let mut run = 0usize;
    for token in name.split('_') {
        if token.chars().count() == 1 {
            run += 1;
            if run >= 2 {
                return true;
            }
        } else {
            run = 0;
        }
    }
    false
}

/// Format plugin domains as a human-readable `domain  method, method` list.
fn format_plugin_domains(domains: &[PluginToolDomain]) -> String {
    let width = domains
        .iter()
        .map(|d| d.domain.chars().count())
        .max()
        .unwrap_or(0);
    domains
        .iter()
        .map(|d| {
            format!(
                "  {:<width$}  {}",
                d.domain,
                d.methods.join(", "),
                width = width
            )
        })
        .collect::<Vec<_>>()
        .join("\n")
}

/// `plugin` subcommands that are static CLI commands, not tool domains.
const BUILTIN_PLUGIN_SUBCOMMANDS: &[&str] = &["list", "info", "install", "remove", "commands"];

/// Identify a plugin tool domain named by a help request.
///
/// Answers both spellings users type — `--help plugin-markdown` and
/// `plugin markdown --help` — and `None` for the static `plugin` subcommands so
/// their own help pages stay in charge.
fn plugin_domain_help_target(command: &str, args: &[String]) -> Option<String> {
    if let Some(domain) = command.strip_prefix("plugin-") {
        if !domain.is_empty() && !BUILTIN_PLUGIN_SUBCOMMANDS.contains(&domain) {
            return Some(domain.to_string());
        }
        return None;
    }
    // `plugin <domain> --help`: the second word is the domain, unless it is a
    // flag or one of the static subcommands.
    if command == "plugin" {
        let candidate = args.iter().skip(1).find(|arg| !arg.starts_with('-'))?;
        if !BUILTIN_PLUGIN_SUBCOMMANDS.contains(&candidate.as_str()) {
            return Some(candidate.clone());
        }
    }
    None
}

/// Short help for the `tool` passthrough surface: `tool --help`, bare `tool`.
///
/// `tool` is a prefix-only command (it maps to no single backend tool), so it
/// had no help page: `--help tool` printed a two-line stub and bare `tool`
/// dumped the whole ~360-line reference with exit 2.
fn print_tool_surface_help() {
    cli_println!("browser4-cli tool — call any advertised MCP tool by name");
    cli_println!("");
    cli_println!("  browser4-cli tool list [--filter <substr>]   list the advertised tool names");
    cli_println!("  browser4-cli tool call <mcp-name> [--json '{{...}}']   invoke one tool");
    cli_println!("  browser4-cli tool call <name> --fail-on-error          exit non-zero on success:false");
    cli_println!("  browser4-cli plugin <domain> --help          methods of one plugin domain");
    cli_println!("");
    cli_println!("Tool names are snake_case: captcha.detect -> captcha_detect.");
    cli_println!("Plugin-declared commands also work directly, e.g. browser4-cli profile import.");
}

/// The usage error for a `tool` subcommand the CLI does not implement.
///
/// Bare `tool` and `tool <typo>` used to print the whole general reference with
/// no hint which subcommands exist — and the `tool call` help text pointed at
/// `plugin list`, which lists plugin JARs rather than tools.
fn unknown_tool_subcommand_message(subcommand: Option<&str>) -> String {
    let named = subcommand
        .map(|sub| format!("Unknown subcommand '{sub}' for 'tool'."))
        .unwrap_or_else(|| "'tool' needs a subcommand.".to_string());
    format!(
        "{named}\nSupported: `tool call <mcp-name>`, `tool list [--filter <substr>]`.\n\
         Run `browser4-cli tool list` for the advertised tool names, or \
         `browser4-cli plugin` for plugin tool domains."
    )
}

///
/// Plugin tool commands are discovered at runtime, so the static help path can
/// only fall through to `Unknown command: plugin-markdown` plus the whole
/// ~350-line reference — even for a domain whose command works. Returns `false`
/// when the domain has no advertised tools (or the backend is unreachable), so
/// the caller keeps its existing fallback.
/// Focused message for `--help plugin-<domain>` when the domain's methods cannot
/// be listed.
///
/// Falling through to the caller would print `Unknown command: plugin-<domain>`
/// followed by the whole ~200-line command reference, which hides the real
/// cause and buries the answer.
fn report_plugin_domain_help_unavailable(domain: &str, cause: &str) {
    eprintln!("Plugin tool domain '{domain}' has no help to show: {cause}");
    eprintln!("  - List every advertised tool:  browser4-cli tool list");
    eprintln!("  - Check the backend:           browser4-cli status");
    eprintln!(
        "  - Plugin commands are served by the running backend; install the plugin (or start the backend) and retry."
    );
}

async fn print_plugin_domain_help(base_url: &str, domain: &str) -> bool {
    let Ok(client) = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(2))
        .build()
    else {
        report_plugin_domain_help_unavailable(domain, "the CLI could not build an HTTP client");
        return true;
    };
    let Ok(tools) = fetch_advertised_tool_names(&client, base_url).await else {
        report_plugin_domain_help_unavailable(
            domain,
            "the backend did not report its tool list — is it running? is the plugin installed?",
        );
        return true;
    };
    let prefix = format!("{domain}_");
    let mut methods: Vec<&str> = tools
        .iter()
        .filter(|tool| tool.starts_with(&prefix))
        .map(|tool| &tool[prefix.len()..])
        .collect();
    if methods.is_empty() {
        report_plugin_domain_help_unavailable(
            domain,
            "the backend advertised no tools for this domain — is the plugin installed?",
        );
        return true;
    }
    methods.sort();
    methods.dedup();

    cli_println!("Plugin tool domain '{domain}' ({} method(s)):", methods.len());
    for method in &methods {
        cli_println!("  {method}");
    }
    cli_println!("");
    cli_println!("Call one with: browser4-cli plugin {domain} <method> [--key value]");
    cli_println!("Or directly:   browser4-cli tool call {domain}_<method> [--json '{{...}}']");
    cli_println!("Every advertised tool name: browser4-cli tool list");
    true
}

/// The member of `browser4-plugins/` that provides [domain]'s tools, if this is
/// a source checkout that has built it.
///
/// `tool call media_detect_videos` on a checkout whose `browser4-media` plugin
/// was built but not installed answered "unknown tool" and nothing else, so the
/// user had to find the JAR by hand.  Only source checkouts can be searched: an
/// installed release returns `None` and the original error stands unchanged.
fn suggest_plugin_jar_for_domain(domain: &str) -> Option<PathBuf> {
    let root = crate::daemon::dev_workspace_root()?;
    let modules_dir = root.join("browser4-plugins");
    let wanted = depluralize(&domain.to_ascii_lowercase());

    let mut candidates: Vec<PathBuf> = Vec::new();
    for entry in std::fs::read_dir(&modules_dir).ok()?.flatten() {
        let module = entry.file_name().to_string_lossy().to_ascii_lowercase();
        let stem = plugin_stem(&module);
        if stem != wanted && depluralize(&stem) != wanted {
            continue;
        }
        if let Some(jar) = newest_plugin_jar(&entry.path().join("target")) {
            candidates.push(jar);
        }
    }
    candidates.sort();
    // Prefer the artifact built for this CLI's version.
    if let Some(matching) = candidates.iter().find(|jar| {
        jar.file_name()
            .and_then(|name| name.to_str())
            .is_some_and(|name| name.contains(VERSION))
    }) {
        return Some(matching.clone());
    }
    candidates.into_iter().next()
}

/// The newest `*.jar` in [target_dir], or `None` when it holds none.
///
/// Ties are broken by path so the choice is deterministic for a caller that
/// reports it to the user.
fn newest_plugin_jar(target_dir: &Path) -> Option<PathBuf> {
    let mut jars: Vec<(std::time::SystemTime, PathBuf)> = std::fs::read_dir(target_dir)
        .ok()?
        .flatten()
        .filter(|entry| entry.path().is_file())
        .filter(|entry| entry.file_name().to_string_lossy().ends_with(".jar"))
        .filter_map(|entry| {
            let modified = entry.metadata().ok()?.modified().ok()?;
            Some((modified, entry.path()))
        })
        .collect();
    jars.sort_by(|a, b| b.0.cmp(&a.0).then_with(|| a.1.cmp(&b.1)));
    jars.into_iter().next().map(|(_, path)| path)
}

/// The install recipe for a plugin JAR this checkout has already built.
fn plugin_install_hint(jar: &Path) -> String {
    format!(
        "The tool is provided by a plugin this checkout has built but not installed:\n  {}\n\
         Install it and restart the backend so it loads:\n  browser4-cli plugin install \"{}\"\n  browser4-cli stop",
        jar.display(),
        jar.display()
    )
}

/// True when a backend error says the requested MCP tool name is not registered.
///
/// Covers both phrasings the backend uses: the `UNKNOWN_TOOL` error code and the
/// "Unknown tool: <name>" message.
fn is_unknown_tool_error(message: &str) -> bool {
    let lower = message.to_ascii_lowercase();
    lower.contains("unknown tool")
        || lower.contains("unknown_tool")
        || lower.contains("tool not found")
        || lower.contains("no such tool")
}

/// Append the in-repo plugin JAR and its install command to an unknown-tool
/// error, so "unknown tool" is actionable instead of a dead end.
fn enrich_unknown_tool_error(message: String, tool_name: &str) -> String {
    if !is_unknown_tool_error(&message) {
        return message;
    }
    let Some(domain) = tool_name.split('_').next().filter(|d| !d.is_empty()) else {
        return message;
    };
    let Some(jar) = suggest_plugin_jar_for_domain(domain) else {
        return message;
    };
    format!("{message}\n{}", plugin_install_hint(&jar))
}

/// Short help for the `plugin` surface itself: `plugin`, `plugin --help`.///
/// The bare command lists plugin tools from the backend; this page keeps the
/// static picture (subcommands + how to reach the dynamic surface) in the
/// binary, so it works with no backend at all.
fn print_plugin_surface_help() {
    cli_println!("browser4-cli plugin — installed plugins and the tools they expose");
    cli_println!("");
    cli_println!("  browser4-cli plugin                    plugin tool domains and their methods");
    cli_println!("  browser4-cli plugin <domain> <method>  run one plugin tool");
    cli_println!("  browser4-cli plugin <domain> --help    methods of one plugin domain");
    cli_println!("  browser4-cli plugin list               installed plugin JARs (not tools)");
    cli_println!("  browser4-cli plugin info <name>        details for one installed plugin");
    cli_println!("  browser4-cli plugin install <jar>      install a plugin (then restart the backend)");
    cli_println!("  browser4-cli plugin remove <name>      remove a plugin");
    cli_println!("  browser4-cli plugin commands           commands declared by plugins ([plugin])");
    cli_println!("");
    cli_println!("  browser4-cli tool list                 every advertised MCP tool name");
    cli_println!("  browser4-cli tool call <name>          invoke a tool by its MCP name");
}

/// Convert a kebab-case flag name to camelCase for plugin tool parameters.
/// Examples: "max-depth" → "maxDepth", "url" → "url".
fn kebab_to_camel(s: &str) -> String {
    if !s.contains('-') {
        return s.to_string();
    }
    let mut result = String::with_capacity(s.len());
    let mut upper_next = false;
    for ch in s.chars() {
        if ch == '-' {
            upper_next = true;
        } else if upper_next {
            result.push(ch.to_ascii_uppercase());
            upper_next = false;
        } else {
            result.push(ch);
        }
    }
    result
}

/// Returns true when npm's output indicates browser4-cli was not installed
/// via npm, as opposed to a genuine uninstall failure.
fn npm_not_installed_message(msg: &str) -> bool {
    let lower = msg.to_ascii_lowercase();
    lower.contains("enoent")
        || lower.contains("not found")
        || lower.contains("not installed")
        || lower.contains("no such package")
        || lower.is_empty()
}

/// Returns true when cargo's output indicates browser4-cli was not installed
/// via cargo, as opposed to a genuine uninstall failure.
fn cargo_not_installed_message(msg: &str) -> bool {
    let lower = msg.to_ascii_lowercase();
    lower.contains("did not match any packages")
        || lower.contains("no packages found")
        || lower.contains("not found")
        || lower.is_empty()
}

/// Format the output lines for `handle_uninstall`.  Extracted as a pure function
/// so the branching logic can be unit-tested without network I/O.
fn format_uninstall_output(
    npm_removed: bool,
    npm_error: Option<&str>,
    cargo_removed: bool,
    cargo_error: Option<&str>,
    runtime_dir_removed: bool,
    runtime_dir: &str,
    cache_dir_removed: bool,
    cache_dir: &str,
    dry_run: bool,
) -> Vec<String> {
    let mut lines = Vec::new();

    if dry_run {
        lines.push("🔍 DRY RUN — no changes will be made.".to_string());
        lines.push(String::new());
    }

    // npm
    if dry_run {
        if npm_removed {
            lines.push("🔍 Would remove browser4-cli from npm global packages.".to_string());
        } else {
            lines.push("ℹ  npm not found or browser4-cli not installed via npm.".to_string());
        }
    } else if npm_removed {
        lines.push("✅ Removed browser4-cli from npm global packages.".to_string());
    } else if let Some(err) = npm_error {
        lines.push(format!("⚠  npm uninstall failed: {err}"));
    } else {
        lines.push("ℹ  npm not found or browser4-cli not installed via npm.".to_string());
    }

    // cargo
    if dry_run {
        if cargo_removed {
            lines.push("🔍 Would remove browser4-cli from cargo installs.".to_string());
        } else {
            lines.push("ℹ  cargo not found or browser4-cli not installed via cargo.".to_string());
        }
    } else if cargo_removed {
        lines.push("✅ Removed browser4-cli from cargo installs.".to_string());
    } else if let Some(err) = cargo_error {
        lines.push(format!("⚠  cargo uninstall failed: {err}"));
    } else {
        lines.push("ℹ  cargo not found or browser4-cli not installed via cargo.".to_string());
    }

    // runtime data dir
    if dry_run {
        if runtime_dir_removed {
            lines.push(format!(
                "🔍 Would remove runtime data directory: {runtime_dir}"
            ));
        } else {
            lines.push(format!(
                "ℹ  Runtime data directory not present: {runtime_dir}"
            ));
        }
    } else if runtime_dir_removed {
        lines.push(format!("✅ Removed runtime data directory: {runtime_dir}"));
    } else {
        lines.push(format!(
            "ℹ  Runtime data directory not present: {runtime_dir}"
        ));
    }

    // cache dir
    if dry_run {
        if cache_dir_removed {
            lines.push(format!(
                "🔍 Would remove runtime cache directory: {cache_dir}"
            ));
        } else {
            lines.push(format!(
                "ℹ  Runtime cache directory not present: {cache_dir}"
            ));
        }
    } else if cache_dir_removed {
        lines.push(format!("✅ Removed runtime cache directory: {cache_dir}"));
    } else {
        lines.push(format!(
            "ℹ  Runtime cache directory not present: {cache_dir}"
        ));
    }

    lines
}

/// Attempt to remove the running browser4-cli binary from disk.
///
/// On Unix, the file can be unlinked while the process is running — the
/// directory entry disappears immediately and the inode is freed when the
/// process exits.  On Windows the running executable is locked, so we
/// schedule a deferred deletion via a detached PowerShell script.
fn attempt_self_removal(exe_path: &std::path::Path) -> bool {
    // Companion link names that the install scripts create alongside the binary.
    // We clean these up too so stale symlinks / hardlinks / .cmd wrappers don't
    // linger after uninstall.
    #[cfg(windows)]
    const COMPANION_NAMES: &[&str] = &["b4.exe", "b4.cmd", "browser4-cli.exe", "browser4-cli.cmd"];
    #[cfg(not(windows))]
    const COMPANION_NAMES: &[&str] = &["b4", "browser4-cli"];

    #[cfg(windows)]
    {
        let exe_str = exe_path.display().to_string();
        // PowerShell single-quoted strings: only ' is special — escape it
        // by doubling.  Everything else ($, `, etc.) is literal inside '…'.
        let escaped = exe_str.replace('\'', "''");

        // Build companion-removal lines.  Each companion is removed
        // unconditionally (best-effort) after the main binary is gone.
        let mut companion_lines = String::new();
        let exe_dir = exe_path
            .parent()
            .map(|p| p.display().to_string())
            .unwrap_or_default();
        let escaped_dir = exe_dir.replace('\'', "''");
        for name in COMPANION_NAMES {
            companion_lines.push_str(&format!(
                "$c = Join-Path '{escaped_dir}' '{name}'\n\
                 if ((Test-Path -LiteralPath $c) -and ($c -ne $target)) {{\n\
                     Remove-Item -Force -LiteralPath $c -ErrorAction SilentlyContinue\n\
                 }}\n"
            ));
        }

        // Retry loop (up to 30 s, 500 ms intervals) for the main binary so
        // the script is resilient to the parent process taking a moment to
        // flush stdout / release the file handle.  Companion links are
        // cleaned up afterwards; then the script removes itself.
        let ps_script = format!(
            "$target = '{escaped}'\n\
             if (Test-Path -LiteralPath $target) {{\n\
                 $deadline = (Get-Date).AddSeconds(30)\n\
                 while ((Get-Date) -lt $deadline) {{\n\
                     try {{\n\
                         Remove-Item -Force -LiteralPath $target -ErrorAction Stop\n\
                         break\n\
                     }} catch {{\n\
                         Start-Sleep -Milliseconds 500\n\
                     }}\n\
                 }}\n\
             }}\n\
             {companion_lines}\
             Remove-Item -Force -LiteralPath $MyInvocation.MyCommand.Path -ErrorAction SilentlyContinue\n"
        );

        let tmp_dir = std::env::temp_dir();
        let script_path =
            tmp_dir.join(format!("browser4-cli-uninstall-{}.ps1", std::process::id()));

        if let Err(e) = std::fs::write(&script_path, &ps_script) {
            cli_println!("  Warning: Could not write cleanup script: {e}");
            return false;
        }

        match std::process::Command::new("powershell")
            .args([
                "-WindowStyle",
                "Hidden",
                "-NoProfile",
                "-NonInteractive",
                "-File",
            ])
            .arg(&script_path)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .spawn()
        {
            Ok(_) => {
                cli_println!("  Binary and companion links scheduled for removal after exit.");
                true
            }
            Err(e) => {
                cli_println!("  Warning: Could not schedule binary removal: {e}");
                false
            }
        }
    }

    #[cfg(not(windows))]
    {
        let mut removed = false;
        match std::fs::remove_file(exe_path) {
            Ok(()) => {
                cli_println!("  Binary removed.");
                removed = true;
            }
            Err(e) => {
                cli_println!("  Warning: Could not remove binary: {e}");
            }
        }

        // Clean up companion symlinks (b4, browser4-cli) from the same
        // directory.  These are best-effort — silently skip if missing.
        let dir = exe_path.parent().unwrap_or(std::path::Path::new("."));
        for name in COMPANION_NAMES {
            let companion = dir.join(name);
            if companion != exe_path {
                match std::fs::remove_file(&companion) {
                    Ok(()) => cli_println!("  Removed companion link: {}", name),
                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                    Err(e) => cli_println!("  Warning: Could not remove {}: {e}", name),
                }
            }
        }

        removed
    }
}

async fn handle_uninstall(tool_params: &Value) -> Result<(), String> {
    use std::process::Command;

    eprintln!("🧹 Uninstalling browser4-cli ...");
    eprintln!();

    let dry_run = tool_params
        .get("dry_run")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if dry_run {
        eprintln!("🔍 DRY RUN — no changes will be made.");
        eprintln!();
    }

    // Helper: run a subprocess with a wall-clock timeout.  Returns the
    // process output or a timeout/spawn error.
    //
    // stdout and stderr are drained on background threads to prevent
    // pipe-buffer deadlock: if the child process writes more than the
    // OS pipe buffer (~64 KB on Windows) and no one is reading, the
    // child blocks on write → wait_with_output never returns.
    fn run_with_timeout(
        mut cmd: Command,
        timeout_secs: u64,
    ) -> Result<std::process::Output, String> {
        let mut child = cmd.spawn().map_err(|e| e.to_string())?;

        // Take the pipe handles and drain them on background threads.
        let stdout_reader = child.stdout.take().map(|mut out| {
            std::thread::spawn(move || {
                let mut buf = Vec::new();
                let _ = std::io::Read::read_to_end(&mut out, &mut buf);
                buf
            })
        });
        let stderr_reader = child.stderr.take().map(|mut err| {
            std::thread::spawn(move || {
                let mut buf = Vec::new();
                let _ = std::io::Read::read_to_end(&mut err, &mut buf);
                buf
            })
        });

        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(timeout_secs);
        loop {
            match child.try_wait() {
                Ok(Some(status)) => {
                    let stdout = stdout_reader
                        .and_then(|h| h.join().ok())
                        .unwrap_or_default();
                    let stderr = stderr_reader
                        .and_then(|h| h.join().ok())
                        .unwrap_or_default();
                    return Ok(std::process::Output {
                        status,
                        stdout,
                        stderr,
                    });
                }
                Ok(None) => {
                    if std::time::Instant::now() >= deadline {
                        let _ = child.kill();
                        // Drain the pipe readers after killing so the
                        // threads don't linger.
                        let _stdout = stdout_reader.and_then(|h| h.join().ok());
                        let _stderr = stderr_reader.and_then(|h| h.join().ok());
                        return Err(format!("process did not complete within {timeout_secs}s"));
                    }
                    std::thread::sleep(std::time::Duration::from_millis(200));
                }
                Err(e) => return Err(e.to_string()),
            }
        }
    }

    // ── 1. npm global uninstall ──
    // On Windows npm ships as `npm.cmd` (a batch shim) — a bare `npm` is
    // not resolvable by CreateProcess (it does not consult PATHEXT), so
    // resolve the real command name first.  Otherwise npm is reported as
    // "not installed" and a globally installed package is silently left
    // behind while the CLI claims uninstall succeeded.
    let npm = resolve_npm();
    let (npm_removed, npm_error) = if dry_run {
        // Check whether npm would find the package, but don't remove anything.
        let installed = npm
            .map(|npm| {
                Command::new(npm)
                    .args(["list", "-g", "browser4-cli", "--depth=0"])
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::null())
                    .output()
                    .map(|o| o.status.success())
                    .unwrap_or(false)
            })
            .unwrap_or(false);
        (installed, None)
    } else {
        match npm {
            Some(npm) => {
                let mut cmd = Command::new(npm);
                cmd.args(["uninstall", "-g", "browser4-cli"])
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::piped());
                match run_with_timeout(cmd, 60) {
                    Ok(output) => {
                        if output.status.success() {
                            (true, None)
                        } else {
                            let stderr =
                                String::from_utf8_lossy(&output.stderr).trim().to_string();
                            let stdout =
                                String::from_utf8_lossy(&output.stdout).trim().to_string();
                            let msg = if stderr.is_empty() { stdout } else { stderr };
                            if npm_not_installed_message(&msg) {
                                (false, None)
                            } else {
                                (false, Some(msg))
                            }
                        }
                    }
                    Err(_) => {
                        // npm not on PATH or spawn failed — treat as not installed
                        (false, None)
                    }
                }
            }
            None => (false, None),
        }
    };

    // ── 2. cargo uninstall ──
    let (cargo_removed, cargo_error) = if dry_run {
        // Check whether cargo would find the package, but don't remove anything.
        let installed = Command::new("cargo")
            .args(["install", "--list"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::null())
            .output()
            .map(|o| {
                String::from_utf8_lossy(&o.stdout)
                    .lines()
                    .any(|l| l.contains("browser4-cli"))
            })
            .unwrap_or(false);
        (installed, None)
    } else {
        let mut cmd = Command::new("cargo");
        cmd.args(["uninstall", "browser4-cli"])
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        match run_with_timeout(cmd, 120) {
            Ok(output) => {
                if output.status.success() {
                    (true, None)
                } else {
                    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
                    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
                    let msg = if stderr.is_empty() { stdout } else { stderr };
                    if cargo_not_installed_message(&msg) {
                        (false, None)
                    } else {
                        (false, Some(msg))
                    }
                }
            }
            Err(_) => {
                // cargo not on PATH or spawn failed — treat as not installed
                (false, None)
            }
        }
    };

    // ── 3. Remove runtime data directory (with confirmation if it exists) ──
    let runtime_dir = state::resolve_runtime_data_dir();
    let runtime_dir_str = runtime_dir.display().to_string();
    let cache_dir = state::resolve_runtime_cache_dir();
    let cache_dir_str = cache_dir.display().to_string();

    let has_data = runtime_dir.exists();
    let has_cache = cache_dir.exists();

    let skip_confirm = tool_params
        .get("yes")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    let (runtime_dir_removed, cache_dir_removed) = if has_data || has_cache {
        // In dry-run mode, skip the confirmation prompt — we're just
        // previewing what would happen.
        let confirmed = if dry_run || skip_confirm {
            true
        } else if !std::io::stdin().is_terminal() {
            // Stdin is not a terminal (piped or redirected, e.g. from
            // a CI runner or a non-interactive PowerShell session).
            // Blocking on read_line would hang indefinitely, so auto-deny
            // the removal and tell the caller to pass --yes explicitly.
            eprintln!();
            eprintln!("The following directories would be removed:");
            if has_data {
                eprintln!("  Runtime data:  {runtime_dir_str}");
            }
            if has_cache {
                eprintln!("  Runtime cache: {cache_dir_str}");
            }
            eprintln!();
            eprintln!("Non-interactive session — confirmation skipped (directories preserved).");
            eprintln!("Re-run with  browser4-cli uninstall --yes  to remove them.");
            false
        } else {
            eprintln!();
            eprintln!("The following directories will be removed:");
            if has_data {
                eprintln!("  Runtime data:  {runtime_dir_str}");
            }
            if has_cache {
                eprintln!("  Runtime cache: {cache_dir_str}");
            }
            eprintln!();
            eprintln!("Type 'yes' to confirm, anything else to skip:");

            let mut input = String::new();
            match std::io::stdin().read_line(&mut input) {
                Ok(_) if input.trim().eq_ignore_ascii_case("yes") => true,
                _ => false,
            }
        };

        if confirmed {
            if dry_run {
                (has_data, has_cache)
            } else {
                let removed_data = if has_data {
                    std::fs::remove_dir_all(&runtime_dir).is_ok()
                } else {
                    false
                };
                let removed_cache = if has_cache {
                    std::fs::remove_dir_all(&cache_dir).is_ok()
                } else {
                    false
                };
                (removed_data, removed_cache)
            }
        } else {
            eprintln!("Skipped directory removal.");
            (false, false)
        }
    } else {
        (false, false)
    };

    // ── Print output ──
    let lines = format_uninstall_output(
        npm_removed,
        npm_error.as_deref(),
        cargo_removed,
        cargo_error.as_deref(),
        runtime_dir_removed,
        &runtime_dir_str,
        cache_dir_removed,
        &cache_dir_str,
        dry_run,
    );
    for line in &lines {
        cli_println!("{}", line);
    }

    // ── JSON fields ──
    json_field("npm_removed", json!(npm_removed));
    if let Some(ref err) = npm_error {
        json_field("npm_error", json!(err));
    }
    json_field("cargo_removed", json!(cargo_removed));
    if let Some(ref err) = cargo_error {
        json_field("cargo_error", json!(err));
    }
    json_field("runtime_dir_removed", json!(runtime_dir_removed));
    json_field("runtime_dir", json!(&runtime_dir_str));
    json_field("cache_dir_removed", json!(cache_dir_removed));
    json_field("cache_dir", json!(&cache_dir_str));
    json_field("dry_run", json!(dry_run));

    if !npm_removed && !cargo_removed && npm_error.is_none() && cargo_error.is_none() {
        cli_println!();
        cli_println!("ℹ  browser4-cli was not found in npm or cargo global installs.");

        if dry_run {
            // Locate the running binary and report what would happen.
            if let Ok(exe_path) = std::env::current_exe() {
                cli_println!("   Running binary: {}", exe_path.display());
                let inside_repo = daemon::find_browser4_root()
                    .map(|root| exe_path.starts_with(&root))
                    .unwrap_or(false);
                if inside_repo {
                    cli_println!(
                        "   This is a development build inside a Browser4 repo — remove it from"
                    );
                    cli_println!("   your PATH or delete it manually after leaving the repo.");
                } else {
                    cli_println!("   🔍 Would attempt to remove the binary.");
                }
            } else {
                cli_println!("   Could not determine binary location. Remove it manually.");
            }
        } else {
            // Locate the running binary and attempt self-removal.
            if let Ok(exe_path) = std::env::current_exe() {
                cli_println!("   Running binary: {}", exe_path.display());

                // Check whether the binary lives inside a Browser4 repository
                // checkout (i.e. a local dev build that should not be auto-deleted).
                let inside_repo = daemon::find_browser4_root()
                    .map(|root| exe_path.starts_with(&root))
                    .unwrap_or(false);

                if inside_repo {
                    cli_println!(
                        "   This is a development build inside a Browser4 repo — remove it from"
                    );
                    cli_println!("   your PATH or delete it manually after leaving the repo.");
                } else {
                    cli_println!("   Attempting to remove the binary...");
                    let removed = attempt_self_removal(&exe_path);
                    json_field("binary_removed", json!(removed));
                    json_field("binary_path", json!(exe_path.display().to_string()));
                }
            } else {
                cli_println!("   Could not determine binary location. Remove it manually.");
            }
        }
    }

    cli_println!();
    if dry_run {
        cli_println!("🔍 dry run complete (no changes made).");
    } else {
        cli_println!("✅ uninstall complete.");
    }
    Ok(())
}

/// Format the output lines for `handle_upgrade`.  Extracted as a pure function
/// so the branching logic can be unit-tested without network I/O.
fn format_upgrade_output(runtime: &InstalledBrowser4Runtime, force: bool) -> Vec<String> {
    if runtime.reused_existing && !force {
        return vec![format!(
            "Browser4 is already at the latest version ({}).",
            runtime.tag
        )];
    }
    vec![
        format!("Browser4 upgraded successfully to {}.", runtime.tag),
        format!("- Install dir: {}", runtime.install_dir.display()),
        format!("- Lib dir: {}", runtime.lib_dir.display()),
        format!("- Java: {}", runtime.java_path.display()),
    ]
}

/// Names to try when invoking npm.
///
/// On Windows npm ships as `npm.cmd` (a batch shim) — plain `npm` is not
/// resolvable because CreateProcess does not consult PATHEXT.
fn npm_command_names() -> &'static [&'static str] {
    #[cfg(windows)]
    {
        &["npm.cmd", "npm"]
    }
    #[cfg(not(windows))]
    {
        &["npm"]
    }
}

/// Locate a working npm invocation, or `None` when npm is not on PATH.
fn resolve_npm() -> Option<&'static str> {
    npm_command_names().iter().copied().find(|name| {
        std::process::Command::new(name)
            .arg("--version")
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false)
    })
}

/// Whether the CLI self-upgrade step should be skipped entirely.
///
/// The e2e harness sets this so install/upgrade scenarios never touch npm or
/// download/execute the real install scripts from the public CDN.
fn self_upgrade_skip_requested() -> bool {
    std::env::var(CLI_SELF_UPGRADE_SKIP_ENV)
        .map(|v| v == "1" || v.eq_ignore_ascii_case("true"))
        .unwrap_or(false)
}

/// URL of the platform-specific install script used to self-upgrade the CLI.
// Only called from the Windows upgrade path today, but its unit test checks
// both platform variants, so keep it compiled everywhere.
#[cfg_attr(not(target_os = "windows"), allow(dead_code))]
fn cli_install_script_url() -> &'static str {
    #[cfg(windows)]
    {
        "https://browser4.oss-cn-beijing.aliyuncs.com/scripts/install-browser4-cli.ps1"
    }
    #[cfg(not(windows))]
    {
        "https://browser4.oss-cn-beijing.aliyuncs.com/scripts/install-browser4-cli.sh"
    }
}

/// Download the CLI install script to `target` using the CLI's own HTTP stack.
///
/// This avoids depending on PowerShell's `irm` (or curl) for the script fetch:
/// `irm` can be blocked by execution policy, antivirus, or a broken PATH even
/// when plain HTTPS from the CLI works fine.
#[cfg(target_os = "windows")]
fn download_cli_install_script(url: &str, target: &Path) -> Result<(), String> {
    let client = reqwest::blocking::Client::builder()
        .timeout(std::time::Duration::from_secs(60))
        .build()
        .map_err(|e| format!("Cannot build HTTP client: {e}"))?;
    let response = client
        .get(url)
        .send()
        .map_err(|e| format!("Download failed: {e}"))?;
    if !response.status().is_success() {
        return Err(format!("Download failed with status: {}", response.status()));
    }
    let bytes = response.bytes().map_err(|e| format!("Read failed: {e}"))?;
    if bytes.is_empty() {
        return Err("Downloaded install script is empty.".to_string());
    }
    std::fs::write(target, &bytes)
        .map_err(|e| format!("Cannot write {}: {e}", target.display()))?;
    Ok(())
}

/// Candidate PowerShell executables, most preferred first.
///
/// The absolute Windows PowerShell path comes first: it is immune to a PATH
/// where a non-executable `powershell.exe` shadow (e.g. a leftover shim or
/// decoy file) makes CreateProcess fail with "Access is denied (os error 5)".
#[cfg(windows)]
fn windows_powershell_candidates() -> Vec<String> {
    let system_root = std::env::var("SystemRoot")
        .or_else(|_| std::env::var("WINDIR"))
        .unwrap_or_else(|_| r"C:\Windows".to_string());
    let system_root = system_root.trim_end_matches('\\');
    vec![
        format!(r"{system_root}\System32\WindowsPowerShell\v1.0\powershell.exe"),
        "powershell.exe".to_string(),
        "pwsh.exe".to_string(),
    ]
}

/// Arguments for running the downloaded install script under PowerShell.
///
/// `-SkipBackend` stops the script from re-running `browser4-cli install` —
/// the runtime upgrade is handled by the caller right after this step.
#[cfg(windows)]
fn windows_install_script_args(script_path: &Path, tag: Option<&str>) -> Vec<String> {
    let mut args = vec![
        "-NoProfile".to_string(),
        "-NonInteractive".to_string(),
        "-ExecutionPolicy".to_string(),
        "Bypass".to_string(),
        "-File".to_string(),
        script_path.display().to_string(),
        "-SkipBackend".to_string(),
        "-Silent".to_string(),
    ];
    if let Some(tag) = tag {
        args.push("-Version".to_string());
        args.push(tag.to_string());
    }
    args
}

/// Actionable guidance for a failed install-script spawn, keyed on the error
/// kind (never the localized message text).
fn upgrade_spawn_advice(err: &std::io::Error) -> &'static str {
    match err.kind() {
        std::io::ErrorKind::NotFound => {
            "PowerShell was not found on this system. Install Node.js and run \
             'npm install -g browser4-cli', or run the install script manually \
             from https://browser4.io."
        }
        std::io::ErrorKind::PermissionDenied => {
            "Windows refused to start the shell (access denied). This is usually \
             caused by antivirus or AppLocker blocking PowerShell, or by a \
             non-executable 'powershell.exe' earlier in PATH. Run the install \
             script manually from an elevated PowerShell: irm \
             https://browser4.oss-cn-beijing.aliyuncs.com/scripts/install-browser4-cli.ps1 | iex"
        }
        _ => {
            "Run 'npm install -g browser4-cli' or the install script manually \
             from https://browser4.io."
        }
    }
}

/// Upgrade the `browser4-cli` binary itself.
///
/// Strategy:
/// 1. If `npm` is on PATH, use `npm install -g browser4-cli` (fast, atomic, handles running binary).
/// 2. Otherwise, use the platform-specific install script from the README.
///    - Windows: download the script with the CLI's own HTTP stack (immune to
///      a blocked `irm` or PowerShell), then run it via PowerShell resolved by
///      absolute path first, with `powershell` / `pwsh` on PATH as fallbacks.
///    - Linux / macOS: `curl … | bash`.
///
/// On Unix the running binary can be safely replaced in-place (the old inode
/// stays alive until this process exits).  On Windows the install script may
/// fail with a "file locked" error when the binary is running; the error is
/// surfaced and the runtime upgrade proceeds regardless.
///
/// All failures are non-fatal — a warning is printed and the runtime upgrade continues.
async fn upgrade_cli_binary(tag: Option<&str>) {
    // Test / e2e isolation: never touch npm or execute the real install scripts.
    if self_upgrade_skip_requested() {
        eprintln!(
            "Skipping browser4-cli self-upgrade ({} is set).",
            CLI_SELF_UPGRADE_SKIP_ENV
        );
        return;
    }

    // ── 1. npm (preferred) ──
    if let Some(npm) = resolve_npm() {
        eprintln!("Upgrading browser4-cli binary via npm...");

        let package_spec = match tag {
            Some(t) => {
                // Strip a leading 'v' so that `--tag v4.11.0` maps to `browser4-cli@4.11.0`.
                let version = t.strip_prefix('v').unwrap_or(t);
                format!("browser4-cli@{}", version)
            }
            None => "browser4-cli".to_string(),
        };

        let result = tokio::task::spawn_blocking(move || {
            std::process::Command::new(npm)
                .args(["install", "-g", &package_spec])
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped())
                .output()
        })
        .await;

        match result {
            Ok(Ok(output)) if output.status.success() => {
                cli_println!("✅ browser4-cli upgraded via npm.");
                return;
            }
            Ok(Ok(output)) => {
                let stderr = String::from_utf8_lossy(&output.stderr);
                eprintln!("⚠  npm upgrade failed: {}", stderr.trim());
                eprintln!("   Falling back to install script...");
            }
            Ok(Err(e)) => {
                eprintln!("⚠  npm command failed: {e}");
                eprintln!("   Falling back to install script...");
            }
            Err(e) => {
                eprintln!("⚠  npm spawn failed: {e}");
                eprintln!("   Falling back to install script...");
            }
        }
    }

    // ── 2. Platform-specific install script (fallback) ──
    eprintln!("Upgrading browser4-cli via install script...");

    #[cfg(windows)]
    {
        // a) Fetch the script with our own HTTP stack — works even when
        //    PowerShell / `irm` is blocked.
        let script_url = cli_install_script_url().to_string();
        let tmp_dir =
            std::env::temp_dir().join(format!("browser4-cli-upgrade-{}", std::process::id()));
        let script_path = tmp_dir.join("install-browser4-cli.ps1");

        let download_result = {
            let script_path = script_path.clone();
            tokio::task::spawn_blocking(move || -> Result<(), String> {
                std::fs::create_dir_all(&tmp_dir).map_err(|e| {
                    format!("Cannot create temp directory {}: {e}", tmp_dir.display())
                })?;
                download_cli_install_script(&script_url, &script_path)
            })
            .await
        };

        match download_result {
            Ok(Ok(())) => {}
            Ok(Err(e)) => {
                eprintln!("⚠  Could not download the install script: {e}");
                eprintln!("   Run it manually from an elevated PowerShell:");
                eprintln!("     irm https://browser4.oss-cn-beijing.aliyuncs.com/scripts/install-browser4-cli.ps1 | iex");
                eprintln!("   The runtime upgrade will still proceed.");
                return;
            }
            Err(e) => {
                eprintln!("⚠  Install-script download task failed: {e}");
                eprintln!("   The runtime upgrade will still proceed.");
                return;
            }
        }

        // b) Run the script.  Prefer the absolute Windows PowerShell path so a
        //    poisoned PATH cannot break the spawn; fall back to `powershell`
        //    / `pwsh` on PATH (PowerShell Core).
        let mut last_spawn_error: Option<std::io::Error> = None;
        for shell in windows_powershell_candidates() {
            let args = windows_install_script_args(&script_path, tag);
            let result = tokio::task::spawn_blocking(move || {
                std::process::Command::new(&shell)
                    .args(&args)
                    .stdout(std::process::Stdio::piped())
                    .stderr(std::process::Stdio::piped())
                    .output()
            })
            .await;

            match result {
                Ok(Ok(output)) if output.status.success() => {
                    cli_println!("✅ browser4-cli upgraded via install script.");
                    return;
                }
                Ok(Ok(output)) => {
                    let stderr = String::from_utf8_lossy(&output.stderr);
                    let combined = if stderr.is_empty() {
                        String::from_utf8_lossy(&output.stdout).trim().to_string()
                    } else {
                        stderr.trim().to_string()
                    };
                    eprintln!("⚠  Install script failed: {combined}");
                    if combined.to_lowercase().contains("access")
                        || combined.to_lowercase().contains("denied")
                        || combined.to_lowercase().contains("locked")
                    {
                        eprintln!("   The binary may be locked because browser4-cli is running.");
                        eprintln!("   Close all browser4-cli processes and run 'browser4-cli upgrade' again,");
                        eprintln!("   or install the latest version manually from https://browser4.io.");
                    }
                    eprintln!("   The runtime upgrade will still proceed.");
                    return;
                }
                Ok(Err(e)) => {
                    // Spawn failed for this shell — remember it and try the
                    // next candidate before giving up.
                    last_spawn_error = Some(e);
                }
                Err(e) => {
                    eprintln!("⚠  Failed to run install script (task error): {e}");
                    eprintln!("   The runtime upgrade will still proceed.");
                    return;
                }
            }
        }

        match last_spawn_error {
            Some(e) => {
                eprintln!("⚠  Failed to run install script: {e}");
                eprintln!("   {}", upgrade_spawn_advice(&e));
            }
            None => {
                eprintln!("⚠  Install script did not run (no usable PowerShell found).");
            }
        }
        eprintln!("   The runtime upgrade will still proceed.");
    }
    #[cfg(not(windows))]
    {
        let result = tokio::task::spawn_blocking(|| {
            std::process::Command::new("sh")
                .args([
                    "-c",
                    "curl -fsSL https://browser4.oss-cn-beijing.aliyuncs.com/scripts/install-browser4-cli.sh | bash",
                ])
                .stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped())
                .output()
        })
        .await;

        match result {
            Ok(Ok(output)) if output.status.success() => {
                cli_println!("✅ browser4-cli upgraded via install script.");
            }
            Ok(Ok(output)) => {
                let stderr = String::from_utf8_lossy(&output.stderr);
                let combined = if stderr.is_empty() {
                    String::from_utf8_lossy(&output.stdout).trim().to_string()
                } else {
                    stderr.trim().to_string()
                };
                eprintln!("⚠  Install script failed: {combined}");
                eprintln!("   The runtime upgrade will still proceed.");
            }
            Ok(Err(e)) => {
                // Missing curl / bash / sh on a minimal system
                let msg = format!("{e}");
                if msg.to_lowercase().contains("not found") {
                    eprintln!("⚠  Cannot run install script: curl and bash are required.");
                    eprintln!("   Install npm first, or run the install script manually.");
                } else {
                    eprintln!("⚠  Failed to run install script: {e}");
                    eprintln!("   {}", upgrade_spawn_advice(&e));
                }
                eprintln!("   The runtime upgrade will still proceed.");
            }
            Err(e) => {
                eprintln!("⚠  Failed to spawn shell: {e}");
                eprintln!("   The runtime upgrade will still proceed.");
            }
        }
    }
}

async fn handle_upgrade(tool_params: &Value) -> Result<(), String> {
    let tag = tool_params.get("tag").and_then(|value| value.as_str());
    let force = tool_params
        .get("force")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);

    // ── 1. Upgrade the CLI binary itself ──
    // This is non-fatal: if it fails we still attempt the runtime upgrade.
    upgrade_cli_binary(tag).await;

    // ── 2. Upgrade the runtime ──

    // Snapshot the currently-installed tag *before* the upgrade so we can
    // detect the "same version re-downloaded via latest" case.
    let prev_tag = read_current_tag();

    eprintln!("Upgrading Browser4 runtime...");
    let mut runtime = install_browser4_runtime(tag, force).await?;

    // Pre-train the JVM AOT cache in the background right after the runtime is
    // committed: the upgraded jar set changes the cache key, so the old cache
    // is invalid and a fresh training run should start as early as possible.
    // Non-blocking and non-fatal; a failed training run self-heals on the next
    // launch (its marker is reclaimed after a short grace period).
    ensure_aot_cache_trained(&runtime);

    // When no explicit tag was requested (`upgrade` → "latest"), the early-exit
    // fast-path in `install_browser4_runtime` does not fire, so `reused_existing`
    // is always `false` even if the resolved tag matches what is already installed.
    // Detect this case here and flip the flag so the output message is correct.
    if !force && !runtime.reused_existing && tag.is_none() {
        if prev_tag.as_deref() == Some(&runtime.tag) {
            runtime.reused_existing = true;
        }
    }

    let output = format_upgrade_output(&runtime, force);
    let was_upgraded = !runtime.reused_existing || force;
    for line in &output {
        cli_println!("{}", line);
    }
    if was_upgraded {
        let bin = cli_binary_name();
        eprintln!(
            "NOTE: Restart the server to use the new version: {bin} stop && {bin} open <url>"
        );
    }
    json_field("tag", json!(&runtime.tag));
    json_field("asset_name", json!(&runtime.asset_name));
    json_field(
        "install_dir",
        json!(runtime.install_dir.display().to_string()),
    );
    json_field("reused_existing", json!(runtime.reused_existing));
    json_field("source_url", json!(&runtime.download_url));

    // Unpack bundled skill files into the (possibly new) versioned install
    // directory.  `upgrade` may have just replaced the CLI binary with one
    // that embeds newer skills, so always re-sync — write-if-changed makes
    // the no-op case cheap.  Failure is non-fatal.
    let skills_dir = runtime.install_dir.join("skills");
    match sync_skills_for_runtime(&runtime) {
        Ok(outcome) => {
            eprintln!("{}", format_skills_sync_message(outcome, &skills_dir));
            json_field("skills_dir", json!(skills_dir.display().to_string()));
            json_field("skills_files_unpacked", json!(outcome.files_written));
            json_field("skills_files_total", json!(outcome.files_total));
        }
        Err(e) => {
            eprintln!("⚠  Failed to unpack skill files: {e}");
        }
    }

    // Keep the AI-agent skills directory (`~/.agents/skills`) in sync too:
    // only the agent-synced skills (just `browser4-cli` by default).
    match sync_skills_to_agents_dir() {
        Ok(Some((outcome, agents_dir))) => {
            eprintln!("{}", format_agents_skills_sync_message(outcome, &agents_dir));
            json_field("agents_skills_dir", json!(agents_dir.display().to_string()));
            json_field("agents_skills_files_unpacked", json!(outcome.files_written));
        }
        Ok(None) => {}
        Err(e) => {
            eprintln!("⚠  Failed to install skill files for AI agents: {e}");
        }
    }

    Ok(())
}

// ---------------------------------------------------------------------------
// Auto-update (BROWSER4_AUTO_UPGRADE=off|notify|runtime|full)
// ---------------------------------------------------------------------------

/// Commands that must never trigger an auto-update check: the hidden updater
/// itself, install/upgrade lifecycle commands (they manage versions
/// explicitly), and meta commands where a hint would be noise.
fn is_update_check_suppressed_command(command: &str) -> bool {
    matches!(
        command,
        "__update-agent"
            | "install"
            | "uninstall"
            | "upgrade"
            | "doctor"
            | "doctor-log"
            | "doctor-metrics"
            | "doctor-status"
            | "stop"
            | "status"
            | "kill-all"
            | "delete-data"
            | "help"
            | "version"
            | "batch"
            | "loop"
    )
}

/// One auto-update pass: resolve the latest tag (TTL-cached), print a dedup'd
/// hint, and — for the `runtime`/`full` policies — spawn a detached prefetch.
///
/// Fully best-effort: every failure mode (no network, no runtime installed,
/// remote backend, dev build) silently skips so the user's command is never
/// affected.
async fn maybe_auto_update(command: &str, base_url: &str, global: &GlobalFlags) {
    use update_check::*;

    let policy = AutoUpgradePolicy::from_env();
    if policy == AutoUpgradePolicy::Off || is_update_check_suppressed_command(command) {
        return;
    }
    // Dev builds track the source tree, not packaged releases.
    if VERSION.contains("-SNAPSHOT") || daemon::is_dev_mode() {
        return;
    }
    // Only for the local backend — a remote server is someone else's deployment.
    if !(base_url.contains("localhost") || base_url.contains("127.0.0.1")) {
        return;
    }
    // No installed runtime yet → the first-run install path handles versioning.
    let Some(current_tag) = read_current_tag() else {
        return;
    };

    let mut state = load_state();
    let now = Utc::now().timestamp();

    // Resolve the latest tag at most once per TTL.  A failed attempt counts
    // too, so an offline machine does not pay the resolve timeout on every
    // command; the stale cache (if any) keeps being served meanwhile.
    let latest_tag = if should_attempt_check(&state, now) {
        let resolved = tokio::time::timeout(
            std::time::Duration::from_secs(RESOLVE_TIMEOUT_SECS),
            daemon::resolve_latest_tag(&daemon::load_mirrors()),
        )
        .await
        .ok()
        .flatten()
        .map(|(tag, _info)| tag);
        state.last_check_at = Some(now);
        if let Some(ref tag) = resolved {
            state.latest_tag = Some(tag.clone());
        }
        save_state(&state);
        resolved.or_else(|| state.latest_tag.clone())
    } else {
        state.latest_tag.clone()
    };
    let Some(latest_tag) = latest_tag else {
        return;
    };

    let latest_on_disk =
        daemon::install_dir_contains_runtime(&daemon::versioned_install_dir(&latest_tag));
    let decision = decide(policy, &current_tag, &latest_tag, &state, now, latest_on_disk);

    if let Some(ref tag) = decision.notify {
        if !global.quiet {
            eprintln!(
                "💡 A new Browser4 release is available: {tag} (current: {current_tag}). \
                 Run '{bin} upgrade' to update.",
                tag = tag,
                current_tag = current_tag,
                bin = cli_binary_name(),
            );
        }
        json_field("update_available", json!(tag));
        // Only mark the tag as seen when the user could actually observe it —
        // under `--quiet` an unprinted hint would otherwise be suppressed
        // forever, since the dedup check keys off this field.
        if !global.quiet || json_active() {
            state.last_notified_tag = Some(tag.clone());
            save_state(&state);
        }
    }

    if let Some(ref plan) = decision.prefetch {
        // Record the attempt only once the child actually started, so a spawn
        // failure (deleted/moved executable) neither disappears silently nor
        // burns the one-hour retry window.
        if spawn_update_agent(plan) {
            state.last_prefetch_attempt = Some(PrefetchAttempt {
                tag: plan.tag.clone(),
                at: now,
            });
            save_state(&state);
        } else if !global.quiet {
            eprintln!(
                "⚠  Could not start the background updater for {}; \
                 run '{bin} upgrade' to update manually.",
                plan.tag,
                bin = cli_binary_name(),
            );
        }
    }
}

/// Launch the detached background updater process.  Fire-and-forget: stdio is
/// nulled and the child is never waited on, so it outlives this invocation.
///
/// Returns whether the child was started; the caller only records the
/// prefetch attempt (and its retry window) on success.
fn spawn_update_agent(plan: &update_check::PrefetchPlan) -> bool {
    let Ok(exe) = std::env::current_exe() else {
        return false;
    };
    let mut cmd = std::process::Command::new(exe);
    cmd.arg("__update-agent").arg("--tag").arg(&plan.tag);
    if plan.self_upgrade {
        cmd.arg("--self-upgrade");
    }
    cmd.stdin(std::process::Stdio::null())
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::null());
    #[cfg(windows)]
    {
        use std::os::windows::process::CommandExt;
        const CREATE_NO_WINDOW: u32 = 0x08000000;
        const DETACHED_PROCESS: u32 = 0x00000008;
        cmd.creation_flags(CREATE_NO_WINDOW | DETACHED_PROCESS);
    }
    cmd.spawn().is_ok()
}

/// Entry point of the hidden `__update-agent` command.
async fn handle_update_agent(global: &GlobalFlags) -> Result<(), CliError> {
    let mut tag: Option<String> = None;
    let mut self_upgrade = false;
    let args: Vec<&str> = global.args.iter().skip(1).map(String::as_str).collect();
    let mut i = 0;
    while i < args.len() {
        match args[i] {
            "--tag" => {
                tag = args.get(i + 1).map(|s| (*s).to_string());
                i += 2;
            }
            "--self-upgrade" => {
                self_upgrade = true;
                i += 1;
            }
            _ => i += 1,
        }
    }
    let Some(tag) = tag else {
        return Err(CliError(
            ExitCode::Usage,
            "__update-agent requires --tag <tag>".to_string(),
        ));
    };
    run_update_agent(&tag, self_upgrade).await;
    Ok(())
}

/// The background updater body: mirror `handle_upgrade`'s runtime steps for
/// the target tag, then record the outcome in the state file.  Success parks
/// the tag in `pending_tag` — activation happens on the next backend launch
/// via `update_check::commit_pending_tag_if_ready`.
async fn run_update_agent(tag: &str, self_upgrade: bool) {
    let result: Result<(), String> = async {
        // `full` policy: self-upgrade the CLI binary first (best-effort).
        if self_upgrade {
            upgrade_cli_binary(Some(tag)).await;
        }
        let runtime = install_browser4_runtime(Some(tag), false).await?;
        ensure_aot_cache_trained(&runtime);
        sync_skills_for_runtime(&runtime).map_err(|e| e.to_string())?;
        Ok(())
    }
    .await;

    let mut state = update_check::load_state();
    let now = Utc::now().timestamp();
    match result {
        Ok(()) => {
            state.pending_tag = Some(tag.to_string());
            state.failures.remove(tag);
        }
        Err(err) => {
            update_check::record_prefetch_failure(&mut state, tag, now);
            eprintln!("Auto-update prefetch of {tag} failed: {err}");
        }
    }
    update_check::save_state(&state);
}

/// Stop the Browser4 backend.
///
/// In development mode only the backends of *this* checkout are stopped: every
/// workspace runs its own port from 8282 upward (`daemon::DEV_SERVER_PORT_START`),
/// and killing a neighbouring workspace's server would defeat the point of
/// running several checkouts side by side.  The workspace's managed-process
/// registry — not the currently resolved URL — decides what "this workspace"
/// means, so a one-off `--server` probe cannot make `stop` miss the local dev
/// backend.  `kill-all` remains the global hammer.  Production installs keep
/// the original stop-everything behaviour: there is only one backend to stop.
async fn handle_stop(base_url: &str) -> Result<(), String> {
    let workspace_scoped = daemon::is_dev_mode();
    // Only a loopback URL can name a local backend; a remote `--server` must
    // not add its port to the local kill sweep.
    let local_port = daemon::local_backend_port(base_url);

    if workspace_scoped {
        eprintln!("🛑 Stopping the Browser4 server(s) of this workspace ...");
    } else {
        eprintln!("🛑 Stopping Browser4 server ...");
    }
    eprintln!();

    let stop_result = if workspace_scoped {
        stop_workspace_servers_forcibly(local_port)
    } else {
        stop_browser4_server_forcibly()
    };
    let shutdown_result = &stop_result.shutdown;
    let workspace_browser_kill = &stop_result.browser_kill;
    finalize_global_cleanup("Stopped", shutdown_result, true);

    // Reclaim browsers whose backend was killed without closing them. The workspace
    // stop above deliberately leaves browsers alone (another workspace may own one),
    // but an orphan under the shared `browser4-pereg` temp root belongs to no live
    // backend: left behind, the launcher reuses it by user-data-dir, and a stale
    // browser newer than the driver poisons every later session (2026-10-28: 169
    // orphaned Chrome processes, every navigation failing with `createDevTools`).
    let orphan_kill = kill_orphaned_browser_processes();
    if !orphan_kill.killed_pids.is_empty() {
        let pids: Vec<String> = orphan_kill
            .killed_pids
            .iter()
            .map(|p| p.to_string())
            .collect();
        cli_println!(
            "Reclaimed {} orphaned Browser4 browser process(es): {}",
            orphan_kill.killed_pids.len(),
            pids.join(", ")
        );
    }
    if !orphan_kill.remaining_pids.is_empty() {
        cli_println!(
            "warning: {} orphaned Browser4 browser process(es) survived the sweep",
            orphan_kill.remaining_pids.len()
        );
    }

    let server_was_running = !(shutdown_result.stopped_pids.is_empty()
        && shutdown_result.missing_pids.is_empty()
        && shutdown_result.forced_pids.is_empty()
        && shutdown_result.fallback_killed_server_pids.is_empty());
    json_field("server_was_running", json!(server_was_running));
    json_field("server_pids", json!(shutdown_result.stopped_pids));
    json_field("server_port", json!(local_port));
    // Both sweeps report into one field: the browsers this workspace's backends
    // launched, plus any orphan left under the shared temp root.
    let mut browser_killed = orphan_kill.killed_pids.clone();
    browser_killed.extend(workspace_browser_kill.killed_pids.iter().copied());
    browser_killed.sort_unstable();
    browser_killed.dedup();
    let mut browser_remaining = orphan_kill.remaining_pids.clone();
    browser_remaining.extend(workspace_browser_kill.remaining_pids.iter().copied());
    browser_remaining.sort_unstable();
    browser_remaining.dedup();
    json_field("browser_pids_killed", json!(browser_killed));
    json_field("browser_pids_remaining", json!(browser_remaining));

    eprintln!();

    // A force-stopped backend cannot close the browsers it launched, so this
    // path does it — otherwise a stopped workspace strands a headless
    // `PULSAR_CHROME` root whose parent pid no longer exists, and no later
    // command can attribute it back to this checkout.
    if !workspace_browser_kill.killed_pids.is_empty() {
        let pids: Vec<String> = workspace_browser_kill
            .killed_pids
            .iter()
            .map(u32::to_string)
            .collect();
        cli_println!(
            "Closed {} browser process(es) launched by this workspace's backend(s): {}",
            workspace_browser_kill.killed_pids.len(),
            pids.join(", ")
        );
    }
    if !workspace_browser_kill.remaining_pids.is_empty() {
        let pids: Vec<String> = workspace_browser_kill
            .remaining_pids
            .iter()
            .map(u32::to_string)
            .collect();
        eprintln!(
            "⚠  {} browser process(es) of this workspace survived the stop: {} — \
             retry `browser4-cli stop` or use `browser4-cli kill-all`.",
            workspace_browser_kill.remaining_pids.len(),
            pids.join(", ")
        );
    }

    if !shutdown_result.fallback_killed_server_pids.is_empty() {
        let pids: Vec<String> = shutdown_result
            .fallback_killed_server_pids
            .iter()
            .map(|p| p.to_string())
            .collect();
        cli_println!(
            "Fallback-killed Browser4 backend process(es): {}",
            pids.join(", ")
        );
    }

    if shutdown_result.stopped_pids.is_empty()
        && shutdown_result.missing_pids.is_empty()
        && shutdown_result.forced_pids.is_empty()
        && shutdown_result.fallback_killed_server_pids.is_empty()
    {
        if workspace_scoped {
            cli_println!("No Browser4 server was running for this workspace.");
        } else {
            cli_println!("No Browser4 server was running.");
        }
    } else {
        cli_println!("Browser4 server stopped.");
    }

    if workspace_scoped {
        cli_println!(
            "Other workspaces keep their own backends; use 'browser4-cli kill-all' to stop every workspace."
        );
    }
    Ok(())
}

async fn handle_status(
    client: &Client,
    base_url: &str,
    session_name: Option<&str>,
    server_override: Option<&str>,
) -> Result<(), String> {
    cli_println!("Browser4 Status");
    cli_println!("===============");
    cli_println!("CLI version: {}", VERSION);
    cli_println!("Server URL: {}", base_url);

    json_field("cli_version", json!(VERSION));
    json_field("server_url", json!(base_url));

    // Where the URL came from, and which recorded value (if any) the resolver
    // rejected as stale.  Without this a server URL that disagrees with the
    // documentation (e.g. a corrupt port recorded by an older session) can only
    // be diagnosed by reading the resolver's source.
    let resolved = daemon::resolve_base_url_with_origin(server_override, session_name);
    cli_println!("  resolved from: {}", resolved.source.label());
    json_field("server_url_source", json!(resolved.source.label()));
    if let Some(rejected) = resolved.rejected_recorded.as_deref() {
        cli_println!(
            "  ignored recorded URL: {} (not usable — re-allocated; \
             remove ~/.browser4/workspaces/<checkout>/cli-state.json to reset)",
            rejected
        );
        json_field("server_url_recorded_ignored", json!(rejected));
    }

    // Show installed runtime bundle info (informational only).
    let dev_mode = daemon::is_dev_mode();
    if let Some(metadata) = daemon::read_installed_browser4_runtime_metadata() {
        if dev_mode {
            // In a checkout the installed bundle is NOT what runs — the daemon
            // launches the locally built runtime bundle — so label it instead of
            // printing two bundle versions that look like a contradiction.
            cli_println!(
                "Installed bundle: {} (at {}) — used only outside a repository checkout",
                metadata.tag,
                metadata.installed_at
            );
        } else {
            cli_println!(
                "Installed bundle: {} (at {})",
                metadata.tag,
                metadata.installed_at
            );
        }
        json_field("installed_version", json!(&metadata.tag));
        json_field("installed_at", json!(&metadata.installed_at));
    } else {
        cli_println!("Installed bundle: not installed (run 'browser4-cli install')");
        json_field("installed_version", json!(null));
        json_field("installed_at", json!(null));
    }

    // Development mode: name the per-checkout backend state root (browser
    // profiles, data, logs) so it is obvious which workspace this CLI — and
    // therefore the browser it drives — belongs to.
    if let Some(app_data) = daemon::workspace_app_data_path() {
        cli_println!("Workspace app data: {}", app_data.display());
        json_field(
            "workspace_app_data",
            json!(app_data.display().to_string()),
        );
    }

    // Dev-mode provenance: which locally assembled bundle the backend is (or
    // would be) started from, and whether it still matches the checkout.  The
    // launcher refuses to serve a stale bundle, so this is how a test run's
    // provenance can be audited after the fact.
    if let Some(bundle) = daemon::local_bundle_provenance() {
        cli_println!("");
        cli_println!("Local runtime bundle (dev mode):");
        for (label, value) in bundle.report_rows() {
            cli_println!("  {}: {}", label, value);
        }
        json_field("local_bundle", bundle.to_json());
    }

    // Check server health and, if reachable, get the running backend's actual
    // version.  Comparing against the live backend prevents false "version
    // mismatch" warnings when the installed bundle is a different version than
    // the locally-built dev backend.
    let health_url = format!("{base_url}/actuator/health");
    let health;
    let mut server_version: Option<String> = None;
    match client.get(&health_url).send().await {
        Ok(response) => {
            if response.status().is_success() {
                match response.text().await {
                    Ok(body) if body.contains("\"status\":\"UP\"") => {
                        cli_println!("Server health: UP");
                        health = "UP";
                    }
                    Ok(body) => {
                        cli_println!("Server health: NOT READY ({})", body);
                        health = "NOT_READY";
                    }
                    Err(e) => {
                        cli_println!("Server health: ERROR ({})", e);
                        health = "ERROR";
                    }
                }

                // Query the running backend for its actual version so we compare
                // CLI version against the live server, not a stale installed bundle.
                if health == "UP" {
                    let build_url = format!("{base_url}/api/system/build");
                    if let Ok(build_resp) = client.get(&build_url).send().await {
                        if let Ok(body) = build_resp.text().await {
                            if let Ok(parsed) = serde_json::from_str::<Value>(&body) {
                                server_version = parsed
                                    .get("version")
                                    .and_then(|v| v.as_str())
                                    .map(|s| s.to_string());
                                if let Some(ref ver) = server_version {
                                    cli_println!("Server version: {}", ver);
                                    json_field("server_version", json!(ver));
                                }
                            }
                        }
                    }
                }
            } else {
                cli_println!("Server health: DOWN (HTTP {})", response.status());
                health = "DOWN";
            }
        }
        Err(_) => {
            cli_println!("Server health: UNREACHABLE (no response from {})", base_url);
            health = "UNREACHABLE";
        }
    }
    json_field("health", json!(health));

    // Point the user at the web status panel — available whenever the backend
    // is reachable, regardless of health.
    cli_println!("Status panel: {}/status", base_url);
    json_field("status_panel", json!(format!("{base_url}/status")));

    // Current-session summary — which browser this CLI session talks to,
    // including the ACTUAL connected browser for attached sessions (the
    // "attached to the wrong browser" detector).
    let state = read_state(None, session_name);
    if let Some(sid) = state.session_id.as_deref() {
        let name = session_name.unwrap_or("(default)").to_string();
        let records = if health == "UP" {
            call_tool(client, base_url, "list_sessions", json!({}))
                .await
                .ok()
                .map(|r| parse_backend_session_records(&r))
        } else {
            None
        };
        let record = records
            .as_ref()
            .and_then(|recs| recs.iter().find(|r| r.session_id == *sid));
        let status = list_session_status(records.as_deref(), sid);
        let next_open = list_session_next_open_action(records.as_deref(), sid);
        let conn = connection_label_full(&state, record);
        let display = session_display_label(&state, record);
        cli_println!("\nSession:");
        cli_println!("  Name: {}", name);
        cli_println!("  Session ID: {}", sid);
        cli_println!("  Status: {}", status);
        cli_println!("  Display: {}", display);
        cli_println!("  Connection: {}", conn);
        cli_println!("  Next open: {}", next_open);
        json_field(
            "session",
            json!({
                "name": name,
                "session_id": sid,
                "status": status,
                "display_mode": display.to_lowercase(),
                "connection": conn,
                "next_open": next_open,
            }),
        );
    }

    // Version comparison: use the live server version if available; fall back
    // to the installed bundle only when the server is unreachable.
    // Both sides are normalized so that "4.13.0" and "4.13.0-SNAPSHOT" (dev
    // mode) are treated as matching — the SNAPSHOT suffix only means the
    // backend was built from a mutable source tree, not that the versions
    // actually differ.
    if let Some(ref server_ver) = server_version {
        if normalize_version(server_ver) != normalize_version(VERSION) {
            cli_println!(
                "⚠  Version mismatch: CLI is {} but running backend is {}.",
                VERSION,
                server_ver
            );
            cli_println!(
                "   The CLI and backend were built from different versions of the source tree."
            );
            cli_println!(
                "   Rebuild both to match:  mvn install -pl browser4-rest -am && cargo build --manifest-path cli/browser4-cli/Cargo.toml"
            );
            json_field("version_mismatch", json!(true));
        } else {
            json_field("version_mismatch", json!(false));
        }
    } else if health == "UNREACHABLE" || health == "DOWN" {
        if dev_mode {
            // Comparing against the installed bundle would be misleading in a
            // checkout: the next command starts the locally built backend, not
            // that bundle, so there is no mismatch to report.
            cli_println!(
                "Backend is not running; in a repository checkout the next command starts the locally built \
                 backend (rebuild it with 'b4w -Rebuild <command>' after changing backend sources)."
            );
            json_field("version_mismatch", json!(false));
        } else if let Some(ref metadata) = daemon::read_installed_browser4_runtime_metadata() {
            let installed_ver = metadata.tag.trim().trim_start_matches('v');
            if normalize_version(installed_ver) != normalize_version(VERSION.trim()) {
                cli_println!(
                    "⚠  Version mismatch: CLI is {} but installed backend is {}.",
                    VERSION,
                    metadata.tag
                );
                cli_println!(
                    "   The backend is not running, so the installed bundle version is shown."
                );
                cli_println!("   Start the backend to compare against the live server version.");
                json_field("version_mismatch", json!(true));
            } else {
                json_field("version_mismatch", json!(false));
            }
        }
    }

    Ok(())
}

// ---------------------------------------------------------------------------
// Version comparison helpers (used by `handle_doctor` and `handle_status`)
// ---------------------------------------------------------------------------

/// Strip version display noise so two versions can be compared.
/// "v4.11.22" → "4.11.22", "4.12.0-rc.3-SNAPSHOT" → "4.12.0-rc.3"
fn normalize_version(v: &str) -> &str {
    v.trim_start_matches('v').trim_end_matches("-SNAPSHOT")
}

/// Extract the MAJOR.MINOR numeric pair from a version string.
/// Returns `None` when the string cannot be parsed as a dotted version.
/// "v4.11.22" → Some((4, 11))
/// "4.12.0-rc.3-SNAPSHOT" → Some((4, 12))
fn parse_major_minor(v: &str) -> Option<(u64, u64)> {
    let v = normalize_version(v);
    let mut parts = v.splitn(3, '.');
    let major: u64 = parts.next()?.parse().ok()?;
    // The minor segment may carry a pre-release suffix (e.g. "0-rc.3").
    let minor: u64 = parts.next()?.split('-').next()?.parse().ok()?;
    Some((major, minor))
}

/// Render the `-- LLM Status --` body from the backend's
/// `GET /api/doctor/llm-status` payload.
///
/// "✓ LLM is configured" alone cannot be trusted: any configured provider key
/// wins over the one the user just added when it sits higher in the built-in
/// priority list, so a leftover `DEEPSEEK_API_KEY` in the same properties file
/// keeps the routing on DeepSeek while `OPENAI_*` looks configured.  The lines
/// below therefore name the configured keys *with their source*, the key that won
/// the selection, and the model the backend will actually request.
///
/// Kept pure (no I/O) so it can be unit tested.
fn render_llm_status_lines(llm_info: &Value) -> Vec<String> {
    let mut lines = Vec::new();

    let configured = llm_info
        .get("configured")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if !configured {
        if let Some(message) = llm_info.get("message").and_then(|v| v.as_str()) {
            for line in message.lines() {
                lines.push(format!("  {}", line));
            }
        } else {
            lines.push("  LLM is not configured.".to_string());
            lines.push(
                "  It is highly recommended to set OPENROUTER_API_KEY or other LLM keys to enable LLM features."
                    .to_string(),
            );
        }
        // Even when nothing is usable, reporting the keys that *are* set — and the
        // ones that are set but empty — explains why.
        for line in llm_status_config_file_lines(llm_info) {
            lines.push(line);
        }
        lines.extend(llm_status_configured_key_lines(llm_info));
        if let Some(warning) = llm_info.get("warning").and_then(|v| v.as_str()) {
            if !warning.is_empty() {
                lines.push(format!("  ⚠  {}", warning));
            }
        }
        return lines;
    }

    lines.push("  ✓ LLM is configured.".to_string());

    lines.extend(llm_status_configured_key_lines(llm_info));

    for line in llm_status_config_file_lines(llm_info) {
        lines.push(line);
    }

    let selected_key = llm_info.get("selectedKey").and_then(|v| v.as_str());
    let selected_by = llm_info.get("selectedBy").and_then(|v| v.as_str());
    match (selected_key, selected_by) {
        (Some(key), _) => lines.push(format!(
            "  Selected key: {} (first in the priority list)",
            key
        )),
        (None, Some(by)) if by.starts_with("llm.provider=") => {
            lines.push(format!("  Selected by: {}", by))
        }
        _ => {}
    }

    if let Some(active) = llm_info.get("activeModel") {
        let model = active.get("model").and_then(|v| v.as_str());
        let client = active.get("client").and_then(|v| v.as_str());
        if let Some(model) = model {
            match client {
                Some(client) => lines.push(format!("  Active model: {} ({})", model, client)),
                None => lines.push(format!("  Active model: {}", model)),
            }
        }
    }

    if let Some(warning) = llm_info.get("warning").and_then(|v| v.as_str()) {
        if !warning.is_empty() {
            lines.push(format!("  ⚠  {}", warning));
        }
    }

    match llm_info.get("detectedVia").and_then(|v| v.as_str()) {
        Some("env") => lines.push("  Source: environment variables".to_string()),
        Some("system_property") => lines.push("  Source: JVM system properties".to_string()),
        // The exact file is already printed by the `Config file:` line above — naming a
        // fixed `~/.browser4/config/` here would be wrong whenever the data directory
        // lives elsewhere (`-Dapp.data.dir`, containers).
        Some("configuration") => lines.push("  Source: configuration file".to_string()),
        // Older backends reported `config_file` for *any* configured key, including
        // keys that came from the environment — only trust it when the payload does
        // not also report an environment variable.
        Some("config_file")
            if llm_info
                .get("foundEnvVars")
                .and_then(|v| v.as_array())
                .map_or(true, |vars| vars.is_empty()) =>
        {
            lines.push("  Source: configuration file".to_string())
        }
        _ => {}
    }

    lines
}

/// The user-editable LLM configuration file, with the writable path it actually
/// has on the backend host and whether that file exists yet.
///
/// Reporting the path — not just "configure an API key" — is the difference
/// between a user guessing a location and a user editing the right file; until
/// now the path had to be reconstructed from the SDK's internals.
fn llm_status_config_file_lines(llm_info: &Value) -> Vec<String> {
    let Some(config_file) = llm_info.get("configFile") else {
        return Vec::new();
    };
    let path = config_file
        .get("enabledPathDisplay")
        .or_else(|| config_file.get("enabledPath"))
        .and_then(|v| v.as_str());
    let Some(path) = path else {
        return Vec::new();
    };

    let exists = config_file
        .get("enabledExists")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    if exists {
        vec![format!("  Config file: {}", path)]
    } else {
        vec![format!(
            "  Config file: {} (not present — 'browser4-cli doctor --fix' writes a commented template)",
            path
        )]
    }
}

/// The configured-key lines, preferring the per-key `source` reported by the
/// backend and falling back to the plain env-var list of older backends.
fn llm_status_configured_key_lines(llm_info: &Value) -> Vec<String> {
    let mut lines = Vec::new();

    if let Some(keys) = llm_info.get("configuredKeys").and_then(|v| v.as_array()) {
        let rendered: Vec<String> = keys
            .iter()
            .filter_map(|entry| {
                let key = entry.get("key").and_then(|v| v.as_str())?;
                match entry.get("source").and_then(|v| v.as_str()) {
                    Some(source) => Some(format!("{} ({})", key, describe_llm_key_source(source))),
                    None => Some(key.to_string()),
                }
            })
            .collect();
        if !rendered.is_empty() {
            lines.push(format!("  Configured keys: {}", rendered.join(", ")));
        }
        return lines;
    }

    if let Some(vars) = llm_info.get("foundEnvVars").and_then(|v| v.as_array()) {
        let names: Vec<&str> = vars.iter().filter_map(|v| v.as_str()).collect();
        if !names.is_empty() {
            lines.push(format!("  Configured keys: {}", names.join(", ")));
        }
    }

    lines
}

fn describe_llm_key_source(source: &str) -> &str {
    match source {
        "env" => "environment variable",
        "system_property" => "JVM system property",
        "configuration" => "configuration file",
        other => other,
    }
}

async fn handle_doctor(
    client: &Client,
    base_url: &str,
    args: &HashMap<String, Value>,
) -> Result<(), String> {
    cli_println!("Browser4 Doctor");
    cli_println!("================");
    cli_println!("");

    let is_fix = args.get("fix").and_then(|v| v.as_bool()).unwrap_or(false);
    let verbose = args
        .get("verbose")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);

    // ---- Auto-clean Stale Daemon Files ----
    cli_println!("-- Stale File Cleanup --");
    let cleaned = clean_stale_daemon_files();
    if cleaned > 0 {
        cli_println!("  Cleaned {} stale daemon file(s)", cleaned);
    } else {
        cli_println!("  No stale daemon files found");
    }
    json_field("stale_files_cleaned", json!(cleaned));

    // ---- CLI Build Info (always available) ----
    cli_println!("");
    cli_println!("-- CLI Build Info --");
    cli_println!("  CLI version: {}", VERSION);
    json_field("cli_version", json!(VERSION));

    let runtime_metadata = daemon::read_installed_browser4_runtime_metadata();
    if let Some(ref metadata) = runtime_metadata {
        cli_println!("  Installed runtime: {}", metadata.tag);
        cli_println!("  Installed at: {}", metadata.installed_at);
        json_field(
            "installed_runtime",
            json!({
                "tag": &metadata.tag,
                "asset_name": &metadata.asset_name,
                "download_url": &metadata.download_url,
                "installed_at": &metadata.installed_at,
            }),
        );

        // Version compatibility: CLI vs installed runtime
        if let (Some(cli_mm), Some(rt_mm)) =
            (parse_major_minor(VERSION), parse_major_minor(&metadata.tag))
        {
            // A -SNAPSHOT CLI is a dev build from the source tree: the runtime
            // it would get via 'browser4-cli install' is the latest packaged
            // RELEASE, which does not track the source under test — so the
            // usual update advice is suppressed (following it would replace
            // the dev runtime with a stale release).
            let cli_is_dev_build = VERSION.contains("-SNAPSHOT");
            match cli_mm.cmp(&rt_mm) {
                std::cmp::Ordering::Greater => {
                    if cli_is_dev_build {
                        cli_println!(
                            "  ℹ  Dev build ({}): installed runtime ({}) is a packaged release, not the backend under test — install advice suppressed.",
                            VERSION,
                            metadata.tag
                        );
                        cli_println!(
                            "     Refresh the runtime by rebuilding from the source tree (bin/build.ps1 — or run via b4w.ps1 / b4w.sh) instead of 'browser4-cli install'."
                        );
                    } else {
                        cli_println!(
                            "  ⚠  Runtime ({}) is older than CLI ({}) — run 'browser4-cli install' to update.",
                            metadata.tag,
                            VERSION
                        );
                    }
                }
                std::cmp::Ordering::Less => {
                    if cli_is_dev_build {
                        cli_println!(
                            "  ⚠  CLI dev build ({}) is older than runtime ({}) — rebuild the CLI from a newer source-tree checkout.",
                            VERSION,
                            metadata.tag
                        );
                    } else {
                        cli_println!(
                            "  ⚠  CLI ({}) is older than runtime ({}) — consider rebuilding or updating the CLI.",
                            VERSION,
                            metadata.tag
                        );
                    }
                }
                std::cmp::Ordering::Equal => {
                    cli_println!("  ✓ CLI and runtime versions match.");
                }
            }
        }
    } else {
        if VERSION.contains("-SNAPSHOT") {
            cli_println!("  Installed runtime: not installed (dev build — the backend normally runs from the source tree; run 'browser4-cli install' only to install a packaged runtime)");
        } else {
            cli_println!("  Installed runtime: not installed (run 'browser4-cli install')");
        }
        json_field("installed_runtime", json!(null));
    }

    // ---- Auto-Update ----
    {
        use update_check::*;
        cli_println!("");
        cli_println!("-- Auto-Update --");
        let policy = AutoUpgradePolicy::from_env();
        cli_println!("  Policy: {} (env {})", policy.as_str(), AUTO_UPGRADE_ENV);
        let update_state = load_state();
        let format_epoch = |at: Option<i64>| {
            at.map(|ts| {
                DateTime::from_timestamp(ts, 0)
                    .map(|dt: DateTime<Utc>| dt.format("%Y-%m-%d %H:%M:%S UTC").to_string())
                    .unwrap_or_else(|| ts.to_string())
            })
            .unwrap_or_else(|| "never".to_string())
        };
        cli_println!("  Last check: {}", format_epoch(update_state.last_check_at));
        cli_println!(
            "  Latest release: {}",
            update_state.latest_tag.as_deref().unwrap_or("unknown")
        );
        if let Some(ref pending) = update_state.pending_tag {
            cli_println!("  Pending activation (next launch): {}", pending);
        }
        if let Some(ref previous) = update_state.previous_tag {
            cli_println!("  Previous runtime: {}", previous);
        }
        if !update_state.failures.is_empty() {
            let blocked: Vec<String> = update_state
                .failures
                .iter()
                .filter(|(_, f)| f.count >= FAILURE_BLACKLIST_THRESHOLD)
                .map(|(tag, _)| tag.clone())
                .collect();
            if !blocked.is_empty() {
                cli_println!(
                    "  ⚠  Prefetch blacklisted (repeated failures): {}",
                    blocked.join(", ")
                );
            }
        }
        json_field(
            "auto_update",
            json!({
                "policy": policy.as_str(),
                "last_check_at": update_state.last_check_at,
                "latest_tag": update_state.latest_tag,
                "pending_tag": update_state.pending_tag,
                "previous_tag": update_state.previous_tag,
            })
        );
    }

    // ---- Local Runtime Bundle (dev-mode provenance) ----
    // The same facts the launcher acts on — a version mismatch refuses to
    // start, newer sources are rebuilt before serving: which bundle dev mode
    // would serve, when it was built, and whether it matches the checkout.
    if let Some(bundle) = daemon::local_bundle_provenance() {
        cli_println!("");
        cli_println!("-- Local Runtime Bundle (dev mode) --");
        for (label, value) in bundle.report_rows() {
            cli_println!("  {}: {}", label, value);
        }
        json_field("local_bundle", bundle.to_json());
    }

    // ---- Backend Build Info (conditional) ----
    cli_println!("");
    cli_println!("-- Backend Build Info --");
    let build_url = format!("{base_url}/api/system/build");
    match get_json(client, &build_url).await {
        Ok(build_info) => {
            if let Some(obj) = build_info.as_object() {
                for (key, value) in obj {
                    cli_println!("  {}: {}", key, value);
                }
                // Annotate the backend version after the raw fields.
                if let Some(ver) = obj.get("version").and_then(|v| v.as_str()) {
                    let backend_is_dev = ver.contains("-SNAPSHOT");
                    if backend_is_dev {
                        cli_println!("  ⚠  Backend is a development snapshot — it may be unstable.");
                    } else if ver.contains("-rc.") {
                        cli_println!("  ℹ  Backend is a release candidate — suitable for testing, not production.");
                    }
                    // Compare backend version against installed runtime tag.
                    if let Some(ref metadata) = runtime_metadata {
                        if normalize_version(ver) != normalize_version(&metadata.tag) {
                            if backend_is_dev {
                                // The backend runs from the local source tree
                                // (dev build) — it is NOT expected to match the
                                // packaged runtime, and installing a release
                                // bundle would replace the code under test.
                                cli_println!(
                                    "  ℹ  Backend is a dev build ({}) running against the source tree — it is not expected to match the packaged runtime ({}); install-to-repair advice suppressed.",
                                    ver,
                                    metadata.tag
                                );
                            } else {
                                cli_println!(
                                    "  ⚠  Backend version ({}) doesn't match installed runtime ({}) — the installation may be partially updated. Run 'browser4-cli install' to repair.",
                                    ver,
                                    metadata.tag
                                );
                            }
                        }
                    }
                }
            }
            json_field("backend_build", build_info);
        }
        Err(e) => {
            cli_println!("  (server not running or unreachable: {})", e);
            json_field("backend_build", json!(null));
        }
    }

    // ---- LLM Status (conditional) ----
    cli_println!("");
    cli_println!("-- LLM Status --");
    let llm_url = format!("{base_url}/api/doctor/llm-status");
    match get_json(client, &llm_url).await {
        Ok(llm_info) => {
            for line in render_llm_status_lines(&llm_info) {
                cli_println!("{}", line);
            }
            json_field("llm_status", llm_info);
        }
        Err(e) => {
            cli_println!("  (server not running or unreachable: {})", e);
            json_field("llm_status", json!(null));
        }
    }

    // ---- Skills (conditional) ----
    cli_println!("");
    cli_println!("-- Skills --");
    let skills_url = format!("{base_url}/api/skills");
    match get_json(client, &skills_url).await {
        Ok(skills) => {
            if let Some(items) = skills.as_array() {
                if items.is_empty() {
                    cli_println!("  No skills registered.");
                } else {
                    let names: Vec<&str> = items
                        .iter()
                        .filter_map(|s| s.get("name").and_then(|v| v.as_str()))
                        .collect();
                    if names.is_empty() {
                        cli_println!("  {} skill(s) registered.", items.len());
                    } else {
                        cli_println!("  {} skill(s): {}", items.len(), names.join(", "));
                    }
                }
                json_field("skills", skills);
            } else {
                cli_println!("  (skills report unavailable)");
                json_field("skills", json!(null));
            }
        }
        Err(e) => {
            cli_println!("  (server not running or skills unavailable: {})", e);
            json_field("skills", json!(null));
        }
    }

    // ---- Backend Logs (conditional, shown only with --verbose) ----
    if verbose {
        let log_file = args
            .get("file")
            .and_then(|v| v.as_str())
            .unwrap_or("pulsar");
        let log_lines: u32 = args
            .get("lines")
            .and_then(|v| v.as_str())
            .and_then(|v| v.parse().ok())
            .unwrap_or(50)
            .min(500);
        let log_filter = args
            .get("log_filter")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        cli_println!("");
        if log_filter.is_empty() {
            cli_println!(
                "-- Backend Logs: {}.log (last {} lines) --",
                log_file,
                log_lines
            );
        } else {
            cli_println!(
                "-- Backend Logs: {}.log (last {} lines, filter: \"{}\") --",
                log_file,
                log_lines,
                log_filter
            );
        }
        let log_url = format!(
            "{base_url}/api/doctor/logs?file={}&lines={}&filter={}",
            log_file,
            log_lines,
            urlencoding::encode(log_filter)
        );
        match get_json(client, &log_url).await {
            Ok(log_data) => {
                if let Some(entries) = log_data.get("lines").and_then(|v| v.as_array()) {
                    for line in entries {
                        if let Some(text) = line.as_str() {
                            cli_println!("  {}", text);
                        }
                    }
                    if entries.is_empty() {
                        if log_filter.is_empty() {
                            cli_println!("  (log file empty or not found)");
                        } else {
                            cli_println!("  (no log lines matched filter \"{}\")", log_filter);
                        }
                    }
                }
                json_field("backend_logs", log_data);
            }
            Err(e) => {
                cli_println!("  (server not running or log unavailable: {})", e);
                json_field("backend_logs", json!(null));
            }
        }
    }

    // ---- Backend Metrics (conditional, shown only with --verbose) ----
    if verbose {
        let metric_filter = args
            .get("metric_filter")
            .and_then(|v| v.as_str())
            .unwrap_or("");

        cli_println!("");
        if metric_filter.is_empty() {
            cli_println!("-- Backend Metrics --");
        } else {
            cli_println!("-- Backend Metrics (filter: \"{}\") --", metric_filter);
        }
        let metrics_url = if metric_filter.is_empty() {
            format!("{base_url}/api/doctor/metrics")
        } else {
            format!(
                "{base_url}/api/doctor/metrics?filter={}",
                urlencoding::encode(metric_filter)
            )
        };
        match get_json(client, &metrics_url).await {
            Ok(metrics) => {
                if let Some(gauges) = metrics.get("gauges").and_then(|v| v.as_object()) {
                    for (key, value) in gauges {
                        if is_zero_value(value) {
                            continue;
                        }
                        cli_println!("  {}: {}", key, value);
                    }
                }
                // Print meter summary counts
                if let Some(meters) = metrics.get("meters").and_then(|v| v.as_object()) {
                    let mut shown_header = false;
                    for (key, val) in meters {
                        if let Some(obj) = val.as_object() {
                            let count = obj.get("count").and_then(|v| v.as_u64()).unwrap_or(0);
                            let rate = obj.get("meanRate").and_then(|v| v.as_f64()).unwrap_or(0.0);
                            if count == 0 && rate == 0.0 {
                                continue;
                            }
                            if !shown_header {
                                cli_println!("  -- Meters --");
                                shown_header = true;
                            }
                            cli_println!("  {}: {} count, {:.2}/s avg", key, count, rate);
                        }
                    }
                }
                json_field("backend_metrics", metrics);
            }
            Err(e) => {
                cli_println!("  (server not running or metrics unavailable: {})", e);
                json_field("backend_metrics", json!(null));
            }
        }
    }

    if !verbose {
        cli_println!("");
        cli_println!("💡 Tip: Use 'doctor --verbose' to include logs and metrics inline, 'doctor status' for the full status panel report (sessions, browsers, plugins, skills, metrics), or 'doctor log' / 'doctor metrics' subcommands for more control.");
    }

    // ---- Destructive Repairs (--fix) ----
    if is_fix {
        cli_println!("");
        cli_println!("-- Destructive Repairs (--fix) --");
        let fix_count = run_destructive_repairs();
        cli_println!("  Repairs applied: {}", fix_count);
        json_field("repairs_applied", json!(fix_count));

        // The LLM configuration file: a repair that hands the user the writable path
        // (and a commented template) instead of a directory they must complete
        // themselves.  Never overwrites an existing file, so it is safe to repeat.
        let llm_config_url = format!("{base_url}/api/doctor/llm-config/enable");
        let llm_config_result = post_json(client, &llm_config_url).await;
        for line in render_llm_config_fix_lines(&llm_config_result, base_url) {
            cli_println!("{}", line);
        }
        match &llm_config_result {
            Ok(info) => json_field("llm_config_file", info.clone()),
            Err(_) => json_field("llm_config_file", json!(null)),
        }
    } else {
        cli_println!("");
        cli_println!("💡 Tip: Run 'browser4-cli doctor --fix' to auto-repair common issues (reinstall Chrome, purge old state, clean temp files, write a commented LLM config template).");
    }

    Ok(())
}

// ---------------------------------------------------------------------------
// `doctor status` — the aggregated status panel report, layered.
// Layer 1 (default): one summary line per report section.
// Layer 2 (--verbose): per-section detail (session/plugin/skill lists, reports).
// Layer 3 (--section <name>): a single section in full detail.
// --json emits the raw `/api/system/status` document (all layers) for machines.
// ---------------------------------------------------------------------------

/// Map user-facing section names to JSON keys in `/api/system/status`.
fn status_section_key(section: &str) -> Option<&'static str> {
    match section {
        "health" => Some("health"),
        "build" => Some("build"),
        "runtime" => Some("runtime"),
        "llm" => Some("llm"),
        "sessions" => Some("sessions"),
        "pulsar-sessions" => Some("pulsarSessions"),
        "swarm" => Some("swarm"),
        "url-pool" => Some("urlPool"),
        "browsers" => Some("browsers"),
        "drivers" => Some("drivers"),
        "privacy" => Some("privacy"),
        "plugins" => Some("plugins"),
        "skills" => Some("skills"),
        "metrics" => Some("metrics"),
        "logs" => Some("logs"),
        _ => None,
    }
}

fn all_status_section_names() -> &'static str {
    "health, build, runtime, llm, sessions, pulsar-sessions, swarm, url-pool, browsers, drivers, privacy, plugins, skills, metrics, logs"
}

fn fmt_uptime_human(seconds: u64) -> String {
    let h = seconds / 3600;
    let m = (seconds % 3600) / 60;
    let s = seconds % 60;
    if h > 0 {
        format!("{}h {}m {}s", h, m, s)
    } else if m > 0 {
        format!("{}m {}s", m, s)
    } else {
        format!("{}s", s)
    }
}

/// Append `  key: value` (— for null/empty) to a text line buffer.
fn push_kv(lines: &mut Vec<String>, key: &str, value: &Value) {
    match value {
        Value::Null => lines.push(format!("  {}: —", key)),
        Value::String(s) if s.is_empty() => lines.push(format!("  {}: —", key)),
        Value::String(s) => lines.push(format!("  {}: {}", key, s)),
        other => lines.push(format!("  {}: {}", key, other)),
    }
}

fn push_section_header(lines: &mut Vec<String>, title: &str) {
    lines.push(String::new());
    lines.push(format!("-- {} --", title));
}

fn render_health(
    lines: &mut Vec<String>,
    overall_status: Option<&Value>,
    health_obj: Option<&Value>,
    timestamp: Option<&Value>,
    _verbose: bool,
) {
    push_section_header(lines, "Health");
    // The overall status lives at the top level of the report; when rendering
    // the health section alone, fall back to the health object's `check`.
    let status_str = overall_status.and_then(|v| v.as_str()).unwrap_or_else(|| {
        match health_obj
            .and_then(|v| v.get("check"))
            .and_then(|v| v.as_str())
        {
            Some("UP") => "healthy",
            Some(other) => other,
            None => "unknown",
        }
    });
    if status_str == "healthy" {
        lines.push("  ✓ healthy".to_string());
    } else {
        lines.push(format!("  ✗ {}", status_str));
    }
    if let Some(ts) = timestamp.and_then(|v| v.as_str()) {
        lines.push(format!("  timestamp: {}", ts));
    }
    if let Some(health) = health_obj.and_then(|v| v.as_object()) {
        for (k, v) in health {
            push_kv(lines, k, v);
        }
    }
}

fn render_build(lines: &mut Vec<String>, build: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Build");
    match build {
        Some(Value::Object(b)) => {
            push_kv(lines, "version", b.get("version").unwrap_or(&Value::Null));
            push_kv(lines, "git commit", b.get("gitCommitIdAbbrev").unwrap_or(&Value::Null));
            push_kv(lines, "branch", b.get("gitBranch").unwrap_or(&Value::Null));
            push_kv(lines, "commit time", b.get("gitCommitTime").unwrap_or(&Value::Null));
            if verbose {
                for (k, v) in b {
                    if !["version", "gitCommitIdAbbrev", "gitBranch", "gitCommitTime"]
                        .contains(&k.as_str())
                    {
                        push_kv(lines, k, v);
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_runtime(lines: &mut Vec<String>, runtime: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Runtime");
    match runtime {
        Some(Value::Object(r)) => {
            if let Some(uptime) = r.get("uptimeSeconds").and_then(|v| v.as_u64()) {
                lines.push(format!("  uptime: {}", fmt_uptime_human(uptime)));
            }
            push_kv(lines, "processors", r.get("processors").unwrap_or(&Value::Null));
            if let Some(load) = r.get("systemLoadAverage") {
                if load.as_f64().map(|f| f >= 0.0).unwrap_or(false) {
                    lines.push(format!("  load avg: {:.2}", load.as_f64().unwrap_or(0.0)));
                }
            }
            if let Some(mem) = r.get("memory").and_then(|v| v.as_object()) {
                let used_percent = mem
                    .get("heapUsedPercent")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(0);
                let used = mem.get("heapUsed").and_then(|v| v.as_u64()).unwrap_or(0);
                let max = mem.get("heapMax").and_then(|v| v.as_u64()).unwrap_or(0);
                lines.push(format!(
                    "  heap: {}% used ({} / {} bytes)",
                    used_percent, used, max
                ));
                if verbose {
                    for (k, v) in mem {
                        if !["heapUsedPercent", "heapUsed", "heapMax"].contains(&k.as_str()) {
                            push_kv(lines, k, v);
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_llm(lines: &mut Vec<String>, llm: Option<&Value>, verbose: bool) {
    push_section_header(lines, "LLM");
    match llm {
        Some(Value::Object(l)) => {
            let configured = l.get("configured").and_then(|v| v.as_bool()).unwrap_or(false);
            if configured {
                lines.push("  ✓ configured".to_string());
                if let Some(detected) = l.get("detectedVia").and_then(|v| v.as_str()) {
                    lines.push(format!("  detected via: {}", detected));
                }
                if verbose {
                    if let Some(vars) = l.get("foundEnvVars").and_then(|v| v.as_array()) {
                        let names: Vec<&str> = vars.iter().filter_map(|v| v.as_str()).collect();
                        if !names.is_empty() {
                            lines.push(format!("  env vars: {}", names.join(", ")));
                        }
                    }
                    if let Some(props) = l.get("foundProperties").and_then(|v| v.as_array()) {
                        let names: Vec<&str> = props.iter().filter_map(|v| v.as_str()).collect();
                        if !names.is_empty() {
                            lines.push(format!("  properties: {}", names.join(", ")));
                        }
                    }
                }
            } else if let Some(message) = l.get("message").and_then(|v| v.as_str()) {
                lines.push("  ✗ not configured".to_string());
                for line in message.lines() {
                    lines.push(format!("    {}", line));
                }
            } else {
                lines.push("  ✗ not configured".to_string());
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_sessions(lines: &mut Vec<String>, sessions: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Sessions");
    match sessions {
        Some(Value::Object(s)) => {
            let total = s.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            let mut parts = vec![format!("total: {}", total)];
            if let Some(by_status) = s.get("byStatus").and_then(|v| v.as_object()) {
                let mut statuses: Vec<(&String, &Value)> = by_status.iter().collect();
                statuses.sort_by(|a, b| a.0.cmp(b.0));
                for (k, v) in statuses {
                    parts.push(format!("{}: {}", k, v));
                }
            }
            lines.push(format!("  {}", parts.join(", ")));
            if verbose {
                if let Some(items) = s.get("items").and_then(|v| v.as_array()) {
                    for it in items {
                        if let Some(obj) = it.as_object() {
                            let id = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
                            let kind = obj.get("kind").and_then(|v| v.as_str()).unwrap_or("?");
                            let status = obj.get("status").and_then(|v| v.as_str()).unwrap_or("?");
                            let active = obj.get("active").and_then(|v| v.as_bool()).unwrap_or(false);
                            let url = obj.get("url").and_then(|v| v.as_str()).unwrap_or("");
                            lines.push(format!(
                                "  {} [{}] {} active={} url={}",
                                id,
                                kind,
                                status,
                                if active { "yes" } else { "no" },
                                url
                            ));
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_pulsar_sessions(lines: &mut Vec<String>, ps: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Pulsar Sessions");
    match ps {
        Some(Value::Object(p)) => {
            let total = p.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            lines.push(format!("  total: {}", total));
            if verbose {
                if let Some(items) = p.get("items").and_then(|v| v.as_array()) {
                    for it in items {
                        if let Some(obj) = it.as_object() {
                            let id = obj
                                .get("managedSessionId")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let label = obj.get("label").and_then(|v| v.as_str()).unwrap_or("");
                            let active = obj
                                .get("isActive")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let loop_running = obj
                                .get("mainLoopRunning")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            lines.push(format!(
                                "  {} label={} active={} mainLoop={}",
                                id,
                                label,
                                if active { "yes" } else { "no" },
                                if loop_running { "running" } else { "stopped" }
                            ));
                            if let Some(report) = obj.get("mainLoopReport").and_then(|v| v.as_str()) {
                                for line in report.lines() {
                                    lines.push(format!("    {}", line));
                                }
                            }
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_swarm(lines: &mut Vec<String>, swarm: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Swarm");
    match swarm {
        Some(Value::Object(sw)) => {
            match sw.get("session") {
                Some(Value::Object(s)) => {
                    lines.push(format!(
                        "  session: {} (status: {})",
                        s.get("id").and_then(|v| v.as_str()).unwrap_or("?"),
                        s.get("status").and_then(|v| v.as_str()).unwrap_or("?")
                    ));
                    if verbose {
                        push_kv(lines, "active", s.get("active").unwrap_or(&Value::Null));
                        push_kv(lines, "url", s.get("url").unwrap_or(&Value::Null));
                    }
                }
                _ => lines.push("  session: none".to_string()),
            }
            if let Some(tasks) = sw.get("tasks").and_then(|v| v.as_object()) {
                let total = tasks.get("total").unwrap_or(&Value::Null);
                let done = tasks.get("done").unwrap_or(&Value::Null);
                let running = tasks.get("running").unwrap_or(&Value::Null);
                lines.push(format!(
                    "  tasks: total={} done={} running={}",
                    total, done, running
                ));
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_url_pool(lines: &mut Vec<String>, url_pool: Option<&Value>, verbose: bool) {
    push_section_header(lines, "URL Pool");
    match url_pool {
        Some(Value::Object(up)) => {
            push_kv(lines, "pool id", up.get("id").unwrap_or(&Value::Null));
            push_kv(lines, "total", up.get("totalCount").unwrap_or(&Value::Null));
            push_kv(lines, "real-time", up.get("realTime").unwrap_or(&Value::Null));
            push_kv(lines, "delay", up.get("delay").unwrap_or(&Value::Null));
            if verbose {
                if let Some(caches) = up.get("caches").and_then(|v| v.as_object()) {
                    let mut names: Vec<String> = caches
                        .values()
                        .filter_map(|c| c.get("name").and_then(|n| n.as_str()))
                        .map(|n| n.to_string())
                        .collect();
                    names.sort();
                    if !names.is_empty() {
                        lines.push(format!("  caches: {}", names.join(", ")));
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_browsers(lines: &mut Vec<String>, browsers: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Browsers");
    match browsers {
        Some(Value::Object(b)) => {
            let total = b.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            let tabs = b.get("tabTotal").and_then(|v| v.as_u64()).unwrap_or(0);
            lines.push(format!("  {} browser(s), {} tab(s)", total, tabs));
            if verbose {
                if let Some(items) = b.get("items").and_then(|v| v.as_array()) {
                    for it in items {
                        if let Some(obj) = it.as_object() {
                            let id = obj.get("sessionId").and_then(|v| v.as_str()).unwrap_or("?");
                            let has_browser = obj
                                .get("hasBrowser")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let has_driver = obj
                                .get("hasDriver")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false);
                            let tab_count = obj
                                .get("tabCount")
                                .and_then(|v| v.as_u64())
                                .unwrap_or(0);
                            let url = obj.get("url").and_then(|v| v.as_str()).unwrap_or("");
                            lines.push(format!(
                                "  {} browser={} driver={} tabs={} url={}",
                                id,
                                if has_browser { "open" } else { "—" },
                                if has_driver { "bound" } else { "—" },
                                tab_count,
                                url
                            ));
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_text_report(lines: &mut Vec<String>, report_text: Option<&Value>, title: &str, _verbose: bool) {
    push_section_header(lines, title);
    match report_text {
        Some(Value::Object(r)) => match r.get("report") {
            Some(Value::String(text)) if !text.is_empty() => {
                for line in text.lines() {
                    lines.push(format!("  {}", line));
                }
            }
            _ => lines.push("  (no report)".to_string()),
        },
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_plugins(lines: &mut Vec<String>, plugins: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Plugins");
    match plugins {
        Some(Value::Object(p)) => {
            let total = p.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            let loaded = p.get("loaded").and_then(|v| v.as_u64()).unwrap_or(0);
            let enabled = p.get("enabled").and_then(|v| v.as_u64()).unwrap_or(0);
            let warnings = p.get("warnings").and_then(|v| v.as_u64()).unwrap_or(0);
            let blocked = p.get("blocked").and_then(|v| v.as_u64()).unwrap_or(0);
            lines.push(format!(
                "  total: {} (loaded: {}, enabled: {}, warnings: {}, blocked: {})",
                total, loaded, enabled, warnings, blocked
            ));
            if verbose {
                if let Some(items) = p.get("items").and_then(|v| v.as_array()) {
                    for it in items {
                        if let Some(obj) = it.as_object() {
                            let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("?");
                            let version = obj
                                .get("version")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let sdk = obj
                                .get("sdkVersion")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let status = if obj
                                .get("loaded")
                                .and_then(|v| v.as_bool())
                                .unwrap_or(false)
                            {
                                "loaded"
                            } else {
                                "not loaded"
                            };
                            let verdict = obj
                                .get("compatibility")
                                .and_then(|v| v.get("verdict"))
                                .and_then(|v| v.as_str())
                                .unwrap_or("unknown");
                            lines.push(format!(
                                "  {} v{} (sdk {}) [{}] compatibility: {}",
                                name, version, sdk, status, verdict
                            ));
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_skills(lines: &mut Vec<String>, skills: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Skills");
    match skills {
        Some(Value::Object(s)) => {
            let total = s.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            let mut parts = vec![format!("total: {}", total)];
            if let Some(by_origin) = s.get("byOrigin").and_then(|v| v.as_object()) {
                let mut origins: Vec<(&String, &Value)> = by_origin.iter().collect();
                origins.sort_by(|a, b| a.0.cmp(b.0));
                for (k, v) in origins {
                    parts.push(format!("{}: {}", k, v));
                }
            }
            lines.push(format!("  {}", parts.join(", ")));
            if verbose {
                if let Some(items) = s.get("items").and_then(|v| v.as_array()) {
                    for it in items {
                        if let Some(obj) = it.as_object() {
                            let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("?");
                            let id = obj.get("id").and_then(|v| v.as_str()).unwrap_or("?");
                            let version = obj
                                .get("version")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let origin_kind = obj
                                .get("originKind")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let origin = obj.get("origin").and_then(|v| v.as_str()).unwrap_or("");
                            lines.push(format!(
                                "  {} ({}) v{} [{}] {}",
                                name, id, version, origin_kind, origin
                            ));
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_metrics(lines: &mut Vec<String>, metrics: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Metrics");
    match metrics {
        Some(Value::Object(m)) => {
            let total = m.get("total").and_then(|v| v.as_u64()).unwrap_or(0);
            lines.push(format!("  total: {}", total));
            if verbose {
                for k in ["gauges", "counters", "meters", "histograms", "timers"] {
                    if let Some(v) = m.get(k) {
                        lines.push(format!("  {}: {}", k, v));
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

fn render_logs(lines: &mut Vec<String>, logs: Option<&Value>, verbose: bool) {
    push_section_header(lines, "Log Files");
    match logs {
        Some(Value::Object(l)) => {
            let count = l.get("count").and_then(|v| v.as_u64()).unwrap_or(0);
            push_kv(lines, "directory", l.get("directory").unwrap_or(&Value::Null));
            lines.push(format!("  count: {}", count));
            if verbose {
                if let Some(files) = l.get("files").and_then(|v| v.as_array()) {
                    for f in files {
                        if let Some(obj) = f.as_object() {
                            let name = obj.get("name").and_then(|v| v.as_str()).unwrap_or("?");
                            let size = obj
                                .get("sizeHuman")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            lines.push(format!("  {} ({})", name, size));
                        }
                    }
                }
            }
        }
        _ => lines.push("  (unavailable)".to_string()),
    }
}

/// Build the human-readable line buffer for the whole report.
/// `verbose` toggles between the summary layer (default) and the detail layer.
fn build_status_report_lines(report: &Value, verbose: bool) -> Vec<String> {
    let mut lines = Vec::new();
    render_health(
        &mut lines,
        report.get("status"),
        report.get("health"),
        report.get("timestamp"),
        verbose,
    );
    render_build(&mut lines, report.get("build"), verbose);
    render_runtime(&mut lines, report.get("runtime"), verbose);
    render_llm(&mut lines, report.get("llm"), verbose);
    render_sessions(&mut lines, report.get("sessions"), verbose);
    render_pulsar_sessions(&mut lines, report.get("pulsarSessions"), verbose);
    render_swarm(&mut lines, report.get("swarm"), verbose);
    render_url_pool(&mut lines, report.get("urlPool"), verbose);
    render_browsers(&mut lines, report.get("browsers"), verbose);
    render_text_report(&mut lines, report.get("drivers"), "Driver Pools", verbose);
    render_text_report(&mut lines, report.get("privacy"), "Privacy Contexts", verbose);
    render_plugins(&mut lines, report.get("plugins"), verbose);
    render_skills(&mut lines, report.get("skills"), verbose);
    render_metrics(&mut lines, report.get("metrics"), verbose);
    render_logs(&mut lines, report.get("logs"), verbose);
    lines
}

/// Build the human-readable line buffer for a single section (full detail).
fn build_status_section_lines(sec: &str, value: &Value) -> Vec<String> {
    let mut lines = Vec::new();
    match sec {
        "health" => render_health(&mut lines, None, Some(value), None, true),
        "build" => render_build(&mut lines, Some(value), true),
        "runtime" => render_runtime(&mut lines, Some(value), true),
        "llm" => render_llm(&mut lines, Some(value), true),
        "sessions" => render_sessions(&mut lines, Some(value), true),
        "pulsar-sessions" => render_pulsar_sessions(&mut lines, Some(value), true),
        "swarm" => render_swarm(&mut lines, Some(value), true),
        "url-pool" => render_url_pool(&mut lines, Some(value), true),
        "browsers" => render_browsers(&mut lines, Some(value), true),
        "drivers" => render_text_report(&mut lines, Some(value), "Driver Pools", true),
        "privacy" => render_text_report(&mut lines, Some(value), "Privacy Contexts", true),
        "plugins" => render_plugins(&mut lines, Some(value), true),
        "skills" => render_skills(&mut lines, Some(value), true),
        "metrics" => render_metrics(&mut lines, Some(value), true),
        "logs" => render_logs(&mut lines, Some(value), true),
        _ => lines.push(format!("  (unknown section: {})", sec)),
    }
    lines
}

/// `doctor status` — access every report on the status panel
/// (`/api/system/status`) from the doctor command.
async fn handle_doctor_status(
    client: &Client,
    base_url: &str,
    args: &HashMap<String, Value>,
) -> Result<(), String> {
    let verbose = args
        .get("verbose")
        .and_then(|v| v.as_bool())
        .unwrap_or(false);
    let section = args
        .get("section")
        .and_then(|v| v.as_str())
        .map(|s| s.to_string());

    cli_println!("Browser4 Status Panel Report");
    cli_println!("============================");
    cli_println!("");
    cli_println!("Source: {}/api/system/status", base_url);

    let status_url = format!("{base_url}/api/system/status");
    let report = match get_json(client, &status_url).await {
        Ok(report) => report,
        Err(e) => {
            cli_println!("");
            cli_println!("Cannot reach {}: {}", status_url, e);
            cli_println!("Start the backend first, then retry.");
            json_field("status_report", json!(null));
            return Ok(());
        }
    };

    // Machine-readable mode: emit the raw document (all layers). When a
    // section was requested, also emit that section slice.
    json_field("status_report", report.clone());
    if let Some(ref sec) = section {
        if let Some(key) = status_section_key(sec) {
            if let Some(value) = report.get(key) {
                json_field("status_report_section", value.clone());
            }
        }
    }

    let lines = if let Some(sec) = &section {
        let key = match status_section_key(sec) {
            Some(key) => key,
            None => {
                cli_println!("");
                cli_println!("Unknown section: {}", sec);
                cli_println!("Available sections: {}", all_status_section_names());
                return Ok(());
            }
        };
        match report.get(key) {
            Some(value) => build_status_section_lines(sec, value),
            None => {
                cli_println!("");
                cli_println!("Section '{}' is not present in the status report.", sec);
                return Ok(());
            }
        }
    } else {
        build_status_report_lines(&report, verbose)
    };

    for line in lines {
        cli_println!("{}", line);
    }

    if !verbose && section.is_none() {
        cli_println!("");
        cli_println!("💡 Tip: Use 'doctor status --verbose' for full detail, 'doctor status --section <name>' to drill into one report, 'doctor status --json' for machine-readable JSON.");
    }

    Ok(())
}

/// The lines the `--fix` step prints for the LLM configuration template.
///
/// A configuration file created by the backend lives on the **backend host**, which is
/// why a non-local backend says so — otherwise "I edited the file and nothing happened"
/// follows a Docker deployment.  Pure so both branches can be unit tested.
fn render_llm_config_fix_lines(result: &Result<Value, String>, base_url: &str) -> Vec<String> {
    let mut lines = Vec::new();

    let info = match result {
        Ok(info) => info,
        Err(e) => {
            lines.push(format!("  LLM config file: not created ({})", e));
            lines.push(
                "  ℹ  This backend does not create the template — set the key as an environment \
                 variable, or see docs/config.md for the file locations."
                    .to_string(),
            );
            return lines;
        }
    };

    if let Some(display) = info.get("enabledPathDisplay").and_then(|v| v.as_str()) {
        lines.push(format!("  LLM config file: {}", display));
        if !is_local_backend(base_url) {
            lines.push(format!(
                "  ℹ  That path is on the backend host ({}), which is not this machine.",
                base_url
            ));
        }
    }
    if let Some(message) = info.get("message").and_then(|v| v.as_str()) {
        lines.push(format!("  ℹ  {}", message));
    }
    if let Some(error) = info.get("error").and_then(|v| v.as_str()) {
        lines.push(format!("  ⚠  LLM config file: {}", error));
    }

    lines
}

/// Whether a backend URL points at this machine.
fn is_local_backend(base_url: &str) -> bool {
    let url = base_url.to_ascii_lowercase();
    ["//localhost", "//127.0.0.1", "//[::1]", "//0.0.0.0"]
        .iter()
        .any(|host| url.contains(host))
}

/// GET a JSON endpoint and return the parsed Value.
async fn get_json(client: &Client, url: &str) -> Result<Value, String> {
    let response = client
        .get(url)
        .send()
        .await
        .map_err(|e| format!("HTTP request failed: {e}"))?;
    if !response.status().is_success() {
        return Err(format!("HTTP {}", response.status()));
    }
    response
        .json::<Value>()
        .await
        .map_err(|e| format!("JSON parse failed: {e}"))
}

/// POST a JSON endpoint with an empty body and return the parsed Value.
///
/// The response body is included in the error so that a backend-side failure
/// (e.g. an unwritable configuration directory) reaches the user instead of
/// being collapsed into a bare status code.
async fn post_json(client: &Client, url: &str) -> Result<Value, String> {
    let response = client.post(url).send().await
        .map_err(|e| format!("HTTP request failed: {e}"))?;
    let status = response.status();
    if !status.is_success() {
        let body = response.text().await.unwrap_or_default();
        let body = body.trim();
        return Err(if body.is_empty() {
            format!("HTTP {}", status)
        } else {
            format!("HTTP {}: {}", status, body)
        });
    }
    response.json::<Value>().await
        .map_err(|e| format!("JSON parse failed: {e}"))
}

/// Returns true if a JSON value represents zero (0, 0.0, 0 as string, etc.).
fn is_zero_value(value: &Value) -> bool {
    match value {
        Value::Number(n) => n.as_f64().map(|f| f == 0.0).unwrap_or(false),
        Value::String(s) => s.is_empty() || s == "0" || s == "0.0",
        Value::Null => true,
        Value::Bool(b) => !*b,
        Value::Array(a) => a.is_empty(),
        Value::Object(o) => o.is_empty(),
    }
}

/// Clean up stale daemon files (PID files, socket files, lock files) from the
/// state directory that may have been left behind by previous runs.
/// Returns the number of files cleaned.
fn clean_stale_daemon_files() -> usize {
    let state_dir = state::resolve_default_state_dir();
    let mut cleaned = 0usize;

    // Patterns to clean: PID files, socket files, lock files, temp files
    let stale_patterns = [".pid", ".sock", ".lock", ".tmp"];
    let stale_extensions = ["pid", "sock", "lock", "tmp"];

    // Clean files in the state directory root
    if let Ok(entries) = std::fs::read_dir(&state_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                    let should_clean = stale_patterns.iter().any(|p| name.contains(p))
                        || stale_extensions
                            .iter()
                            .any(|ext| path.extension().and_then(|e| e.to_str()) == Some(ext));
                    if should_clean {
                        if std::fs::remove_file(&path).is_ok() {
                            cleaned += 1;
                        }
                    }
                }
            }
        }
    }

    // Clean dedicated sessions directory
    let sessions_dir = state_dir.join("sessions");
    if let Ok(entries) = std::fs::read_dir(&sessions_dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_file() {
                if let Some(name) = path.file_name().and_then(|n| n.to_str()) {
                    if stale_patterns.iter().any(|p| name.contains(p)) {
                        if std::fs::remove_file(&path).is_ok() {
                            cleaned += 1;
                        }
                    }
                }
            }
        }
    }

    // Clean the tmp directory if it exists
    let tmp_dir = state_dir.join("tmp");
    if tmp_dir.exists() && tmp_dir.is_dir() {
        if let Ok(entries) = std::fs::read_dir(&tmp_dir) {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_file() {
                    if std::fs::remove_file(&path).is_ok() {
                        cleaned += 1;
                    }
                }
            }
        }
    }

    cleaned
}

/// Run destructive repairs when `--fix` is passed.
/// - Removes Chrome profile directories that may be corrupted
/// - Purges the runtime download cache
/// - Removes temp cli directories
/// Returns the number of repair actions applied.
fn run_destructive_repairs() -> usize {
    let mut repairs = 0usize;
    let runtime_data_dir = state::resolve_runtime_data_dir();
    let runtime_cache_dir = state::resolve_runtime_cache_dir();

    // 1. Clean stale daemon files (same as auto-clean)
    repairs += clean_stale_daemon_files();

    // 2. Clean temp/cli directory under runtime data dir
    let cli_tmp = runtime_data_dir.join("tmp").join("cli");
    if cli_tmp.exists() {
        if std::fs::remove_dir_all(&cli_tmp).is_ok() {
            repairs += 1;
        }
    }

    // 3. Clean downloads cache (frees disk space, forces fresh downloads)
    let downloads_dir = runtime_cache_dir.join("downloads");
    if downloads_dir.exists() {
        if std::fs::remove_dir_all(&downloads_dir).is_ok() {
            repairs += 1;
        }
    }

    // 4. Remove install lock directory (may be stale from interrupted installs)
    let install_lock = runtime_data_dir.join(".install.lock");
    if install_lock.exists() {
        if install_lock.is_dir() {
            let _ = std::fs::remove_dir_all(&install_lock);
        } else {
            let _ = std::fs::remove_file(&install_lock);
        }
        repairs += 1;
    }

    repairs
}

/// Handle `doctor log` subcommand:
/// - `doctor log` or `doctor log list` → list available log files
/// - `doctor log <name>` → show log file content
/// - `doctor log <name> --tail` → show last few lines
/// - `doctor log <name> grep <pattern>` → search log file with grep syntax
async fn handle_doctor_log(
    client: &Client,
    base_url: &str,
    args: &HashMap<String, Value>,
) -> Result<(), String> {
    let log_name = args
        .get("name")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty() && *s != "list");
    let is_tail = args.get("tail").and_then(|v| v.as_bool()).unwrap_or(false);
    let grep_pattern = args.get("grep").and_then(|v| v.as_str()).map(String::from);

    // Mode: list log files (no name, or name == "list")
    if log_name.is_none() {
        cli_println!("Available Log Files");
        cli_println!("===================");
        cli_println!("");

        let list_url = format!("{base_url}/api/doctor/log-files");
        match get_json(client, &list_url).await {
            Ok(data) => {
                if let Some(files) = data.get("files").and_then(|v| v.as_array()) {
                    if files.is_empty() {
                        cli_println!("  (no log files found)");
                    } else {
                        cli_println!("  {:<25} {:>10}  {:>20}", "NAME", "SIZE", "LAST MODIFIED");
                        cli_println!("  {:<25} {:>10}  {:>20}", "----", "----", "-------------");
                        for file in files {
                            let name = file
                                .get("nameWithoutExt")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let size = file
                                .get("sizeHuman")
                                .and_then(|v| v.as_str())
                                .unwrap_or("?");
                            let modified_ms = file
                                .get("lastModified")
                                .and_then(|v| v.as_i64())
                                .unwrap_or(0);
                            let modified_str = if modified_ms > 0 {
                                let secs = modified_ms / 1000;
                                let datetime = chrono::DateTime::from_timestamp(secs, 0)
                                    .map(|dt| {
                                        dt.with_timezone(&chrono::Local)
                                            .format("%Y-%m-%d %H:%M:%S")
                                            .to_string()
                                    })
                                    .unwrap_or_else(|| "unknown".to_string());
                                datetime
                            } else {
                                "unknown".to_string()
                            };
                            cli_println!("  {:<25} {:>10}  {:>20}", name, size, modified_str);
                        }
                        cli_println!("");
                        cli_println!(
                            "  {} log file(s). Use 'doctor log <name>' to view a specific log.",
                            files.len()
                        );
                    }
                }
                json_field("log_files", data);
            }
            Err(e) => {
                // The backend cannot list its logs when it is not running — and
                // that is precisely when a user needs them ("the start failed,
                // where is the log?").  Fall back to the launcher logs on disk
                // and name the directory that was searched.
                let dir = daemon::backend_log_dir();
                cli_println!("  (backend not reachable: {})", e);
                cli_println!("");
                cli_println!("  Local launcher logs in {}:", dir.display());
                let mut files: Vec<std::path::PathBuf> = std::fs::read_dir(&dir)
                    .map(|entries| {
                        entries
                            .flatten()
                            .map(|entry| entry.path())
                            .filter(|path| {
                                path.extension().and_then(|ext| ext.to_str()) == Some("log")
                            })
                            .collect()
                    })
                    .unwrap_or_default();
                files.sort();
                let mut shown = 0usize;
                for path in files.iter().rev().take(10) {
                    let metadata = std::fs::metadata(path).ok();
                    let size = metadata.as_ref().map(|m| m.len()).unwrap_or(0);
                    let modified = metadata
                        .and_then(|m| m.modified().ok())
                        .map(|time| {
                            chrono::DateTime::<chrono::Local>::from(time)
                                .format("%Y-%m-%d %H:%M:%S")
                                .to_string()
                        })
                        .unwrap_or_else(|| "unknown".to_string());
                    cli_println!(
                        "  {:<55} {:>10}  {:>20}",
                        path.file_name()
                            .map(|name| name.to_string_lossy().to_string())
                            .unwrap_or_else(|| "?".to_string()),
                        size,
                        modified
                    );
                    shown += 1;
                }
                if shown == 0 {
                    cli_println!("  (no launcher logs found there)");
                } else {
                    cli_println!("");
                    cli_println!(
                        "  The newest file is the record of the last start — open it directly; \
                         it exists even when the backend never listened."
                    );
                }
                json_field("log_files", json!(null));
                json_field("log_dir", json!(dir.to_string_lossy()));
            }
        }
        return Ok(());
    }

    let name = log_name.unwrap();
    let display_name = format!("{}.log", name);

    // Mode: grep — search log file content using grep syntax
    if let Some(pattern) = grep_pattern {
        let lines: u32 = args
            .get("lines")
            .and_then(|v| v.as_str())
            .and_then(|v| v.parse().ok())
            .unwrap_or(50000);
        let log_url = format!(
            "{base_url}/api/doctor/logs?file={}&lines={}&filter=",
            name,
            lines.min(50000)
        );
        let log_content = match get_json(client, &log_url).await {
            Ok(data) => {
                if let Some(entries) = data.get("lines").and_then(|v| v.as_array()) {
                    entries
                        .iter()
                        .filter_map(|v| v.as_str())
                        .collect::<Vec<&str>>()
                        .join("\n")
                } else {
                    return Err(format!("Failed to read log file: {}", display_name));
                }
            }
            Err(e) => {
                return Err(format!(
                    "Failed to fetch log file '{}': {}",
                    display_name, e
                ))
            }
        };

        // Build GrepOptions from args, using the grep pattern
        let mut grep_params = args.clone();
        grep_params.insert("pattern".to_string(), json!(pattern));
        let grep_params_value: Value = json!(grep_params);
        let grep_options = parse_grep_options(&grep_params_value)?;

        let (page, page_size, show_all) = parse_page_opts(&grep_params_value);
        cli_println!(
            "--- doctor log {} grep \"{}\" ---",
            display_name,
            grep_options.pattern
        );
        run_grep_on_source(
            &log_content,
            &grep_options,
            &display_name,
            page,
            page_size,
            show_all,
        )?;
        return Ok(());
    }

    // Mode: view log file (with or without --tail)
    let lines: u32 = args
        .get("lines")
        .and_then(|v| v.as_str())
        .and_then(|v| v.parse().ok())
        .unwrap_or(if is_tail { 200 } else { 50000 });
    let log_url = format!(
        "{base_url}/api/doctor/logs?file={}&lines={}&filter=",
        name,
        lines.min(50000)
    );

    cli_println!(
        "--- doctor log {} ({}) ---",
        display_name,
        if is_tail {
            format!("last {} lines", lines)
        } else {
            "full".to_string()
        }
    );
    cli_println!("");

    match get_json(client, &log_url).await {
        Ok(log_data) => {
            if let Some(entries) = log_data.get("lines").and_then(|v| v.as_array()) {
                if entries.is_empty() {
                    cli_println!("  (log file empty or not found)");
                } else {
                    for line in entries {
                        if let Some(text) = line.as_str() {
                            cli_println!("{}", text);
                        }
                    }
                    cli_println!("");
                    cli_println!("  {} line(s). Use 'doctor log {} grep <pattern>' to search, '--tail' for recent lines.", entries.len(), name);
                }
            }
            json_field("log_content", log_data);
        }
        Err(e) => {
            cli_println!("  (server not running or log unavailable: {})", e);
            json_field("log_content", json!(null));
        }
    }

    Ok(())
}

/// Handle `doctor metrics` subcommand:
/// - `doctor metrics` → overview: metric counts by type, then list non-zero metric names
/// - `doctor metrics <filter>` → show metrics matching filter (server-side)
/// - `doctor metrics grep <pattern>` → search metric names/values with grep syntax
async fn handle_doctor_metrics(
    client: &Client,
    base_url: &str,
    args: &HashMap<String, Value>,
) -> Result<(), String> {
    let filter_arg = args
        .get("filter")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty() && *s != "list");
    let grep_pattern = args.get("grep").and_then(|v| v.as_str()).map(String::from);

    // Fetch all metrics from the backend
    let metrics_url = format!("{base_url}/api/doctor/metrics");
    let all_metrics: Value = match get_json(client, &metrics_url).await {
        Ok(data) => data,
        Err(e) => {
            cli_println!("(server not running or metrics unavailable: {})", e);
            json_field("metrics", json!(null));
            return Ok(());
        }
    };

    // Helper: collect all non-zero metrics as "type: name = value" lines
    fn collect_metric_lines(metrics: &Value) -> Vec<String> {
        let mut lines = Vec::new();
        if let Some(gauges) = metrics.get("gauges").and_then(|v| v.as_object()) {
            for (key, value) in gauges {
                if is_zero_value(value) {
                    continue;
                }
                lines.push(format!("[gauge] {} = {}", key, value));
            }
        }
        if let Some(counters) = metrics.get("counters").and_then(|v| v.as_object()) {
            for (key, value) in counters {
                if let Some(n) = value.as_u64() {
                    if n == 0 {
                        continue;
                    }
                    lines.push(format!("[counter] {} = {}", key, n));
                }
            }
        }
        if let Some(meters) = metrics.get("meters").and_then(|v| v.as_object()) {
            for (key, val) in meters {
                if let Some(obj) = val.as_object() {
                    let count = obj.get("count").and_then(|v| v.as_u64()).unwrap_or(0);
                    let rate = obj.get("meanRate").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    if count == 0 && rate == 0.0 {
                        continue;
                    }
                    lines.push(format!(
                        "[meter] {} = count:{}, rate:{:.2}/s",
                        key, count, rate
                    ));
                }
            }
        }
        if let Some(histograms) = metrics.get("histograms").and_then(|v| v.as_object()) {
            for (key, val) in histograms {
                if let Some(obj) = val.as_object() {
                    let count = obj.get("count").and_then(|v| v.as_u64()).unwrap_or(0);
                    if count == 0 {
                        continue;
                    }
                    let mean = obj.get("mean").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    let p99 = obj.get("p99").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    lines.push(format!(
                        "[histogram] {} = count:{}, mean:{:.2}, p99:{:.2}",
                        key, count, mean, p99
                    ));
                }
            }
        }
        if let Some(timers) = metrics.get("timers").and_then(|v| v.as_object()) {
            for (key, val) in timers {
                if let Some(obj) = val.as_object() {
                    let count = obj.get("count").and_then(|v| v.as_u64()).unwrap_or(0);
                    if count == 0 {
                        continue;
                    }
                    let mean = obj.get("mean").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    let p99 = obj.get("p99").and_then(|v| v.as_f64()).unwrap_or(0.0);
                    lines.push(format!(
                        "[timer] {} = count:{}, mean:{:.2}, p99:{:.2}",
                        key, count, mean, p99
                    ));
                }
            }
        }
        lines.sort();
        lines
    }

    // Mode: grep — search metric lines using grep syntax
    if let Some(pattern) = grep_pattern {
        let lines = collect_metric_lines(&all_metrics);
        let source = lines.join("\n");

        let mut grep_params = args.clone();
        grep_params.insert("pattern".to_string(), json!(pattern));
        let grep_params_value: Value = json!(grep_params);
        let grep_options = parse_grep_options(&grep_params_value)?;

        let (page, page_size, show_all) = parse_page_opts(&grep_params_value);
        cli_println!("--- doctor metrics grep \"{}\" ---", grep_options.pattern);
        run_grep_on_source(&source, &grep_options, "metrics", page, page_size, show_all)?;
        return Ok(());
    }

    // Mode: filtered view (positional arg used as server-side filter)
    if let Some(filter) = filter_arg {
        let filter_url = format!(
            "{base_url}/api/doctor/metrics?filter={}",
            urlencoding::encode(filter)
        );
        let filtered: Value = match get_json(client, &filter_url).await {
            Ok(data) => data,
            Err(e) => {
                cli_println!("(server not running or metrics unavailable: {})", e);
                return Ok(());
            }
        };
        cli_println!("--- doctor metrics filter \"{}\" ---", filter);
        cli_println!("");
        let lines = collect_metric_lines(&filtered);
        if lines.is_empty() {
            cli_println!("  (no metrics matched filter \"{}\")", filter);
        } else {
            for line in &lines {
                cli_println!("{}", line);
            }
            cli_println!("");
            cli_println!(
                "  {} metric(s) matched. Use 'doctor metrics grep <pattern>' for advanced search.",
                lines.len()
            );
        }
        json_field("metrics", filtered);
        return Ok(());
    }

    // Mode: overview (no args)
    let lines = collect_metric_lines(&all_metrics);
    let total = lines.len();

    // Count by type
    let gauge_count = lines.iter().filter(|l| l.starts_with("[gauge]")).count();
    let counter_count = lines.iter().filter(|l| l.starts_with("[counter]")).count();
    let meter_count = lines.iter().filter(|l| l.starts_with("[meter]")).count();
    let histogram_count = lines
        .iter()
        .filter(|l| l.starts_with("[histogram]"))
        .count();
    let timer_count = lines.iter().filter(|l| l.starts_with("[timer]")).count();

    cli_println!("Backend Metrics Overview");
    cli_println!("=======================");
    cli_println!("");
    cli_println!("  {:>12}: {:>4}", "gauges", gauge_count);
    cli_println!("  {:>12}: {:>4}", "counters", counter_count);
    cli_println!("  {:>12}: {:>4}", "meters", meter_count);
    cli_println!("  {:>12}: {:>4}", "histograms", histogram_count);
    cli_println!("  {:>12}: {:>4}", "timers", timer_count);
    cli_println!("  {:>12}  -----", "");
    cli_println!("  {:>12}: {:>4}", "total", total);
    cli_println!("");

    if total > 0 {
        cli_println!("Non-zero metrics:");
        for line in &lines {
            cli_println!("  {}", line);
        }
        cli_println!("");
        cli_println!("  Use 'doctor metrics <filter>' to filter by name, 'doctor metrics grep <pattern>' to search with grep options.");
    } else {
        cli_println!("  (no non-zero metrics found)");
    }

    json_field("metrics", all_metrics);
    Ok(())
}

/// Whether the CLI may restart a running localhost server whose version no
/// longer matches the version this CLI would launch.  Disabled when the user
/// explicitly chose the server via `--server` or the config file — an
/// explicitly targeted server is the user's choice, not the CLI's to replace.
fn should_enforce_server_version(global: &args::GlobalFlags) -> bool {
    global.server_url.is_none() && crate::config::read_config().server.is_none()
}

fn should_ensure_server_running(command: &str) -> bool {
    command != "close"
        && command != "disconnect"
        && command != "close-all"
        && command != "kill-all"
        && command != "session-default"
        && command != "list"
        && command != "install"
        && command != "uninstall"
        && command != "upgrade"
        && command != "stop"
        && command != "status"
        && command != "doctor"
        && command != "doctor-log"
        && command != "doctor-metrics"
        && command != "doctor-status"
        && command != "agent-list"
        && command != "agent-cancel"
        && command != "crawl-list"
        && command != "swarm-list"
        && command != "skills"
        && command != "skills-list"
        && command != "skills-get"
        && command != "skills-path"
        && command != "skills-unpack"
        && command != "loop"
        && command != "snapshot-list"
        && command != "snapshot-clean"
        && command != "config"
        && command != "config-list"
        && command != "config-get"
        && command != "config-set"
        && command != "config-delete"
        // webminer runs a local Java tool — no Browser4 server needed.
        && command != "webminer"
        && command != "webminer-install"
        && command != "webminer-update"
        && command != "webminer-version"
        && command != "webminer-uninstall"
        && command != "webminer-run-example"
        && command != "webminer-all"
        && command != "webminer-views"
}

/// Commands that require a web page to already be loaded in the browser.
/// For these commands, the CLI will NOT auto-start the server — instead
/// it guides the user to run `open <url>` or `goto <url>` first.
fn is_page_dependent_command(command: &str) -> bool {
    matches!(
        command,
        // Interaction — needs elements on a page
        "click" | "dblclick" | "hover"
        | "type" | "fill" | "press" | "key" | "keydown" | "keyup"
        | "check" | "uncheck"
        | "mousemove" | "mousedown" | "mouseup" | "mousewheel"
        // Snapshot / screenshot / export — needs page content
        | "snapshot" | "snapshot-grep"
        | "screenshot" | "pdf"
        // HTML snapshot commands — need page content
        | "htmlsnapshot" | "htmlsnapshot-capture" | "htmlsnapshot-get"
        | "htmlsnapshot-get-all" | "htmlsnapshot-query" | "htmlsnapshot-export"
        | "htmlsnapshot-summary" | "htmlsnapshot-grep" | "htmlsnapshot-inspect"
        // Queries — need page content
        | "get" | "extract" | "summarize" | "eval"
        | "generate-locator"
        // Viewport management — needs a page
        | "scroll" | "resize"
        // Console — needs a page to intercept messages
        | "console"
        // Network inspection / HAR / routing — needs a live page with network traffic
        | "network-requests" | "network-request" | "network-route" | "network-unroute"
        | "network-routes"
        | "har-start" | "har-stop"
        // Storage commands — need page origin context
        | "cookie-list" | "cookie-get" | "cookie-set" | "cookie-delete" | "cookie-clear"
        | "localstorage-list" | "localstorage-get" | "localstorage-set"
        | "localstorage-delete" | "localstorage-clear"
        | "sessionstorage-list" | "sessionstorage-get" | "sessionstorage-set"
        | "sessionstorage-delete" | "sessionstorage-clear"
        // Storage state — needs a page for save/load
        | "state-save" | "state-load" | "delete-data"
        // Wait — needs timing on a page
        | "wait"
    )
}

/// Message for a page-dependent command whose local backend could not be
/// reached (or started).
///
/// Reports the endpoint that is down and what the user loses, instead of the
/// old "No active browser session … open <url> first" wording, which blamed the
/// session for a server failure.  The launcher's own error is carried verbatim
/// so the real cause is not replaced by a second, invented one.
fn backend_unreachable_message(base_url: &str, command: &str, cause: &str) -> String {
    let bin = cli_binary_name();
    format!(
        "Browser4 backend is not reachable at {} — '{command}' needs a running server.\n\
         The saved session's live page/tab state is lost with the previous backend instance; \
         after it is reachable again, run '{bin} open <url>' or '{bin} goto <url>' to load a page.\n\
         Cause: {cause}",
        base_url.trim_end_matches('/')
    )
}

/// Semantic fast-fail checks that mirror backend validations, so the user
/// gets a clear usage error without a server round-trip.
fn validate_command_semantics(
    command: &str,
    parsed: &HashMap<String, Value>,
) -> Result<(), String> {
    if command == "network-route" {
        let abort = parsed
            .get("abort")
            .and_then(|v| v.as_bool())
            .unwrap_or(false);
        let has_body = parsed
            .get("body")
            .map(|v| !v.is_null() && !(v.as_str().unwrap_or("").is_empty()))
            .unwrap_or(false);
        if abort && has_body {
            return Err(
                "network route cannot combine --abort with --body: choose exactly one action"
                    .to_string(),
            );
        }
        if !abort && !has_body {
            return Err(
                "network route requires at least one action: --abort or --body <text>".to_string(),
            );
        }
    }
    if command == "har-start" {
        match parsed.get("content") {
            None => {}
            Some(Value::String(content)) => {
                if !matches!(content.as_str(), "all" | "text" | "none") {
                    return Err(format!(
                        "invalid --content '{content}' for har start. Valid options: all, text, none"
                    ));
                }
            }
            // parse_raw_args coerces "true"/"false" to booleans; a non-string
            // --content would silently drop the option — reject it instead.
            Some(_) => {
                return Err(
                    "invalid --content for har start. Valid options: all, text, none".to_string(),
                );
            }
        }
    }
    if command == "click" {
        // `click --count` drives CDP `clickCount`, so the value has to be a
        // whole number of clicks. The backend's `paramInt` rejects garbage too,
        // but only after a session exists and the call has crossed the wire:
        // name the bad value here, before anything is dispatched.
        if let Some(raw) = parsed.get("count") {
            match raw {
                Value::String(value) => match value.trim().parse::<i64>() {
                    Ok(count) if count >= 1 => {}
                    Ok(count) => {
                        return Err(format!(
                            "invalid --count {count} for click: the click count must be at least 1"
                        ))
                    }
                    Err(_) => {
                        return Err(format!(
                            "invalid --count '{value}' for click: expected a whole number of clicks (e.g. --count=3)"
                        ))
                    }
                },
                // A valueless `--count` parses as `true`; no other JSON shape
                // can be a click count either.
                _ => {
                    return Err(
                        "invalid --count for click: expected a whole number of clicks (e.g. --count=3)"
                            .to_string(),
                    )
                }
            }
        }
        // The driver's click overloads take a repeat count or a modifier, never
        // both; combining them reached the backend and came back as a generic
        // "click requires 'selector' plus optionally …".
        if parsed.contains_key("count") && parsed.contains_key("modifiers") {
            return Err(
                "click cannot combine --count with --modifiers: a repeated click repeats one \
                 button press, so pass one of them (use keydown/keyup to hold a key across \
                 separate clicks)"
                    .to_string(),
            );
        }
    }
    if command == "open" {
        // `--display-mode` is the backend's own display axis; it replaces the
        // `--headed`/`--headless` boolean rather than layering on it, and the
        // mode is fixed when the session is created — so a value the backend
        // would silently drop must fail here instead.
        if let Some(raw) = parsed.get("display-mode") {
            let mode = match raw {
                Value::String(value) => value.trim().to_ascii_uppercase(),
                _ => {
                    return Err(
                        "invalid --display-mode for open: expected GUI, HEADLESS, or SUPERVISED"
                            .to_string(),
                    )
                }
            };
            if !matches!(mode.as_str(), "GUI" | "HEADLESS" | "SUPERVISED") {
                return Err(format!(
                    "invalid --display-mode '{mode}' for open. Valid modes: GUI, HEADLESS, SUPERVISED"
                ));
            }
            let conflicting = if parsed.contains_key("headed") {
                Some("--headed")
            } else if parsed.contains_key("headless") {
                Some("--headless")
            } else {
                None
            };
            if let Some(flag) = conflicting {
                return Err(format!(
                    "open cannot combine --display-mode={mode} with {flag}: --display-mode already \
                     carries the display choice, so pass only one of them"
                ));
            }
        }
        // `PulsarSettings` reads `maxOpenTabs` with `toIntOrNull()`, so a bad
        // value would be dropped silently instead of bounding the tab count.
        if let Some(raw) = parsed.get("max-open-tabs") {
            let valid = match raw {
                Value::String(value) => matches!(value.trim().parse::<u32>(), Ok(tabs) if tabs >= 1),
                _ => false,
            };
            if !valid {
                return Err(format!(
                    "invalid --max-open-tabs '{}' for open: expected a positive whole number \
                     (e.g. --max-open-tabs 4)",
                    raw.as_str().unwrap_or_default()
                ));
            }
        }
    }
    if command == "type" {
        // --method needs a ref target: exec/verify need a read-back target and
        // auto/chars make no sense on the "currently focused element" path.
        if let Some(method) = parsed.get("method").and_then(|v| v.as_str()) {
            if !matches!(method, "auto" | "chars" | "exec") {
                return Err(format!(
                    "invalid --method '{method}' for type. Valid options: auto, chars, exec"
                ));
            }
            let has_ref = parsed
                .get("ref")
                .map(|v| v.as_str().map(|s| !s.is_empty()).unwrap_or(false))
                .unwrap_or(false);
            if !has_ref {
                return Err(
                    "type --method requires a target ref: type <text> <ref> --method <auto|chars|exec>"
                        .to_string(),
                );
            }
        }
    }
    if is_htmlsnapshot_read_command(command) {
        // The backend rejects an unparsable `expires` too, but the round-trip hides *which*
        // command's option was wrong and needs a session first — fail here instead.
        match parsed.get("expires") {
            None => {}
            Some(Value::String(value)) => validate_htmlsnapshot_expires(value)?,
            // `parse_raw_args` stores a boolean when the flag carries no value
            // (`htmlsnapshot get --expires --all`); a non-string would be sent as-is.
            Some(_) => {
                return Err(
                    "invalid --expires for htmlsnapshot: expected a duration value (e.g. --expires 1d)"
                        .to_string(),
                );
            }
        }
    }
    Ok(())
}

/// The htmlsnapshot commands whose snapshot a caller may take from the store instead of the live
/// page — the reads.  `htmlsnapshot` (capture) is deliberately absent: it always writes the live
/// document, which is its whole purpose.
fn is_htmlsnapshot_read_command(command: &str) -> bool {
    matches!(
        command,
        "htmlsnapshot-get"
            | "htmlsnapshot-get-all"
            | "htmlsnapshot-query"
            | "htmlsnapshot-export"
            | "htmlsnapshot-summary"
            | "htmlsnapshot-grep"
            | "htmlsnapshot-inspect"
            | "htmlsnapshot-readability"
    )
}

/// Whether [value] is a duration the backend accepts for `--expires`.
///
/// The grammar is the one `LoadOptions -expires` understands — `0s`, `500ms`, `30s`, `10m`, `2h`,
/// `1d`, or an ISO-8601 duration such as `PT30S` / `P1D` — plus a bare `0`, which is how the
/// option's default is usually spelled.  A bare non-zero number is **rejected**: the engine's
/// `SParser` turns anything it cannot parse (a bare `5` included) into an always-expired sentinel,
/// so accepting it would silently mean "0s" instead of "5 seconds".
fn is_htmlsnapshot_expires_value(value: &str) -> bool {
    let value = value.trim();
    if value == "0" {
        return true;
    }

    // ISO-8601 first: such a value *starts* with a letter, so the amount+unit branch below would
    // read `PT30S` as "unit PT30S" and reject a perfectly valid duration.  Its exact shape is
    // validated by the backend, which parses it with `Duration.parse`.
    let upper = value.strip_prefix('-').unwrap_or(value).to_ascii_uppercase();
    if upper.starts_with('P') {
        return upper.len() > 1
            && upper
                .chars()
                .all(|c| c.is_ascii_digit() || matches!(c, 'P' | 'T' | 'H' | 'M' | 'S' | 'D' | 'W' | '.'));
    }

    // `<digits><unit>`: the amount is required, the unit is one of ms/s/m/h/d.
    match value.find(|c: char| !c.is_ascii_digit()) {
        Some(index) if index > 0 => {
            matches!(value[index..].to_ascii_lowercase().as_str(), "ms" | "s" | "m" | "h" | "d")
        }
        _ => false,
    }
}

/// Reject an `--expires` value the backend would refuse, with the accepted grammar spelled out.
fn validate_htmlsnapshot_expires(value: &str) -> Result<(), String> {
    if is_htmlsnapshot_expires_value(value) {
        return Ok(());
    }
    Err(format!(
        "invalid --expires value '{}' for htmlsnapshot. Expected a duration such as 0s, 30s, 10m, 2h or 1d \
         (or an ISO-8601 duration such as PT30S); outside `0`, a bare number is not a duration. 0s (the \
         default) reads the live page; a positive value reads the stored snapshot while it is younger \
         than the window.",
        value.trim()
    ))
}

/// Whether an `--expires` value asks the read for the **stored** snapshot (a positive window) instead
/// of the live page.
///
/// Only used to pick the right guidance when a read matches nothing; a value that is not a duration at
/// all counts as "live page", which is what the read does by default (and the backend rejects such a
/// value anyway).
fn htmlsnapshot_expires_is_store_only(value: &str) -> bool {
    is_htmlsnapshot_expires_value(value) && value.chars().any(|c| matches!(c, '1'..='9'))
}

/// Validate that all required (non-optional) positional arguments are present
/// in the parsed argument map.  Catches malformed commands (e.g. `htmlsnapshot grep`
/// without a pattern) before the backend is started.
fn validate_required_args(
    cmd_def: &commands::CommandDef,
    parsed: &HashMap<String, Value>,
) -> Result<(), String> {
    for arg in cmd_def.args {
        if !arg.optional {
            let has_value = match parsed.get(arg.name) {
                Some(Value::String(_)) => true, // empty string "" is a valid explicit value
                Some(Value::Number(_)) => true,
                Some(Value::Bool(_)) => true,
                Some(Value::Array(arr)) => !arr.is_empty(),
                _ => false,
            };
            if !has_value {
                // Build a concise usage line from the command definition
                let usage_args: Vec<String> = cmd_def
                    .args
                    .iter()
                    .map(|a| {
                        if a.optional {
                            format!("[{}]", a.name)
                        } else {
                            format!("<{}>", a.name)
                        }
                    })
                    .collect();
                return Err(format!(
                    "Missing required argument: <{}>.\nUsage: browser4-cli {} {}\n{}",
                    arg.name,
                    public_command_name(cmd_def.name),
                    usage_args.join(" "),
                    help::help_hint(cmd_def.name)
                ));
            }
        }
    }
    Ok(())
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

/// Rewrite spaced prefixed subcommands like `swarm create` / `agent run`
/// to their internal kebab-case command forms.
fn rewrite_prefixed_command(args: &[String]) -> Option<Vec<String>> {
    let prefix = args.first().map(|s| s.as_str())?;
    let sub = args.get(1)?;
    // Do not rewrite when the second argument looks like a flag (e.g. --help)
    // rather than a subcommand name.
    if sub.starts_with('-') {
        return None;
    }
    // `htmlsnapshot get all` is a two-level subcommand — rewrite to the flat
    // `htmlsnapshot-get-all` form so the dispatch matches it correctly.
    if prefix == "htmlsnapshot" && sub == "get" {
        if let Some(inner) = args.get(2) {
            if inner == "all" {
                let mut rewritten = vec!["htmlsnapshot-get-all".to_string()];
                rewritten.extend(args[3..].iter().cloned());
                return Some(rewritten);
            }
        }
    }
    // "chat" works standalone (chat <prompt>) AND as a prefix (chat result).
    // Only rewrite known chat subcommands so positional prompts pass through.
    if prefix == "chat" {
        let known_subs = ["result"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("chat-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "crawl" works standalone (crawl <url>) AND as a prefix (crawl list).
    // Only rewrite known crawl subcommands so positional URLs pass through.
    if prefix == "crawl" {
        let known_subs = ["status", "result", "cancel", "clear", "list", "resume"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("crawl-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "webdb" works standalone (webdb) AND as a prefix (webdb export).
    if prefix == "webdb" {
        let known_subs = ["export", "normalize"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("webdb-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "scrape" works standalone (scrape <url>) AND as a prefix (scrape formats).
    // Only rewrite the known subcommand so a positional URL passes through.
    if prefix == "scrape" {
        let known_subs = ["formats"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("scrape-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "doctor" works standalone (doctor) AND as a prefix (doctor log).
    if prefix == "doctor" {
        let known_subs = ["log", "metrics", "status"];
        if known_subs.contains(&sub.as_str()) {
            let rest: Vec<String> = args[2..].iter().cloned().collect();
            // Handle `doctor log <name> grep <pattern> [grep-options]`:
            // and `doctor metrics grep <pattern> [grep-options]`:
            // rewrite so that "grep" and its pattern become --grep <pattern>,
            // while the log/metric name stays as the first positional arg.
            // Examples: doctor log pulsar grep ERROR -i
            //        → doctor-log pulsar --grep ERROR -i
            //           doctor metrics grep cpu -i
            //        → doctor-metrics --grep cpu -i
            if let Some(grep_pos) = rest.iter().position(|a| a == "grep") {
                let mut rewritten = vec![format!("doctor-{}", sub)];
                // Everything before "grep" (the log name)
                rewritten.extend(rest[..grep_pos].iter().cloned());
                // Replace "grep" with "--grep" and add the pattern
                rewritten.push("--grep".to_string());
                rewritten.extend(rest[grep_pos + 1..].iter().cloned());
                return Some(rewritten);
            }
            let mut rewritten = vec![format!("doctor-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `experience deep learn` is a two-level subcommand — rewrite to the flat
    // `experience-deep-learn` form so the dispatch matches it correctly.
    if prefix == "experience" && sub == "deep" {
        if let Some(inner) = args.get(2) {
            if inner == "learn" {
                let mut rewritten = vec!["experience-deep-learn".to_string()];
                rewritten.extend(args[3..].iter().cloned());
                return Some(rewritten);
            }
        }
    }
    // `is visible|enabled|checked <sel>` — agent-browser style assertion commands.
    if prefix == "is" {
        let known_subs = ["visible", "enabled", "checked"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("is-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `window new [url]` — new browser window (tab alias).
    if prefix == "window" {
        let known_subs = ["new"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("window-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `diff snapshot [before] [after]` — diff saved accessibility snapshots.
    if prefix == "diff" {
        let known_subs = ["snapshot"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("diff-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `profiler start|stop [--file ...]` — V8 CPU profiling.
    if prefix == "profiler" {
        let known_subs = ["start", "stop"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("profiler-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `network requests|request <id>` and `network har start|stop [path]` —
    // request inspection and HAR recording.
    if prefix == "network" {
        if sub == "har" {
            let inner = args.get(2).map(|s| s.as_str());
            let flat = match inner {
                Some("start") => "har-start",
                Some("stop") => "har-stop",
                _ => return None,
            };
            let mut rewritten = vec![flat.to_string()];
            rewritten.extend(args[3..].iter().cloned());
            return Some(rewritten);
        }
        let known_subs = ["requests", "request", "route", "unroute", "routes"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("network-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // `profiles list` — list browser profile directories.
    if prefix == "profiles" {
        let known_subs = ["list"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("profiles-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "webminer" works standalone (webminer) AND as a prefix
    // (webminer install / all / views ...).  Known subcommands are
    // rewritten to their flat forms; unknown ones (arbitrary JAR commands
    // like `webminer encode <dir>`) fall through so the bare command
    // handler can forward them verbatim to scent-miner.jar.
    if prefix == "webminer" {
        let known_subs = [
            "install",
            "update",
            "version",
            "uninstall",
            "run-example",
            "all",
            "views",
        ];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("webminer-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    // "tool" is a prefix-only command (tool call <name>, tool list). Only
    // rewrite known subcommands so anything else passes through to the
    // unknown-command error.
    if prefix == "tool" {
        let known_subs = ["call", "list"];
        if known_subs.contains(&sub.as_str()) {
            let mut rewritten = vec![format!("tool-{}", sub)];
            rewritten.extend(args[2..].iter().cloned());
            return Some(rewritten);
        }
        return None;
    }
    let rewritten_command = match prefix {
        "swarm" => format!("swarm-{}", sub),
        "agent" => format!("agent-{}", sub),
        "experience" => format!("experience-{}", sub),
        "htmlsnapshot" => format!("htmlsnapshot-{}", sub),
        "snapshot" => format!("snapshot-{}", sub),
        "skills" => format!("skills-{}", sub),
        "plugin" => format!("plugin-{}", sub),
        "config" => format!("config-{}", sub),
        "code" => format!("code-{}", sub),
        _ => return None,
    };
    let mut rewritten = vec![rewritten_command];
    rewritten.extend(args[2..].iter().cloned());
    Some(rewritten)
}

