    #[test]
    fn snapshot_clean_prunes_diff_reports_with_their_capture() {
        let dir = PathBuf::from("snaps");
        // newest first, as `handle_snapshot_clean` sorts them
        let reports = vec![
            dir.join("snapshot-b.diff.txt"),
            dir.join("snapshot-a.diff.txt"),
        ];

        // `snapshot-a.yml` is going away, so its report follows it; the report
        // whose capture is kept stays.
        assert_eq!(
            stale_diff_reports(&reports, &[dir.join("snapshot-a.yml")], 10, false),
            vec![dir.join("snapshot-a.diff.txt")]
        );
        // `--all` removes every report.
        assert_eq!(stale_diff_reports(&reports, &[], 10, true).len(), 2);
        // Reports beyond the retention count go too — they can come from a
        // `--stdout` capture, which persists no `.yml` to key on.
        assert_eq!(
            stale_diff_reports(&reports, &[], 1, false),
            vec![dir.join("snapshot-a.diff.txt")]
        );
        // Nothing to delete when every capture is kept and the count fits.
        assert!(stale_diff_reports(&reports, &[], 10, false).is_empty());
    }

    #[test]
    fn parse_tab_entry_accepts_boolean_and_string_active() {
        // The backend now emits a real Boolean, but older bundles still send
        // the legacy string form — both must parse (Issue 1).
        let bool_form = serde_json::json!({
            "index": 1, "url": "https://a", "title": "A", "guid": "G1", "active": true
        });
        let tab = parse_tab_entry(&bool_form).expect("bool form parses");
        assert!(tab.active);

        let string_form = serde_json::json!({
            "index": 0, "url": "https://b", "title": "B", "guid": "G0", "active": "true"
        });
        let tab = parse_tab_entry(&string_form).expect("legacy string form parses");
        assert!(tab.active);

        let string_false = serde_json::json!({ "index": 0, "active": "False" });
        let tab = parse_tab_entry(&string_false).expect("case-insensitive string parses");
        assert!(!tab.active);
    }

    #[test]
    fn tab_list_table_header_aligns_with_data_rows() {
        let tabs = vec![
            TabInfo {
                index: 0,
                url: "https://example.com/a/very/long/path/that/keeps/going".to_string(),
                title: "First".to_string(),
                guid: Some("0123456789abcdef0123456789abcdef".to_string()),
                active: false,
            },
            TabInfo {
                index: 1,
                url: "about:blank".to_string(),
                title: "Second".to_string(),
                guid: None,
                active: true,
            },
        ];

        let table = format_tab_table(&tabs);
        let lines: Vec<&str> = table.lines().collect();

        assert_eq!(lines.len(), 4, "header + separator + 2 rows:\n{table}");
        // Every row has the same width, so each column sits under its header.
        let width = lines[0].chars().count();
        for line in &lines {
            assert_eq!(
                line.chars().count(),
                width,
                "row '{line}' does not align:\n{table}"
            );
        }
        // The 32-char GUID is printed in full (it used to overflow a 4-char cell).
        assert!(
            table.contains("0123456789abcdef0123456789abcdef"),
            "{table}"
        );
        // The active tab is the one `--json` reports as active, marked with ▶;
        // the inactive row reserves the same two columns.
        assert!(lines[3].starts_with("▶ 1"), "{table}");
        assert!(lines[2].starts_with("  0"), "{table}");
    }

    #[test]
    fn truncate_for_table_never_splits_a_character() {
        assert_eq!(truncate_for_table("short", 60), "short");
        assert_eq!(
            truncate_for_table(&"a".repeat(100), 60),
            format!("{}…", "a".repeat(59))
        );
        // The limit counts characters, and a byte-wise cut used to panic on
        // multi-byte text.
        let accents = "é".repeat(100);
        let truncated = truncate_for_table(&accents, 60);
        assert_eq!(truncated.chars().count(), 60, "{truncated}");
        assert!(truncated.ends_with('…'), "{truncated}");
        assert!(
            accents.starts_with(truncated.trim_end_matches('…')),
            "{truncated}"
        );
    }

    #[test]
    fn validate_tab_select_target_maps_usage_errors() {
        let tabs = vec![
            TabInfo {
                index: 0,
                url: "https://a".to_string(),
                title: "A".to_string(),
                guid: Some("G0".to_string()),
                active: true,
            },
            TabInfo {
                index: 1,
                url: "https://b".to_string(),
                title: "B".to_string(),
                guid: Some("G1".to_string()),
                active: false,
            },
        ];

        // Missing target → usage error, not the backend's Arg(...) signature.
        let err = validate_tab_select_target(Some(&tabs), None, None).unwrap_err();
        assert!(err.contains("requires an index or --guid"));
        assert!(err.contains("usage:"));

        // Out-of-range index → tab-close's friendly wording.
        let err = validate_tab_select_target(Some(&tabs), Some(99), None).unwrap_err();
        assert!(err.contains("out of range"));
        assert!(err.contains("There are 2 tabs (indices 0-1)"));

        // Singular wording for a single-tab list.
        let one = vec![tabs[0].clone()];
        let err = validate_tab_select_target(Some(&one), Some(5), None).unwrap_err();
        assert!(err.contains("There is 1 tab (indices 0-0)"));

        // Unknown GUID → friendly not-found error.
        let err = validate_tab_select_target(Some(&tabs), None, Some("NOPE")).unwrap_err();
        assert!(err.contains("No tab found with GUID 'NOPE'"));

        // Valid targets pass.
        assert!(validate_tab_select_target(Some(&tabs), Some(1), None).is_ok());
        assert!(validate_tab_select_target(Some(&tabs), None, Some("G1")).is_ok());

        // No pre-switch list → let the backend decide.
        assert!(validate_tab_select_target(None, Some(99), None).is_ok());

        // Index takes precedence over an unrelated GUID (backend behavior).
        assert!(validate_tab_select_target(Some(&tabs), Some(0), Some("NOPE")).is_ok());
    }

    #[test]
    fn storage_state_path_normalizes_mixed_separators() {
        // A joined child path keeps its own separators in PathBuf::display;
        // normalize_path_display rebuilds with native separators so printed
        // messages never mix "\" and "/".
        let joined = PathBuf::from(r"D:\work").join(".test-sessions/browser_state.json");
        let normalized = normalize_path_display(&joined);
        let display = normalized.display().to_string();
        if cfg!(windows) {
            assert!(!display.contains('/'), "mixed separators remain: {display}");
            assert!(
                display.contains(r"\.test-sessions\browser_state.json"),
                "got: {display}"
            );
        } else {
            assert_eq!(display, joined.display().to_string());
        }
    }

