    #[test]
    fn validate_required_args_passes_when_optional_only() {
        let cmd_def = commands::CommandDef {
            name: "test-cmd",
            description: "",
            category: commands::Category::Core,
            hidden: false,
            batch_supported: false,
            args: &[commands::ArgDef {
                name: "x",
                description: "",
                optional: true,
            }],
            options: &[],
            e2e_coverage: commands::E2eCoverage::Excluded,
            tool_name_fn: |_| "test".to_string(),
            tool_params_fn: |_| json!({}),
        };
        let parsed = HashMap::new(); // no args provided, but all are optional
        assert!(validate_required_args(&cmd_def, &parsed).is_ok());
    }

    #[test]
    fn validate_required_args_fails_when_required_missing() {
        let cmd_def = commands::CommandDef {
            name: "test-cmd",
            description: "",
            category: commands::Category::Core,
            hidden: false,
            batch_supported: false,
            args: &[commands::ArgDef {
                name: "url",
                description: "",
                optional: false,
            }],
            options: &[],
            e2e_coverage: commands::E2eCoverage::Excluded,
            tool_name_fn: |_| "test".to_string(),
            tool_params_fn: |_| json!({}),
        };
        let parsed = HashMap::new(); // missing required "url"
        let err = validate_required_args(&cmd_def, &parsed).unwrap_err();
        assert!(err.contains("Missing required argument"));
        assert!(err.contains("url"));
        // The usage line alone leaves the user guessing about the options — the
        // error must also point at the command's own help page.
        assert!(
            err.contains("Usage: browser4-cli test-cmd <url>"),
            "error should carry a usage line: {err}"
        );
        assert!(
            err.contains("`browser4-cli --help test-cmd`"),
            "error should point at the help page: {err}"
        );
    }

