    fn tool_call_fail_on_error_option_is_opt_in() {
        assert!(!parse_tool_call_fail_on_error(None));
        assert!(!parse_tool_call_fail_on_error(Some(json!(false))));
        assert!(parse_tool_call_fail_on_error(Some(json!(true))));
    }

