    #[test]
    fn parse_crawl_poll_response_ok() {
        let response = json!({"status": "OK", "pagesFound": 5});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Done { pages_found: 5 }
        );
    }

    #[test]
    fn parse_crawl_poll_response_sc_ok() {
        let response = json!({"status": "SC_OK", "pagesFound": 10});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Done { pages_found: 10 }
        );
    }

    #[test]
    fn parse_crawl_poll_response_timeout() {
        let response = json!({"status": "SC_REQUEST_TIMEOUT", "error": "timed out"});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Error {
                message: "timed out".to_string()
            }
        );
    }

    #[test]
    fn parse_crawl_poll_response_internal_error() {
        let response = json!({"status": "SC_INTERNAL_SERVER_ERROR", "error": "boom"});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Error {
                message: "boom".to_string()
            }
        );
    }

    #[test]
    fn parse_crawl_poll_response_error_without_message() {
        let response = json!({"status": "SC_REQUEST_TIMEOUT"});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Error {
                message: "Unknown crawl error".to_string()
            }
        );
    }

    #[test]
    fn parse_crawl_poll_response_still_running() {
        let response = json!({"status": "RUNNING", "pagesFound": 3});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Running { pages_found: 3 }
        );
    }

    #[test]
    fn parse_crawl_poll_response_unknown_status_treated_as_running() {
        let response = json!({"status": "QUEUED", "pagesFound": 0});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Running { pages_found: 0 }
        );
    }

    #[test]
    fn parse_crawl_poll_response_empty_status_treated_as_running() {
        let response = json!({});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Running { pages_found: 0 }
        );
    }

    /// The status that must never be classified "still running": waiting on it
    /// would hang the poll loop forever, because nothing advances it.
    #[test]
    fn parse_crawl_poll_response_interrupted_is_terminal() {
        for status in ["Interrupted", "INTERRUPTED"] {
            let response = json!({"status": status, "pagesFound": 4, "remaining": 3});
            assert_eq!(
                parse_crawl_poll_response(&response),
                CrawlPollStatus::Interrupted,
                "status {status}"
            );
        }
    }

    #[test]
    fn parse_crawl_poll_response_zero_pages_done() {
        let response = json!({"status": "OK", "pagesFound": 0});
        assert_eq!(
            parse_crawl_poll_response(&response),
            CrawlPollStatus::Done { pages_found: 0 }
        );
    }

    // -------------------------------------------------------------------
    // crawl_failure_counts tests
    // -------------------------------------------------------------------

    #[test]
    fn crawl_failure_counts_clean_crawl_reports_no_failures() {
        let parsed = json!({
            "status": "OK",
            "pagesFound": 2,
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 2000}
            ],
            "failedPages": [],
            "pagesExpected": 2
        });
        assert_eq!(crawl_failure_counts(&parsed, 2), (2, 0));
    }

    #[test]
    fn crawl_failure_counts_counts_the_loss_ledger() {
        // pagesFound (2) + failedPages (1) == pagesExpected (3): the ledger is
        // the loss signal and stays disjoint from the delivered pages.
        let parsed = json!({
            "status": "OK",
            "pagesFound": 2,
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 2000}
            ],
            "failedPages": [
                {"url": "https://example.com/lost", "depth": 1, "protocolStatus": 408, "reason": "timeout"}
            ],
            "pagesExpected": 3
        });
        assert_eq!(crawl_failure_counts(&parsed, 2), (2, 1));
    }

    #[test]
    fn crawl_failure_counts_adds_delivered_pages_with_no_usable_content() {
        // A delivered page with an extraction error or a 0-byte body is a
        // failure too, and is never part of the loss ledger.
        let parsed = json!({
            "status": "OK",
            "pagesFound": 3,
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 0},
                {"url": "https://example.com/c", "contentLength": 500, "extractionError": "selector not found"}
            ],
            "failedPages": [],
            "pagesExpected": 3
        });
        assert_eq!(crawl_failure_counts(&parsed, 3), (1, 2));
    }

    #[test]
    fn crawl_failure_counts_falls_back_when_the_ledger_is_absent() {
        // Historical crawl rows carry no `failedPages`: per-page errors and
        // seed-level errors are then the only backstop, and they are not
        // summed (a failed seed is normally a lost page as well).
        let parsed = json!({
            "status": "OK",
            "pagesFound": 2,
            "pages": [
                {"url": "https://example.com/a", "contentLength": 0},
                {"url": "https://example.com/b", "contentLength": 2000}
            ],
            "seedStatuses": [
                {"url": "https://example.com/a", "status": "error", "error": "boom"},
                {"url": "https://example.com/x", "status": "error", "error": "boom"},
                {"url": "https://example.com/y", "status": "error", "error": "boom"}
            ]
        });
        // max(broken pages = 1, seed errors = 3), not 4.
        assert_eq!(crawl_failure_counts(&parsed, 2), (1, 3));
    }

    #[test]
    fn crawl_failure_counts_ignores_seed_errors_when_the_ledger_exists() {
        // With a loss ledger present the seed errors are already reflected in
        // it — adding them again would over-report.
        let parsed = json!({
            "status": "OK",
            "pagesFound": 1,
            "pages": [{"url": "https://example.com/a", "contentLength": 1000}],
            "failedPages": [{"url": "https://example.com/x", "reason": "boom"}],
            "seedStatuses": [{"url": "https://example.com/x", "status": "error", "error": "boom"}],
            "pagesExpected": 2
        });
        assert_eq!(crawl_failure_counts(&parsed, 1), (1, 1));
    }

    // -------------------------------------------------------------------
    // crawl completion line (issue 115140#4)
    // -------------------------------------------------------------------

    #[test]
    fn crawl_completion_line_counts_successes_not_attempts() {
        // Regression: a 10-page crawl whose every page failed extraction printed
        // "10 pages crawled, 10 rows extracted." directly above
        // "Summary: ok: 0, failed: 10".
        let parsed = json!({
            "status": "OK",
            "pagesFound": 10,
            "pagesExpected": 10,
            "failedPages": [],
            "pages": (0..10)
                .map(|i| json!({
                    "url": format!("https://example.com/{i}"),
                    "contentLength": 1000,
                    "extractionError": "The X-SQL extracted no data: every field is empty for https://example.com",
                }))
                .collect::<Vec<_>>(),
        });

        let line = crawl_completion_line(&parsed, 10, 10);
        assert!(
            line.starts_with("0 of 10 page(s) crawled (10 failed)"),
            "got: {line}"
        );
        assert!(
            line.contains("first failure: The X-SQL extracted no data"),
            "the reason must be visible without a second command: {line}"
        );
        assert!(!line.contains("10 pages crawled"), "got: {line}");
    }

    #[test]
    fn crawl_completion_line_reports_lost_pages_from_the_ledger() {
        let parsed = json!({
            "status": "OK",
            "pagesFound": 2,
            "pagesExpected": 3,
            "failedPages": [{"url": "https://example.com/x", "reason": "connection reset"}],
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 900},
            ],
        });

        let line = crawl_completion_line(&parsed, 3, 2);
        assert!(line.starts_with("2 of 3 page(s) crawled (1 failed)"), "got: {line}");
        assert!(line.contains("first failure: connection reset"), "got: {line}");
    }

    #[test]
    fn crawl_completion_line_is_unchanged_for_a_clean_crawl() {
        let parsed = json!({
            "status": "OK",
            "pagesFound": 3,
            "pagesExpected": 3,
            "failedPages": [],
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 1000},
                {"url": "https://example.com/c", "contentLength": 1000},
            ],
        });
        assert_eq!(
            crawl_completion_line(&parsed, 3, 3),
            "3 pages crawled, 3 rows extracted."
        );
    }

    // -------------------------------------------------------------------
    // tracked crawl labels and the --status filter (issue 115140#3)
    // -------------------------------------------------------------------

    /// The payload of the reported all-empty-extraction run: status OK with the
    /// loss ledger telling the real story.
    fn partial_failure_payload() -> Value {
        json!({
            "status": "OK",
            "pagesFound": 10,
            "pagesExpected": 10,
            "failedPages": [],
            "pages": (0..10)
                .map(|i| json!({
                    "url": format!("https://example.com/{i}"),
                    "contentLength": 1000,
                    "extractionError": "The X-SQL extracted no data: every field is empty",
                }))
                .collect::<Vec<_>>(),
        })
    }

    #[test]
    fn crawl_tracked_status_label_keeps_the_partial_failure_accounting() {
        // Regression: the list refresh relabelled this run "completed" on every
        // poll, so a run that exited 6 looked clean forever.
        assert_eq!(
            crawl_tracked_status_label("OK", &partial_failure_payload()),
            "partial failure (0 of 10 pages ok)"
        );
        // A clean terminal crawl keeps the plain lifecycle label.
        let clean = json!({
            "status": "OK",
            "pagesFound": 3,
            "pagesExpected": 3,
            "failedPages": [],
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 1000},
                {"url": "https://example.com/c", "contentLength": 1000},
            ],
        });
        assert_eq!(crawl_tracked_status_label("OK", &clean), "completed");
        // Non-terminal statuses are untouched: `status = OK` still means "the
        // poller should stop", so the ledger must not rewrite other labels.
        assert_eq!(crawl_tracked_status_label("Processing", &partial_failure_payload()), "processing");
        assert_eq!(
            crawl_tracked_status_label("Request Timeout", &partial_failure_payload()),
            "failed (timeout)"
        );
        assert_eq!(
            crawl_tracked_status_label("Interrupted", &partial_failure_payload()),
            "interrupted"
        );
    }

    #[test]
    fn crawl_tracked_status_label_counts_lost_pages_from_the_ledger() {
        let payload = json!({
            "status": "OK",
            "pagesFound": 2,
            "pagesExpected": 3,
            "failedPages": [{"url": "https://example.com/x", "reason": "connection reset"}],
            "pages": [
                {"url": "https://example.com/a", "contentLength": 1000},
                {"url": "https://example.com/b", "contentLength": 900},
            ],
        });
        assert_eq!(
            crawl_tracked_status_label("OK", &payload),
            "partial failure (2 of 3 pages ok)"
        );
    }

    #[test]
    fn crawl_status_filter_matches_partial_failures_under_failed() {
        // `crawl list --status failed` used to match nothing for a run that
        // exited 6 with every page failed.
        assert!(crawl_status_filter_matches(
            "failed",
            "partial failure (0 of 10 pages ok)"
        ));
        assert!(!crawl_status_filter_matches(
            "completed",
            "partial failure (0 of 10 pages ok)"
        ));
        assert!(crawl_status_filter_matches("failed", "failed (timeout)"));
        assert!(crawl_status_filter_matches("interrupted", "interrupted"));
        assert!(!crawl_status_filter_matches("failed", "interrupted"));
        // The lifecycle labels are unchanged.
        assert!(crawl_status_filter_matches("completed", "completed"));
        assert!(crawl_status_filter_matches("running", "queued"));
    }

